T0 = time.time()


def _load_profile():
    """comfytrain/profile.env (KEY=VALUE lines) sets per-entry defaults; explicit environment variables win."""
    f = Path(__file__).resolve().parent / "profile.env"
    if f.exists():
        for line in f.read_text().splitlines():
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                k, v = line.split("=", 1)
                os.environ.setdefault(k.strip(), v.strip())


_load_profile()
os.environ.setdefault("G56CT_PROFILE", "c26s") if __name__ == "__main__" else None  # T287 (d): the release profile without ENV

VERBOSE = os.environ.get("G56CT_VERBOSE", "0") == "1"
_OUT_DIR = None  # set by main() as soon as the upload folder is known; the crash handler looks for a usable adapter there
LOGFILE = os.environ.get("G56CT_LOGFILE", "/tmp/g56ct.log")


def log(*a, public=False):
    """Container stdout is public (validator Loki). Details go to a private file; stdout gets only heartbeats unless
    G56CT_VERBOSE=1 (local tests)."""
    line = f"[ct {time.time() - T0:7.1f}s] " + " ".join(str(x) for x in a)
    try:
        with open(LOGFILE, "a") as f:
            f.write(line + "\n")
    except Exception:
        pass
    if VERBOSE or public:
        print(line if VERBOSE else " ".join(str(x) for x in a), flush=True)


def env(name, default, cast=str):
    v = os.environ.get("G56CT_" + name)
    if v is None or v == "":
        return default
    if cast is bool:
        return v.lower() in ("1", "true", "yes", "on")
    return cast(v)


# CPU threads = the container's CPU quota (6 Oct). The validator starts the trainer container with nano_cpus = 24 x GPUs
# (G.O.D trainer/runtime.py calculate_container_resources, trainer/constants.py CPUS_PER_GPU) and no OMP_NUM_THREADS, so
# torch would run one OpenMP thread per host core (252 on an 8-GPU node) inside a 24-CPU CFS quota: with several such
# containers on a node the CPU phases (key check, the finite check of a save) stalled for minutes (flux key check 165-392 s,
# 16-19 s with 24 threads). Before anything imports torch: when the quota (bounded by the affinity mask) leaves fewer CPUs
# than the host has and the caller did not set OMP_NUM_THREADS, OMP / MKL / OpenBLAS get floor(quota) threads, and main()
# passes the same count to torch.set_num_threads right after importing torch. No quota or OMP_NUM_THREADS set: no change.
CGROUP_ROOT = os.environ.get("G56CT_CGROUP_ROOT", "/sys/fs/cgroup")  # tests point it at fake cgroup files


def cgroup_cpu_quota(root=None):
    """CPUs granted by this container's CFS quota (float); None without a quota or when anything cannot be read / parsed.
    cgroup v2: <root>/cpu.max = '<quota> <period>' ('max ...': no quota); v1: <root>/cpu or <root>/cpu,cpuacct with
    cpu.cfs_quota_us (-1: no quota) / cpu.cfs_period_us."""
    root = Path(CGROUP_ROOT if root is None else root)
    try:
        if (root / "cpu.max").exists():
            quota, period = (root / "cpu.max").read_text().split()[:2]
            if quota == "max":
                return None
            q, p = float(quota), float(period)
        else:
            d = next((root / s for s in ("cpu", "cpu,cpuacct") if (root / s / "cpu.cfs_quota_us").exists()), None)
            if d is None:
                return None
            q, p = float((d / "cpu.cfs_quota_us").read_text()), float((d / "cpu.cfs_period_us").read_text())
        return q / p if q > 0 and p > 0 and math.isfinite(q / p) else None
    except Exception:  # noqa: BLE001  (unreadable / garbage: no quota known, nothing changes)
        return None


def set_cpu_threads(root=None):
    """Module import, before torch: n = floor(min(quota, affinity, host CPUs)) >= 1. Only when n < the host's CPU count and
    OMP_NUM_THREADS is not set: OMP_NUM_THREADS / MKL_NUM_THREADS / OPENBLAS_NUM_THREADS = n (values the caller set are
    kept) and n is returned for torch.set_num_threads (apply_torch_threads); else None. Private log lines only."""
    host, quota = os.cpu_count(), cgroup_cpu_quota(root)
    if quota is None or not host:
        return None
    try:
        aff = len(os.sched_getaffinity(0))
    except Exception:  # noqa: BLE001  (no affinity call on this platform)
        aff = host
    n = max(1, int(min(quota, aff, host)))
    if n >= host:
        return None
    why = f"cgroup quota {round(quota, 2)} of {host} host CPUs" + (f", affinity {aff}" if aff < quota else "")
    omp = os.environ.get("OMP_NUM_THREADS", "").strip()
    if omp:
        log(f"cpu threads: OMP_NUM_THREADS={omp[:16]} set by the caller, kept ({why})")
        return None
    for k in ("OMP_NUM_THREADS", "MKL_NUM_THREADS", "OPENBLAS_NUM_THREADS"):
        if not os.environ.get(k, "").strip():
            os.environ[k] = str(n)
    log(f"cpu threads: {n} ({why})")
    return n


CPU_THREADS = set_cpu_threads()


def apply_torch_threads():
    """main(), right after its torch import: torch's intra-op pool = CPU_THREADS (the env above is read when torch starts
    its thread pool; this also covers a torch imported before this module). Nothing when set_cpu_threads did not act."""
    if CPU_THREADS:
        import torch
        torch.set_num_threads(CPU_THREADS)


