def apply_big_n_defaults(fam, n_images):
    """Apply FAMILY_DEFAULTS_BIG_N[fam] when n_images >= its threshold, then FAMILY_DEFAULTS_BIG_N_BAND[fam] when n_images lies in
    its band (keys without an explicit env var); returns the applied keys."""
    if os.environ.get("G56CT_FAMILY_DEFAULTS", "1") == "0":
        return {}
    spec, band = FAMILY_DEFAULTS_BIG_N.get(fam), FAMILY_DEFAULTS_BIG_N_BAND.get(fam)
    tiers = ([spec[1]] if spec and n_images >= spec[0] else []) + ([band[2]] if band and band[0] <= n_images <= band[1] else [])
    applied = {}
    for k, v in (kv for tier in tiers for kv in tier.items()):
        if os.environ.get("G56CT_" + k.upper()) in (None, ""):
            CFG[k] = v
            applied[k] = v
    return applied


