def base_root_dtype(repo):
    """The safetensors dtype string ('F8_E5M2', 'F8_E4M3', 'BF16', ...) of the probe tensor img_in.weight (QF8_PROBES[0]) in the
    task's root checkpoint (root_checkpoint), from the file header alone; None when the root has no such tensor."""
    hdr = safetensors_header(root_checkpoint(repo))
    ent = {_qf8_name(k): v for k, v in hdr.items() if k != "__metadata__"}.get(QF8_PROBES[0])
    return ent.get("dtype") if isinstance(ent, dict) else None


def apply_base_defaults(fam, kind):
    """Apply FAMILY_DEFAULTS_BASE[fam][kind] (keys without an explicit env var) when G56CT_BASECOND is on; returns the
    applied keys."""
    if not CFG["basecond"] or os.environ.get("G56CT_FAMILY_DEFAULTS", "1") == "0":
        return {}
    applied = {}
    for k, v in FAMILY_DEFAULTS_BASE.get(fam, {}).get(kind, {}).items():
        if os.environ.get("G56CT_" + k.upper()) in (None, ""):
            CFG[k] = v
            applied[k] = v
    return applied


def basecond_setup(fam, repo):
    """main(), right after gencond_setup: with G56CT_BASECOND on and a FAMILY_DEFAULTS_BASE entry for the family, the root
    checkpoint's probe dtype picks the cell; one private line. Off, or no entry: nothing at all. An exception leaves CFG as it
    was (one private WARN line): the run continues with the defaults applied before it."""
    if not CFG["basecond"] or fam not in FAMILY_DEFAULTS_BASE:
        return {}
    saved = dict(CFG)
    try:
        kind = base_root_dtype(repo)
        cell = FAMILY_DEFAULTS_BASE[fam].get(kind, {})
        applied = apply_base_defaults(fam, kind)
        env_kept = sorted(k for k in cell if k not in applied and os.environ.get("G56CT_" + k.upper()) not in (None, ""))
        log(f"basecond: {fam} root {QF8_PROBES[0]} {kind} -> " + (json.dumps(applied, sort_keys=True) if applied else "no change")
            + (f" (env kept: {', '.join(env_kept)})" if env_kept else ""))
        return applied
    except Exception as e:  # noqa: BLE001  (basecond never ends a run: the defaults before it stay)
        CFG.clear()
        CFG.update(saved)
        log(f"WARN basecond: {type(e).__name__}: {str(e)[:120]}; no change")
        return {}


