def fcpb_identity(path):
    """T224 A2: (size in bytes, sha256 hex of the 8-byte header length + the header JSON) of a safetensors file; reads the header only."""
    import struct
    with open(path, "rb") as f:
        b8 = f.read(8)
        if len(b8) != 8:
            raise IOError("short safetensors file")
        n = struct.unpack("<Q", b8)[0]
        if not 0 < n <= 100 * 1024 * 1024:
            raise ValueError(f"safetensors header length {n}")
        h = f.read(n)
        if len(h) != n:
            raise IOError("short safetensors header")
    return int(Path(path).stat().st_size), hashlib.sha256(b8 + h).hexdigest()


def fcpb_value(fam, ident, profile_on, env_val, current):
    """T224 A2: -> (the flux_fc value to use, the private line or None). Pure (fcpb_check): ident = fcpb_identity of the root
    checkpoint; acts only for flux under the profile with T224_FCPB_IN_C26S and an FC in effect; a T224_FCPB_CONTENT entry with no
    explicit G56CT_FLUX_FC -> its string; an explicit value -> kept (one 'not applied' line); no entry -> kept (one 'no match' line)."""
    if not (profile_on and T224_FCPB_IN_C26S) or fam != "flux" or not str(current or "").strip():
        return current, None  # (no FC in effect - e.g. the c26s FC switch off: the per-base string never turns one on)
    hit = T224_FCPB_CONTENT.get((int(ident[0]), str(ident[1]))) if ident else None
    if hit is None:
        return current, (f"fc-per-base: no content match (root {ident[0]} B, header sha256 {str(ident[1])[:12]}): flux_fc {current!r} kept"
                         if ident else None)
    label, want = hit
    if env_val not in (None, ""):
        return current, f"fc-per-base: {label} (content match) -> {want!r} not applied (G56CT_FLUX_FC={env_val!r} set: it wins)"
    return want, (f"fc-per-base: {label} (content match: {ident[0]} B, header sha256 {str(ident[1])[:12]}) -> flux_fc {want!r} "
                  f"(was {current!r}; T224 A2 under the c26s profile)")


def fcpb_setup(fam, repo):
    """main(), right after basecond_setup: T224 A2 per-base flux FC by content (fcpb_value); nothing at all unless the profile, flux and
    an FC in effect; a root checkpoint that cannot be identified -> one WARN line, flux_fc kept."""
    prof = str(os.environ.get("G56CT_PROFILE") or "").strip().lower() in ("c26s",)
    cur = CFG.get("flux_fc", "")
    if not (prof and T224_FCPB_IN_C26S) or fam != "flux" or not str(cur or "").strip():
        return cur
    try:
        ident = fcpb_identity(root_checkpoint(repo))
    except Exception as e:  # noqa: BLE001  (the per-base FC never ends a run)
        log(f"WARN fc-per-base: no identity for the root checkpoint ({type(e).__name__}: {str(e)[:120]}); flux_fc {cur!r} kept")
        return cur
    value, line = fcpb_value(fam, ident, prof, os.environ.get("G56CT_FLUX_FC"), cur)
    if line is not None:
        log(line)
    CFG["flux_fc"] = value
    return value


