    compile_blocks=env("COMPILE_BLOCKS", False, bool),
    compile_backend=env("COMPILE_BACKEND", "inductor"),
    compile_dynamic=env("COMPILE_DYNAMIC", "auto"),
    compile_min_gain=env("COMPILE_MIN_GAIN", 0.02, float),
    compile_min_left=env("COMPILE_MIN_LEFT", 900.0, float),
    compile_max_s=env("COMPILE_MAX_S", 300.0, float),
    # ours (T093, 13 Oct; speed): FAST_EMA - the per-step EMA update e = e x d + p x (1 - d) as two foreach kernels over all
