    small_max_k=env("SMALL_MAX_K", 256.0, float),      # only params with at most this many thousand elements
    qf8=env("QF8", False, bool),                       # ours (7 Oct): qwen-image fp8 bias / norm restoration in every written file
    qf8_path=env("QF8_PATH", False, bool),             # ours (T062, 10 Oct): + exact io / t-embed layers and a rank-8 restoration
                                                       # of the 120 modulation layers in every written file (needs QF8)
    qf8_train=env("QF8_TRAIN", False, bool),           # ours (T062, 10 Oct): the restoration also written into the in-memory
                                                       # base before training: the LoRA learns on the restored model (needs QF8)
