_post_scale_sd_t146 = post_scale_sd


def post_scale_sd(sd, interim=False):  # noqa: F811  (T157: T079 / T146 first, then G56CT_FLUX_FC / G56CT_ZIMG_P1's record)
    return t157_sd(_post_scale_sd_t146(sd, interim), interim)


_save_lora_t157 = save_lora


def _t157_save_lora(sd, out_dir, meta=None, interim=False):
    """save_lora (T162): the old record is dropped first (no extra state at this write's peak RAM), then the trainer's own save_lora;
    when it returns True the file on disk is this write, so t157_sd's record of it (a knob's non-interim write) becomes _T157['fin']
    with the file's stat (_t157_final checks it) - an interim write, another family or the knobs off leave none, as does a refused
    write (False) or an exception (the file on disk then ships as written). Every caller of save_lora (any write schedule, any
    planner) goes through here."""
    _T157["pend"] = _T157["fin"] = None
    try:
        ok = _save_lora_t157(sd, out_dir, meta, interim)
        if ok and _T157["pend"] is not None:
            _T157["n"] = _T157.get("n", 0) + 1
            _T157["fin"] = _T157["pend"] + (Path(out_dir), meta, _T157["n"], _t157_stat(out_dir))
        return ok
    finally:
        _T157["pend"] = None


def _t157_stat(out_dir):
    """(inode, mtime ns, size) of out_dir/last.safetensors - save_lora replaces the file, a new inode per write - or None"""
    try:
        s = os.stat(Path(out_dir) / "last.safetensors")
        return s.st_ino, s.st_mtime_ns, s.st_size
    except OSError:
        return None


_t157_save_lora.__wrapped__ = _save_lora_t157  # inspect.getsource(save_lora) -> the trainer's own
save_lora = _t157_save_lora
