def _t157_loop_sample(self, *a, **k):
    """Loop.sample (T162): the trainer's own (train_loop - whichever planner runs the members - and the end of Loop.sample), then
    _t157_final: the shipped file's transform, once (nothing with the knobs off). A raise ends the run before it, as before."""
    out = _loop_sample_t157(self, *a, **k)
    _t157_final()
    return out


_t157_loop_sample.__wrapped__ = _loop_sample_t157  # inspect.getsource(Loop.sample) -> the trainer's own
