def t159_cells(spec):
    """G56CT_PLANNER_CELLS 'family:min_n:f_max,...' -> {family: (min_n, f_max)}; ValueError when malformed"""
    out = {}
    for part in str(spec or "").replace(" ", "").split(","):
        if not part:
            continue
        bits = part.split(":")
        if len(bits) != 3 or bits[0] not in FAMILIES or bits[0] in out:
            raise ValueError(f"{part!r} is not family:min_n:f_max (one per family of {', '.join(sorted(FAMILIES))})")
        mn, fm = int(bits[1]), float(bits[2])
        if mn < 1 or not (math.isfinite(fm) and 1.0 <= fm <= 4.0):
            raise ValueError(f"{part!r}: min_n >= 1 and 1 <= f_max <= 4")
        out[bits[0]] = (mn, fm)
    return out


def _t159_mode(cfg):
    """the planner of this run: 'v1' | 'v2safe' | 'v2' (anything else: one private WARN line and v1)"""
    m = str(cfg.get("planner") or "v1").strip().lower() or "v1"
    if m not in T159_MODES:
        _t159_say_once("mode", f"WARN planner: G56CT_PLANNER {cfg.get('planner')!r} is not one of {', '.join(T159_MODES)}; v1")
        return "v1"
    return m


def _t159_probe_step(cfg):
    """member 1's probe step: WARM + MEASURE (90); SAVE_EVERY + WARM when member 1 writes interim saves every <= 1000 steps, so
    one is measured before the plan (ideogram4 SAVE_EVERY 100: step 110; z-image / qwen-image 500: step 510)"""
    p = T159_WARM + T159_MEASURE
    se = int(cfg.get("save_every") or 0)
    return max(p, se + T159_WARM) if 0 < se <= 1000 else p


def _t159_n_bar(c):
    try:
        sizes = [it["scaled"].numel() for it in c["train"]]
        return sum(sizes) / len(sizes) if sizes else 0.0
    except Exception:  # noqa: BLE001  (no latent sizes: the plain mean of the probe steps)
        return 0.0


def _t159_buffer(writes, window):
    """max(30 s, 3 x the sample sd of the measured member writes), at most 5 % of the window (member 1's start -> deadline)"""
    sd = 0.0
    if len(writes) >= 2:
        mu = sum(writes) / len(writes)
        sd = math.sqrt(sum((w - mu) ** 2 for w in writes) / (len(writes) - 1))
    return min(max(T159_BUFFER_MIN, 3.0 * sd), max(T159_BUFFER_MIN, T159_BUFFER_FRAC * max(0.0, window)))


def _t159_stop_margin(c, k_done):
    """_run_one's all-data stop margin of a member started with k_done members on disk (the stop base; with SAFE the measured save
    margin of k_done + 1 members) - the very formula of _run_one at the current CFG / _SAVE_STATS"""
    kd = c.get("k_done", None)
    c["k_done"] = int(k_done)
    try:  # T126's stop base by name (t126_check counts its own call sites of that helper outside its block: not one more here)
        m = globals()["_t126_stop"](c.get("eval_cost", 60.0))
        if c["cfg"].get("safe") and not c["holdout"]:
            m = max(m, _save_margin(c))
    finally:
        if kd is None:
            c.pop("k_done", None)
        else:
            c["k_done"] = kd
    return m


def _t159_step_s(step_times, lats, n_bar, step, first, s_ref, x=None):
    """lr_full_step_s over the steps first..step with every step's time capped at x (T159_SPIKE_X) times s_ref, its latent's
    share (s_ref x size / n_bar): one slow step - a pause, a hiccup - must not read as a slower node (s_ref <= 0: no cap)"""
    x = T159_SPIKE_X if x is None else x
    lo = first if step >= first else 1
    st, la = list(step_times[lo - 1:step]), list(lats[lo - 1:step])
    if not st:
        return None
    sized = n_bar > 0 and len(la) == len(st) and all(isinstance(v, (int, float)) and v > 0 for v in la)
    if s_ref and s_ref > 0:
        st = [min(t, x * s_ref * (la[i] / n_bar if sized else 1.0)) for i, t in enumerate(st)]
    per_size = sum(st) / sum(la) if sized else None  # (lr_full_step_s's weighting; its own line is another check's anchor)
    return per_size * n_bar if sized else sum(st) / len(st)


def _t159_block_s(step_times, lats, n_bar, step):
    """the member's recent s/step, robustly: the median of the latent-weighted mean s/step of its last T159_REPLAN_BLOCKS blocks of
    T159_REPLAN_BLOCK steps (fewer steps: blocks of what there is after the warm-up); None with fewer than 2 steps per block"""
    size = min(T159_REPLAN_BLOCK, (step - T159_WARM) // T159_REPLAN_BLOCKS)
    if size < 2:
        return None
    means = sorted(_t159_step_s(step_times, lats, n_bar, step - j * size, step - (j + 1) * size + 1, 0.0)
                   for j in range(T159_REPLAN_BLOCKS))
    return means[T159_REPLAN_BLOCKS // 2]


def t159_scale(cells, n, target):
    """the exposure counts of a member of `target` cases -> (f, counts, total): at the table's own total the table itself
    (exposure_counts, as today); otherwise every cell's quota E x f x N / 2 at f = target / sum(E x N / 2), floored, and the
    remaining cases to the largest remainders (ties: the cell order) - Hamilton's apportionment of round(E x f x N / 2): exactly
    `target` cases, every cell within one case of its quota, so equal members can have any length (the caller bounds f)"""
    base = exposure_counts(cells, n)
    bt = sum(base.values())
    target = int(target)
    if target == bt or target <= 0:
        return 1.0, base, bt
    q_sum = sum(e * n / 2.0 for e in cells.values())
    f = target / q_sum
    quota = {k: e * f * n / 2.0 for k, e in cells.items()}
    cnt = {k: int(math.floor(v + 1e-9)) for k, v in quota.items()}
    rest = target - sum(cnt.values())
    for k in sorted(quota, key=lambda k_: (-(quota[k_] - cnt[k_]), k_))[:max(0, rest)]:
        cnt[k] += 1
    return f, cnt, sum(cnt.values())


def t159_bounded(req, used):
    """per-cell totals of a running member: req {cell: cases} (its new counts), used {cell: trained + dropped so far} - a cell
    never goes below what it used; when some cells already used more than their new count, those keep what they used and the
    other cells share the rest of sum(req) in proportion to req (largest remainders, ties: the cell order; a cell that falls
    below its used count in turn keeps that) -> exactly sum(req) cases whenever sum(used) <= sum(req) (else every cell at its
    used count: the member is past its total). Nothing above its count: req itself."""
    keys = sorted(set(req) | set(used))
    r = {k: int(req.get(k, 0)) for k in keys}
    u = {k: int(used.get(k, 0)) for k in keys}
    if all(r[k] >= u[k] for k in keys):
        return r
    target = sum(r.values())
    if sum(u.values()) >= target:
        return u
    fixed = {k: u[k] for k in keys if r[k] <= 0}
    while True:
        free = [k for k in keys if k not in fixed]
        t, w = target - sum(fixed.values()), sum(r[k] for k in free)
        low = [k for k in free if r[k] * t / max(1, w) < u[k]]
        if not low:
            break
        for k in low:
            fixed[k] = u[k]
    out = dict(fixed)
    q = {k: r[k] * t / max(1, w) for k in free}
    cnt = {k: int(math.floor(v + 1e-9)) for k, v in q.items()}
    for k in sorted(q, key=lambda k_: (-(q[k_] - cnt[k_]), k_))[:max(0, t - sum(cnt.values()))]:
        cnt[k] += 1
    out.update(cnt)
    return out


class _T159Exposure(Exposure):
    """G56CT_PLANNER v2safe / v2 (the planner's train_loop swaps it in for its members; the class above otherwise): Exposure + what
    the planner needs to resize the schedule of the member that runs - the trained / dropped cases per (image, half, band) and
    per cell; registers itself as the live member schedule. Draws stay Exposure's own (same seed, same stream)."""

    def __init__(self, counts, n_images, seed):
        super().__init__(counts, n_images, seed)  # super(): the planner swaps the global name Exposure to this class
        self.t159_img, self.t159_drop = {}, {}
        _T159["exs"] = self

    def done(self):
        p = self.pending
        super().done()
        if p is not None:
            self.t159_img[p] = self.t159_img.get(p, 0) + 1

    def drop(self):
        p = self.pending
        super().drop()
        if p is not None:
            self.t159_drop[p[2], p[1]] = self.t159_drop.get((p[2], p[1]), 0) + 1

    def t159_resize(self, counts):
        """the rest of this member's schedule for new per-cell totals (counts {(half, band): cases}) - between steps only: no cell
        below what it trained / dropped (t159_bounded: cells already past their new count keep it, the others share the rest, so
        the total stays sum(counts)); a cell gets its missing cases on its images with the fewest of that cell so far, or loses
        queued ones from its images with the most; the remaining items are shuffled again by the schedule's own RNG (nothing to
        change: the schedule as it is, no draw from that RNG). -> the member's new case total (trained + dropped + queued)."""
        if self.pending is not None:
            raise RuntimeError("t159_resize with a pending case")
        queue = list(self.queue)
        q_cell, q_img = {}, {}
        for it in queue:
            i, b, h = it
            q_cell[h, b] = q_cell.get((h, b), 0) + 1
            q_img[it] = q_img.get(it, 0) + 1
        keys = sorted(set(counts) | set(self.counts) | set(q_cell))
        used = {hb: self.trained.get(hb, 0) + self.t159_drop.get(hb, 0) for hb in keys}
        wants = t159_bounded({hb: int(counts.get(hb, 0)) for hb in keys}, used)
        if all(wants[hb] == used[hb] + q_cell.get(hb, 0) for hb in keys):  # every cell already at its new count
            return sum(wants.values())
        new_counts, add, rem = {}, [], {}
        for hb in keys:
            h, b = hb
            want, have = wants[hb], used[hb] + q_cell.get(hb, 0)
            if want > 0:
                new_counts[hb] = want
            if want == have:
                continue
            per = [self.t159_img.get((i, b, h), 0) + q_img.get((i, b, h), 0) for i in range(self.n)]
            order = list(range(self.n))
            self.rand.shuffle(order)
            if want > have:
                for _ in range(want - have):
                    i = min(order, key=lambda x: per[x])
                    per[i] += 1
                    add.append((i, b, h))
            elif want < have:
                for _ in range(have - want):
                    cand = [x for x in order if q_img.get((x, b, h), 0) - rem.get((x, b, h), 0) > 0]
                    i = max(cand, key=lambda x: per[x])
                    per[i] -= 1
                    rem[i, b, h] = rem.get((i, b, h), 0) + 1
        out = []
        for it in queue:
            if rem.get(it, 0) > 0:
                rem[it] -= 1
                continue
            out.append(it)
        out += add
        self.rand.shuffle(out)
        self.queue = out
        self.counts = new_counts
        self.total = sum(new_counts.values())
        return self.total


def _t159_live_exposure(c, cap0):
    """the member schedule the running member draws from (the planner's swap of Exposure), or None (no EXPOSURE / not ours)"""
    exs = _T159.get("exs")
    if c.get("exposure") is None or not isinstance(exs, _T159Exposure):
        return None
    return exs


def _t159_gptq_rec(c, s, deadline):
    """the dense GPTQ speed gate's own projection (_gptq_gate) at seconds per step s, for a training deadline: -> (rec, R, conv)
    with R = the reserve the gate would commit (None: the gate would skip - rec['why']); None when the gate does not apply to this
    run (not ideogram4 / DENSE gptq / gate speed, or already decided)"""
    if c.get("fam") != "ideogram4" or not _gptq_mode() or "gate" in _GPTQ_RUN \
            or str(CFG.get("dense_gptq_gate") or "speed").strip().lower() != "speed":
        return None
    return _t159_gptq_proj(c, s, deadline)


def _t159_gptq_proj(c, s, deadline):
    """the speed gate's projection itself (no test whether the gate applies): -> (rec, R, conv) as above; None without a kill time"""
    caps = _gptq_caps()
    if caps is None:
        return None
    hard, ghard = caps
    ex = c.get("exposure") or {}
    cnt = ex.get("counts") or {}
    tot = sum(cnt.values())
    f_text = (sum(v for (h, _), v in cnt.items() if h == 0) / tot) if tot else 1.0 - float(c["cfg"].get("empty_frac", 0.5))
    sref = _GPTQ_REF["K_REF"] * _gptq_cost_units(c["train"], f_text)
    rho = s / sref
    conv = _GPTQ_REF["CONV_S"] * rho * (1.0 + float(CFG.get("dense_gptq_margin", 0.10)))
    h_case = _GPTQ_REF["H_CASE"] * s
    p_min = conv + int(CFG["dense_gptq_min_cases"]) * h_case
    p_full = conv + int(CFG["dense_gptq_cases"]) * h_case
    a0, rmax = ghard - deadline, float(CFG["dense_gptq_reserve_s"])
    rec = {"k": 0, "s_step": round(s, 4), "s_ref": round(sref, 4), "rho": round(rho, 3), "f_text": round(f_text, 4),
           "conv_s": round(conv, 1), "h_case_s": round(h_case, 3), "p_min": round(p_min, 1), "p_full": round(p_full, 1),
           "a0": round(a0, 1), "reserve_max": rmax}
    if p_min > a0 + rmax:
        rec["why"] = f"speed: projected {p_min:.0f}s > {a0 + rmax:.0f}s"
        return rec, None, conv
    return rec, min(rmax, max(0.0, p_full - a0)), conv


def _t159_gptq_commit(c, rec, R, conv, by):
    """record a GPTQ decision made by the planner (the speed gate after member 1 then does nothing): kept -> the deadline moves
    earlier by R; R None -> skipped (dense_ship ships hyb). One private line as the gate's."""
    if R is not None:
        c["deadline"] = c["deadline"] - R
        rec.update(decision="kept", reserve=round(R, 1), deadline_in=round(c["deadline"] - time.time(), 1), by=by)
        _GPTQ_RUN["est"] = conv
        _GPTQ_RUN["gate"] = rec
        log(f"dense: gptq kept ({by}: projected {rec['p_min']:.0f}s <= {rec['a0'] + rec['reserve_max']:.0f}s; x{rec['rho']:.2f} "
            f"the SXM5 reference; reserve {R:.0f}s) {json.dumps(rec)}")
    else:
        why = rec.get("why") or "skipped"
        rec.update(decision="skipped", by=by)
        _GPTQ_RUN["gate"] = rec
        _GPTQ_RUN["off"] = why
        _GPTQ_RUN.pop("est", None)
        log(f"dense: gptq skipped ({by}: {why}) {json.dumps(rec)}")


def _t159_gate_why(c, steps=None, net_s=None):
    """the speed gate is the planner's to decide (G56CT_DENSE=gptq, gate 'speed', not decided yet) but cannot project: the reason
    the gate itself would skip with (_gptq_gate's own checks, in its order); None otherwise (the gate does not apply - e.g. the
    static gate, whose reserve main() committed - or it can project)"""
    if not _gptq_mode() or "gate" in _GPTQ_RUN or str(CFG.get("dense_gptq_gate") or "speed").strip().lower() != "speed":
        return None
    if c.get("fam") != "ideogram4":
        return f"ideogram4 only (family {c.get('fam')})"
    if _gptq_caps() is None:
        return "no kill time recorded"
    if steps is not None and (steps < 20 or not (net_s is not None and net_s > 0 and math.isfinite(net_s))):
        return f"no member-1 timing ({steps} steps)"
    return None


class _T159Safe(object):
    """G56CT_PLANNER=v2safe (and v2 outside its cells): member 1's probe inside v1's train_loop, in the place of the _LrFull probe
    (_kfirst_setup hands it over when no LR / stretch / K-first probe runs; train_loop calls start / reads st_cap / decide exactly
    as for _LrFull). At the probe step it predicts member 1's end at its v1 step cap from the measured s/step; only when that
    end lies later than the deadline stop's cut point less the buffer does it shorten member 1 (cfg max_steps from the next step
    on and, under EXPOSURE, its live case list scaled to the same factor). st_cap stays None: every later member = v1."""
    kfirst = kf_done = False

    def __init__(self, c):
        self.c, self.cfg = c, c["cfg"]
        self.st_cap, self.done, self.t0, self.lats, self.acted = None, False, None, [], False
        self.cap0 = int(self.cfg["max_steps"])
        self.n_bar = _t159_n_bar(c)
        self.P = _t159_probe_step(self.cfg)

    def start(self, t0):
        self.t0 = t0
        if self.P < self.cap0:
            self.c["lr_full_probe"] = self.step
        else:
            self.done = True
            log(f"planner-v2safe: member 1's step cap {self.cap0} <= its probe step {self.P}: the v1 plan")

    def decide(self, d1, how, cut=False):  # train_loop: member 1 ended before the probe step
        if not self.done:
            self.done = True
            self.c["lr_full_probe"] = None
            log(f"planner-v2safe: {how} before its probe step {self.P}; the v1 plan")

    def step(self, step, step_times, lat):
        try:
            self.lats.append(lat)
            if step < self.P:
                return
            self.c["lr_full_probe"] = None
            self.done = True
            self.plan(step, step_times)
        except Exception as e:  # noqa: BLE001  (never ends a member: the v1 cap)
            self.c["lr_full_probe"] = None
            self.done = True
            if not self.acted:
                self.cfg["max_steps"] = self.cap0
            log(f"WARN planner-v2safe: {type(e).__name__}: {str(e)[:160]}; member 1 at {self.cfg['max_steps']} steps")

    def plan(self, step, step_times):
        c, cfg = self.c, self.cfg
        s = lr_full_step_s(step_times, self.lats, self.n_bar, step, first=T159_WARM + 1)
        now = time.time()
        se = int(cfg.get("save_every") or 0)
        n_int = step // se if se > 0 else 0
        t_int = (float(c.get("interim_s", 0.0)) / n_int) if n_int > 0 else T159_INTERIM_PRIOR

        def end1(L):  # member 1's predicted end at step cap L (its interim saves included)
            return now + (L - step) * s + ((L // se - step // se) * t_int if se > 0 else 0.0) + T159_MEMBER_O
        D = c["deadline"]
        cut = D - _t159_stop_margin(c, 0) - s  # where _run_one's deadline stop ends member 1
        b = _t159_buffer([], D - self.t0)
        spare = cut - end1(self.cap0)
        n = len(c["train"])
        if spare >= 0:  # v1's member 1 ends before the deadline stop: v1 exactly (also inside the buffer)
            log(f"planner-v2safe: member 1 fits: {self.cap0} steps ({self.cap0 / max(1, n):.1f}/img) end {spare:.0f}s before the "
                f"deadline stop (s_step {s:.4f}, buffer {b:.0f}s) -> the v1 plan")
            return
        lo = max(step + 1, int(cfg["warmup"]) + 1)
        if end1(lo) + b > cut:
            log(f"planner-v2safe: member 1 does not fit even at {lo} steps (s_step {s:.4f}); the deadline stop decides")
            return
        a_, z_ = lo, self.cap0  # end1(a_) + b <= cut, end1(z_) + b > cut
        while z_ - a_ > 1:
            m_ = (a_ + z_) // 2
            a_, z_ = (m_, z_) if end1(m_) + b <= cut else (a_, m_)
        L = a_
        f, steps, how = L / self.cap0, L, f"step cap {self.cap0} -> {L}"
        exs = _t159_live_exposure(c, self.cap0)
        if exs is not None:
            f, cnt, steps = t159_scale(exposure_cells(c["exposure"]["spec"], cfg["bands"]), n, L)
            steps = exs.t159_resize(cnt)
            how = f"exposure x{f:.4f}: {steps} cases ({exposure_text(exs.counts, cfg['bands'])})"
        cfg["max_steps"] = steps
        self.acted = True
        g = _t159_gptq_rec(c, s, D)
        if g is not None:
            g[0]["why"] = f"member 1 shortened to {steps} of {self.cap0} steps to end before the deadline stop"
            _t159_gptq_commit(c, g[0], None, g[2], "planner-v2safe")
        log(f"planner-v2safe: member 1 shortened: {how} ({steps / max(1, n):.1f}/img, f {f:.3f}; at {self.cap0} steps the deadline "
            f"stop would cut it {-spare:.0f}s early; now it ends {b:.0f}s (buffer) before that stop; s_step {s:.4f}, interim "
            f"{f'{t_int:.1f}s/save' if se > 0 else '-'}, stop margin {D - cut - s:.0f}s)")


_kfirst_setup_t159 = _kfirst_setup


def _t159_kfirst_setup(c, lrf):
    """_kfirst_setup, then (G56CT_PLANNER v2safe / v2 outside its cells) member 1's planner probe when no other probe runs"""
    lrf = _kfirst_setup_t159(c, lrf)
    if c.get("t159_safe") and c.get("t159_safe_obj") is None:
        if lrf is not None:
            log("planner-v2safe: off (LR_MIN_FULL / STRETCH_MAX / KFIRST_K plan member 1 themselves); the v1 plan")
            return lrf
        c["t159_safe_obj"] = _T159Safe(c)
        return c["t159_safe_obj"]
    return lrf


_kfirst_setup = _t159_kfirst_setup  # noqa: F811  (T159: train_loop calls it by name; without the planner flag: the function itself)


class _T159Plan(object):
    """G56CT_PLANNER=v2 in a v2 cell: the plan of one training run (pure Python: arithmetic on measured seconds, no probe run,
    no extra save). Times: member m's training = o + L x u (u = its seconds per step), the running-average write after member m
    = W(m), the last member K stops at max(15 s, the measured save margin x 1) + a step before the deadline, minus the buffer."""

    def __init__(self, c, cell):
        cfg = c["cfg"]
        self.c, self.cfg, self.cell = c, cfg, cell
        self.fam = c.get("fam") or _T157.get("fam")
        self.n = len(c["train"])
        self.cap0 = int(cfg["max_steps"])  # the base length (after exposure_setup: the table's cases)
        self.f_max = float(cell[1])
        ex = c.get("exposure")
        self.cells = exposure_cells(ex["spec"], cfg["bands"]) if ex is not None else None
        self.base_counts = dict(ex["counts"]) if ex is not None else None
        slots, fill_only = _t126_kplan(c)
        self.k_cap = max(1, int(slots) - (1 if fill_only else 0))
        if self.k_cap > int(cfg["seeds_auto"]):  # K beyond SEEDS_AUTO (PLAN_FILL_KMAX): never a file above 8.4 GB (T160 sec. 3.6)
            per_b = 4 if (cfg.get("save_fp32", True) and not CFG.get("save_bf16")) else 2  # the shipped bytes per value (BF16 / F32)
            mb = sum(int(p.numel()) for p in c["params"]) * per_b
            if mb > 0:
                tot = max(1, int((T159_FILE_CAP_GB * 1e9 - _t126_fixed_bytes(c, mb)) // mb))
                if tot < self.k_cap:
                    log(f"planner-v2: file cap {tot} member(s) ({mb / 1e9:.2f} GB each, {T159_FILE_CAP_GB:g} GB) below {self.k_cap} slots")
                    self.k_cap = max(1, tot)
        self.K, self.L, self.planned, self.t0, self.lats = None, self.cap0, False, None, []
        self.n_bar = _t159_n_bar(c)
        self.se = int(cfg.get("save_every") or 0)
        self.P = _t159_probe_step(cfg)
        self.members, self.writes, self.plans, self.brakes, self.g_kept, self.g_fail = [], [], [], [], False, 0
        self.cur_times, self.cur_lats, self.s_probe = None, [], None  # the running member's step times (track / brake / probe)
        self.D0, self.u, self.o = None, None, T159_MEMBER_O
        pr = T159_WRITE_PRIOR.get(self.fam)
        self.shape = (pr[2], pr[3]) if pr else (0.0, 1.0)
        self.prior = pr

    # ---- the time model
    def write_s(self, k):
        """seconds of the running-average write after member k: the measured writes scaled by the family's shape a + b k (the
        largest such estimate); before any measurement the a priori write (or the identity write's rate), whichever is larger"""
        a, b = self.shape
        if self.writes:
            return max(w * (a + b * k) / max(1e-9, a + b * (i + 1)) for i, w in enumerate(self.writes))
        spb = _SAVE_STATS.get("spb", 0.0) * self.c.get("member_bytes", 0) * k
        return max(spb, a + b * k if self.prior else 0.0)

    def m_stop(self, K):
        """member K's stop margin + one step: _run_one's formula (k_done = K - 1) on the save statistics it will hold when member K
        runs - the canonical-form reference then is the (K-1)-member write's (its seconds linear in k: T126 sec. 2b 2.6 / 5.1 / 7.7 s
        for ideogram4), and before any measured member write the a priori 1-member write (the identity write is no measure of a
        member's). _SAVE_STATS is restored exactly."""
        c, st = self.c, _SAVE_STATS
        saved = dict(st)
        try:
            mb, mu = c.get("member_bytes", 0), c.get("member_units", 0)
            if not self.writes and self.prior and mb > 0:
                w1, c1 = self.prior[0], self.prior[1]
                st["spb"] = max(st.get("spb", 0.0), max(0.0, w1 - c1) / mb)
                if c1 > 0 and mu > 0 and K >= 2:
                    st["canon_ref"] = ((K - 1) ** 2 * mu, c1 * (K - 1))
            elif st.get("canon_ref") and mu > 0 and K >= 2:
                u, t = st["canon_ref"]
                k_ref = math.sqrt(max(u, 1e-12) / mu)
                if K - 1 > k_ref + 1e-9:
                    st["canon_ref"] = ((K - 1) ** 2 * mu, t / k_ref * (K - 1))
            m = _t159_stop_margin(c, K - 1)
        finally:
            st.clear()
            st.update(saved)
        return m + (self.u or 0.0)

    def need(self, K, L, j, cur):
        """seconds from now until member K's training ends, members j+1..K at L steps (cur: member j+1 in progress at the probe:
        dict(P, s, t_int))"""
        t = 0.0
        for m in range(j + 1, K + 1):
            if cur is not None and m == j + 1:
                t += (L - cur["P"]) * cur["s"] + self.o
                if self.se > 0:
                    t += (L // self.se - cur["P"] // self.se) * cur["t_int"]
            else:
                t += self.o + L * self.u
            if m < K:
                t += self.write_s(m)
        return t

    def avail(self, now, D, K):
        return D - now - self.m_stop(K) - self.buffer(D)

    def buffer(self, D):
        return _t159_buffer(self.writes, (self.D0 if self.D0 is not None else D) - (self.t0 if self.t0 is not None else time.time()))

    def fit(self, now, D, j, cur, k_max, tol=0.0):
        """the most members j+1..K (K <= k_max) that fit at the base length (their time x (1 + tol)) -> K (j when none)"""
        K = j
        for k in range(j + 1, k_max + 1):
            if self.need(k, self.cap0, j, cur) * (1.0 + tol) <= self.avail(now, D, k):
                K = k
            else:
                break
        return K

    def length(self, now, D, K, j, cur):
        """the longest equal length in [cap0, f_max x cap0] at which members j+1..K end in time (cap0 when only that fits)"""
        a_, z_ = self.cap0, int(math.floor(self.f_max * self.cap0 + 1e-9))
        if self.need(K, z_, j, cur) <= self.avail(now, D, K):
            return z_
        while z_ - a_ > 1:
            m_ = (a_ + z_) // 2
            a_, z_ = (m_, z_) if self.need(K, m_, j, cur) <= self.avail(now, D, K) else (a_, m_)
        return a_

    def realize(self, L):
        """steps (EXPOSURE: the case total of the largest factor whose total <= L) and counts of a member planned at L steps"""
        if self.cells is None:
            return L, None, L / self.cap0
        f, cnt, tot = t159_scale(self.cells, self.n, L)
        return tot, cnt, f

    def fit_frac(self, now, D, K, j, cur):
        """the real-valued number of base-length members the time holds (log only)"""
        spare = self.avail(now, D, K) - self.need(K, self.cap0, j, cur)
        per = self.o + self.cap0 * self.u + self.write_s(K)
        return K + max(0.0, spare) / max(1e-9, per) if K > j else j + spare / max(1e-9, per)

    # ---- the plan points
    def arm(self, t0):
        self.t0 = t0
        self.D0 = self.c["deadline"]
        self.cur_times, self.cur_lats = None, self.lats
        if self.P < self.cap0:
            self.c["lr_full_probe"] = self.probe
        else:
            log(f"planner-v2: member 1's step cap {self.cap0} <= its probe step {self.P}: planned after member 1")

    def probe(self, step, step_times, lat):
        try:
            self.lats.append(lat)
            self.cur_times = step_times
            if step < self.P:
                return
            self.c["lr_full_probe"] = None
            self.plan1(step, step_times)
        except Exception as e:  # noqa: BLE001  (never ends a member: the base cap, planned after member 1)
            self.g_kept = self.D0 is not None and self.c["deadline"] < self.D0  # a reserve kept before the problem: the brake
            self.c["lr_full_probe"] = self.brake if self.g_kept else self.track
            if not self.planned:
                self.cfg["max_steps"] = self.cap0
            log(f"WARN planner-v2: {type(e).__name__}: {str(e)[:160]}; member 1 at {self.cfg['max_steps']} steps (planned after it)")

    def plan1(self, step, step_times):
        """member 1's probe step: the GPTQ reserve, K, the members' length - member 1's cap from the next step on"""
        c, cfg = self.c, self.cfg
        s = lr_full_step_s(step_times, self.lats, self.n_bar, step, first=T159_WARM + 1)
        now = time.time()
        n_int = step // self.se if self.se > 0 else 0
        t_int = (float(c.get("interim_s", 0.0)) / n_int) if n_int > 0 else T159_INTERIM_PRIOR
        self.u = s
        # every later member repeats member 1's start (its first WARM steps above the steady s/step): + that per member
        self.o = T159_MEMBER_O + max(0.0, sum(step_times[:T159_WARM]) - T159_WARM * s)
        cur = {"P": step, "s": s, "t_int": t_int}
        D0 = c["deadline"]
        k_hyb = self.fit(now, D0, 0, cur, self.k_cap, T159_K_TOL)
        g, R, gtag = _t159_gptq_rec(c, s, D0), 0.0, "-"
        if g is not None:
            rec, r_full, conv = g
            if r_full is not None:
                k_full = self.fit(now, D0 - r_full, 0, cur, self.k_cap, T159_K_TOL)
                if k_full >= max(1, k_hyb):
                    R, gtag = r_full, f"kept {r_full:.0f}s"
                    _t159_gptq_commit(c, rec, r_full, conv, "planner-v2")
                else:
                    rec["why"] = f"the reserve {r_full:.0f}s would cost a member (K {k_hyb} -> {k_full}): hyb"
                    gtag = "hyb (member)"
                    _t159_gptq_commit(c, rec, None, conv, "planner-v2")
            else:
                gtag = "hyb (speed)"
                _t159_gptq_commit(c, rec, None, conv, "planner-v2")
        elif _t159_gate_why(c) is not None:  # the gate cannot project here: it skips, as the speed gate would after member 1
            gtag = "hyb (gate)"
            _t159_gptq_commit(c, {"k": 0, "why": _t159_gate_why(c)}, None, 0.0, "planner-v2")
        D = c["deadline"]
        K = self.fit(now, D, 0, cur, self.k_cap, T159_K_TOL)
        if K >= 1:
            L = self.length(now, D, K, 0, cur)
        else:  # not even one base-length member: member 1 alone, shortened to end in time (v2safe's rule)
            K, L = 1, self.cap0
            lo = max(step + 1, int(cfg["warmup"]) + 1)
            if self.need(1, lo, 0, cur) <= self.avail(now, D, 1):
                a_, z_ = lo, self.cap0
                while z_ - a_ > 1:
                    m_ = (a_ + z_) // 2
                    a_, z_ = (m_, z_) if self.need(1, m_, 0, cur) <= self.avail(now, D, 1) else (a_, m_)
                L = a_
        steps, cnt, f = self.realize(L)
        exs = _t159_live_exposure(c, self.cap0)
        if exs is not None:
            steps = exs.t159_resize(cnt)
        cfg["max_steps"] = steps
        self.K, self.L, self.planned = K, steps, True
        self.log_plan(1, now, D0, D, K, steps, f, 0, cur, f"member 1 step {step}", gtag)
        self.s_probe = s
        if c["deadline"] < self.D0:  # the GPTQ reserve moved the deadline under member 1: member 1 follows it (brake)
            self.g_kept = True
            c["lr_full_probe"] = self.brake
        else:  # member 1's step times for the re-plan after it
            c["lr_full_probe"] = self.track

    def track(self, step, step_times, lat):
        """members without the brake: their step times (the re-plan after a member reads its recent s/step)"""
        self.cur_times = step_times
        self.cur_lats.append(lat)

    def brake(self, step, step_times, lat):
        """member 1 after its probe kept a GPTQ reserve: the deadline moved earlier while member 1 runs, and its _run_one still
        stops at the deadline it started with - so here, every step, the deadline stop's rule on c['deadline'] as it is now, as
        v2safe's shortening: when member 1's predicted end at its cap (s/step over its last T159_BRAKE_WIN steps, its interim
        saves at their measured seconds) passes that deadline's cut point (the stop margin member 1's own running-average write
        needs, should it end as the last member), its cap (under EXPOSURE its live case list too) becomes the longest that ends
        the buffer before that point - its cosine still reaches the floor and the reserve stays whole; when the node is fast
        again, the cap grows back toward the plan (by >= T159_RELEASE, or to the plan itself) as far as it ends the buffer before
        that point. While the reserve stands, the gate's own projection is redone at member 1's mean s/step so far and at its
        last-100 s/step: once both fail it for T159_GPTQ_PERSIST consecutive steps, GPTQ is skipped (hyb) and the deadline goes
        back; member 1 gets its planned length back, the brake then aims at that deadline. Every step's time counts at most
        T159_SPIKE_X x the probe's (its latent's share). Never raises (a problem: the brake off, member 1 keeps its cap)."""
        c, cfg = self.c, self.cfg
        try:
            self.lats.append(lat)
            self.cur_times = step_times
            cap0 = cap = int(cfg["max_steps"])
            if step >= cap:
                return
            sref = float(self.u or 0.0)
            s = _t159_step_s(step_times, self.lats, self.n_bar, step, max(T159_WARM + 1, step - T159_BRAKE_WIN + 1), sref)
            if self.g_kept:
                s_all = _t159_step_s(step_times, self.lats, self.n_bar, step, T159_WARM + 1, sref)
                g = _t159_gptq_proj(c, s_all, self.D0) if s_all and s_all > 0 else None
                g2 = _t159_gptq_proj(c, s, self.D0) if s and s > 0 else None
                fail = g is not None and g[1] is None and g2 is not None and g2[1] is None
                self.g_fail = self.g_fail + 1 if fail else 0
                if self.g_fail >= T159_GPTQ_PERSIST:  # GPTQ no longer fits at the measured speed (persistently): hyb, deadline back
                    self.g_kept = False
                    moved = self.D0 - c["deadline"]
                    c["deadline"] = self.D0
                    g[0]["why"] = (f"{g[0].get('why')} at member 1 step {step} (its s/step {s_all:.4f} so far, {s:.4f} over the last "
                                   f"{min(T159_BRAKE_WIN, step - T159_WARM)} steps, for {self.g_fail} steps)")
                    _t159_gptq_commit(c, g[0], None, g[2], "planner-v2 re-check")
                    cap = max(cap, int(self.L))  # the brake's shortening for that reserve undone (the brake below aims at D0)
                    self.brakes.append({"step": step, "gptq": "skipped", "deadline_back_s": round(moved, 1)})
                    log(f"planner-v2: member 1 step {step}: GPTQ no longer fits at its measured speed -> hyb, the deadline "
                        f"{moved:.0f}s later again; member 1 may run up to its planned {cap} steps again, the brake on that deadline")
            L, over, stop, b, D, grow = cap, 0.0, 0.0, 0.0, c["deadline"], False
            if s and s > 0:
                now, se, Lp = time.time(), self.se, max(cap, int(self.L))
                n_done = (step - 1) // se if se > 0 else 0  # this step's own interim save comes after this hook
                t_int = (float(c.get("interim_s", 0.0)) / n_done) if n_done > 0 else T159_INTERIM_PRIOR

                def end1(L_):  # member 1's predicted end at step cap L_
                    return now + (L_ - step) * s + ((L_ // se - n_done) * t_int if se > 0 else 0.0) + T159_MEMBER_O
                # member 1 may end as the last member: the stop margin its own running-average write will need (the plan's
                # m_stop(1), a priori before any member write was measured) when that is above the margin _run_one holds now
                stop = max(_t159_stop_margin(c, 0), self.m_stop(1) - sref)
                cut = D - stop - s
                b = self.buffer(D)

                def fit(hi):  # the longest cap in [step, hi] that ends the buffer before the cut (step itself when none does)
                    a_, z_ = step, hi
                    if end1(z_) + b <= cut:
                        return z_
                    if end1(a_) + b > cut:
                        return a_
                    while z_ - a_ > 1:
                        m_ = (a_ + z_) // 2
                        a_, z_ = (m_, z_) if end1(m_) + b <= cut else (a_, m_)
                    return a_
                over = end1(cap) - cut
                if over > 0:
                    L = fit(cap)
                elif cap < Lp:  # the node is fast again: the cap back toward the plan (>= T159_RELEASE more, or the plan itself;
                    Lf = fit(Lp)  # the buffer between 'past the cut' and 'a buffer before it' keeps the two from alternating)
                    if Lf == Lp or Lf >= cap * (1.0 + T159_RELEASE):
                        L, grow = Lf, True
            if L == cap0:
                return
            steps = L
            exs = _t159_live_exposure(c, self.cap0)
            if exs is not None and self.cells is not None:
                steps = exs.t159_resize(t159_scale(self.cells, self.n, L)[1])
            cfg["max_steps"] = steps
            if over > 0 or grow:
                which = (f"the deadline the GPTQ reserve moved, {self.D0 - D:.0f}s earlier" if D < self.D0 else "the deadline")
                self.brakes.append({"step": step, "from": cap, "to": steps, "over": round(over, 1), "s_step": round(s, 4),
                                    "stop": round(stop, 1), "grow": grow})
                log((f"planner-v2: brake at member 1 step {step}: at {cap} steps it would end {over:.0f}s past the deadline stop "
                     if not grow else f"planner-v2: brake release at member 1 step {step}: the node is fast again, {cap} steps "
                     f"back toward its planned {int(self.L)} ")
                    + f"({which}) -> {steps} steps ({steps / max(1, self.n):.1f}/img, s_step {s:.4f} over its last "
                    f"{min(T159_BRAKE_WIN, step - T159_WARM)} steps, stop {stop:.0f}s, buffer {b:.0f}s)")
        except Exception as e:  # noqa: BLE001  (never ends a member: its cap as it is)
            c["lr_full_probe"] = None
            log(f"WARN planner-v2: brake: {type(e).__name__}: {str(e)[:160]}; member 1 keeps {cfg['max_steps']} steps")

    def gptq_late(self, r, net_s):
        """member 1 ended before its probe step (no plan yet): the dense GPTQ reserve from member 1's net seconds per step, as the
        speed gate after member 1 would decide it (a member cut below its cap or abandoned: skipped), kept only when it costs no
        member of the plan that follows (else hyb). Never raises (a problem: GPTQ skipped, one private line)."""
        c = self.c
        if self.planned or "gate" in _GPTQ_RUN:
            return
        try:
            steps = int(r.get("steps") or 0)
            why = _t159_gate_why(c, steps, net_s)
            g = _t159_gptq_rec(c, net_s / max(1, steps), c["deadline"]) if why is None else None
            if g is None:  # the gate cannot project (why): skipped as the gate itself would; else it does not apply (static: v1)
                if why is not None:
                    _t159_gptq_commit(c, {"k": 0, "why": why}, None, 0.0, "planner-v2")
                return
            rec, r_full, conv = g
            if steps < self.cap0 or r.get("abandoned"):
                rec["why"] = f"member 1 ended at {steps} of {self.cap0} steps (deadline / SAFE)"
                r_full = None
            if r_full is not None:
                self.u, self.o = max(1e-6, net_s / steps), 0.0
                now = time.time()
                k_hyb = self.fit(now, c["deadline"], 1, None, self.k_cap)
                k_full = self.fit(now, c["deadline"] - r_full, 1, None, self.k_cap)
                if k_full < k_hyb:
                    rec["why"] = f"the reserve {r_full:.0f}s would cost a member (K {k_hyb} -> {k_full}): hyb"
                    r_full = None
            _t159_gptq_commit(c, rec, r_full, conv, "planner-v2")
        except Exception as e:  # noqa: BLE001  (never ends a run: no GPTQ, hyb ships)
            _GPTQ_RUN["off"] = f"planner-v2: {type(e).__name__}: {str(e)[:120]}"
            _GPTQ_RUN.setdefault("gate", {"decision": "skipped", "why": _GPTQ_RUN["off"]})
            log(f"WARN planner-v2: GPTQ decision after member 1: {type(e).__name__}: {str(e)[:120]}; gptq skipped (hyb)")

    def replan(self, j):
        """after member j (its write done): the remaining members' equal length (0: stop); K drops while the rest no longer fits at
        the base length; not planned yet (member 1 ended before its probe step): K from the measured members. Never raises: a
        problem stops the ensemble (one private WARN line; the running average on disk is shipped)."""
        try:
            return self._replan(j)
        except Exception as e:  # noqa: BLE001
            log(f"WARN planner-v2: re-plan after member {j}: {type(e).__name__}: {str(e)[:160]}; no further member")
            self.K = j
            return 0

    def _replan(self, j):
        c = self.c
        now, D = time.time(), c["deadline"]
        if self.K is not None and j >= self.K:  # the planned members are done
            self.plans.append({"plan": len(self.plans) + 1, "after": j, "K": j, "stop": True})
            log(f"planner-v2: the {j} planned member(s) done ({D - now:.0f}s left)")
            return 0
        k_max = self.K if self.K is not None else self.k_cap
        K = min(k_max, self.fit(now, D, j, None, k_max))
        if K <= j:
            self.K = j
            self.plans.append({"plan": len(self.plans) + 1, "after": j, "K": j, "stop": True})
            log(f"planner-v2: after member {j}: no further member fits at the base length {self.cap0} "
                f"({self.cap0 / max(1, self.n):.1f}/img; {D - now:.0f}s left) -> K={j}")
            return 0
        L = self.length(now, D, K, j, None)
        if K == self.K and self.L and self.L <= L < self.L * (1.0 + T159_GROW):  # the planned length still fits: kept (equal)
            L = self.L
        steps, cnt, f = self.realize(L)
        self.K, self.L = K, steps
        self.log_plan(len(self.plans) + 1, now, D, D, K, steps, f, j, None, f"after member {j}", "-")
        return steps

    def log_plan(self, no, now, D0, D, K, steps, f, j, cur, at, gtag):
        n = max(1, self.n)
        fit = self.fit_frac(now, D, K, j, cur)
        writes = sum(self.write_s(m) for m in range(j + 1, K))
        stop, b = self.m_stop(K), self.buffer(D)
        reserve = (D0 - D) + stop + b + writes
        rec = {"plan": no, "at": at, "K": K, "steps": steps, "f": round(f, 4), "fit": round(fit, 2), "s_step": round(self.u, 4),
               "avail": round(D0 - now, 1), "reserve": round(reserve, 1), "buffer": round(b, 1), "stop": round(stop, 1),
               "writes": round(writes, 1), "gptq": gtag, "after": j}
        self.plans.append(rec)
        log(f"planner-v2: K={K} L={steps / n:.1f}/img (fit {fit:.2f} at {self.cap0 / n:.1f}/img, s_step {self.u:.3f}, avail "
            f"{D0 - now:.0f}s, reserve {reserve:.0f}s) plan {no} at {at}: {steps} steps x {K - j} member(s) (f {f:.3f}, base "
            f"{self.cap0}), buffer {b:.0f}s, stop {stop:.0f}s, writes {writes:.0f}s, gptq {gtag}")

    # ---- member boundaries
    def begin(self, k):
        """cfg max_steps / the exposure counts member k + 1 starts with (member 1: the base, its probe may change it); members 2+
        record their step times (track)"""
        c, cfg = self.c, self.cfg
        L = self.cap0 if k == 0 else self.L
        _T159["exs"] = None
        if k > 0:
            self.cur_times, self.cur_lats = None, []
            c["lr_full_probe"] = self.track
        if self.cells is not None:
            if k == 0 or L == self.cap0:
                cnt = dict(self.base_counts)
            else:
                cnt = self.realize(L)[1]
            c["exposure"]["counts"], c["exposure"]["total"] = cnt, sum(cnt.values())
            L = c["exposure"]["total"]
        cfg["max_steps"] = L
        return L

    def end(self, k):
        c, cfg = self.c, self.cfg
        cfg["max_steps"] = self.cap0
        if self.cells is not None:
            c["exposure"]["counts"], c["exposure"]["total"] = dict(self.base_counts), sum(self.base_counts.values())

    def done(self, k, r, d, interim, w):
        steps = int(r.get("steps") or 0)
        self.members.append({"steps": steps, "seconds": round(d, 1), "interim": round(interim, 1), "write": round(w, 2)})
        self.writes.append(w)
        if steps >= 1:
            u, o = max(1e-6, (d - interim) / steps), 0.0  # measured wall per step (the member's own overhead folded in)
            ts, ls = self.cur_times, self.cur_lats
            if ts is not None and len(ts) == steps and len(ls) == steps:
                # the next members' speed: the member's RECENT speed, robustly (_t159_block_s: the median of its last 5 blocks of
                # 40 steps) - a node that slowed late plans the rest at its new speed, a burst or a spike anywhere is ignored;
                # o = its seconds outside the steps + its first WARM steps above that speed (plan1's member model)
                tr = _t159_block_s(ts, ls, self.n_bar, steps)
                if tr and tr > 0:
                    u = tr
                    o = max(0.0, d - interim - sum(ts)) + max(0.0, sum(ts[:T159_WARM]) - T159_WARM * tr)
                    self.members[-1]["s_step"] = round(tr, 4)
            self.u, self.o = max(1e-6, u), o
            self.cur_times = None


def _t159_v2_loop(c, model_wrap, conds, extra_args, device, cell):
    """G56CT_PLANNER=v2 in a v2 cell: train_loop's seeds-auto ensemble with the v2 plan (_T159Plan). The lines before the members
    are train_loop's own; the members run _run_one as there; SAFE's running average after every member; the same log lines."""
    cfg = c["cfg"]
    if c.get("te"):
        c.setdefault("te_placeholder", conds[c["te_slots"][0]])
    if cfg["fast_lora"]:
        fast_lora_guard(c, model_wrap, conds, extra_args, device)
    if cfg["spec_init"] and "spec_ranked" not in c:
        c["spec_ranked"] = spectral_down_init(c, model_wrap, conds, extra_args, device)
        apply_spectral(c, 0)
    if cfg.get("gc_keep"): gc_keep_setup(c, model_wrap, conds, extra_args, device)  # noqa: E701  T252: G56CT_GC_KEEP as train_loop (before the cache probe, member 1)
    if cfg["fast_lora"] and (cfg.get("fast_wcache") or cfg.get("fast_mcache")): fast_mem_probe(c, model_wrap, conds, extra_args, device)  # noqa: E701
    c["member_bytes"] = sum(p.numel() for p in c["params"]) * (4 if cfg["save_fp32"] else 2)
    if cfg.get("canon"):
        c["member_units"] = canon_units(c["adapters"])
    exposure_setup(c)
    empty_band_lr_setup(c)
    text_band_lr_setup(c)
    c["multi"] = True
    ens = _SafeEnsemble(c, cfg["final_scale"])
    if cfg.get("lr_pilot"):
        lr_pilot_select(c, model_wrap, conds, extra_args, device)
    pl = (_T252Plan if cfg.get("gc_keep") else _T159Plan)(c, cell)  # T252: GC_KEEP set -> its OOM drop priced as v1 (the T252 block)
    c["planner_v2"] = pl
    runs = []
    for k in range(pl.k_cap):
        c["k_done"] = len(ens.sds)
        if k > 0:
            if not pl.replan(k):
                log(f"seeds-auto: stop after {k} member(s) (planner-v2: K={pl.K}, {c['deadline'] - time.time():.0f}s left)")
                break
            reinit_adapters(c, cfg["seed"] + 1000 * k, k)
        pl.begin(k)
        t0m = time.time()
        if k == 0:
            pl.arm(t0m)
        try:
            r = _run_one(c, model_wrap, conds, extra_args, device, cfg["seed"] + 1000 * k, c["deadline"], k)
            if k == 0:  # the probe did not run (member 1 shorter than its probe step): the planner's GPTQ decision now
                pl.gptq_late(r, time.time() - t0m - float(c.get("interim_s", 0.0)))
        finally:
            c["lr_full_probe"] = None
            planned = cfg["max_steps"]
            pl.end(k)
        d = time.time() - t0m
        interim = float(c.pop("interim_s", 0.0))
        runs.append(r)
        tw = time.time()
        ens.add(r, k)
        pl.done(k, r, d, interim, time.time() - tw)
        if r["steps"] < planned:
            log(f"planner-v2: member {k + 1} ended at {r['steps']} of its {planned} planned steps (deadline stop / SAFE)")
        if cfg["save_runs"] and r.get("best_sd") is not None:
            from safetensors.torch import save_file
            save_file(fg_inject(r["best_sd"]), str(side_dir(c) / f"run{k}.safetensors"))
        log(f"seeds-auto: member {k + 1} done in {d:.0f}s ({r['steps']} steps)")
    sd, n_avg = ens.final(), len(ens.members())
    log(f"seeds-auto: shipped the exact average of {n_avg} member(s), scale {cfg['final_scale']:g}")
    if cfg["rrf"]:
        sd = rrf_finalize(c, model_wrap, conds, extra_args, device, sd, sum(r["step_time"] for r in runs) / len(runs))
    return {"steps": sum(r["steps"] for r in runs), "evals": [], "best": {"score": None, "tag": f"auto_avg{n_avg}"},
            "best_sd": sd, "base": None, "step_time": sum(r["step_time"] for r in runs) / len(runs), "runs": len(runs),
            "planner": {"mode": "v2", "plans": pl.plans, "members": pl.members, "brakes": pl.brakes}}


def _t159_off_reason(c, mode):
    """why the planner (v2safe / v2) cannot act on this run (None: it can)"""
    cfg = c["cfg"]
    if c["holdout"] or cfg["seeds_auto"] <= 1:
        return "not the seeds-auto ensemble"
    if cfg["max_steps"] <= 0:
        return "no step cap: the members are time-bound"
    return None


def _t159_v2_off(c):
    """why the v2 loop cannot run on a v2 cell (None: it can)"""
    cfg = c["cfg"]
    if not cfg.get("safe"):
        return "needs G56CT_SAFE"
    if cfg.get("compile_blocks"):
        return "COMPILE_BLOCKS"
    if cfg.get("lr_min_full", 0) > 0 or cfg.get("kfirst_k", 0) > 0 or cfg.get("stretch_max", 0.0) > 1.0:
        return "LR_MIN_FULL / KFIRST_K / STRETCH_MAX plan member 1 themselves"
    if cfg.get("member_lr_mults"):
        return "MEMBER_LR_MULTS (research knob; the v1 loop runs it)"
    if os.environ.get("G56CT_MAX_STEPS", "").strip() not in ("", "0"):  # exposure_setup's own test of a fixed length
        return "an explicit G56CT_MAX_STEPS fixes the members' length"
    return None


_train_loop_t159 = train_loop


def _t159_train_loop(c, model_wrap, conds, extra_args, device):
    """train_loop with G56CT_PLANNER (v1: train_loop itself) and the TEST-ONLY G56CT_EMULATE_SLOWDOWN"""
    cfg = c["cfg"]
    if _t159_slow_setup(cfg):  # G56CT_EMULATE_SLOWDOWN (TEST ONLY): no step open around training (a skipped last step left one)
        _T159.pop("step_t0", None)
        try:
            return _t159_train_loop_planned(c, model_wrap, conds, extra_args, device)
        finally:
            _T159.pop("step_t0", None)
    return _t159_train_loop_planned(c, model_wrap, conds, extra_args, device)


def _t159_train_loop_planned(c, model_wrap, conds, extra_args, device):
    """G56CT_PLANNER: v1 -> train_loop itself; v2safe -> train_loop with member 1's probe; v2 -> the v2 loop in a v2 cell"""
    cfg = c["cfg"]
    mode = _t159_mode(cfg)
    if mode == "v1":
        return _train_loop_t159(c, model_wrap, conds, extra_args, device)
    why = _t159_off_reason(c, mode)
    if why is not None:
        log(f"planner-{mode}: off ({why}); planner v1")
        return _train_loop_t159(c, model_wrap, conds, extra_args, device)
    gx, saved = globals()["Exposure"], {}
    globals()["Exposure"] = _T159Exposure
    try:
        if mode == "v2":
            fam, n = c.get("fam") or _T157.get("fam"), len(c["train"])
            try:
                cells = t159_cells(cfg.get("planner_cells", T159_CELLS_DEFAULT))
            except ValueError as e:
                cells = {}
                log(f"WARN planner-v2: G56CT_PLANNER_CELLS {cfg.get('planner_cells')!r}: {e}; no v2 cell")
            cell = cells.get(fam)
            off = (f"{fam} is not a v2 cell ({', '.join(sorted(cells)) or 'none'})" if cell is None
                   else f"{fam} N {n} < {cell[0]}" if n < cell[0] else _t159_v2_off(c))
            if off is None:
                for k_, v_, e_ in (("stop_margin_s", T159_STOP_FLOOR, "G56CT_STOP_MARGIN_S"),
                                   ("save_margin_x", T159_SAVE_X, "G56CT_SAVE_MARGIN_X")):
                    if os.environ.get(e_) in (None, ""):
                        saved[k_] = CFG.get(k_)
                        CFG[k_] = v_
                log(f"planner-v2: on ({fam} N {n}, cell min N {cell[0]}, max length x{cell[1]:g}; stop margin "
                    f"{CFG.get('stop_margin_s')}, save margin x{CFG.get('save_margin_x')})")
                return _t159_v2_loop(c, model_wrap, conds, extra_args, device, cell)
            log(f"planner-v2: {off}: the v2safe rules")
        c["t159_safe"] = True
        res = _train_loop_t159(c, model_wrap, conds, extra_args, device)
        obj = c.get("t159_safe_obj")
        if isinstance(res, dict) and obj is not None:
            res["planner"] = {"mode": "v2safe", "acted": bool(obj.acted)}
        return res
    finally:
        globals()["Exposure"] = gx
        for k_, v_ in saved.items():
            CFG[k_] = v_
        c.pop("t159_safe", None)
        c.pop("t159_safe_obj", None)
        _T159["exs"] = None


train_loop = _t159_train_loop  # noqa: F811  (T159: Loop.sample calls it by name; G56CT_PLANNER v1 -> the function above itself)


# ---- G56CT_EMULATE_SLOWDOWN (TEST ONLY): every wrapper below is installed by _t159_slow_setup only (knob off: none at all)
T159_SLOW_DN = ("cache_w0", "w0_exact", "round_feasible", "_check_lokr", "_gptq_pass1", "gptq_factor", "_gptq_targets", "gptq_round")


def t159_slow_factor(raw):
    """G56CT_EMULATE_SLOWDOWN value -> (factor, None), (None, None) for '' / off, (None, why) when rejected (not 1 <= F <= 3)"""
    v = str(raw or "").strip()
    if v.lower() in ("", "off", "none"):
        return None, None
    try:
        f = float(v)
    except ValueError:
        return None, f"{v!r} is not a number"
    if not (math.isfinite(f) and 1.0 <= f <= 3.0):
        return None, f"{v!r} outside 1..3"
    return f, None


def _t159_sleep(seconds):
    if seconds > 0:
        time.sleep(seconds)


def _t159_sync():
    try:
        import torch
        if torch.cuda.is_available():
            torch.cuda.synchronize()
    except Exception:  # noqa: BLE001
        pass


def _t159_slowed(fn):
    """fn taking F x its wall time (sleep (F - 1) x the measured seconds right after it, the GPU synchronised first)"""
    def run(*a, **k):
        f = _T159.get("slow")
        if not f or f <= 1.0:
            return fn(*a, **k)
        t0 = time.time()
        try:
            return fn(*a, **k)
        finally:
            _t159_sync()
            _t159_sleep((f - 1.0) * (time.time() - t0))
    run.__doc__, run._t159_orig = fn.__doc__, fn
    return run


def _t159_slow_step_close():
    """the end of an optimizer step (the emulation's AdamW.step): sleep (F - 1) x the step's seconds since its start (the
    stretch_tail_step call _run_one makes first in every step attempt), inside the step's own timing (step_times)"""
    f, t0 = _T159.get("slow"), _T159.pop("step_t0", None)
    if f and f > 1.0 and t0 is not None:
        _t159_sync()
        _t159_sleep((f - 1.0) * (time.time() - t0))


def _t159_slow_wrappers():
    """{global name: wrapper} of the emulation (installed by _t159_slow_setup)"""
    tail, pred = globals()["stretch_tail_step"], globals()["predict"]

    def stretch_tail_step_(c, step, band_pool, cases, acc_groups, tail_on):  # every training step attempt's first call
        _T159["step_t0"] = time.time()
        return tail(c, step, band_pool, cases, acc_groups, tail_on)

    def predict_(model_wrap, conds, cond_idx, x, sigma_value, extra_args):  # a forward outside a step: F x its own seconds
        if _T159.get("step_t0") is not None:
            return pred(model_wrap, conds, cond_idx, x, sigma_value, extra_args)
        t0 = time.time()
        out = pred(model_wrap, conds, cond_idx, x, sigma_value, extra_args)
        _t159_sync()
        _t159_sleep((_T159["slow"] - 1.0) * (time.time() - t0))
        return out
    return {"stretch_tail_step": stretch_tail_step_, "predict": predict_, "save_lora": _t159_slowed(globals()["save_lora"]),
            "average_loras": _t159_slowed(globals()["average_loras"])}


def _t159_slow_setup(cfg):
    """G56CT_EMULATE_SLOWDOWN (TEST ONLY): arm the emulation once per process (one private line); rejected / off: nothing at all.
    F = 1 arms nothing either (the H100 SXM5 control: the trainer unchanged)."""
    f, why = t159_slow_factor(cfg.get("emulate_slowdown"))
    if why is not None:
        _t159_say_once("slow", f"WARN emulate-slowdown: G56CT_EMULATE_SLOWDOWN {why}: rejected, off")
        return None
    if f is None or _T159.get("slow_on"):
        return f
    if f <= 1.0:
        _t159_say_once("slow", "emulate-slowdown: x1 (TEST ONLY): nothing slowed (the SXM5 control)")
        return f
    g, sv = globals(), {}
    _T159.update(slow=f, slow_on=True, slow_saved=sv)
    for name, w in _t159_slow_wrappers().items():
        sv[name] = g[name]
        g[name] = w
    try:
        import torch

        class _T159SlowAdamW(torch.optim.AdamW):
            def step(self, *a, **k):
                out = super().step(*a, **k)
                _t159_slow_step_close()
                return out
        sv["torch.AdamW"] = torch.optim.AdamW
        torch.optim.AdamW = _T159SlowAdamW
    except Exception as e:  # noqa: BLE001  (no torch here: the step end is the caller's _t159_slow_step_close)
        log(f"emulate-slowdown: no torch AdamW to wrap ({type(e).__name__})")
    try:
        sys.path.insert(0, str(Path(__file__).resolve().parent))
        import g56dense as DN
        for name in T159_SLOW_DN:
            if callable(getattr(DN, name, None)):
                sv["DN." + name] = getattr(DN, name)
                setattr(DN, name, _t159_slowed(getattr(DN, name)))
        sv["DN"] = DN
    except Exception as e:  # noqa: BLE001  (no dense module here: the training steps / forwards / saves only)
        log(f"emulate-slowdown: g56dense not wrapped ({type(e).__name__}: {str(e)[:80]})")
    log(f"emulate-slowdown: x{f:g} (TEST ONLY) - every training step, forward outside a step (GPTQ H collection), save (canonical "
        f"form included), member average and dense GPTQ / hyb pass + verify takes {f:g} x its wall time")
    return f


def _t159_slow_teardown():
    """tests only: undo _t159_slow_setup (every original back)"""
    if not _T159.get("slow_on"):
        return
    sv, g = _T159.get("slow_saved") or {}, globals()
    for name in ("stretch_tail_step", "predict", "save_lora", "average_loras"):
        if name in sv:
            g[name] = sv[name]
    if "torch.AdamW" in sv:
        import torch
        torch.optim.AdamW = sv["torch.AdamW"]
    DN = sv.get("DN")
    for k, v in sv.items():
        if k.startswith("DN.") and DN is not None:
            setattr(DN, k[3:], v)
    _T159.update(slow=None, slow_on=False, slow_saved={})
    _T159.pop("step_t0", None)


# ----------------------------------------------------------------------------------------------------------------------
#
# PCIe box (W30C0s0__d7e3685b, ideogram4 1.0 h, the entry tree): the speed gate after member 1 logged 'dense: gptq skipped (speed:
# projected 402s > 333s)' (its window = ghard - deadline + DENSE_GPTQ_RESERVE_S), the run then stopped after 2 members with 584 s
#
# speed gate sizes the window from the reserve it may take from TRAINING; it never sees the time the members leave idle at the end.
#   G56CT_GPTQ_LATE=1 (default 0 = today; the c26s profile turns it on): a GPTQ skipped for TIME - a record carrying the projection
#   (p_min = conversion + verify + DENSE_GPTQ_MIN_CASES H cases at the measured s/step, conv_s): the speed gate's skip, the T159
#   planner's skips (speed, a reserve that would cost a member, the member-1 re-check drop) and its records for a shortened / cut
#   member 1 - is decided again after the last member, on Loop.sample's _gptq_after_train line before the H collection, and kept
#   when the time to ghard holds p_min + T164_MARGIN_S. The members ran exactly as with the skip (nothing is reserved from them:
#   never at the price of a member, in every planner); the gptq pass keeps all its own stops (the H collection ends its projected
#   conversion before ghard, convert_gptq aborts when its projected end passes ghard, any failure ships hyb, which keeps its
#   DENSE_EST_S + DENSE_GPTQ_SLACK_S after ghard) - never past the dense hard stop / the kill. Records without a projection (no
#   member-1 timing, no kill time, not ideogram4) are never revived. One private line either way.
#   G56CT_GPTQ_LATE_FILL_MAX f (default 0 = off; c26s: the rc-A switch T164_C26S_FILL_MAX, 0.75 = replayed): a PARTIAL fill member
#   (v1 / v2safe: train_loop's last member on a shortened schedule, SEEDS_FILL) of at most f of the step cap gives way to such a
#   GPTQ when stopping instead leaves the late gate its window + one more T164_MARGIN_S (one private line); full-length members
#
#
#   No reserve beyond DENSE_GPTQ_RESERVE_S is ever taken (a K-aware v2 reserve was replayed and dropped: under a 6-10 % slowdown
#   after member 1 it cost full members - independent review 22 Oct, H1).
# ----------------------------------------------------------------------------------------------------------------------
T164_MARGIN_S = 30.0         # the late gate keeps GPTQ when the time to ghard >= the projected minimal pass + this
T164_IN_C26S = True          # G56CT_PROFILE=c26s turns G56CT_GPTQ_LATE on (an explicit env var wins)
T164_C26S_FILL_MAX = 0.0     # rc-A switch (T170, 23 Oct): G56CT_GPTQ_LATE_FILL_MAX under c26s - 0.0 = off (idle time only, today);
                             # 0.75 once the FM pairs pass (W37PFM d7e3, W38PFM 03d1 / 36b4; rule DECISIONS 23 Oct 05:03 WIB); an
                             # explicit G56CT_GPTQ_LATE_FILL_MAX wins


def _t164_c26s():
    """G56CT_PROFILE c26s (the same test as the T161 block below, worded apart: t161_check anchors a mutation on T161's line)"""
    return (os.environ.get("G56CT_PROFILE") or "").strip().lower() == "c26s"


CFG.update(gptq_late=env("GPTQ_LATE", bool(_t164_c26s() and T164_IN_C26S), bool),
           gptq_late_fill_max=env("GPTQ_LATE_FILL_MAX", 0.0, float))  # 0 (default): no fill member ever gives way (idle time only)
if _t164_c26s() and T164_IN_C26S:
    log(f"profile: c26s -> gptq_late {CFG['gptq_late']} (T164)")
if _t164_c26s():  # T170 (rc-A): the c26s fill give-way share - the switch above unless the env var is set; one private line
    if os.environ.get("G56CT_GPTQ_LATE_FILL_MAX") in (None, ""):
        CFG["gptq_late_fill_max"] = float(T164_C26S_FILL_MAX)
    log(f"profile: c26s -> gptq_late_fill_max {CFG['gptq_late_fill_max']:g} (T164; rc-A switch T164_C26S_FILL_MAX {T164_C26S_FILL_MAX:g})")


def t164_late_check(rec, now, ghard):
    """the late gate on one skipped record: -> (keep, window, need) - window = the seconds to ghard, need = the record's projected
    minimal gptq pass (p_min) + T164_MARGIN_S; keep only for a record skipped with a projection (p_min and conv_s present)"""
    if not rec or rec.get("decision") != "skipped" or "p_min" not in rec or "conv_s" not in rec:
        return False, None, None
    need = float(rec["p_min"]) + T164_MARGIN_S
    window = float(ghard) - float(now)
    return window >= need, window, need


def _t164_late_gate(c):
    """after the last member (Loop.sample's _gptq_after_train line, before the H collection): a GPTQ skipped for time is kept when
    the members left time for it (t164_late_check); -> True kept / False stays skipped / None not applicable. Never raises."""
    try:
        if not CFG.get("gptq_late") or not _gptq_mode() or not _GPTQ_RUN.get("off"):
            return None
        rec = _GPTQ_RUN.get("gate") or {}
        caps = _gptq_caps()
        if caps is None:
            return None
        keep, window, need = t164_late_check(rec, time.time(), caps[1])
        if window is None:
            return None
        was = str(rec.get("why") or rec.get("decision"))
        late = {"window": round(window, 1), "need": round(need, 1), "was": was[:160]}
        if keep:
            est = float(rec["conv_s"])
            rec.update(decision="kept", by=f"late gate (T164; first {rec.get('by') or 'speed gate'})", late=late, reserve=0.0,
                       why_skipped=rec.pop("why", None))  # nothing reserved from training; the first decision's reason kept apart
            _GPTQ_RUN["est"] = est
            _GPTQ_RUN.pop("off", None)  # last: gptq on only with its record and est in place
            log(f"dense: gptq kept (late gate: {window:.0f}s to ghard after the last member >= projected {float(rec['p_min']):.0f}s + "
                f"{T164_MARGIN_S:.0f}s; skipped before: {was[:120]}) {json.dumps(late)}")
            return True
        rec["late"] = late
        log(f"dense: gptq stays skipped (late gate: {window:.0f}s to ghard after the last member < projected "
            f"{float(rec['p_min']):.0f}s + {T164_MARGIN_S:.0f}s) {json.dumps(late)}")
        return False
    except Exception as e:  # noqa: BLE001  (never ends a run: gptq stays as decided, hyb ships)
        log(f"WARN gptq late gate: {type(e).__name__}: {str(e)[:160]}; gptq stays as decided")
        return None


_t126_fill_cap_t164 = globals().get("_t126_fill_cap")  # None in a text without T126's block (t126_check's knob-free build)


def _t164_fill_cap(fill, k, c):
    """train_loop's fill decision (T126's cap first), then G56CT_GPTQ_LATE with G56CT_GPTQ_LATE_FILL_MAX > 0: a PARTIAL fill member
    (<= that share of the step cap) gives way to a GPTQ skipped for time when stopping here leaves the late gate its window with one
    more T164_MARGIN_S (the final write): 0 -> 'stop after k member(s)'. A full-length member is never touched; knobs off / no such
    skip: the function itself. Never raises."""
    fill = _t126_fill_cap_t164(fill, k, c)
    if not fill or not CFG.get("gptq_late") or not _gptq_mode() or not _GPTQ_RUN.get("off"):
        return fill
    try:
        caps, cap = _gptq_caps(), int(c["cfg"]["max_steps"])
        if caps is None or fill >= cap or fill > float(CFG.get("gptq_late_fill_max") or 0.0) * cap:
            return fill  # a full-length member never; longer than the knob's share (0 = every fill): the fill member runs
        rec = _GPTQ_RUN.get("gate") or {}
        keep, window, need = t164_late_check(rec, time.time() + T164_MARGIN_S, caps[1])
        if not keep:
            return fill
        rec["fill_given"] = {"member": k + 1, "steps": int(fill), "window": round(window + T164_MARGIN_S, 1)}
        log(f"seeds-auto: the fill member {k + 1} ({fill} of {int(c['cfg']['max_steps'])} steps) gives way to GPTQ (T164 late gate: "
            f"{window + T164_MARGIN_S:.0f}s to ghard >= projected {float(rec['p_min']):.0f}s + 2 x {T164_MARGIN_S:.0f}s)")
        return 0
    except Exception as e:  # noqa: BLE001  (never stops a run: the fill member runs)
        log(f"WARN gptq late gate (fill member): {type(e).__name__}: {str(e)[:160]}; the fill member runs")
        return fill


if _t126_fill_cap_t164 is not None:
    _t126_fill_cap = _t164_fill_cap  # noqa: F811  (T164: train_loop calls it by name; knob off -> T126's function itself)
_gptq_after_train_t164 = globals().get("_gptq_after_train")  # None in a text without T144's dense gptq code


def _t164_gptq_after_train(c, model_wrap, conds, extra_args, device, ret):
    """_gptq_after_train with G56CT_GPTQ_LATE's decision first (knob off: the function itself)"""
    if CFG.get("gptq_late"):
        _t164_late_gate(c)
    return _gptq_after_train_t164(c, model_wrap, conds, extra_args, device, ret)


if _gptq_after_train_t164 is not None:
    _gptq_after_train = _t164_gptq_after_train  # noqa: F811  (T164: Loop.sample calls it by name; knob off -> the function itself)


# ----------------------------------------------------------------------------------------------------------------------
# ours (T167, 23 Oct 2026): G56CT_QF8_D15 - the qwen Jib-Mix dense 15-block base correction "D15" shipped by the trainer
#
#
#
#
# returns at once and the trainer writes the same bytes (knobs_check vs 472a3a2); G56CT_PROFILE=c26s sets it in the qwen-image
# F8_E5M2 (Jib-Mix) basecond cell only (T167_IN_C26S + the rc-A switch T167_C26S_D15; an explicit G56CT_QF8_D15 wins).
#   When on, after the run's last write (main(), after the dense line): only for qwen-image with a float8_e5m2 root whose QF8_PRIOR
#   (bayes) restoration is in the file, and only when that root is the Jib-Mix V4_E file the T119 fits belong to (size + header
#   sha256), the shipped LoRA file is rewritten: the 180 attn / MLP matrices of the blocks S15 become LoKr pairs (lokr_w1 F32
#   [[2^k]], lokr_w2 F8_E4M3 = RTNE((r + up @ down x alpha / rank) / 2^k), r = the posterior restoration toward the repo's own
#   bf16 transformer/, F32; the LoRA folded, its keys dropped), every other tensor byte for byte - the bedah's tools' output for
#   that file (b20q_ops r2d + b21q_ops lokr; tools/qf8d15_check.py). Written NEXT TO the upload folder, re-read and verified
#   (keys / dtypes / shapes, the kept tensors byte for byte, every module's codes, an independent re-derivation of sampled rows,
#   the estimator gate on the six io matrices vs this run's own QF8_PRIOR restoration), loaded with the evaluator's own
#   comfy.lora.load_lora against the live key map (every key consumed, one patch per target) and its EFFECT checked (the LoKr
#   patch of two modules applied to a zero weight == lokr_w2 x 2^k), then swapped in with os.replace.
#   Never past the deadline: the pass uses the time the members leave idle - nothing is reserved from training (the T164 late
#   gate's rule, never at the price of a member or a step). It starts only when its projected time (QF8_D15_EST_US us per element
#   per worker + the write / re-read, g56qd15.estimate_s) fits before the hard stop = the validator's kill - QF8_D15_MARGIN_S
#   (75 s: the watchdog's 60 s + 15 s), re-projects after every module from the measured rate and stops when the end would pass
#   it. Never above the size cap: a D15 file above T167_CAP_BYTES (8.4 GB, T159's file cap) is not written. Any skip / failure /
#   time / size / disk problem: the LoRA file as written is shipped (one 'WARN qf8-d15: skipped (...)' line), a partial file is
#   removed. G56CT_QF8_D15_KEEP=1 (research only): the file before the swap is also kept as <task folder>/qf8_d15_pre.safetensors
#   (next to the upload folder, never in it) - the run's own pre-D15 state for the eval-only pair and the byte comparison.
# The same profile also carries the two T162 post-training transforms that passed production validation (coordinator 23 Oct; the
# knobs and their code: the T157 block, unchanged) as family defaults (T167_PROFILE_FAMILY, applied at import under c26s only, like
# T161's family values; an explicit env var wins - an EMPTY value counts as unset in apply_family_defaults, so a c26s run switches
# one off with a non-empty malformed value, e.g. G56CT_FLUX_FC=off: one 'WARN flux-fc: off' line, nothing transformed):
#
#
#
# ----------------------------------------------------------------------------------------------------------------------
T167_IN_C26S = True          # G56CT_PROFILE=c26s: the qwen Jib cell carries qf8_d15 True + T167_PROFILE_FAMILY (an explicit env var wins)
T167_C26S_D15 = True         # rc-A switch (T170, 23 Oct): D15 in the c26s qwen Jib cell (False: off in c26s; G56CT_QF8_D15 still wins)
T167_C26S_FC = True          # rc-A switch (T170): FC - the c26s flux family value flux_fc (False: off in c26s)
T167_C26S_P1 = True          # rc-A switch (T170): P1 - the c26s z-image family value zimg_p1 (False: off in c26s)
T167_PROFILE_FAMILY = {"flux": {"flux_fc": "tail16:1.3,gv:1.25,mod:1.1"}, "z-image": {"zimg_p1": "tail64:1.6;tpb:0.853,0.212;attn:1.1"}}
#
#
# independent counts agree: the c26s flux FC string's tail16 factor 1.3 -> 1.0 (gv 1.25 and mod 1.1 kept; with tail16 at 1.0 the tail
# part scales nothing). The per-base strings (T224 PixelWave gv 1, T234 FLUX.1-dev gv 1.33) keep tail16 1.3; the Mono root by
# T309_FC_MONO_KEEP13. Evidence regime: the fluxunchained-dev root (2 tasks x 2 seeds, eval-only on the shipped files). False = 1.3.
T309_FC_TAIL10 = True
if T309_FC_TAIL10:
    T167_PROFILE_FAMILY["flux"]["flux_fc"] = "tail16:1.0,gv:1.25,mod:1.1"
T167_CAP_BYTES = int(round(float(globals().get("T159_FILE_CAP_GB", 8.4)) * 1e9))   # never a shipped file above this (8.4 GB)
T167_KEEP_NAME = "qf8_d15_pre.safetensors"
CFG.update(qf8_d15=env("QF8_D15", False, bool), qf8_d15_est_us=env("QF8_D15_EST_US", 0.45, float),
           qf8_d15_workers=env("QF8_D15_WORKERS", 0, int), qf8_d15_margin_s=env("QF8_D15_MARGIN_S", 75.0, float),
           qf8_d15_free_gb=env("QF8_D15_FREE_GB", 2.0, float), qf8_d15_keep=env("QF8_D15_KEEP", False, bool))


def _t167_profile():
    """G56CT_PROFILE is c26s (worded apart from T161's / T164's tests: their checks anchor mutations on those lines)"""
    return str(os.environ.get("G56CT_PROFILE") or "").strip().lower() in ("c26s",)


def t167_c26s_switches():
    """{switch: on} of the T167 entries under c26s (T170 rc-A switches: D15 = the qwen Jib cell's qf8_d15, FC / P1 = the flux / z-image
    family values of T167_PROFILE_FAMILY)"""
    return {"D15": bool(T167_C26S_D15), "FC": bool(T167_C26S_FC), "P1": bool(T167_C26S_P1)}


if _t167_profile() and T167_IN_C26S:
    _t167_sw = t167_c26s_switches()
    if _t167_sw["D15"]:
        FAMILY_DEFAULTS_BASE.setdefault("qwen-image", {}).setdefault("F8_E5M2", {})["qf8_d15"] = True
    for _t167_fam, _t167_vals in T167_PROFILE_FAMILY.items():
        if _t167_sw.get({"flux": "FC", "z-image": "P1"}.get(_t167_fam), False):  # (a family without a switch: never)
            FAMILY_DEFAULTS[_t167_fam].update(_t167_vals)
    _t167_env = lambda k: (f" [G56CT_{k}={os.environ.get('G56CT_' + k)!r} set: it wins]"  # noqa: E731  (the value in effect)
                           if os.environ.get("G56CT_" + k) not in (None, "") else "")
    log("profile: c26s -> D15 " + ("on (qwen-image Jib cell, basecond F8_E5M2: qf8_d15 True)" if _t167_sw["D15"] else "off")
        + _t167_env("QF8_D15") + "; FC " + (f"on (flux flux_fc {T167_PROFILE_FAMILY['flux']['flux_fc']!r})" if _t167_sw["FC"] else "off")
        + _t167_env("FLUX_FC") + "; P1 " + (f"on (z-image zimg_p1 {T167_PROFILE_FAMILY['z-image']['zimg_p1']!r})" if _t167_sw["P1"] else "off")
        + _t167_env("ZIMG_P1") + " (T167; rc-A switches T167_C26S_D15 / _FC / _P1)")
    del _t167_fam, _t167_vals, _t167_sw, _t167_env


def _t167_mem_gib():
    """GiB this container may still allocate: cgroup v2 memory.max - memory.current + inactive_file (v1: limit - usage), else
    /proc/meminfo MemAvailable; None when unknown"""
    try:
        root = Path(CGROUP_ROOT)
        if (root / "memory.max").exists():
            lim = (root / "memory.max").read_text().strip()
            if lim != "max":
                cur = int((root / "memory.current").read_text())
                ina = 0
                for line in (root / "memory.stat").read_text().splitlines():
                    if line.startswith("inactive_file "):
                        ina = int(line.split()[1])
                return (int(lim) - cur + ina) / 2 ** 30
        v1 = root / "memory"
        if (v1 / "memory.limit_in_bytes").exists():
            lim, use = int((v1 / "memory.limit_in_bytes").read_text()), int((v1 / "memory.usage_in_bytes").read_text())
            if lim < 1 << 60:
                return (lim - use) / 2 ** 30
        for line in Path("/proc/meminfo").read_text().splitlines():
            if line.startswith("MemAvailable:"):
                return int(line.split()[1]) / 2 ** 20
    except Exception:  # noqa: BLE001  (unknown: no memory bound)
        return None
    return None


def _t167_workers():
    """(workers, why): G56CT_QF8_D15_WORKERS, else min(12, the container's CPUs); at most (free GiB - 6) / 1.25 (~0.65 GiB per
    worker on the largest matrices, measured 626 MB, + the queued results), >= 1"""
    w = int(CFG.get("qf8_d15_workers") or 0)
    why = "QF8_D15_WORKERS" if w > 0 else "CPUs"
    if w <= 0:
        try:
            cpus = len(os.sched_getaffinity(0))
        except Exception:  # noqa: BLE001
            cpus = os.cpu_count() or 4
        w = max(1, min(12, int(CPU_THREADS or cpus)))
    mem = _t167_mem_gib()
    if mem is not None and w > max(1, int((mem - 6.0) / 1.25)):
        w, why = max(1, int((mem - 6.0) / 1.25)), f"memory {mem:.0f} GiB"
    return w, why


def _t167_targets(keys):
    """{(module, 'w' | 'b')}: the weights / biases a file's keys patch (comfy.lora.load_lora: one patch per target)"""
    out = set()
    for k in keys:
        for suf, kind in ((".lora_up.weight", "w"), (".lokr_w2", "w"), (".diff", "w"), (".diff_b", "b"), (".set_weight", "w")):
            if k.endswith(suf):
                out.add((k[: -len(suf)], kind))
    return out


def _t167_load_check(mp, path, pl, QD):
    """the evaluator's loader on the D15 file: every key consumed by comfy.lora.load_lora against the live key map with one patch
    per target (verify_lora_loadable on placeholders), and the EFFECT of the LoKr patch of the first attn and the first MLP module
    (ComfyUI's calculate_weight on a zero weight of the live weight's shape == lokr_w2 x 2^k exactly, not all zero). -> patches"""
    import torch
    import comfy.lora
    import comfy.utils
    from safetensors import safe_open
    with safe_open(str(path), framework="pt", device="cpu") as f:
        keys = list(f.keys())
        n_patch, missing = verify_lora_loadable(mp, {k: torch.zeros(1) for k in keys})
        want = len(_t167_targets(keys))
        if missing or n_patch != want:
            raise QD.Skip(f"load check: {len(missing)} keys not loaded ({missing[:2]}), {n_patch} patches for {want} targets")
        key_map = comfy.lora.model_lora_keys_unet(mp.model, {})
        picks = [next(m for m in pl["mods"] if ".attn." in m), next(m for m in pl["mods"] if "_mlp." in m)]
        for m in picks:
            sd = {m + QD.W1: f.get_tensor(m + QD.W1), m + QD.W2: f.get_tensor(m + QD.W2)}
            tk = key_map.get(m)
            ad = comfy.lora.load_lora(sd, key_map, log_missing=False).get(tk) if tk else None
            if ad is None:
                raise QD.Skip(f"effect check: no LoKr patch for {m}")
            shape = tuple(comfy.utils.get_attr(mp.model, tk).shape)
            got = ad.calculate_weight(torch.zeros(shape, dtype=torch.float32), tk, 1.0, 1.0, 0, lambda a: a, torch.float32)
            exp = sd[m + QD.W2].to(torch.float32) * float(sd[m + QD.W1].reshape(-1)[0])
            if tuple(exp.shape) != shape or not torch.equal(got, exp) or not bool(exp.ne(0).any()):
                raise QD.Skip(f"effect check: {m} patch != lokr_w2 x 2^k (shape {shape} vs {tuple(exp.shape)})")
    return n_patch


def qf8_d15_ship(fam, repo, mp, out_dir, t_start, hours):
    """G56CT_QF8_D15 (the note above): rewrite out_dir/last.safetensors with the D15 correction. -> report (also when off /
    skipped); never raises; any problem keeps the LoRA file."""
    import shutil
    rep = {"shipped": False}
    if fam != "qwen-image":
        rep["off"] = f"family {fam}"
        return rep
    final = Path(out_dir) / "last.safetensors"
    tmp = Path(out_dir).parent / f".{Path(out_dir).name}.qf8d15.tmp"
    kill = t_start + max(1, int(hours * 3600))
    hard = kill - float(CFG.get("qf8_d15_margin_s", 75.0))
    t0 = time.time()
    try:
        kind = base_root_dtype(repo)
    except Exception as e:  # noqa: BLE001
        kind = f"unreadable ({type(e).__name__})"
    if kind != "F8_E5M2":
        rep["off"] = f"root {kind} is not a Jib-Mix float8_e5m2 root"
        log(f"qf8-d15: off ({rep['off']})")
        return rep
    try:
        import g56qd15 as QD
        info = _QF8.get("info") or {}
        if info.get("prior") != "bayes" or not _QF8.get("sd"):
            raise QD.Skip("the QF8_PRIOR (bayes) restoration is not in this run's files")
        root = root_checkpoint(repo)
        QD.root_ok(root)
        pl = _t249_d15x_plan(QD, final, root, model_dir(repo) / "transformer", hard)  # T249 (switch off: QD.plan, S15)
        rep.update(src_bytes=pl["src_bytes"], out_bytes=pl["out_bytes"], modules=len(pl["mods"]), folded=pl["folded"])
        kept = {k for k, _, _ in pl["entries"]}
        if any(f"diffusion_model.{m}.diff" not in kept for m in QD.QWEN_IO):   # QF8 off for the last write (a failed write with it)
            raise QD.Skip("the shipped file does not carry the QF8_PRIOR io restoration ('.diff' of the six io layers)")
        if pl["out_bytes"] > T167_CAP_BYTES:
            raise QD.Skip(f"size: the D15 file would be {pl['out_bytes'] / 1e9:.2f} GB > the {T167_CAP_BYTES / 1e9:g} GB cap "
                          f"(LoRA file {pl['src_bytes'] / 1e9:.2f} GB)")
        keep = Path(out_dir).parent / T167_KEEP_NAME if CFG.get("qf8_d15_keep") else None
        need = pl["out_bytes"] + (pl["src_bytes"] if keep is not None else 0)
        free = shutil.disk_usage(str(tmp.parent)).free
        if free < need + float(CFG.get("qf8_d15_free_gb", 2.0)) * 2 ** 30:
            raise QD.Skip(f"disk: {free / 2 ** 30:.1f} GiB free < {need / 2 ** 30:.1f} GiB + QF8_D15_FREE_GB")
        workers, wwhy = _t167_workers()
        est = QD.estimate_s(pl, workers, float(CFG.get("qf8_d15_est_us", 0.45)))
        tail = 10.0 + 2.0 * pl["out_bytes"] / 400e6 + (pl["src_bytes"] / 400e6 if keep is not None else 0.0)
        left = hard - time.time()
        rep.update(workers=workers, est_s=round(est, 1), window_s=round(left, 1))
        if left < est + tail:
            raise QD.Skip(f"time: {left:.0f}s before the hard stop < projected {est:.0f}s + {tail:.0f}s ({workers} workers)")
        io_ref = {}
        for mio in QD.QWEN_IO:
            v = _QF8["sd"].get(f"diffusion_model.{mio}.diff")
            if v is None:
                raise QD.Skip(f"the run's QF8_PRIOR restoration has no io '{mio}.diff' (estimator gate)")
            io_ref[mio] = v.detach().float().cpu().numpy()
        log(f"qf8-d15: building {len(pl['mods'])} modules ({pl['folded']} LoRA folded, {pl['elements'] / 1e9:.2f} G elements), "
            f"{workers} workers ({wwhy}), projected {est:.0f}s + {tail:.0f}s, {left:.0f}s before the hard stop")
        if tmp.exists():   # our own temp file of an attempt that was killed (build never overwrites)
            tmp.unlink()
        stats = QD.build(pl, str(tmp), workers=workers, hard_stop=hard, log=log, io_ref=io_ref, tail_s=tail)
        vr = QD.verify(str(tmp), pl, stats)
        rows = QD.spot_check(str(tmp), pl)
        n_patch = _t167_load_check(mp, tmp, pl, QD)
        if time.time() + (pl["src_bytes"] / 400e6 if keep is not None else 0.0) > hard:
            raise QD.Skip("the hard stop passed during the checks")
        if keep is not None:
            shutil.copyfile(str(final), str(keep))
            rep["keep"] = str(keep)
        size = tmp.stat().st_size
        os.replace(tmp, final)
        try:
            os.chmod(final, 0o644)
        except Exception:  # noqa: BLE001
            pass
        rep.update(shipped=True, bytes=size, seconds=round(time.time() - t0, 1), build_s=stats["seconds"], k_range=stats["k_range"],
                   worst_rel=stats["worst_rel"], gate=stats["gate"], kept_identical=vr["kept_identical"], rows=rows, patches=n_patch)
        log(f"qf8-d15: shipped ({len(pl['mods'])} LoKr modules, {size / 1e9:.2f} GB from {pl['src_bytes'] / 1e9:.2f} GB, "
            f"{time.time() - t0:.0f}s, {hard - time.time():.0f}s before the hard stop) {json.dumps(rep, default=str)}")
    except Exception as e:  # noqa: BLE001  (any failure: the LoRA file is shipped)
        rep["skip"] = f"{type(e).__name__}: {str(e)[:200]}"
        rep["seconds"] = round(time.time() - t0, 1)
        log(f"WARN qf8-d15: skipped ({rep['skip']}); the LoRA file is shipped")
    finally:
        try:
            tmp.unlink()
        except FileNotFoundError:
            pass
        except Exception as e:  # noqa: BLE001
            log(f"WARN qf8-d15: could not remove {tmp.name}: {e}")
    return rep


def _t167_hook(summary, fam, repo, mp, out_dir, t_start, hours):
    """main()'s line before the summary write: G56CT_QF8_D15 on -> summary['qf8_d15'] = qf8_d15_ship(...); off: nothing at all"""
    if not CFG.get("qf8_d15"):
        return None
    rep = qf8_d15_ship(fam, repo, mp, out_dir, t_start, hours)
    summary["qf8_d15"] = rep
    return rep


# ----------------------------------------------------------------------------------------------------------------------
#
# with G56CT_ADAPT unset / 0 nothing below acts - _kfirst_setup, _t126_fill_cap and _gptq_gate are the objects above behind
# pass-through wrappers (assigned, not redefined; train_loop itself is not wrapped) and the trainer writes the same bytes
# (tools/t166_check.py; knobs_check vs 472a3a2). The member rule lives in the v1 loop with the T159 v2safe probe (G56CT_PROFILE
# c26 / c26s, PLANNER v2safe, or PLANNER v2 outside its v2 cells - it falls back to v2safe there); PLANNER v1 and the v2 loop of a
# v2 cell: no member rule (no v2safe probe object to extend). The disk gate below acts in any ideogram4 DENSE gptq run with
# G56CT_ADAPT on.
#   The rule (a family of G56CT_ADAPT_FAMS, default krea2). At member 1's v2safe probe (krea2: step 90), after v2safe's own
#   decision: the probe's s/step (the median of 5 block means - a short hiccup in the window is not a slow node) gives (a) the
#   base-length members that fit - T159's v2 time model (_T159Plan) with v1's OWN stop margins - and (b) v1's predicted members
#   (its rule on that model: full members while 1.10 x the member + 30 s fits, then a fill of >= SEEDS_FILL x the cap, else an idle
#   tail). It acts only when at most T166_K_MAX base members fit, fewer than the member slots (K held by SEEDS_AUTO / the file cap
#   is no slow node), and v1 is predicted to end in an idle tail (no fill) of >= max(T166_IDLE_MIN_S, T166_IDLE_FRAC of a member):
#   the K members are then planned EQUAL and LENGTHENED into that tail (<= T166_F_MAX x the base, T159's v2 length rule). Evidence
#   (krea2, 20-22 Oct): longer members always help sigma-low; 2 x 47/img in 2/3 of the budget beat the full-budget SXM C0 (3 x 40 +
#
#
#
#   of at most T166_K2FILL_MAX of the cap (G56CT_ADAPT_K2FILL, default on with G56CT_ADAPT; =0: the idle-tail rule only).
#   On every measured task at H100 SXM5 speed the rule does not act (= the profile exactly).
#   Mechanics (no line of train_loop changed): st_cap carries the planned length to every later member (train_loop's STRETCH
#   path), their exposure counts are the table scaled to it (t159_scale), member 1's cap and live list follow at the probe (resized
#   last). v1 starts members 2..K-1 at that cap (its 1.10 x + 30 s rule passes them); the LAST planned member takes v1's fill path,
#   where the plan sets its length (the planned one, or what ends in time at the previous member's recent s/step; below
#   T166_LAST_MIN of the base: stop). Safety, all from measured seconds (two independent reviews, 22 Oct):
#   (1) right after member 1 its measured s/step re-checks the plan - v1 would run more full members than K, or more base-length
#   members fit from member 1's start (the probe was misled) -> off, every later member at the base under v1; else the members
#   left take the longest length that fits at that speed (never below the base: below -> off; longer only by >= T159_GROW). The
#   same test runs early, at member 1's brake checks once the speed window has left the probe steps (off while member 1 can still
#   end near the base).
#   (2) the brake, every T166_BRAKE_EVERY steps of a planned member, at its recent s/step (block median, never below the mean of
#   the last T166_SPEED_WIN steps): the members left must end in time (beyond T166_BRAKE_SLACK of the buffer), else their length
#   shrinks (never below the base); when the base does not fit either but the members before the last at it + a last one of
#   T166_LAST_MIN x the base do, K stays (no irreversible step on a slowdown that may pass); else member 1 goes back toward the
#   base (off) or a later member becomes the last planned one (its cap shrinks to what ends in time). A node that is fast again
#   gets the length back (the release: a full buffer to spare on T166_RELEASE_CHECKS consecutive checks, toward the length planned
#   before the brakes); the last planned member, early in it, grows once into time after it that no fill could use (the absorb).
#   (3) after the planned members / the plan stopping, v1's own fill decides at v1's own length (as in c26s: the deadline stop is
#   its brake, and a member it cuts already has its LR near the floor through lr_at's time share); when v1 grants none (its
#   threshold is a share of the LENGTHENED cap) a rescue fill: what ends in time, at most the base, from T166_GUARD_MIN of the base.
#   _run_one's deadline stop stays the last brake; an exception anywhere -> one private WARN line and v1's rules.
#   G56CT_ADAPT=sxm (23 Oct; default off: the value 'sxm' of the same knob, no new CFG key): the rule above, plus - where it does
#   not act - the H100 SXM5 rule for krea2 with >= T166_SXM_MIN_N images on a 1.0 h budget (t166_sxm_choice): 3 equal members, each
#   the shorter of the longest equal length that ends in time and v1's own predicted steps / 3 (EXK3: the same total, the exposure
#   table scaled to the length), when that is 46..56/img with >= 97 % of v1's steps - exactly the two measured K3 regimes: v1 3 full
#   + a fill (EXK3 09af) and v1 4 full + an idle tail (EXK3 / EXLHK3 35cc); v1 4 full + a fill, 5+ full (5bea / 1149 under c26s) or
#   fewer than 3 + a fill keep the profile. After the 3 members: v1's fill, its own or the one its SEEDS_FILL share grants at the
#   base cap (none at a steady speed: the members hold v1's steps; a node that got faster gets the time back), never a shorter one.
#   Member 1 >= 5 % faster than the probe read (a burst before it): the decision again at that speed (_t166_sxm_redo, in the early
#   re-check) - none / another K / < 97 % of v1's steps on 2 checks -> off, c26s back. The after-member-1 'more members fit'
#   turn-off, the absorb and any growth past v1's steps / 3 stay off for an SXM plan; the brake and the release as above. Evidence
#
#   EXLH 09af -0.078 (3 full + fill -> K3); EXK3 - EXL 35cc -0.068 / -0.110, EXLHK3 - EXLH 35cc -0.030 / -0.029 (4 full -> K3);
#   without EXL (K3L*, the C0 table) ~0: the gain needs a low-sigma table. Not K4: the one same-table pair, EXPEQ (EXLP K4 x 48.2 at
#
#   krea2 table is EXLP: EXLP x K3 is what the GPU lines test.
# ----------------------------------------------------------------------------------------------------------------------
T166_FAMS = ("krea2",)       # the families whose slow-node rule G56CT_ADAPT turns on (the others: the profile exactly)
T166_K_MAX = 3               # act only when at most this many base-length members fit (SXM: >= 3 + fill or >= 4 on every measured task)
T166_IDLE_MIN_S = 120.0      # ... and v1's predicted idle tail (no fill member) is at least this long ...
T166_IDLE_FRAC = 0.15        # ... and at least this share of one base member's seconds
T166_F_MAX = 2.0             # the members' length at most this factor of the base (the T159 krea2 v2 cell's f_max)
T166_LAST_MIN = 0.5          # the last planned member, re-planned on v1's fill path: at least this share of the base cap, else stop
T166_K2FILL_MAX = 0.9        # the K2 rule: a predicted fill of at most this share of the cap gives way (PE 35cc: 76 %; a near-full one is a member)
T166_K2_FAMS = ("krea2",)    # ... only in these families (its evidence is krea2's: PE 09af / 35cc; z-image's v1 fill is its measured optimum)
T166_SXM = "sxm"             # G56CT_ADAPT=sxm: the slow-node rule above + the H100 SXM5 rule (t166_sxm_choice) where the slow rule does not act
T166_SXM_ONLY = "sxm-only"   # T170 (rc-A): the H100 SXM5 rule alone (rho-gated, its brake / early re-check), no slow-node rule, no K2FILL
T166_SXM_FAMS = ("krea2",)   # the SXM rule's families (its evidence is krea2 N >= 27: EXK3 / EXLHK3 09af / 35cc)
T166_SXM_MIN_N = 27          # ... from this many training images
T166_SXM_MIN_BUDGET_S = 3000.0  # ... and this many seconds from member 1's start to the deadline: the 1.0 h tasks of the evidence
                             # (3250-3500 s, a slow node's longer setup included) - not the 0.75 h ones (<= 2650 s; untested)
T166_SXM_KC = 3              # ... its plans: 3 members (the measured K3 regimes; K4 is not planned - see the note above)
T166_SXM_MIN_IMG = 46.0      # ... of v1's steps / 3 (in time) between these steps per image: v1 3 full + a fill (>= SEEDS_FILL 0.5 of the
T166_SXM_MAX_IMG = 56.0      # cap) -> >= 46.7/img (EXK3 09af 47), v1 4 full + no fill -> 53.3/img (EXK3 35cc); v1 4 + a fill -> >= 60/img
                             # and 5+ full -> >= 66.7/img (5bea / 1149 under c26s) stay outside: the profile
T166_SXM_TOT = 0.97          # ... 3 x the length >= this share of v1's own predicted steps (EXK3: the same total; EXK3 5bea trained 27 %
                             # fewer steps than its C0)
T166_SXM_REDO_DS = 0.05      # ... an SXM plan's early re-check decides again only when member 1 runs >= this much faster than the probe
                             # read (a burst before it): below that, jitter / warm-up - and a floor or v1 fill at its threshold (5bea
                             # fit 5.01, 35cc 432 s idle) flips the decision on ~1 % (replay: 09af probe window x1.03 undid 3 x 1982)
T166_BRAKE_EVERY = 40        # the brake: every this many steps of a planned member (T159's re-plan block), its recent s/step re-checks the plan
T166_BRAKE_TAIL = 40         # ... a member it shortens keeps at least this many steps from now (its cosine still anneals)
T166_BRAKE_SLACK = 0.5       # ... it acts once the members left would eat more than this share of the plan's buffer (no jitter shrinks)
T166_SPEED_WIN = 200         # ... its s/step: the median of T159's block means, never below the mean over the last this many steps
T166_GROW_FRAC = 0.25        # a later member made the last planned one at most this far into its cap grows into the time after it
                             # that no fill could use (< T166_GUARD_MIN of the base; more: the fill / the guard's fill runs there)
T166_RELEASE_CHECKS = 2      # ... a node fast again: the length back after this many consecutive checks with a full buffer to spare
T166_GUARD_MIN = 0.4         # the rescue fill after the plan (v1 granted none) runs from this share of the base cap (v1's own fills,
                             # planned at 0.5 of the cap on a whole-member s/step, train ~0.49 when the deadline cuts them)
T166_ON = ("1", "on", "true", "yes")
T166_IN_C26S = ""            # rc-A switch (T170, 23 Oct): the G56CT_ADAPT value G56CT_PROFILE=c26s sets - '' off (today), '1' the
                             # slow-node rule, 'sxm' + the H100 SXM5 rule (rho-gated: T166_SXM_RHO_MAX), 'sxm-only' the SXM rule alone
                             # (ADAPT=1 failed on the real PCIe node 23 Oct: never '1' / 'sxm'); an explicit G56CT_ADAPT wins
T166_SXM_RHO_MAX = 1.15      # rc-A (T170): the SXM rule acts only at a measured rho <= this (its evidence: box 2 / box 3, rho ~1) -
                             # rho = the probe's s/step / (T166_SXM_REF_PX x the training images' mean latent pixels); the slow-node
                             # rule is not gated
T166_SXM_REF_PX = {"krea2": 4.32e-5}  # s per step per latent pixel (h x w) on the H100 SXM5 boxes under c26s (the probe lines: 35cc
                             # box 2 0.5312-0.5358 s at 12288 px, 09af box 3 0.5524-0.5557 at ~12910, 5c1d box 3 0.5040 at 12032 ->
                             # 4.19-4.36e-5; the real PCIe box 35cc 0.8136 / 09af 0.8406 -> rho 1.53 / 1.51)
T166_DISK_WARN_GIB = 12.0    # one private WARN line when the upload disk holds less at the start of training (the 0 / 4 GiB box runs)
_T166 = {"said": set()}


def t166_c26s_value(v=None):
    """the G56CT_ADAPT value c26s sets (T170: the rc-A switch T166_IN_C26S): '' / '1' / 'sxm' (True -> '1'; anything else -> '')"""
    v = T166_IN_C26S if v is None else v
    if v is True:
        return "1"
    v = str(v or "").strip().lower()
    return v if v in ("1", T166_SXM, T166_SXM_ONLY) else ""


CFG.update(adapt=env("ADAPT", t166_c26s_value() if str(os.environ.get("G56CT_PROFILE", "") or "").strip().lower() == "c26s"
                     else "", str), adapt_k2fill=env("ADAPT_K2FILL", True, bool),
           adapt_fams=env("ADAPT_FAMS", ",".join(T166_FAMS), str))
if str(os.environ.get("G56CT_PROFILE", "") or "").strip().lower() == "c26s":  # T170 (rc-A): the value in effect, one private line
    log(f"profile: c26s -> adapt {CFG['adapt']!r} (T166; rc-A switch T166_IN_C26S {t166_c26s_value()!r}; the SXM rule only at a measured "
        f"rho <= {T166_SXM_RHO_MAX:g})")


def _t166_enabled():
    """G56CT_ADAPT on (any family): 1 / on / true / yes, sxm (the slow-node rule + the SXM rule) or sxm-only (the SXM rule alone)"""
    v = str(CFG.get("adapt") or "").strip().lower()
    return v in T166_ON or v in (T166_SXM, T166_SXM_ONLY)


def _t166_sxm_only():
    """G56CT_ADAPT=sxm-only (T170): the slow-node rule (and its K2FILL rule) never acts; the SXM rule decides alone"""
    return str(CFG.get("adapt") or "").strip().lower() == T166_SXM_ONLY


def _t166_sxm_on(c):
    """G56CT_ADAPT=sxm and this run is an SXM-rule cell: a T166_SXM_FAMS family with >= T166_SXM_MIN_N training images"""
    return (str(CFG.get("adapt") or "").strip().lower() in (T166_SXM, T166_SXM_ONLY) and (c.get("fam") or _T157.get("fam")) in T166_SXM_FAMS
            and len(c.get("train") or ()) >= T166_SXM_MIN_N)


def t166_sxm_choice(K, k_v1, fill_v1, cap0, n, length_of, budget=None):
    """
    7/7 pairs of the two regimes): T166_SXM_KC equal members, each the shorter of the longest equal length that ends in time
    (length_of(T166_SXM_KC), the plan's own time model) and v1's own predicted steps split that many ways (EXK3: the same total -
    the exposure table scaled to the member length), when that is T166_SXM_MIN_IMG..T166_SXM_MAX_IMG steps per image with >=
    T166_SXM_TOT of v1's steps, on a run with >= T166_SXM_MIN_BUDGET_S from member 1's start to the deadline (budget; None: not
    checked). K (the plan's floor) for the line only -> (Kc, L, why), or (None, None, why)"""
    tot = int(k_v1) * int(cap0) + int(fill_v1 or 0)
    Kc = T166_SXM_KC
    if budget is not None and budget < T166_SXM_MIN_BUDGET_S:
        return None, None, f"SXM: {budget:.0f}s from member 1 to the deadline (< {T166_SXM_MIN_BUDGET_S:.0f}s: not a 1.0 h task)"
    L = min(int(length_of(Kc)), tot // Kc)
    if T166_SXM_MIN_IMG * n <= L <= T166_SXM_MAX_IMG * n and L > cap0 and Kc * L >= T166_SXM_TOT * tot:
        return Kc, L, f"SXM: {Kc} equal members of {L / max(1, n):.1f}/img (floor {K}; v1: {k_v1} full + fill {fill_v1} = {tot} steps)"
    return None, None, (f"SXM: v1's {tot} steps / {Kc} = {tot // Kc / max(1, n):.1f}/img ({L / max(1, n):.1f}/img in time; floor {K}) - "
                        f"not {T166_SXM_MIN_IMG:g}..{T166_SXM_MAX_IMG:g}/img with >= {T166_SXM_TOT:g} of v1's steps")


def t166_sxm_rho(c, s):
    """T170 (rc-A): the SXM rule's measured rho - s (the probe's s/step at the mean latent size) over the H100 SXM5 reference of this
    run, T166_SXM_REF_PX[family] x the mean latent pixels (h x w) of the training images; None without a reference or sizes (then the
    SXM rule does not act). Never raises."""
    try:
        ref = T166_SXM_REF_PX.get(c.get("fam") or _T157.get("fam"))
        px = [int(it["scaled"].shape[-2]) * int(it["scaled"].shape[-1]) for it in (c.get("train") or ())]
        if not ref or not px or not (s and s > 0 and math.isfinite(s)):
            return None
        return float(s) / (float(ref) * (sum(px) / len(px)))
    except Exception:  # noqa: BLE001  (no rho: no SXM plan)
        return None


def t166_fams(raw):
    """G56CT_ADAPT_FAMS 'fam,fam' -> the families of the slow-node rule (qwen-image / ideogram4 never: a longer single qwen
    """
    allowed = ("krea2", "z-image", "flux")
    return tuple(f for f in (x.strip().lower() for x in str(raw or "").split(",")) if f in allowed)


def _t166_on(c):
    """G56CT_ADAPT on for this run's family"""
    return _t166_enabled() and (c.get("fam") or _T157.get("fam")) in t166_fams(CFG.get("adapt_fams"))


def t166_v1_predict(t, D, d1, o, u, cap, slots, frac, write, extra, sfac=1.0, dmargin=0.0, n1=None):
    """v1's seeds-auto members after member 1 on the time model (pure): t = member 1's end with its write, D = the deadline, d1 =
    member 1's wall seconds (train_loop's dur[0]), o + cap x u = a later member's, write(k) = the k-member write, extra(k) = the
    margin above the stop base with k members on disk; full members while 1.10 x sfac x max(dur) + 30 s + dmargin + extra fits,
    then a fill member of int((left - 30 s - extra - dmargin) / (1.10 x sfac x the slowest wall per step)) steps when >= frac x cap
    -> (full members, fill steps, idle seconds after the last write); n1 = member 1's steps (default: the cap)"""
    k, durs = 1, [d1]
    per = max(d1 / max(1, n1 if n1 else cap), (o + cap * u) / max(1, cap))
    while k < slots:
        x = extra(k)
        if t + 1.10 * sfac * max(durs) + 30.0 + dmargin + x <= D:
            d = o + cap * u
            t += d + write(k + 1)
            durs.append(d)
            k += 1
            continue
        n = int((D - t - 30.0 - x - dmargin) / (1.10 * sfac * per))
        fill = min(n, cap) if (frac > 0 and n >= frac * cap) else 0
        if fill:
            t += o + fill * u + write(k + 1)
        return k, fill, D - t
    return k, 0, D - t


def t166_rule(K, k_v1, fill_v1, idle_v1, member_s, k2fill=False, k_cap=None, cap=None):
    """the slow-node rule (pure) -> (act, why); k_cap = the member slots (SEEDS_AUTO / the T126 file cap): a K held by them is no
    slow node (the time left is the slots', not the speed's) -> no action"""
    if K < 1:
        return False, "no base-length member fits (v2safe decides)"
    if k_cap is not None and K >= k_cap:
        return False, f"{K} base members = the {k_cap} member slots (the slots, not the time, set K)"
    if K > T166_K_MAX:
        return False, f"{K} base members fit (> {T166_K_MAX})"
    if k_v1 > K:
        return False, f"v1 predicted {k_v1} full members > {K}"
    if not fill_v1 and idle_v1 >= max(T166_IDLE_MIN_S, T166_IDLE_FRAC * member_s):
        return True, f"v1 predicted {k_v1} full + {idle_v1:.0f}s idle (no fill)"
    if k2fill and fill_v1 and K == 2 and k_v1 <= 2 and (cap is None or fill_v1 <= T166_K2FILL_MAX * cap):
        return True, f"v1 predicted {k_v1} full + a fill of {fill_v1} steps (ADAPT_K2FILL)"
    return False, (f"v1 predicted {k_v1} full + fill {fill_v1}" if fill_v1 else
                   f"v1 predicted {k_v1} full + {idle_v1:.0f}s idle (< max({T166_IDLE_MIN_S:.0f}s, {T166_IDLE_FRAC:g} x {member_s:.0f}s))")


class _T166Safe(globals().get("_T159Safe", object)):  # (a build without the T159 block: never used there)
    """G56CT_ADAPT: the v2safe probe (its own decision first, unchanged), then the slow-node rule (_t166_plan); a plan that acts
    keeps the probe line alive (t166_track: every later step's times + latent sizes of the running member - the brake every
    T166_BRAKE_EVERY steps, the re-check after member 1, the last member's re-plan)"""
    t166_times, t166_lats, t166_member = None, None, 0

    def t166_track(self, step, step_times, lat):
        p = self.c.get("t166_plan")
        try:  # (review round 4 L-a: _run_one calls this every step - nothing here may end a member)
            if step <= 1 or self.t166_lats is None:
                if step <= 1:
                    # (review round 4 L-b: the member's index from the finished members' records - a member abandoned before its
                    # first step never calls this, its record does exist)
                    self.t166_member = (len(p["members"]) + 1) if p else self.t166_member + 1
                    if p:
                        p["room"], p["absorb_seen"] = 0, 0  # (review round 3 L9: the release / absorb checks count within a member)
                    if (p and p.get("active") and self.t166_member != p.get("fill_k") and
                            int(self.cfg["max_steps"]) != int(p["L"])):  # the brake / its release moved the plan's length
                        self.cfg["max_steps"] = int(p["L"])  # (train_loop restored this member's cap to st_cap; its list has L)
                self.t166_lats = []
            self.t166_times = step_times
            self.t166_lats.append(lat)
            if p and p.get("active") and step % T166_BRAKE_EVERY == 0:
                _t166_brake(self, step)
        except Exception as e:  # noqa: BLE001
            if p:
                p["active"], p["guard"] = False, True
            self.c["lr_full_probe"] = None
            log(f"WARN adapt: track: {type(e).__name__}: {str(e)[:120]}; the v1 rules from here")

    def plan(self, step, step_times):
        super().plan(step, step_times)
        if self.acted or not _t166_on(self.c):
            return
        c, cfg = self.c, self.cfg
        snap = (cfg["max_steps"], self.st_cap, dict((c.get("exposure") or {}).get("counts") or {}))
        try:
            _t166_plan(self, step, step_times)
        except Exception as e:  # noqa: BLE001  (never ends a member: the v1 plan; nothing of the plan kept)
            cfg["max_steps"], self.st_cap = snap[0], snap[1]
            if c.get("exposure") is not None and snap[2]:
                c["exposure"]["counts"], c["exposure"]["total"] = snap[2], sum(snap[2].values())
            c.pop("t166_plan", None)
            c["lr_full_probe"] = None
            log(f"WARN adapt: {type(e).__name__}: {str(e)[:160]}; the v1 plan")


def t166_member1_d(now, t0, step, cap, s, se, t_int, net):
    """member 1's seconds as train_loop will measure them (dur[0]) when it runs to step cap at s / step from `step` on (the probe):
    the seconds so far + the rest of its steps + T159_MEMBER_O + its remaining interim saves (not with PLAN_NET: dur is net of them;
    its first steps' warm-up already happened, so it is not added again)"""
    d = (now - t0) + (cap - step) * s + T159_MEMBER_O
    if se > 0 and not net:
        d += (cap // se - step // se) * t_int
    return d


def _t166_plan(obj, step, step_times):
    """member 1's probe step (v2safe kept v1's cap): the members v1 would run vs the base-length members that fit; the rule;
    acting: st_cap, the later members' exposure counts, the plan record and the track line - then member 1's cap and its live
    exposure list (resized last: a failure before it leaves the member as v1 runs it)"""
    c, cfg = obj.c, obj.cfg
    s_mean = lr_full_step_s(step_times, obj.lats, obj.n_bar, step, first=T159_WARM + 1)
    s_blk = _t159_block_s(step_times, obj.lats, obj.n_bar, step)  # robust to a short hiccup in the probe window (review H1)
    s = s_blk if (s_blk and s_blk > 0) else s_mean
    now, D = time.time(), c["deadline"]
    se = int(cfg.get("save_every") or 0)
    n_int = step // se if se > 0 else 0
    t_int = (float(c.get("interim_s", 0.0)) / n_int) if n_int > 0 else T159_INTERIM_PRIOR
    pl = _T159Plan(c, (0, T166_F_MAX))  # the time model only (its own counts / caps read before anything changes)
    pl.t0, pl.D0, pl.u = obj.t0, D, s
    pl.o = T159_MEMBER_O + max(0.0, sum(step_times[:T159_WARM]) - T159_WARM * s)
    cur = {"P": step, "s": s, "t_int": t_int}
    K = pl.fit(now, D, 0, cur, pl.k_cap, T159_K_TOL)
    cap0, n = obj.cap0, max(1, len(c["train"]))
    d1 = t166_member1_d(now, obj.t0, step, cap0, s, se, t_int, bool(CFG.get("plan_net")))
    g_ = globals()  # T126's helpers by name (t126_check counts their call sites outside its block: not one more here)
    slots = int(cfg["seeds_auto"]) + g_["_t126_fill_slot"](c)
    stop0 = g_["_t126_stop"](c.get("eval_cost", 60.0))
    frac = g_["_t126_fill_frac"](float(cfg.get("seeds_fill") or 0.0))
    k_v1, fill_v1, idle_v1 = t166_v1_predict(obj.t0 + d1 + pl.write_s(1), D, d1, pl.o, s, cap0, slots, frac, pl.write_s,
                                             lambda k: max(0.0, _t159_stop_margin(c, k) - stop0), g_["_t126_sfac"](), g_["_t126_dmargin"]())
    member_s = pl.o + cap0 * s
    k2 = bool(CFG.get("adapt_k2fill")) and (c.get("fam") or _T157.get("fam")) in T166_K2_FAMS
    act, why = t166_rule(K, k_v1, fill_v1, idle_v1, member_s, k2, pl.k_cap, cap0)
    if act and _t166_sxm_only():  # (T170: sxm-only - the slow-node rule, K2FILL included, never acts)
        act, why = False, f"the slow-node rule is off under ADAPT=sxm-only (it would act: {why})"
    fit = pl.fit_frac(now, D, K, 0, cur) if K >= 1 else 0.0
    sxm = None
    if not act and _t166_sxm_on(c):  # (the slow-node rule did not act: the H100 SXM5 rule, at a measured rho <= T166_SXM_RHO_MAX)
        rho = t166_sxm_rho(c, s)
        if rho is not None and rho <= T166_SXM_RHO_MAX:
            Kc, Ls, why_s = t166_sxm_choice(K, k_v1, fill_v1, cap0, n, lambda k_: pl.length(now, D, k_, 0, cur), D - obj.t0)
            why_s = f"{why_s}, rho {rho:.2f}"
        else:
            Kc, Ls, why_s = None, None, (f"SXM: rho {rho:.2f} > {T166_SXM_RHO_MAX:g} (its evidence: rho ~1)" if rho is not None
                                         else "SXM: no rho (no SXM5 reference / latent sizes for this run)")
        if Kc:
            act, why, sxm = True, why_s, (Kc, Ls, (int(k_v1) * cap0 + int(fill_v1 or 0)) // Kc)
        else:
            why = f"{why}; {why_s}" if why else why_s
    rec = {"K": K if sxm is None else sxm[0], "fit": round(fit, 2), "s_step": round(s, 4), "s_mean": round(s_mean, 4), "k_v1": k_v1,
           "fill_v1": fill_v1, "idle_v1": round(idle_v1, 1), "member_s": round(member_s, 1), "at": step, "act": act, "why": why,
           "sxm": sxm is not None, "sxm_leq": (sxm[2] if sxm else None)}
    if not act:
        log(f"adapt: no action at member 1 step {step} ({why}; fit {fit:.2f} at {cap0 / n:.1f}/img, s_step {s:.4f}) -> the profile's plan")
        return
    if sxm is not None:
        K = sxm[0]
    L = pl.length(now, D, K, 0, cur) if sxm is None else sxm[1]
    steps, cnt, f = pl.realize(L)
    if steps <= cap0:
        log(f"adapt: no action at member 1 step {step} ({why}; but {K} member(s) at the base {cap0} is all that fits) -> the "
            f"profile's plan")
        return
    base_counts = dict(c["exposure"]["counts"]) if (cnt is not None and c.get("exposure") is not None) else None
    if cnt is not None:
        c["exposure"]["counts"], c["exposure"]["total"] = dict(cnt), sum(cnt.values())
    obj.st_cap = steps
    rec.update(L=steps, L0=steps, f=round(f, 4), m1=steps, members=[], brakes=[])
    c["t166_plan"] = dict(rec, pl=pl, base=cap0, active=True, obj=obj, base_counts=base_counts, t_int=t_int)
    obj.t166_times, obj.t166_lats, obj.t166_member = step_times, list(obj.lats), 1
    c["lr_full_probe"] = obj.t166_track  # member 1's rest and every later member: their step times (brake / re-check / re-plan)
    exs = _t159_live_exposure(c, cap0)
    m1 = exs.t159_resize(cnt) if (exs is not None and cnt is not None) else steps
    cfg["max_steps"] = m1
    c["t166_plan"]["m1"] = m1
    log(f"adapt: {'SXM ' if sxm else ''}K={K} x {steps} steps ({steps / n:.1f}/img, f {f:.3f}; fit {fit:.2f} at {cap0 / n:.1f}/img, "
        f"s_step {s:.4f} (mean {s_mean:.4f})) at member 1 step {step}: {why} -> the members equal and lengthened (member 1 {m1} steps)")


def _t166_set_length(c, p, Lnew, running):
    """the plan's common length -> Lnew (steps; EXPOSURE: the realized total): the later members' counts, st_cap (member 1 running),
    the running member's cap and live exposure list (never below what it trained) -> the running member's new cap"""
    pl, obj = p["pl"], p["obj"]
    tot, cnt, _ = pl.realize(Lnew)
    if cnt is not None:
        c["exposure"]["counts"], c["exposure"]["total"] = dict(cnt), sum(cnt.values())
    p["L"] = tot
    if running == 1:
        obj.st_cap = tot
    exs = _t159_live_exposure(c, p["base"])
    cap = exs.t159_resize(cnt) if (exs is not None and cnt is not None) else tot
    obj.cfg["max_steps"] = cap
    if running == 1:
        p["m1"] = cap  # (review round 2 B1: the re-check after member 1 compares its steps with this)
    return cap


def _t166_off(c, p, why, running=None, step=None):
    """the plan stops acting (one private line): member 1 running (running 1, the brake) -> its cap back to max(the base, now +
    T166_BRAKE_TAIL); member 1 running or just done (running None: the re-check after it, before train_loop reads st_cap) -> the
    later members' cap / counts back to the base (st_cap None); v1's rules decide every later member"""
    p["active"], p["guard"] = False, True  # v1 from here; its fills stay capped by what ends in time (_t166_fill_cap)
    obj = p["obj"]
    if running == 1 and step is not None:
        cap = max(int(p["base"]), int(step) + T166_BRAKE_TAIL)
        if cap < int(obj.cfg["max_steps"]):
            tot, cnt, _ = p["pl"].realize(cap)
            exs = _t159_live_exposure(c, p["base"])
            obj.cfg["max_steps"] = exs.t159_resize(cnt) if (exs is not None and cnt is not None) else tot
            p["m1"] = int(obj.cfg["max_steps"])
    if running in (1, None):
        obj.st_cap = None
        if p.get("base_counts"):
            c["exposure"]["counts"], c["exposure"]["total"] = dict(p["base_counts"]), sum(p["base_counts"].values())
    log(f"adapt: {why} -> the v1 plan from here (member {running or 1} cap {obj.cfg['max_steps']})")


def _t166_shrink_last(c, p, obj, step, cur, K, jj, now, D, why):
    """the running member is the last planned one (jj == K): its cap -> the largest that still ends in time, >= now +
    T166_BRAKE_TAIL steps (below that the deadline stop decides, as for v1); its live exposure list follows"""
    pl = p["pl"]
    cap_now = int(obj.cfg["max_steps"])
    if pl.need(K, cap_now, jj - 1, cur) <= pl.avail(now, D, K):
        return
    lo = min(cap_now, step + T166_BRAKE_TAIL)
    a_, z_ = lo, cap_now
    while z_ - a_ > 1:
        m_ = (a_ + z_) // 2
        a_, z_ = (m_, z_) if pl.need(K, m_, jj - 1, cur) <= pl.avail(now, D, K) else (a_, m_)
    if a_ >= cap_now:
        return
    tot, cnt, _ = pl.realize(a_)
    exs = _t159_live_exposure(c, p["base"])
    obj.cfg["max_steps"] = exs.t159_resize(cnt) if (exs is not None and cnt is not None) else tot
    p["brakes"].append({"member": jj, "step": step, "u": round(cur["s"], 4), "last": obj.cfg["max_steps"]})
    if jj == 1:
        p["m1"] = int(obj.cfg["max_steps"])  # (review round 2 B1)
    log(f"adapt: brake at member {jj} step {step} ({why}): the last planned member's cap {cap_now} -> {obj.cfg['max_steps']}")


def t166_recent_s(ts, ls, n_bar, step):
    """a running member's recent s/step for the brakes: T159's block median (5 blocks of 40 steps), never below the mean over the
    last T166_SPEED_WIN steps - a node that recovered is seen as recovered (the mean since step 11 is not: review round 2 M1), an
    alternating node is not read at its fast blocks -> s/step, or None with too few steps"""
    u = _t159_block_s(ts, ls, n_bar, step)
    if not u or u <= 0:
        return None
    mean = _t159_step_s(ts, ls, n_bar, step, max(T159_WARM + 1, step - T166_SPEED_WIN + 1), 0.0)
    return max(u, mean or 0.0)


def t166_need_last(pl, K, Lc, jj, cur, Llast):
    """seconds from now until member K's training ends: the running member jj (< K) and the members before K at Lc steps, member
    K at Llast steps (_T159Plan.need's model: a running-average write after every member but the last)"""
    return pl.need(K - 1, Lc, jj - 1, cur) + pl.write_s(K - 1) + pl.o + Llast * pl.u


def _t166_absorb(c, p, obj, step, cur, jj, now, D):
    """the running LAST planned member, at most T166_GROW_FRAC into its cap, once: when the time after it (at the recent s/step)
    holds no fill (< T166_GUARD_MIN of the base) on T166_RELEASE_CHECKS consecutive checks it grows into that time (<= f_max x
    the base; the plan's length follows, the release's target). A member is never traded for a long one where a fill would run
    (review round 2 M2); once per member, so the time a passing slowdown gives back later goes to a fill, not into this member
    piece by piece. -> True when it grew"""
    pl = p["pl"]
    cap_now = int(obj.cfg["max_steps"])
    if step > T166_GROW_FRAC * cap_now or p.get("absorbed") == jj or p.get("sxm"):
        return False
    ts, ls = getattr(obj, "t166_times", None), getattr(obj, "t166_lats", None)
    if ts is not None and ls is not None and len(ts) == step and len(ls) == step and step > T159_WARM + 1:
        last = _t159_step_s(ts, ls, pl.n_bar, step, max(T159_WARM + 1, step - T159_REPLAN_BLOCK + 1), 0.0)
        if last and last > cur["s"]:  # the slower of that and its last block: a slowdown that just began is not underrated
            cur = dict(cur, s=last)
    rest = (pl.avail(now, D, jj) - pl.need(jj, cap_now, jj - 1, cur)) / max(1e-6, cur["s"])  # steps after it, at this speed
    z = int(T166_F_MAX * int(p["base"]))
    # (review round 3 MED-4: a member that started on v1's fill path is the run's last one - train_loop ends after it - so no fill
    # can use the time after it: no upper bound there; else only below T166_GUARD_MIN of the base, where no fill would run)
    upper = float("inf") if p.get("fill_k") == jj else T166_GUARD_MIN * int(p["base"])
    if not (max(T166_BRAKE_TAIL, T159_GROW * cap_now) <= rest < upper) or z <= cap_now:
        p["absorb_seen"] = 0
        return False  # (a few steps: no re-plan - the exposure list and the cosine stay as they are)
    p["absorb_seen"] = int(p.get("absorb_seen", 0)) + 1
    if p["absorb_seen"] < T166_RELEASE_CHECKS:
        return False
    a_, z_ = cap_now, z
    if pl.need(jj, z_, jj - 1, cur) <= pl.avail(now, D, jj):
        a_ = z_
    while z_ - a_ > 1:
        m_ = (a_ + z_) // 2
        a_, z_ = (m_, z_) if pl.need(jj, m_, jj - 1, cur) <= pl.avail(now, D, jj) else (a_, m_)
    tot, cnt, _ = pl.realize(a_)
    if tot <= cap_now:
        return False
    exs = _t159_live_exposure(c, p["base"])
    obj.cfg["max_steps"] = exs.t159_resize(cnt) if (exs is not None and cnt is not None) else tot
    p["L"], p["absorbed"] = max(int(p["L"]), int(obj.cfg["max_steps"])), jj  # (review round 3 MED-2: never below the release's target)
    if jj == 1:
        p["m1"] = int(obj.cfg["max_steps"])
    p["brakes"].append({"member": jj, "step": step, "u": round(cur["s"], 4), "absorb": p["L"]})
    log(f"adapt: member {jj} (the last planned one, step {step}) grows into the {rest:.0f} steps after it (< {T166_GUARD_MIN:g} x "
        f"the base: no fill there): cap {cap_now} -> {obj.cfg['max_steps']}")
    return True


def _t166_release(c, p, obj, step, cur, K, jj, now, D, last):
    """review round 2 M1: the brake's release - a node that is fast again gets the length back. The running LAST planned member:
    its cap back toward the plan's length; a member before it: the plan's length back toward the one planned before any brake
    (p['L0']). Only to a length whose members end a FULL buffer before the plan's time (the brake acts at half a buffer past it: no
    alternation), after T166_RELEASE_CHECKS consecutive checks with that room, by >= T159_RELEASE or to the target itself"""
    pl = p["pl"]
    have = int(obj.cfg["max_steps"]) if last else int(p["L"])
    want = int(p["L"]) if last else int(p.get("L0") or p["L"])
    spare = pl.buffer(D)

    def fits(L_):
        return pl.need(K, L_, jj - 1, cur) <= pl.avail(now, D, K) - spare
    if want <= have or not fits(min(want, max(have + 1, int(math.ceil(have * (1.0 + T159_RELEASE) - 1e-6))))):
        p["room"] = 0
        return
    p["room"] = int(p.get("room", 0)) + 1
    if p["room"] < T166_RELEASE_CHECKS:
        return
    p["room"] = 0
    a_, z_ = have, want
    if fits(z_):
        a_ = z_
    while z_ - a_ > 1:
        m_ = (a_ + z_) // 2
        a_, z_ = (m_, z_) if fits(m_) else (a_, m_)
    if a_ <= have:
        return
    if last:
        tot, cnt, _ = pl.realize(a_)
        exs = _t159_live_exposure(c, p["base"])
        obj.cfg["max_steps"] = exs.t159_resize(cnt) if (exs is not None and cnt is not None) else tot
        if jj == 1:
            p["m1"] = int(obj.cfg["max_steps"])
        new = int(obj.cfg["max_steps"])
    else:
        _t166_set_length(c, p, a_, jj)
        new = int(p["L"])
    p["brakes"].append({"member": jj, "step": step, "u": round(cur["s"], 4), "release": new})
    log(f"adapt: brake release at member {jj} step {step} (s_step {cur['s']:.4f}): "
        f"{'the last planned member' if last else 'the plan'}'s length {have} -> {new}")


def _t166_sxm_redo(c, p, obj, step, u, D):
    """an SXM plan's early re-check (_t166_brake; member 1 past the probe window, faster than the probe read, still able to end
    at the base; pl.u = u set by the caller): the probe's SXM decision again at u - its floor, v1's prediction and the time model
    as in _t166_plan -> None while the plan still matches it, else why: another K (or none), or the plan's K x its planned length
    below T166_SXM_TOT of v1's steps at u"""
    pl, cfg = p["pl"], obj.cfg
    now, cap0, n, K = time.time(), int(p["base"]), max(1, len(c["train"])), int(p["K"])
    t_int = float(p.get("t_int", 0.0))
    cur = {"P": step, "s": u, "t_int": t_int}
    K_u = pl.fit(now, D, 0, cur, pl.k_cap, T159_K_TOL)
    d1 = t166_member1_d(now, obj.t0, step, cap0, u, int(cfg.get("save_every") or 0), t_int, bool(CFG.get("plan_net")))
    g_ = globals()  # (T126's helpers by name, as in _t166_plan)
    slots = int(cfg["seeds_auto"]) + g_["_t126_fill_slot"](c)
    stop0 = g_["_t126_stop"](c.get("eval_cost", 60.0))
    frac = g_["_t126_fill_frac"](float(cfg.get("seeds_fill") or 0.0))
    k_v1, fill_v1, _ = t166_v1_predict(obj.t0 + d1 + pl.write_s(1), D, d1, pl.o, u, cap0, slots, frac, pl.write_s,
                                       lambda k: max(0.0, _t159_stop_margin(c, k) - stop0), g_["_t126_sfac"](), g_["_t126_dmargin"]())
    Kc, Lc, _ = t166_sxm_choice(K_u, k_v1, fill_v1, cap0, n, lambda k_: pl.length(now, D, k_, 0, cur), D - obj.t0)
    tot = int(k_v1) * cap0 + int(fill_v1 or 0)
    L0 = int(p.get("L0") or p["L"])
    if Kc == K and K * L0 >= T166_SXM_TOT * tot:
        return None
    return (f"the SXM decision at this speed: {f'K={Kc} x {Lc}' if Kc else 'none'} (floor {K_u}, v1 {k_v1} full + fill {fill_v1} = "
            f"{tot} steps) vs the plan's K={K} x {L0}")


def _t166_brake(obj, step):
    """every T166_BRAKE_EVERY steps of a planned member (review M1): the members left (the running one at the plan's length) at the
    running member's RECENT s/step (T159's block median, never below its mean over the last T166_SPEED_WIN steps; later members at
    the slower of that and the plan's) must still end in time. If not: the plan's length shrinks for every member left, never
    below the base (the running one: >= now + T166_BRAKE_TAIL); when the base does not fit either but the members before the last
    one at that floor and a last one of T166_LAST_MIN x the base do, the length goes to the floor and K stays (review round 2 M1);
    else member 1 goes back toward the base and v1 decides the rest (_t166_off), a later member becomes the last planned one; the
    last planned member's cap shrinks to what ends in time. When they fit again: the release (_t166_release) / the absorb of the
    last member (_t166_absorb). Never raises (a problem: the plan stops acting, its fills capped; the deadline stop stays the
    brake)."""
    c = obj.c
    p = c.get("t166_plan")
    try:
        jj = int(obj.t166_member)  # the running member, 1-based
        K, L = int(p["K"]), int(p["L"])
        ts, ls = obj.t166_times, obj.t166_lats
        if jj > K or ts is None or len(ts) != step or len(ls) != step:
            return
        pl = p["pl"]
        u = t166_recent_s(ts, ls, pl.n_bar, step)
        if not u:
            return
        cur = {"P": step, "s": u, "t_int": p.get("t_int", 0.0) if jj == 1 else 0.0}
        u0 = pl.u
        pl.u = max(u0, u)
        now, D0_ = time.time(), c["deadline"]
        # (review round 3 L4: _T159Plan.need adds pl.o - the setup + warm-up seconds of a member - to the RUNNING member too, whose
        # own are behind it; comparing against the deadline + that excess counts them once)
        D = D0_ + max(0.0, float(pl.o) - T159_MEMBER_O)
        try:
            slack = T166_BRAKE_SLACK * pl.buffer(D0_)
            if (jj == 1 and step >= int(p.get("at") or 0) + T166_SPEED_WIN
                    and step + T166_BRAKE_TAIL <= int(p["base"])):
                # the window holds no probe step any more: the probe's decision again at member 1's speed now (the after-member-1
                # re-check, early): more base-length members fit than the plan's K (with T159_GROW to spare) on
                # T166_RELEASE_CHECKS consecutive checks -> the probe was misled (a burst in its window), off while member 1 can
                # still end near the base (review round 2: the K2 rule on a hiccup at H100 SXM5 speed cost c26s's fill). An SXM
                # plan (its K is below the floor by design), while member 1 runs faster than the probe read: the probe's SXM
                # decision again at this speed (_t166_sxm_redo) - a burst before the probe that lowered the floor / v1's steps (K3 x
                # v1's steps / 3 on a floor-4 / 5 node: up to 23 % fewer steps, replay 5bea x1.3 for 60 s) -> c26s back
                pl.u = u
                k_true = pl.fit(obj.t0 + int(p["base"]) * u + pl.o + pl.write_s(1), D0_, 1, None, pl.k_cap, T159_GROW)
                if p.get("sxm"):  # (an SXM plan: its own re-check; a node slower than the probe read is the brake's)
                    bad = _t166_sxm_redo(c, p, obj, step, u, D0_) if u < float(p["s_step"]) * (1.0 - T166_SXM_REDO_DS) else None
                    misled = bad is not None
                else:
                    bad, misled = None, k_true > K
                pl.u = max(u0, u)
                p["fast_seen"] = int(p.get("fast_seen", 0)) + 1 if misled else 0
                if p["fast_seen"] >= T166_RELEASE_CHECKS:
                    why_ = f"{k_true} base-length members fit > the plan's {K}" if bad is None else bad
                    _t166_off(c, p, f"brake at member 1 step {step}: at s_step {u:.4f} (the probe's {p['s_step']:.4f}) {why_}",
                              running=1, step=step)
                    return
            if jj == K:
                if pl.need(K, int(obj.cfg["max_steps"]), jj - 1, cur) > pl.avail(now, D, K) + slack:
                    p["room"] = 0
                    _t166_shrink_last(c, p, obj, step, cur, K, jj, now, D, f"s_step {u:.4f}")
                elif not _t166_absorb(c, p, obj, step, cur, jj, now, D):
                    _t166_release(c, p, obj, step, cur, K, jj, now, D, True)
                return
            if pl.need(K, L, jj - 1, cur) <= pl.avail(now, D, K) + slack:
                _t166_release(c, p, obj, step, cur, K, jj, now, D, False)
                return
            p["room"] = 0
            lo = max(int(p["base"]), step + T166_BRAKE_TAIL)
            if lo < L and pl.need(K, lo, jj - 1, cur) <= pl.avail(now, D, K):
                a_, z_ = lo, L
                while z_ - a_ > 1:
                    m_ = (a_ + z_) // 2
                    a_, z_ = (m_, z_) if pl.need(K, m_, jj - 1, cur) <= pl.avail(now, D, K) else (a_, m_)
                cap = _t166_set_length(c, p, a_, jj)
                p["brakes"].append({"member": jj, "step": step, "u": round(u, 4), "L": p["L"]})
                log(f"adapt: brake at member {jj} step {step}: the plan's {K} member(s) no longer end in time at s_step {u:.4f} -> "
                    f"length {L} -> {p['L']} (running member cap {cap})")
                return
            # (review round 2 M1) the members before the last one at the floor and the last one at the shortest the plan gives a
            # last member (T166_LAST_MIN x the base; the fill path re-plans it at the speed then) still end in time -> the length
            # goes to the floor and K stays: no irreversible off / cut on a slowdown that may pass (the release grows it back)
            if t166_need_last(pl, K, lo, jj, cur, T166_LAST_MIN * int(p["base"])) <= pl.avail(now, D, K):
                if lo < L:
                    cap = _t166_set_length(c, p, lo, jj)
                    p["brakes"].append({"member": jj, "step": step, "u": round(u, 4), "L": p["L"], "floor": True})
                    log(f"adapt: brake at member {jj} step {step}: the plan's {K} member(s) end in time at s_step {u:.4f} only with a "
                        f"shorter last one -> length {L} -> {p['L']} (running member cap {cap}; the last one re-planned at its start)")
                return
            if jj == 1:
                _t166_off(c, p, f"brake at member 1 step {step}: {K} member(s) do not end in time even at the base length "
                                f"(s_step {u:.4f})", running=1, step=step)
                return
            p["K"], p["k_cut"] = jj, True  # a later member: it becomes the last planned one (v1's fill / the guard after it)
            log(f"adapt: brake at member {jj} step {step}: {K} member(s) do not end in time even at the base length (s_step "
                f"{u:.4f}) -> member {jj} is the last planned one")
            if not _t166_absorb(c, p, obj, step, cur, jj, now, D):
                _t166_shrink_last(c, p, obj, step, cur, jj, jj, now, D, f"now the last planned member, s_step {u:.4f}")
        finally:
            pl.u = u0
    except Exception as e:  # noqa: BLE001
        if p:
            p["active"], p["guard"] = False, True  # (v1 from here, its fills capped by what ends in time)
        log(f"WARN adapt: brake: {type(e).__name__}: {str(e)[:120]}; the v1 rules from here")


_kfirst_setup_t166 = globals().get("_kfirst_setup")  # (bound only where it exists: checks build trainers without blocks)


def _t166_kfirst_setup(c, lrf):
    """_kfirst_setup (T159: the v2safe probe object), then (G56CT_ADAPT, a T166 family) that probe with the slow-node rule; with
    G56CT_ADAPT one private line on the upload disk's free space (WARN below T166_DISK_WARN_GIB) - train_loop's seeds-auto start"""
    lrf = _kfirst_setup_t166(c, lrf)
    if _t166_enabled():
        try:
            free = _t166_disk_free(c) / 2 ** 30
            low = free < T166_DISK_WARN_GIB
            log(f"{'WARN ' if low else ''}adapt: {free:.1f} GiB free on the upload disk at the start of the members"
                + (f" (< {T166_DISK_WARN_GIB:g} GiB: the running-average writes / the dense file may not fit)" if low else ""))
        except Exception:  # noqa: BLE001  (a log line only)
            pass
    if type(lrf) is globals().get("_T159Safe") and _t166_on(c):
        obj = _T166Safe(c)
        c["t159_safe_obj"] = obj
        return obj
    return lrf


if _kfirst_setup_t166 is not None:
    _kfirst_setup = _t166_kfirst_setup  # noqa: F811  (T166: train_loop calls it by name; knob off -> the T159 function itself)
_gptq_gate_t166 = globals().get("_gptq_gate")


def t166_dense_need(adapters):
    """bytes of the dense (fp8) file the hyb / gptq pass writes: sum(out x in) of the DiT LoRA modules - the need of the disk
    tests in dense_ship / _gptq_ship (they read the same shapes from the final file)"""
    need = 0
    for full, a in (adapters or {}).items():
        up, down = getattr(a, "lora_up", None), getattr(a, "lora_down", None)
        if str(full).startswith(TE_PREFIX) or up is None or down is None:
            continue
        need += int(up.weight.shape[0]) * int(down.weight.shape[1])
    return need


def _t166_disk_free(c):
    """free bytes where the upload folder lives (the dense passes' own test: shutil.disk_usage(out_dir.parent).free)"""
    import shutil
    return shutil.disk_usage(str(Path(c["out_dir"]).parent)).free


def _t166_disk_gate(c):
    """G56CT_ADAPT, ideogram4 with DENSE=gptq, right before the speed gate after member 1: when the disk cannot hold the dense file
    + DENSE_FREE_GB (the test dense_ship / _gptq_ship make after training, which then skip both passes), GPTQ is skipped here
    without a projection (no reserve taken from the members; T164's late gate never revives it) and the hyb reserve
    (DENSE_RESERVE_S, in the deadline since main()) goes back to the members. A healthy disk: nothing. Never raises."""
    try:
        if c.get("fam") != "ideogram4" or not _gptq_mode() or "gate" in _GPTQ_RUN:
            return None
        need = t166_dense_need(c.get("adapters")) + float(CFG["dense_free_gb"]) * 2 ** 30
        free = _t166_disk_free(c)
        if need <= 0 or free >= need:
            return None
        why = f"disk: {free / 2 ** 30:.1f} GiB free < {need / 2 ** 30:.1f} GiB (dense file + DENSE_FREE_GB; T166)"
        back = float(_dense_reserve_s()) if CFG.get("dense") else 0.0  # the reserve main()'s deadline took (static gate: + the GPTQ one)
        c["deadline"] = c["deadline"] + back
        _GPTQ_RUN["gate"] = {"k": 0, "decision": "skipped", "why": why, "by": "T166 disk gate", "reserve_back": back}
        _GPTQ_RUN["off"] = why
        log(f"dense: gptq skipped ({why}); the hyb reserve {back:.0f}s back to the members (deadline_in "
            f"{c['deadline'] - time.time():.0f}s) {json.dumps(_GPTQ_RUN['gate'])}")
        return True
    except Exception as e:  # noqa: BLE001  (never ends a run: the gate decides as without T166)
        log(f"WARN adapt: disk gate: {type(e).__name__}: {str(e)[:120]}; the speed gate decides")
        return None


def _t166_recheck(c, p, r, net_s):
    """right after member 1 (before train_loop reads st_cap; review H1): member 1 cut below its plan -> off. Else member 1's measured
    speed (t166_member_speed) replaces the probe's: when v1 from here (its own rule, member 1's real seconds) would run more full
    members than the plan's K, the probe was misled (a hiccup in its window, a node that got faster) -> off, every later member
    at the base cap under v1's rules; else the members left keep the plan's length, shorter when it no longer fits (never below
    the base: below it -> off)"""
    steps = int(r.get("steps") or 0)
    if steps < int(p.get("m1", 0)) or r.get("abandoned"):
        _t166_off(c, p, f"member 1 ended at {steps} of its {p.get('m1')} planned steps")
        return
    pl, obj = p["pl"], p["obj"]
    u, o = t166_member_speed(p["members"][-1], pl)
    pl.u, pl.o = u, o
    now, D, cap0 = time.time(), c["deadline"], int(p["base"])
    g_ = globals()
    cfg = obj.cfg
    slots = int(cfg["seeds_auto"]) + g_["_t126_fill_slot"](c)
    stop0 = g_["_t126_stop"](c.get("eval_cost", 60.0))
    frac = g_["_t126_fill_frac"](float(cfg.get("seeds_fill") or 0.0))
    k_v1, fill_v1, _ = t166_v1_predict(now + pl.write_s(1), D, float(net_s), o, u, cap0, slots, frac, pl.write_s,
                                       lambda k: max(0.0, _t159_stop_margin(c, k) - stop0), g_["_t126_sfac"](), g_["_t126_dmargin"](),
                                       n1=steps)
    # the probe's decision again at the measured speed: base-length members from member 1's start (member 1 at the base length)
    t_b = obj.t0 + cap0 * u + o
    k_true = pl.fit(t_b + pl.write_s(1), D, 1, None, pl.k_cap)
    K = int(p["K"])
    if not p.get("sxm") and (k_v1 > K or k_true > K):  # (an SXM plan's K is below them by design)
        _t166_off(c, p, f"after member 1 (measured s_step {u:.4f} vs the probe's {p['s_step']:.4f}): {max(k_v1, k_true)} base-length "
                        f"members fit > the plan's {K}")
        return
    if K >= 2:
        t_w = now + pl.write_s(1)  # (member 1's running-average write comes after this line)
        L = pl.length(t_w, D, K, 1, None)
        if p.get("sxm") and p.get("sxm_leq"):
            L = min(L, int(p["sxm_leq"]))  # (the SXM rule: never longer than v1's steps split K ways - EXK3's same total)
        if pl.need(K, cap0, 1, None) > pl.avail(t_w, D, K):
            _t166_off(c, p, f"after member 1 (measured s_step {u:.4f}): {K - 1} more member(s) do not fit at the base length")
            return
        if L < int(p["L"]) or L >= int(p["L"]) * (1.0 + T159_GROW):  # (longer only by >= T159_GROW: review round 2 M5)
            tot, cnt, _ = pl.realize(L)
            if tot != int(p["L"]):
                if cnt is not None:
                    c["exposure"]["counts"], c["exposure"]["total"] = dict(cnt), sum(cnt.values())
                log(f"adapt: after member 1 (measured s_step {u:.4f}): the {K - 1} member(s) left {p['L']} -> {tot} steps")
                p["L"] = tot
                obj.st_cap = tot
        p["L0"] = int(p["L"])


def _t166_gptq_gate(c, k, r, net_s):
    """train_loop's line after every member: the member's steps / wall seconds into the T166 plan (G56CT_ADAPT acting), the disk
    gate (G56CT_ADAPT, ideogram4, after member 1), then the speed gate itself (unchanged)"""
    if k == 0 and _t166_enabled():
        _t166_disk_gate(c)
    p = c.get("t166_plan")
    if p is not None:
        try:
            o_ = p.get("obj")
            ts_ = list(o_.t166_times or []) if o_ is not None else []
            ls_ = list(o_.t166_lats or []) if o_ is not None else []
            p["members"].append({"k": int(k), "steps": int(r.get("steps") or 0), "wall": float(net_s), "times": ts_, "lats": ls_})
            if k == 0 and p.get("active"):
                _t166_recheck(c, p, r, net_s)
        except Exception as e:  # noqa: BLE001
            p["active"], p["guard"] = False, True
            log(f"WARN adapt: member record: {type(e).__name__}: {str(e)[:120]}; the v1 rules from here")
    return _gptq_gate_t166(c, k, r, net_s)


if _gptq_gate_t166 is not None:
    _gptq_gate = _t166_gptq_gate  # noqa: F811  (T166: train_loop calls it by name; knob off -> nothing recorded, the gate itself)
_t126_fill_cap_t166 = globals().get("_t126_fill_cap")  # (t126_check's knob-free build has no T126 block: no wrap there)


def t166_member_speed(m, pl):
    """(s/step, seconds outside the steps) the next member is planned with, from the last finished member m: its RECENT speed
    (T159's _t159_block_s: the median of the latent-weighted means of its last 5 blocks of 40 steps - a node that slowed during
    it plans the next member at the new speed), never below its mean s/step over its steps after the warm-up; o = its seconds outside
    the steps + its first T159_WARM steps above that speed (T159's member model); without its step times: its mean wall per step
    (o 0); no record: the probe's"""
    if not m or m.get("steps", 0) < 1:
        return pl.u, pl.o
    steps, wall, ts, ls = int(m["steps"]), float(m["wall"]), m.get("times") or [], m.get("lats") or []
    u = None
    if len(ts) == steps and len(ls) == steps:
        u = _t159_block_s(ts, ls, pl.n_bar, steps)
        mean = _t159_step_s(ts, ls, pl.n_bar, steps, T159_WARM + 1, 0.0)
        if u and mean:
            u = max(u, mean)  # never below its own mean (review M2: an alternating node; a burst only ever slows the plan)
    if not u or u <= 0:
        return max(1e-6, wall / steps), 0.0
    o = max(0.0, wall - sum(ts)) + max(0.0, sum(ts[:T159_WARM]) - T159_WARM * u)
    return u, o


def _t166_fill_cap(fill, k, c):
    """train_loop's fill decision for member k + 1 (the fill path: v1's own 1.10 x rule did not start a full member), after the
    functions it wraps; with a T166 plan acting: k >= K or the plan stopped -> v1's own fill (the deadline stop is its brake), and
    when v1 grants none a rescue fill (what ends in time, at most the base, from T166_GUARD_MIN of the base; an SXM plan: from
    v1's own SEEDS_FILL share of the base); else member k + 1 is
    the last planned one (train_loop ends after a fill-path member): its planned length, or what ends in time now (the previous
    member's recent s/step and seconds outside the steps, t166_member_speed, + the stop margin + one step + the buffer), at least
    T166_LAST_MIN of the base cap, else 0 (the absorb may lengthen it later). Never raises (a problem: v1's fill)."""
    fill = _t126_fill_cap_t166(fill, k, c)
    p = c.get("t166_plan")
    if not p or not (p.get("active") or p.get("guard")):
        return fill
    try:
        pl, L = p["pl"], int(p["L"])
        u, o = t166_member_speed(p["members"][-1] if p["members"] else None, pl)
        left = c["deadline"] - time.time() - _t159_stop_margin(c, k) - u - pl.buffer(c["deadline"]) - o
        n_fit = int(left / max(1e-6, u))
        if k >= int(p["K"]) or not p.get("active"):  # the planned members are done / the plan stopped acting (guard): v1's own fill
            p["active"] = False  # (the plan's members are done or it stopped: v1's rules from here, plus the rescue below)
            p["guard"] = True
            # v1's own fill as it plans it (review round 3 MED-1: cutting it to the recent-speed estimate cost a fill's worth of
            # steps after transients). The deadline stop is its brake, as in c26s: a member that stop cuts already has its LR near
            # the floor through lr_at's time share (review round 4 MED-A: a brake on it cost steps for nothing). When v1 grants none
            # (its threshold is SEEDS_FILL x the LENGTHENED cap, its estimate the lengthened members' seconds; after a K cut by the
            # brake too: review round 2 B2) a rescue fill: what ends in time, at most the base, from T166_GUARD_MIN of the base
            frac = globals()["_t126_fill_frac"](float(c["cfg"].get("seeds_fill") or 0.0))
            # (an SXM plan: from v1's own SEEDS_FILL share of the base instead - the fill v1 grants at the base cap, none at a steady
            # speed (the 3 members hold v1's steps and leave its idle tail), the time back when the node got faster after member 1:
            # independent review 23 Oct M1, dropping it cost up to 20 % of the steps; never T166_GUARD_MIN's shorter fill)
            thr = frac if p.get("sxm") else T166_GUARD_MIN
            if fill:  # (review round 3 MED-1: not cut by n_fit - a transient in the last member's window made it too short)
                out = int(fill)
            else:  # (from T166_GUARD_MIN of the base, at most the base; only where fills run at all: SEEDS_FILL > 0)
                out = min(n_fit, int(p["base"])) if (frac > 0 and n_fit >= thr * int(p["base"])) else 0
            have = int((c.get("exposure") or {}).get("total") or 0)
            if out and (not fill or (have and out > have)):  # (L3: a fill longer than the counts' total would train a second pass)
                tot, cnt, _ = pl.realize(out)
                if cnt is not None:
                    c["exposure"]["counts"], c["exposure"]["total"] = dict(cnt), sum(cnt.values())
                out = tot
            log(f"adapt: {'the ' + str(p['K']) + ' planned member(s) done' if k >= int(p['K']) else 'guard (the plan stopped acting)'} "
                f"({c['deadline'] - time.time():.0f}s left) -> v1's fill {fill or 0} ({n_fit} would end in time at u {u:.4f}s/step): "
                f"{out or 'stop'}")
            return out
        Lp = min(L, n_fit)
        if Lp < T166_LAST_MIN * int(p["base"]):
            log(f"adapt: member {k + 1} (last of {p['K']} planned) would get {max(0, Lp)} steps (< {T166_LAST_MIN:g} x "
                f"{p['base']}) -> stop")
            return 0
        if Lp < L:
            tot, cnt, _ = pl.realize(Lp)
            if cnt is not None:
                c["exposure"]["counts"], c["exposure"]["total"] = dict(cnt), sum(cnt.values())
            Lp = tot
        p["fill_k"] = k + 1  # (its cap is this length: t166_track leaves it)
        log(f"adapt: member {k + 1} = the last of {p['K']} planned: {Lp} of {L} steps (u {u:.4f}s/step measured, "
            f"{c['deadline'] - time.time():.0f}s left)")
        return Lp
    except Exception as e:  # noqa: BLE001
        p["active"], p["guard"] = False, True  # (review round 3 L8)
        log(f"WARN adapt: last member: {type(e).__name__}: {str(e)[:120]}; v1's fill {fill}")
        return fill


if _t126_fill_cap_t166 is not None:
    _t126_fill_cap = _t166_fill_cap  # noqa: F811  (T166: train_loop calls it by name; knob off / no plan -> the functions it wraps)



# ----------------------------------------------------------------------------------------------------------------------
#
#
# cli / train_loop / stretch_tail_step / _SafeEnsemble are the objects above behind pass-through wrappers (assigned, not redefined)
# and the trainer writes the same bytes (tools/t161_check.py; knobs_check vs 472a3a2). A failed task (OOM, timeout, crash, exit != 0)
# is an automatic loss, so the robustness items come first.
#   G56CT_HARD_EXIT=1 (M1): with a complete last.safetensors in the upload folder the process ends with os._exit(0) - no release of
#     main()'s locals, no interpreter or C++ teardown - after stdout / stderr are flushed and last.safetensors + the folder fsynced
#     (the wait bounded by T161_FSYNC_S; the page cache holds the file either way): at main()'s last line (a normal end, its locals
#     still alive: _t161_main_end) or, when cli() settles on exit 0 after a crash / SystemExit with a usable adapter, there. Two forks
#     of our public code finished training on 19 Oct and then died in teardown ('terminate called without an active exception' ->
#
#     or no complete file: today's path (cli's return value through sys.exit). An fsync still writing back at os._exit delays the
#     process end (not its exit code 0) until the kernel finishes it.
#   G56CT_SPARSE_WRITES=pow2: SAFE's running average goes to disk after members 1, 2, 4, 8, ... (a usable trained file from member 1
#     on) and after the last member (final(): the same save_lora call on the same average as today's last write -> the same bytes);
#     the averages in between stay in memory (an exception leaving train_loop writes the in-memory one first: _t161_flush_ensemble). Every write that is made keeps the canonical form, so the save margin keeps measuring
#     its canonical-form time at k = 1, 2, 4, 8 (canonicalizing only the last write would leave _save_margin with the identity
#     write's 1-member reference x K^2 - several times too long at K >= 4 - or an unmeasured growth law). Edge cases (a member
#     abandoned by SAFE, a non-finite member) take today's add(). The T159 v2 loop keeps a write after every member (its plan
#     measures every write).
#   G56CT_SAVE_EVERY_S=s: member 1's interim saves (only where SAVE_EVERY > 0: ideogram4 / flux 100, z-image / qwen-image 500
#     steps; krea2 writes none) every max(SAVE_EVERY, ceil(s / its s/step)) steps, the s/step measured on member 1's steps 11..30 - a
#     save about every s seconds or less often (never more saves than today), none in a member shorter than that. Until the period is
#     known SAVE_EVERY is 0 (the v2safe probe then sits at step 90 and models the measured period; the T159 v2 plan gets the period in
#     its own interim model); train_loop puts SAVE_EVERY back when it returns.
#   G56CT_BAND_IS_CLIP_DIAG=0: BandIS's per-step 'did the clip bind' diagnostic (a second gradient norm and a host sync every step;
#     only the flux 'openai' N <= 11 cell runs BandIS) is skipped; the 500-step line then has no clip share. 1 (default) = today.
#   G56CT_SAVE_MEMBERS=<dir> (research only, not in any profile): the state each member adds to the average (its EMA factors, F32,
#     unscaled: what the running average concatenates) as <dir>/member<k>.safetensors + <dir>/members.json, so subset-K / weighting
#     questions become eval-only. Never inside the upload folder (refused: one WARN line); any problem: one WARN line, the run goes on.
#   G56CT_PROFILE=c26s = c26 (T159: planner v2safe, krea2 EXLP, qwen Jib EXQ) + HARD_EXIT 1 + SPARSE_WRITES pow2 + SAVE_EVERY_S 600
#     + BAND_IS_CLIP_DIAG 0 + per-family values (FAMILY_DEFAULTS updated at import under this profile only; an explicit env var wins
#     as for every family default): ideogram4 canon_device cuda, dense_margin_s 75 (T160 sec. 3.3: GPTQ still passes its gate; NOT the
#     T126-max95 set), plan_net; qwen-image canon_device cuda, plan_net, wall_frac 1.0, reserve_s 75, gc_keep auto, fast_merge_alpha,
#     fast_ema (T129: partial checkpointing with the OOM rung, the GEMM-scaled merge and the foreach EMA - both checked bit for bit per
#     module / per run); krea2 wall_frac 1.0, reserve_s 75 (the z-image / flux values since 18 Oct).
# ----------------------------------------------------------------------------------------------------------------------
T161_FSYNC_S = 20.0          # G56CT_HARD_EXIT: the most seconds the upload folder's fsync may take before os._exit(0) anyway
T161_SE_FROM, T161_SE_TO = 10, 30   # G56CT_SAVE_EVERY_S: member 1's s/step over its steps FROM + 1 .. TO (warm-up steps left out)
T161_PROFILE_GLOBAL = {"hard_exit": True, "sparse_writes": "pow2", "save_every_s": 600.0, "band_is_clip_diag": False}
T161_PROFILE_FAMILY = {
    "ideogram4": {"canon_device": "cuda", "dense_margin_s": 75.0, "plan_net": True},
    "qwen-image": {"canon_device": "cuda", "plan_net": True, "wall_frac": 1.0, "reserve_s": 75.0, "gc_keep": "auto",
                   "fast_merge_alpha": True, "fast_ema": True},
    "krea2": {"wall_frac": 1.0, "reserve_s": 75.0},
}
_T161 = {"said": set()}


def _t161_profile_on():
    """G56CT_PROFILE c26s (T159's parser applies its c26 part through T159_PROFILES['c26s'])"""
    return str(os.environ.get("G56CT_PROFILE", "") or "").strip().lower() == "c26s"


_t161_prof = dict(T161_PROFILE_GLOBAL) if _t161_profile_on() else {}
CFG.update(hard_exit=env("HARD_EXIT", _t161_prof.get("hard_exit", False), bool),
           sparse_writes=env("SPARSE_WRITES", _t161_prof.get("sparse_writes", ""), str),
           save_every_s=env("SAVE_EVERY_S", _t161_prof.get("save_every_s", 0.0), float),
           band_is_clip_diag=env("BAND_IS_CLIP_DIAG", _t161_prof.get("band_is_clip_diag", True), bool),
           save_members=env("SAVE_MEMBERS", "", str))
if _t161_prof:
    for _t161_fam, _t161_vals in T161_PROFILE_FAMILY.items():
        FAMILY_DEFAULTS[_t161_fam].update(_t161_vals)
    log("profile: c26s = c26 + T161 -> " + json.dumps({k: CFG[k] for k in sorted(T161_PROFILE_GLOBAL)}, sort_keys=True)
        + "; family defaults " + json.dumps(T161_PROFILE_FAMILY, sort_keys=True))
    del _t161_fam, _t161_vals
del _t161_prof


def _t161_say_once(key, text):
    """one private line per training process and key"""
    if key not in _T161["said"]:
        _T161["said"].add(key)
        log(text)


# ---- G56CT_HARD_EXIT (M1)
def t161_complete(path):
    """(True, header bytes) when path is a complete safetensors file - an 8-byte little-endian header length, a JSON header naming
    >= 1 tensor with sane data_offsets, the file exactly 8 + header + the largest end offset long - else (False, why). Reads the
    header only (every write is atomic: a file that exists is complete; this confirms it without reading the tensors)."""
    try:
        p = Path(path)
        size = p.stat().st_size
        with open(p, "rb") as f:
            n = int.from_bytes(f.read(8), "little")
            if not 0 < n <= min(size - 8, 100 * 2 ** 20):
                return False, f"header length {n} in a {size}-byte file"
            hdr = json.loads(f.read(n))
        ends = []
        for k, v in hdr.items():
            if k == "__metadata__":
                continue
            a, b = (int(x) for x in v["data_offsets"])
            if not 0 <= a <= b:
                return False, f"data_offsets {a}..{b} of {k[:60]}"
            ends.append(b)
        if not ends:
            return False, "no tensor"
        if 8 + n + max(ends) != size:
            return False, f"{size} bytes, the header says {8 + n + max(ends)}"
        return True, n
    except Exception as e:  # noqa: BLE001  (unreadable / not safetensors: no hard exit)
        return False, f"{type(e).__name__}: {str(e)[:80]}"


def _t161_fsync(folder):
    """fsync last.safetensors (the artifact; never a partial .tmp), then the folder (its rename) -> 1"""
    for p in (Path(folder) / "last.safetensors", Path(folder)):
        fd = os.open(str(p), os.O_RDONLY)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
    return 1


def _t161_flush():
    for s in (sys.stdout, sys.stderr):
        try:
            s.flush()
        except Exception:  # noqa: BLE001  (a closed stream: nothing to flush)
            pass


def _t161_hard_exit():
    """G56CT_HARD_EXIT, cli() settled on 0: with a complete last.safetensors in the upload folder -> flush, fsync (bounded by
    T161_FSYNC_S), os._exit(0) (never returns); else returns why not (the caller then returns 0 as today)."""
    import threading
    out = _OUT_DIR
    if out is None:
        return "no upload folder known"
    ok, why = t161_complete(Path(out) / "last.safetensors")
    if not ok:
        return f"last.safetensors: {why}"
    _t161_flush()
    t0, res = time.time(), {}

    def sync():
        try:
            res["n"] = _t161_fsync(out)
        except Exception as e:  # noqa: BLE001  (fsync is insurance: the exit goes on)
            res["err"] = f"{type(e).__name__}: {str(e)[:80]}"
    th = threading.Thread(target=sync, name="g56-hard-exit-fsync", daemon=True)
    th.start()
    th.join(T161_FSYNC_S)
    how = ("last.safetensors and the folder fsynced" if "n" in res else f"fsync failed ({res['err']})" if "err" in res
           else f"fsync still running after {T161_FSYNC_S:g}s (the page cache holds the files)")
    log(f"hard exit: exit 0 with a complete last.safetensors ({why}-byte header); {how} in {time.time() - t0:.1f}s; "
        f"os._exit(0), no interpreter / C++ teardown")
    _t161_flush()
    os._exit(0)


_cli_t161 = cli


def _t161_cli(main_fn=None):
    """cli() (its exit-code policy unchanged), then G56CT_HARD_EXIT when it settled on 0 (off, or any other code: the value itself)"""
    rc = _cli_t161(main_fn)
    if rc == 0 and CFG.get("hard_exit"):
        try:
            why = _t161_hard_exit()
        except Exception as e:  # noqa: BLE001  (M1 never changes the exit code: exit 0 through the normal teardown)
            why = f"{type(e).__name__}: {str(e)[:80]}"
        log(f"hard exit: not taken ({why}); exit 0 through the normal teardown")
    return rc


cli = _t161_cli  # noqa: F811  (T161: the __main__ guard calls cli by name; G56CT_HARD_EXIT off -> the function above itself)


def _t161_main_end():
    """main()'s last line (G56CT_HARD_EXIT): the hard exit while main()'s locals (model, guider, CUDA state) are still alive, so neither
    their release nor the interpreter's teardown runs; main() has nothing left to do there (the file written, the summary saved).
    Off, no complete file or any problem: returns (main() returns, cli() / _t161_cli take today's path)."""
    if not CFG.get("hard_exit"):
        return
    try:
        why = _t161_hard_exit()
    except Exception as e:  # noqa: BLE001  (main() then returns as today)
        why = f"{type(e).__name__}: {str(e)[:80]}"
    log(f"hard exit: not taken at main()'s end ({why}); main() returns as today")


# ---- G56CT_SPARSE_WRITES / G56CT_SAVE_MEMBERS (SAFE's running ensemble)
def t161_write_due(n):
    """G56CT_SPARSE_WRITES pow2: the running average of n members goes to disk now (n a power of two: 1, 2, 4, 8, ...)"""
    return n >= 1 and n & (n - 1) == 0


def _t161_sparse_on():
    """G56CT_SPARSE_WRITES is 'pow2' ('' / off -> False; any other value -> one private WARN line, False)"""
    v = str(CFG.get("sparse_writes") or "").strip().lower()
    if v in ("", "0", "off", "none"):
        return False
    if v != "pow2":
        _t161_say_once("sparse", f"WARN sparse writes: G56CT_SPARSE_WRITES {CFG.get('sparse_writes')!r} is not 'pow2'; a write after "
                                 f"every member")
        return False
    return True


def _t161_sparse(c):
    """G56CT_SPARSE_WRITES acts on this ensemble: 'pow2' outside the T159 v2 loop (its plan measures a write after every member)"""
    return _t161_sparse_on() and c.get("planner_v2") is None


def _t161_flush_ensemble(c):
    """G56CT_SPARSE_WRITES, an exception leaving train_loop: the running average of the members still only in memory goes to disk
    first (today's write path; best effort, never raises) - cli()'s crash policy then ships it instead of an older power-of-two one"""
    ens = c.get("t161_ens")
    try:
        if ens is None or not _t161_sparse(c) or not ens.members() or (ens.last is not None and ens.last[0] == ens.key()):
            return
        t0 = time.time()
        ok = save_lora(ens.average(), c["out_dir"])
        log(f"WARN safe: train_loop raised - the running average of {len(ens.members())} member(s) in memory written first "
            f"({'ok' if ok else 'refused: not finite'}, {time.time() - t0:.0f}s)")
    except Exception as e:  # noqa: BLE001  (the exception that left train_loop travels on; the file on disk stays)
        log(f"WARN safe: the in-memory running average was not written ({type(e).__name__}: {str(e)[:80]}); the file on disk stays")


def _t161_save_member(c, sd, r, k):
    """G56CT_SAVE_MEMBERS=<dir>: member k + 1's state (as the running average takes it) -> <dir>/member<k + 1>.safetensors (atomic)
    and its record in <dir>/members.json (a new list at member 1). Never raises (one private WARN line)."""
    try:
        d = Path(str(CFG.get("save_members"))).expanduser().resolve()
        out = Path(c["out_dir"]).resolve()
        if d == out or out in d.parents:
            raise ValueError(f"{d} is the upload folder or inside it")
        from safetensors.torch import save_file
        t0 = time.time()
        d.mkdir(parents=True, exist_ok=True)
        name = f"member{k + 1}.safetensors"
        meta = {"member": str(k + 1), "steps": str(r.get("steps")), "abandoned": str(bool(r.get("abandoned"))),
                "seed": str(int(c["cfg"]["seed"]) + 1000 * k), "final_scale": str(c["cfg"].get("final_scale", 1.0)),
                "family": str(c.get("fam"))}
        tmp = d / f".{name}.tmp"
        save_file(fg_inject({key: v.detach().contiguous() for key, v in sd.items()}), str(tmp), metadata=meta)  # (as SAVE_RUNS: + the remap key)
        os.replace(tmp, d / name)
        idx = d / "members.json"
        rec = json.loads(idx.read_text()) if (k > 0 and idx.is_file()) else []
        rec.append(dict(meta, file=name, seconds=round(time.time() - t0, 2)))
        idx.write_text(json.dumps(rec, indent=1))
        log(f"save-members: member {k + 1} -> {d / name} ({time.time() - t0:.1f}s)")
    except Exception as e:  # noqa: BLE001  (research output: never ends a run)
        log(f"WARN save-members: member {k + 1}: {type(e).__name__}: {str(e)[:120]}; not saved")


class _T161Ensemble(_SafeEnsemble):
    """_SafeEnsemble with G56CT_SPARSE_WRITES (a finite, complete member whose running average is not due on disk joins the average
    in memory; final() writes the last average when it is not on disk) and G56CT_SAVE_MEMBERS. Both off: the class above itself."""

    def __init__(self, c, scale):
        super().__init__(c, scale)
        if _t161_sparse_on():  # G56CT_SPARSE_WRITES: train_loop's exception path writes the in-memory average (_t161_flush_ensemble)
            c["t161_ens"] = self

    def add(self, r, k):
        if self.c.get("planner_v2") is not None and "gc_keep_n" not in self.c and str(self.c["cfg"].get("gc_keep") or "").strip().lower() not in ("", "0", "off"):  # T252
            _t161_say_once("gckeep_v2", "WARN gc keep: G56CT_GC_KEEP was never sized before the T159 v2 loop's members (no gc_keep_setup): "
                                        "every block stayed checkpointed")
        n0, spare0 = len(self.sds), self.spare
        sd = r.get("best_sd")
        if not _t161_sparse(self.c) or sd is None or r.get("abandoned") or t161_write_due(n0 + 1) or not _sd_finite(sd):
            super().add(r, k)  # today's add: the knob off, every edge case and every member whose average is due on disk
        else:
            self.sds.append(sd)
            log(f"safe: member {k + 1} joins the running average in memory ({len(self.sds)} member(s); sparse writes: on disk "
                f"after member {1 << len(self.sds).bit_length()} or the last)")
        if CFG.get("save_members") and sd is not None and (len(self.sds) > n0 or (spare0 is None and self.spare is not None)):
            _t161_save_member(self.c, sd, r, k)


_SafeEnsemble = _T161Ensemble  # noqa: F811  (T161: train_loop / the T159 v2 loop build it by name; both knobs off -> the class above)


# ---- G56CT_SAVE_EVERY_S (member 1's interim saves by time)
def _t161_se_on(c):
    cfg = c["cfg"]
    return float(cfg.get("save_every_s") or 0.0) > 0 and int(cfg.get("save_every") or 0) > 0 and not c["holdout"]


def _t161_se_step(c, se, step):
    """G56CT_SAVE_EVERY_S at a step attempt's first call (stretch_tail_step): the clock at step FROM, then at step TO the period
    ceil(s / measured s/step) into cfg save_every (_run_one's interim-save rule reads it every step)"""
    now = time.time()
    if step == T161_SE_FROM:
        se["t_from"] = now
    elif step == T161_SE_TO and se.get("t_from") is not None:
        s = (now - se["t_from"]) / float(T161_SE_TO - T161_SE_FROM)
        if s > 0 and math.isfinite(s):
            se["period"] = c["cfg"]["save_every"] = max(se["orig"], int(math.ceil(se["s"] / s)))  # never more often than today
            pl = c.get("planner_v2")  # the T159 v2 plan read SAVE_EVERY (0 then) once at its start: its interim model takes the period
            if pl is not None and getattr(pl, "se", None) == 0:
                pl.se = se["period"]
            log(f"interim saves: every {se['period']} steps (~{se['s']:g}s at {s:.4f}s/step, member steps {T161_SE_FROM + 1}.."
                f"{T161_SE_TO}; SAVE_EVERY {se['orig']} replaced; never more often than it)")


_stretch_tail_step_t161 = stretch_tail_step


def _t161_stretch_tail_step(c, step, band_pool, cases, acc_groups, tail_on):
    """stretch_tail_step (the first call of every training step attempt) after G56CT_SAVE_EVERY_S's period measurement (off:
    the function above itself)"""
    se = c.get("t161_se")
    if se is not None and se.get("period") is None:
        _t161_se_step(c, se, step)
    return _stretch_tail_step_t161(c, step, band_pool, cases, acc_groups, tail_on)


stretch_tail_step = _t161_stretch_tail_step  # noqa: F811  (T161: _run_one calls it by name; G56CT_SAVE_EVERY_S off -> the function itself)
_train_loop_t161 = train_loop


def _t161_train_loop(c, model_wrap, conds, extra_args, device):
    """train_loop (T159's dispatcher) with G56CT_SAVE_EVERY_S (member 1's interim saves by time) and G56CT_SPARSE_WRITES' exception
    path (the in-memory average written before the exception travels on); both off: the function above itself"""
    se_on, sp_on = _t161_se_on(c), _t161_sparse_on()
    if not se_on and not sp_on:
        return _train_loop_t161(c, model_wrap, conds, extra_args, device)
    cfg, se = c["cfg"], None
    if se_on:
        se = c["t161_se"] = {"orig": int(cfg["save_every"]), "s": float(cfg["save_every_s"]), "period": None}
        cfg["save_every"] = 0  # no interim save before member 1's period is measured (v2safe's probe: step 90, the measured period)
        log(f"interim saves: by time (G56CT_SAVE_EVERY_S {se['s']:g}): member 1 saves about every {se['s']:g}s or less often, the step "
            f"period from its steps {T161_SE_FROM + 1}..{T161_SE_TO}; SAVE_EVERY {se['orig']} off until then; a member shorter than that "
            f"saves none")
    try:
        return _train_loop_t161(c, model_wrap, conds, extra_args, device)
    except BaseException:
        if sp_on:
            _t161_flush_ensemble(c)
        raise
    finally:
        if se is not None:
            cfg["save_every"] = se["orig"]
            c.pop("t161_se", None)
        c.pop("t161_ens", None)


train_loop = _t161_train_loop  # noqa: F811  (T161: Loop.sample calls it by name; G56CT_SAVE_EVERY_S off -> T159's dispatcher itself)


# ----------------------------------------------------------------------------------------------------------------------
# ours (T129, 17 Oct 2026; speed): G56CT_GC_KEEP - partial gradient checkpointing. With block checkpointing on (G56CT_GRAD_CKPT
# on: qwen-image's 846-module rank-64 recipe needs it with the base held in bf16 - 51.4 GiB with every block checkpointed, an
# estimated ~81 GiB without), every checkpointed block runs its forward twice per step: torch's non-reentrant checkpoint()
# re-runs the block in backward, with every GEMM and every LoRA merge / rank-r forward again. GC_KEEP keeps the LAST N blocks
# out of checkpointing (set_checkpointing's own wrapper taken off them): their activations stay alive for backward and their
# forward runs once (backward frees them first, before any recompute). Checkpointing only recomputes the same forward, so
# every value is the same (tools/gc_keep_check.py: losses, factor gradients and the trained state bit for bit on the CPU);
# only memory and time move.
#   N: that many blocks (research). "auto": once before member 1 (train_loop: after the FAST_LORA guard and SPEC_INIT, before
# the cache probe and any member), probe passes - one training forward + backward of the task's largest cases
# (_wc_probe_cases), no optimizer step, a noise generator of their own, gradients cleared, the peak statistics restarted.
# The peak with every block checkpointed sits at the END of backward (one recomputed block + every LoRA gradient), the peak
# with k blocks kept at its START (k blocks of activations) - so the slope is measured on the kept side only (review T129 #1):
# k0 = GC_KEEP_PROBE and k1 = 3 x k0 blocks on the largest case; N = k1 + (target - state - peak(k1)) / slope, target =
# min(GC_KEEP_MAX_GIB, total - GC_KEEP_MARGIN_GIB), state = what a step holds that the probe does not (AdamW exp_avg +
# exp_avg_sq and the EMA copy of every trainable tensor, + EMA_EXTRA / EMA_DEBIAS copies, + the gradients alive in a step's
# later forwards: paired / ACCUM, + AGREE's two accumulators). Verify at N on every probe case (stops at the first case over
# the target): over -> once more at the secant count through THAT case's own (k1, peak) and (N, peak) (one more pass when it
# is not the largest case); still over -> k1 verified on every case, else 0. No growth from k0 to k1 (both under the
# end-of-backward peak: a small-activation task) -> N = every block, verified the same way. An out-of-memory pass or any
# other problem -> 0 = every block checkpointed (the run as without the knob). The speed factor for the planner = one warm
# pass with every block checkpointed / one at N (c['gc_keep_slow']). Delta review 17 Oct (#2 - #6) applied.
#   OOM ladder: a training step that runs out of memory with blocks kept (not in its optimizer update: there the
# activations are already freed and a redo would apply the update twice, review T129 #3) puts every block back under
# checkpointing and is redone with its own draws (the FAST_WCACHE snapshot, review T129 #6) before the existing rungs; the
# planner then prices the members that ran with blocks kept at the all-checkpointed speed (_gc_keep_replan). "" / 0 = off (the
# default): nothing runs, the trainer unchanged byte for byte. Defined at the end of the module (README / SUBMISSION_NOTES line
# references keep their lines); _wcache_snap_needed and _upd_oom_drop are rebound here (callers look them up at call time).
# ----------------------------------------------------------------------------------------------------------------------
CFG.update(gc_keep=env("GC_KEEP", "", str), gc_keep_max_gib=env("GC_KEEP_MAX_GIB", 70.0, float),
           gc_keep_margin_gib=env("GC_KEEP_MARGIN_GIB", 8.0, float), gc_keep_probe=env("GC_KEEP_PROBE", 4, int))
_GC_BLOCK_RE = r"^diffusion_model\.(layers|blocks|transformer_blocks|double_blocks|single_blocks|noise_refiner|context_refiner)\.\d+$"
_GC_SLOW_MAX = 3.0  # the planner's all-checkpointed / kept speed ratio after an OOM drop is clamped to [1, this]


class _GcKeepStop(Exception):
    """G56CT_GC_KEEP auto: a reason to keep every block checkpointed (one log line, never raised further)."""


def _gc_blocks(mp):
    """The blocks set_checkpointing wraps (the same regex), in named_modules order."""
    return [m for full, m in mp.model.named_modules() if re.match(_GC_BLOCK_RE, full)]


def gc_keep_set(mp, n):
    """G56CT_GC_KEEP: every block under set_checkpointing's own wrapper, then that wrapper taken off the last n (exactly
    set_checkpointing(mp, False) for those blocks); returns the n applied (clamped to the block count). The fast path's
    state (when FAST_LORA is on) carries n: a training step then takes the redo snapshot (_wcache_snap_needed)."""
    set_checkpointing(mp, True)
    blocks = _gc_blocks(mp)
    n = max(0, min(int(n), len(blocks)))
    for m in blocks[len(blocks) - n:]:
        if hasattr(m, "_g56_orig_forward"):
            m.forward = m._g56_orig_forward
            del m._g56_orig_forward
    st = getattr(mp, "_g56_fast", None)
    if st is not None:
        st._g56_gk = n
    return n


def _gc_keep_state_bytes(c):
    """Bytes a training step holds beyond what a probe pass sees (one forward + backward from no gradients): AdamW's exp_avg
    and exp_avg_sq and the EMA copy of every trainable tensor (_run_one), + one copy per EMA_EXTRA decay and the EMA_DEBIAS
    start copy, + the gradients alive during a step's later forwards (paired: the empty half after the caption half's
    backward; ACCUM: the later cases), + AGREE's two accumulators (review T129 #2a) and, paired, the caption half's gradient
    next to them during the empty half (delta review #5); each in its tensor's dtype."""
    cfg = c["cfg"]
    nb = sum(p.numel() * p.element_size() for p in c["params"])
    k = 3 + sum(1 for d in (cfg.get("ema_extra") or []) if d > 0) + (1 if cfg.get("ema_debias") else 0)
    accum, agree = int(cfg.get("accum", 1) or 1), float(cfg.get("agree", 0.0) or 0.0)
    paired = cfg.get("prompt_mode") == "paired"
    if accum > 1 and agree > 0:
        k += 3 if paired else 2
    elif accum > 1 or paired:
        k += 1
    return k * nb


def _gc_probe_pass(c, model_wrap, conds, extra_args, device, case, g, sigma):
    """(absolute peak bytes, seconds) of one probe pass: one training forward + backward of case (item, cond index) with
    noise from g, no optimizer step (_wc_probe_pass: gradients cleared and the peak statistics restarted before it). Its own
    frame, so an exception's tensors (the graph of a forward that raised) are gone once the caller's except clause ends."""
    import torch
    sync = torch.cuda.synchronize if torch.cuda.is_available() else (lambda: None)
    sync()
    t0 = time.time()
    _wc_probe_pass(c, model_wrap, conds, extra_args, device, case[0], case[1], g, sigma)
    sync()
    dt = time.time() - t0
    return _cuda_mem()[2], dt  # the pass's own peak: _wc_probe_pass restarted the statistics before it


def _gc_time_pass(c, model_wrap, conds, extra_args, device, case, g, sigma):
    """Seconds of one warm training forward + backward of case (no peak reset, no cache release: the allocator keeps what
    the passes before left), gradients cleared before and after."""
    import torch
    sync = torch.cuda.synchronize if torch.cuda.is_available() else (lambda: None)
    item, idx = case
    x0 = item["scaled"].to(device)
    eps = torch.randn(x0.shape, generator=g, dtype=torch.float32).to(device)
    xt, target = (1 - sigma) * x0 + sigma * eps, eps - x0
    for p in c["params"]:
        p.grad = None
    sync()
    t0 = time.time()
    den = predict(model_wrap, conds, idx, xt, sigma, extra_args)
    ((xt - den.float()) / sigma - target).square().mean().backward()
    sync()
    dt = time.time() - t0
    for p in c["params"]:
        p.grad = None
    return dt


def _cuda_reserved_peak():
    """Peak reserved bytes of the current CUDA device (the allocator's pools incl. fragmentation); None without CUDA."""
    import torch
    if not torch.cuda.is_available():
        return None
    return torch.cuda.max_memory_reserved(torch.cuda.current_device())


def gc_keep_setup(c, model_wrap, conds, extra_args, device):
    """G56CT_GC_KEEP, once before member 1 (train_loop, after the FAST_LORA guard and SPEC_INIT): a block count keeps that
    many blocks; 'auto' sizes it with probe passes (the note above). Sets c['gc_keep_n'] (0: every block checkpointed) and
    c['gc_keep_slow'] (warm all-checkpointed / kept pass time on the largest case, for the planner after an OOM drop). One
    private line; never raises (any problem: every block checkpointed). Returns the number of blocks kept."""
    import torch
    cfg, mp = c["cfg"], c["mp"]
    c["gc_keep_n"], c["gc_keep_slow"] = 0, 1.0
    spec = str(cfg.get("gc_keep") or "").strip().lower()
    if spec in ("", "0", "off"):
        return 0
    t0, gib = time.time(), 2.0 ** 30
    blocks = _gc_blocks(mp)
    why = None
    if not c.get("grad_ckpt_on"):
        why = "gradient checkpointing is off (no recompute to save)"
    elif not blocks:
        why = "no transformer block"
    elif spec != "auto" and not spec.isdigit():
        why = f"G56CT_GC_KEEP {cfg.get('gc_keep')!r} is neither 'auto' nor a block count"
    elif spec == "auto" and c.get("te") is not None:
        why = "TE LoRA (the probe passes do not encode captions)"
    elif spec == "auto" and (not c["train"] or _cuda_mem() is None):
        why = "no CUDA memory statistics" if c["train"] else "no training image"
    if why is not None:
        log(f"gc keep: off ({why}); every block checkpointed")
        return 0
    if spec != "auto":
        n = gc_keep_set(mp, int(spec))
        c["gc_keep_n"] = n
        log(f"gc keep: {n} of {len(blocks)} blocks without checkpointing (G56CT_GC_KEEP {spec}; no speed factor: an OOM drop "
            f"does not re-plan)")
        return n
    nb = len(blocks)
    total = _cuda_mem()[0]
    target = min(cfg["gc_keep_max_gib"] * gib, total - cfg["gc_keep_margin_gib"] * gib)
    state, cases = 0, []
    g = torch.Generator(device="cpu").manual_seed(7171)
    sigma = (cfg["bands"] // 2 + 0.5) / cfg["bands"]
    k0 = max(1, min(int(cfg["gc_keep_probe"]), nb))
    k1 = min(nb, 3 * k0)
    n, info = 0, ""

    def peak_at(k, which):
        gc_keep_set(mp, k)
        return _gc_probe_pass(c, model_wrap, conds, extra_args, device, which, g, sigma)[0]

    def verify(k):  # (the largest peak over the probe cases at k, the case that went over the target - None: none did)
        top = 0
        for cs in cases:
            top = max(top, peak_at(k, cs))
            if top + state > target:
                return top, cs
        return top, None

    try:
        state = _gc_keep_state_bytes(c)  # inside the try: setup never raises (delta review #6)
        cases = _wc_probe_cases(c, conds)
        p0 = peak_at(0, cases[0])
        pa = peak_at(k0, cases[0])
        pb = peak_at(k1, cases[0]) if k1 > k0 else pa
        per = (pb - pa) / (k1 - k0) if k1 > k0 else (pb - p0) / max(1, k1)
        info = (f"largest case {_cond_len(conds[cases[0][1]])}+{_lat_tokens(cases[0][0]['scaled'])} tokens: peak {p0 / gib:.2f} "
                f"GiB all checkpointed, {pa / gib:.2f} at {k0} kept, {pb / gib:.2f} at {k1} kept ({per / gib:+.3f} GiB per kept "
                f"block); state {state / gib:.2f} GiB; target {target / gib:.1f} GiB")
        if per <= 0 and pb + state <= target:  # no growth from k0 to k1: both under the end-of-backward peak (a small-
            n = nb  # activation task, delta review #2) - every block, verified like any count (over: the secant below)
        elif per <= 0:
            raise _GcKeepStop(f"no peak growth between {k0} and {k1} kept blocks, {k1} over the target")
        elif pb + state > target:  # already k1 does not fit (a large-activation task): fewer, from the k0 side
            n = int(max(0, min(nb, k0 + (target - state - pa) // per)))
        else:
            n = int(max(k1, min(nb, k1 + (target - state - pb) // per)))
        ok = False
        if n > 0:
            top, over = verify(n)
            info += f"; verify {n}: peak {top / gib:.2f} GiB"
            ok = over is None
            if not ok and n > k1:  # the secant through the OVER case's own (k1, peak) and (n, top) (delta review #3)
                pk1 = pb if over is cases[0] else peak_at(k1, over)
                if over is not cases[0]:
                    info += f"; that case at {k1} kept: {pk1 / gib:.2f} GiB"
                per2 = max(per, (top - pk1) / (n - k1))
                n = int(max(0, min(n - 1, k1 + (target - state - pk1) // per2))) if per2 > 0 else k1
                if n > 0:
                    top, over = verify(n)
                    info += f"; verify {n}: peak {top / gib:.2f} GiB"
                    ok = over is None
            if not ok and 0 < k1 < n:  # last: the measured k1, verified on every case
                n = k1
                top, over = verify(n)
                info += f"; verify {n}: peak {top / gib:.2f} GiB"
                ok = over is None
        if not ok:
            raise _GcKeepStop(f"over the target with every count tried (last {n})")
        if n > 0:  # the planner's speed factor: warm passes (no cache release in between), all checkpointed vs n
            gc_keep_set(mp, n)
            t_n = _gc_time_pass(c, model_wrap, conds, extra_args, device, cases[0], g, sigma)
            gc_keep_set(mp, 0)
            t_0 = _gc_time_pass(c, model_wrap, conds, extra_args, device, cases[0], g, sigma)
            c["gc_keep_slow"] = max(1.0, min(_GC_SLOW_MAX, t_0 / max(t_n, 1e-9)))
            rp = _cuda_reserved_peak()
            info += f"; warm pass {t_0:.2f}s all checkpointed vs {t_n:.2f}s" + (f"; reserved peak {rp / gib:.2f} GiB" if rp else "")
    except _GcKeepStop as e:
        n, info = 0, f"{info}; {e}"
    except torch.cuda.OutOfMemoryError as e:
        n, info = 0, f"{info}; out of memory in a probe pass ({' '.join(str(e).split())[:80]})"
        try:
            _fast_release(e)  # a checkpointed forward that raised must not leave its hooks behind
        except Exception:  # noqa: BLE001
            pass
    except Exception as e:  # noqa: BLE001  (measurement only: every block checkpointed, the run as without the knob)
        n, info = 0, f"{info}; WARN {type(e).__name__}: {str(e)[:120]}"
        try:
            _fast_release(e)
        except Exception:  # noqa: BLE001
            pass
    finally:
        for p in c["params"]:
            p.grad = None
        n = gc_keep_set(mp, n)
        if n == 0:
            c["gc_keep_slow"] = 1.0
        gc.collect()
        _cuda_peak_reset()
    c["gc_keep_n"] = n
    log(f"gc keep: {n} of {nb} blocks without checkpointing (auto: {info}; slow x{c['gc_keep_slow']:.2f}; "
        f"{time.time() - t0:.1f}s)")
    return n


def _gc_keep_oom(c):
    """G56CT_GC_KEEP in _run_one's OOM handlers: with blocks kept and the error raised before the step's optimizer update
    (an update OOM is tagged by _upd_oom_drop: the activations are already freed there and a redo would apply the update
    twice), every block checkpointed again (c['gc_keep_n'] 0; c['gc_keep_replan'] = the drop's time for the planner) -> True,
    the caller redoes the step with its draws; else False and nothing else happens (the knob off: always)."""
    n = c.get("gc_keep_n") or 0
    if n <= 0 or getattr(sys.exc_info()[1], "_g56_update", False):
        return False
    gc_keep_set(c["mp"], 0)
    c["gc_keep_n"], c["gc_keep_replan"] = 0, time.time()
    log(f"OOM -> gradient checkpointing on every block again (G56CT_GC_KEEP had kept {n}); retrying")
    return True


def _gc_keep_unsnap(snap, rng, gen, c, bis, rbe, cur):
    """G56CT_GC_KEEP's redo of a per-step training step, as FAST_WCACHE's: its draws back from the step's snapshot (the
    case / order / band lists, the band sampler's and RB_EMPTY's records, the RNG states) -> (cases, order, band_order,
    visits); cur (the same tuple) as it is when there is no snapshot (FAST_LORA off: the step draws anew)."""
    if snap is None:
        return cur
    o = _wcache_unsnap(snap, rng, gen, c)
    if bis is not None:
        bis.__dict__.update(o["bis"])
    if rbe is not None:
        rbe.__dict__.update(o["rbe"])
    return o["cases"], o["order"], o["band_order"], o["visits"]


def _gc_keep_unsnap_acc(snap, rng, gen, c, group, acc_groups, acc_case):
    """G56CT_GC_KEEP's redo of an accumulated (ACCUM > 1) group, as FAST_WCACHE's: the group list and case counter back from
    the snapshot (the group in its place, the same draws); without a snapshot the group is put back to be redone."""
    if snap is None:
        acc_groups.append(group)
        return acc_groups, acc_case
    o = _wcache_unsnap(snap, rng, gen, c)
    return o["acc_groups"], o["acc_case"]


def _gc_keep_replan(c, dur, t0m):
    """train_loop after a member, when G56CT_GC_KEEP went off by an OOM (c['gc_keep_replan'] = its time): the members that
    ran before the drop ran with blocks kept - their durations x c['gc_keep_slow']; the member in which it happened, the part
    before the drop x the factor; a drop before this member started (an LR pilot) leaves this member as measured (it ran
    with every block checkpointed). The flag is consumed."""
    t_drop = float(c.pop("gc_keep_replan"))
    slow = float(c.get("gc_keep_slow", 1.0) or 1.0)
    for i in range(len(dur) - 1):
        dur[i] *= slow
    if dur:
        fast = max(0.0, min(dur[-1], t_drop - t0m))
        dur[-1] += fast * (slow - 1.0)


_wcache_snap_needed_classic = _wcache_snap_needed


def _wcache_snap_needed(st):  # noqa: F811  (G56CT_GC_KEEP: also while blocks are kept, the redo snapshot)
    """_wcache_snap_needed_classic, or G56CT_GC_KEEP has blocks out of checkpointing (st._g56_gk, gc_keep_set): an OOM there
    redoes the step with its own draws."""
    return _wcache_snap_needed_classic(st) or bool(getattr(st, "_g56_gk", 0))


_upd_oom_drop_classic = _upd_oom_drop


def _upd_oom_drop(fst):  # noqa: F811  (G56CT_GC_KEEP: the update-phase OOM tagged; _upd_oom_drop_classic's behaviour)
    """_upd_oom_drop_classic; the out-of-memory error being handled (an optimizer update / anchor pull OOM) is tagged, so the
    G56CT_GC_KEEP rung of the outer handler does not redo a step whose update may be in (_gc_keep_oom)."""
    e = sys.exc_info()[1]
    if e is not None:
        try:
            e._g56_update = True
        except Exception:  # noqa: BLE001
            pass
    return _upd_oom_drop_classic(fst)


# ----------------------------------------------------------------------------------------------------------------------
# ours (T129, 17 Oct 2026; speed): G56CT_FAST_MERGE_ALPHA - FAST_MERGE's merge with the LoRA scale in the GEMM. _fm_merge builds
# W' = bf16(fp32(W) + s * (U @ D)) as Comfy's LoraDiff does: the fp32 GEMM U @ D, then diff.mul_(s) (a full read + write pass of
# the out x in fp32 product whenever s = alpha / rank != 1), then the rounding add. With the knob on, the product comes from
# torch.addmm(0, U, D, beta=0, alpha=s): the GEMM's epilogue multiplies its fp32 accumulator by s - the same single fp32 rounding as
#
#
# product and compares the two bit for bit; a module whose products differ (another GEMM kernel, another rounding) keeps the
# classic product for good, so W' stays exactly the bytes FAST_MERGE verifies against Comfy's merge (_fm_verify) either way. A
# module with s == 1 (no scale pass) and the knob off take the classic merge itself (the trainer unchanged byte for byte). The
# 'fast merge:' member line counts the modules on each product. Defined at the end of the module (README references keep their
# lines): the name _fm_merge is rebound here, every caller looks it up at call time.
# ----------------------------------------------------------------------------------------------------------------------
CFG.update(fast_merge_alpha=env("FAST_MERGE_ALPHA", False, bool))
_FM_ALPHA = {"alpha": 0, "classic": 0}
_FM_ZERO = {}
_fm_merge_classic = _fm_merge


def _fm_merge(m, ad, dt, s):  # noqa: F811  (G56CT_FAST_MERGE_ALPHA: the classic _fm_merge above when off)
    """G56CT_FAST_MERGE_ALPHA: _fm_merge_classic's (W', bias, W) with s applied in the GEMM epilogue (the note above). Off, or
    s None (scale 1), or a module whose first-use check found other bits: the classic merge itself."""
    if s is None or not CFG.get("fast_merge_alpha") or getattr(ad, "_g56_fma", None) is False:
        return _fm_merge_classic(m, ad, dt, s)
    import torch
    W = _fast_base_weight(m, dt)
    U, D = ad.lora_up.weight, ad.lora_down.weight
    sf = getattr(ad, "_g56_fma_s", None)
    if sf is None:  # the scale as a Python float once per module (LoraDiff's fp32 alpha / rank, exactly)
        sf = ad._g56_fma_s = float(s)
    key = (U.device, U.dtype)
    z = _FM_ZERO.get(key)
    if z is None:
        z = _FM_ZERO[key] = torch.zeros((), device=U.device, dtype=U.dtype)
    try:
        diff = torch.addmm(z, U, D, beta=0, alpha=sf)
    except torch.cuda.OutOfMemoryError:
        raise
    except Exception:  # noqa: BLE001  (this module keeps the classic merge for good; FAST_MERGE itself is untouched)
        ad._g56_fma = False
        _FM_ALPHA["classic"] += 1
        return _fm_merge_classic(m, ad, dt, s)
    if getattr(ad, "_g56_fma", None) is None:  # first use: the classic product bit for bit, or the classic merge for good
        ref = U @ D
        ref.mul_(s)
        same = torch.equal(diff, ref)
        if same and not bool(ref.ne(0).any()):  # U D == 0 (a factor still zero): equal proves nothing (delta review #4) -
            nt = ad._g56_fma_triv = getattr(ad, "_g56_fma_triv", 0) + 1  # undecided, the classic merge this time; after
            if nt >= _FM_TRIVIAL_MAX:  # _FM_TRIVIAL_MAX such first uses the classic product for good (as _fm_verify's rule)
                ad._g56_fma = False
                _FM_ALPHA["classic"] += 1
            return _fm_merge_classic(m, ad, dt, s)
        ad._g56_fma = bool(same)
        _FM_ALPHA["alpha" if same else "classic"] += 1
        if not same:
            diff = ref
    w = torch.empty(W.shape, dtype=dt, device=W.device)
    torch.add(W, diff.reshape(W.shape), out=w)
    b = m.bias.to(dtype=dt) if getattr(m, "bias", None) is not None else None
    return w, b, W  # (_fm_merge_classic's triple; this line differs from its return line: fast_lora_check's fm_cache mutation)


_fm_line_classic = FastLoRAState.fm_line


def _fm_line_alpha(self):
    """FastLoRAState.fm_line + (G56CT_FAST_MERGE_ALPHA on) the modules on the GEMM-scaled / the classic product so far."""
    line = _fm_line_classic(self)
    if CFG.get("fast_merge_alpha"):
        line += f"; merge alpha: {_FM_ALPHA['alpha']} modules scale in the GEMM, {_FM_ALPHA['classic']} classic (first-use check)"
    return line


FastLoRAState.fm_line = _fm_line_alpha


# ----------------------------------------------------------------------------------------------------------------------
#
# MixedPrecisionOps.Linear.set_weight now keeps a LoRA-PATCHED comfy_quant (fp8) layer as BF16 (weight.to(bf16), layout_type None)
# instead of requantize_from_float(scale="recalculate", stochastic_rounding=seed) (ops/docker/patches/comfyui-fp8-lora.patch). Only
# a base with comfy_quant layers changes: ideogram4's 211 fp8 Linears (and fp8_scaled text encoders, for TE keys). The qwen Jib-Mix
# root (F8_E5M2, no comfy_quant) loads as bf16 on the evaluator's 80 GB A100 (disable_weight_init, no set_weight); krea2 / z-image /
# flux are bf16: their scoring is unchanged. Two knobs, both OFF by default (each rebinding below calls the function it replaced, so
# the trainer is unchanged byte for byte but for the new CFG key flux_env_files in the private 'cfg' line / summary; tools/t173_check.py):
#   G56CT_DENSE=lora (ideogram4): no dense pass. The dense file existed to survive the old re-quantization (W0 + dW rounded by GPTQ /
#     hyb onto the grid the evaluator would re-quantize to); on the BF16 patch path the evaluator scores the LoRA's own W0 + up @ down,
#     so the LoRA file as written (its UNC component rows included) ships with IO_FIX's io LoKr pairs (io_ship_lora, the verified
#     fallback (ii): the io matrices on the 2^k grid the training base holds, kept exact by the BF16 path). IO_FIX accepts the value
#     (its io pairs no longer need a dense pass); the GPTQ speed gate, H collection, T164 late gate and T166 disk gate see no gptq
#     (_gptq_mode is False); main()'s deadline reserves IO_EST_S (the io write) instead of DENSE_RESERVE_S, so the hyb / GPTQ time goes
#     back to the members.
#   G56CT_FLUX_ENV_FILES=1 (flux): the validator passes FLUX_T5_PATH / FLUX_CLIP_PATH / FLUX_VAE_PATH to every flux trainer container
#     (G.O.D trainer/runtime.py; the files exist for a standalone single-file base, trainer/containers/downloader.py). Each replaces
#     its baked file (the /app/flux text encoders, BAKED flux_ae: the same public artifacts, pinned at image build) when it exists and
#     holds the baked file's exact structure (tensor names / dtypes / shapes); otherwise the baked file. One private line says which.
#     Today's path reads the baked files and downloads nothing at training time; the knob follows the validator's current files if
#     upstream ever changes them.
# rc-A switches (one constant each; G56CT_PROFILE=c26s applies them at import as family values; an explicit env var wins):
#   T173_C26S_I4_SHIP  "gptq" (rc-A: the dense GPTQ file) | "lora" (the LoRA file, no dense pass) -> the c26s ideogram4 dense value;
#   T173_C26S_FLUX_ENV False (rc-A: the baked files)      | True    -> the c26s flux family value of flux_env_files.
# ----------------------------------------------------------------------------------------------------------------------
CFG.update(flux_env_files=env("FLUX_ENV_FILES", False, bool))
T173_C26S_I4_SHIP = "lora"   # rc-A switch (T173, 23 Oct): the c26s ideogram4 dense value - "gptq" (rc-A) | "lora" (no dense pass)
T173_C26S_FLUX_ENV = False   # rc-A switch (T173): the c26s flux flux_env_files value - False (rc-A) | True
T173_SHIPS = ("gptq", "lora")
_T173 = {"flux": None}


def _t173_c26s():
    """G56CT_PROFILE is c26s (T173's own test, worded apart from the other blocks' profile tests)"""
    return str(os.environ.get("G56CT_PROFILE") or "").strip().lower() == "c26s"


def t173_c26s_values():
    """(ideogram4 dense value, flux flux_env_files value) the rc-A switches give c26s; a ship value outside T173_SHIPS -> 'gptq'
    (rc-A's dense file) and one private WARN line (tools/profile_env_check.py holds the released positions)"""
    ship = str(T173_C26S_I4_SHIP).strip().lower()
    if ship not in T173_SHIPS:
        log(f"WARN profile: T173_C26S_I4_SHIP {T173_C26S_I4_SHIP!r} is not one of {T173_SHIPS}; 'gptq' (rc-A's dense file)")
        ship = "gptq"
    return ship, T173_C26S_FLUX_ENV is True


if _t173_c26s():
    _t173_ship, _t173_fenv = t173_c26s_values()
    FAMILY_DEFAULTS["ideogram4"]["dense"] = _t173_ship
    if _t173_fenv:
        FAMILY_DEFAULTS["flux"]["flux_env_files"] = True
    _t173_wins = lambda k: (f" [G56CT_{k}={os.environ.get('G56CT_' + k)!r} set: it wins]"  # noqa: E731  (the value in effect)
                            if os.environ.get("G56CT_" + k) not in (None, "") else "")
    log(f"profile: c26s -> ideogram4 ship {_t173_ship!r}" + _t173_wins("DENSE") + f"; flux env files {_t173_fenv}"
        + _t173_wins("FLUX_ENV_FILES") + " (T173; rc-A switches T173_C26S_I4_SHIP / T173_C26S_FLUX_ENV)")
    del _t173_ship, _t173_fenv, _t173_wins


def _t173_lora():
    """G56CT_DENSE is 'lora' (T173): the LoRA file + the io pairs, no dense pass"""
    return str(CFG.get("dense") or "").strip().lower() == "lora"


_dense_ship_t173 = dense_ship
_dense_reserve_s_t173 = _dense_reserve_s
_io_fix_apply_t173 = io_fix_apply


def _t173_dense_ship(fam, repo, mp, out_dir, t_start, hours, device):
    """dense_ship with G56CT_DENSE=lora for ideogram4: no dense pass; with IO_FIX's codes, the LoRA file + the io LoKr pairs through
    io_ship_lora (its own time rule, verification and fallback (iii)); the report as dense_ship's. Any other value or family: the
    dense_ship it wraps."""
    if not _t173_lora() or fam != "ideogram4":
        return _dense_ship_t173(fam, repo, mp, out_dir, t_start, hours, device)
    rep = {"mode": "lora", "shipped": False, "skip": "lora (T173): no dense pass for the BF16 patch path"}
    hard = t_start + max(1, int(hours * 3600)) - CFG["dense_margin_s"]
    log("dense: lora (T173) - no dense pass; " + ("the io pairs follow (io_ship_lora)" if _IO_FIX.get("mods") else "the LoRA file ships as written"))
    if _IO_FIX.get("mods"):
        rep["io"] = io_ship_lora(Path(out_dir) / "last.safetensors", repo, mp, hard, device)
    return rep


def _t173_dense_reserve_s():
    """main()'s ideogram4 deadline reserve: G56CT_DENSE=lora -> IO_EST_S when IO_FIX is on (the io write is all that follows the
    members), else 0; any other value: the function it wraps"""
    if _t173_lora():
        return float(CFG["io_est_s"]) if str(CFG.get("io_fix") or "").strip() else 0.0
    return _dense_reserve_s_t173()


def _t173_io_fix_apply(sd, mode, repo, device):
    """io_fix_apply; with G56CT_DENSE=lora its DENSE precondition reads 'gptq' for the call (the io pairs ship with the LoRA file:
    io_ship_lora), CFG['dense'] restored afterwards whatever happens"""
    if not _t173_lora():
        return _io_fix_apply_t173(sd, mode, repo, device)
    old = CFG["dense"]
    CFG["dense"] = "gptq"
    try:
        return _io_fix_apply_t173(sd, mode, repo, device)
    finally:
        CFG["dense"] = old


dense_ship = _t173_dense_ship  # noqa: F811  (main() calls these three by name: T173 off -> the wrapped functions themselves)
_dense_reserve_s = _t173_dense_reserve_s  # noqa: F811
io_fix_apply = _t173_io_fix_apply  # noqa: F811


def _t173_layout(path):
    """{tensor name: (dtype, shape)} from a safetensors header (no tensor data read) of a COMPLETE file - its size == 8 + the header
    + the largest data offset (a truncated copy is refused, review M2); None when unreadable or incomplete"""
    import struct
    try:
        size = os.path.getsize(path)
        with open(path, "rb") as f:
            n = struct.unpack("<Q", f.read(8))[0]
            if n <= 0 or n > 64 * 2 ** 20 or 8 + n > size:
                return None
            h = json.loads(f.read(n))
        h.pop("__metadata__", None)
        end = max((int(v["data_offsets"][1]) for v in h.values()), default=0)
        if size != 8 + n + end:
            return None
        return {k: (v["dtype"], tuple(v["shape"])) for k, v in h.items()}
    except Exception:  # noqa: BLE001
        return None


def t173_flux_files(fam):
    """G56CT_FLUX_ENV_FILES (flux): {'t5' | 'clip' | 'vae': path} of the validator's files that replace their baked file (exists, the
    baked file's exact header structure); {} when none qualifies; None when the knob is off or the family is not flux. Decided once
    per process (one private line)."""
    if fam != "flux" or not CFG.get("flux_env_files"):
        return None
    if _T173["flux"] is not None:
        return _T173["flux"]
    spec = FAMILIES["flux"]
    baked = {"t5": Path(spec["te_files"][0]), "clip": Path(spec["te_files"][1]), "vae": BAKED / spec["vae_file"]}
    out, why = {}, []
    for key, var in (("t5", "FLUX_T5_PATH"), ("clip", "FLUX_CLIP_PATH"), ("vae", "FLUX_VAE_PATH")):
        p = str(os.environ.get(var) or "")
        if not p:
            why.append(f"{key}: {var} unset")
        elif not Path(p).is_file():
            why.append(f"{key}: {var} {p} missing")
        elif not baked[key].is_file():
            why.append(f"{key}: no baked {baked[key]} to compare with")
        elif _t173_layout(p) is None or _t173_layout(p) != _t173_layout(baked[key]):
            why.append(f"{key}: {p} structure != baked {baked[key].name}")
        else:
            out[key] = p
    _T173["flux"] = out
    log(f"flux env files (T173): in use {json.dumps(out)}" + ("; baked: " + "; ".join(why) if why else ""))
    return out


_load_clip_t173 = load_clip
_load_vae_t173 = load_vae


def _t173_load_clip(fam, device, repo=None):
    """load_clip; G56CT_FLUX_ENV_FILES with BOTH validator TE files qualified (and no explicit G56CT_TE_FILE0/1): those two files
    for the call (load_clip's own te_files path: G56CT_TE_FILE0 = t5, 1 = clip), the environment restored afterwards"""
    fl = t173_flux_files(fam)
    if not fl or not (fl.get("t5") and fl.get("clip")) or any(os.environ.get(f"G56CT_TE_FILE{i}") not in (None, "") for i in (0, 1)):
        return _load_clip_t173(fam, device, repo)
    saved = {k: os.environ.get(k) for k in ("G56CT_TE_FILE0", "G56CT_TE_FILE1")}
    os.environ["G56CT_TE_FILE0"], os.environ["G56CT_TE_FILE1"] = fl["t5"], fl["clip"]
    try:
        return _load_clip_t173(fam, device, repo)
    except Exception as e:  # noqa: BLE001  (the validator's files failed to load: the baked files, below)
        log(f"WARN flux env files (T173): the validator TE files did not load ({type(e).__name__}: {str(e)[:120]}); the baked files")
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    return _load_clip_t173(fam, device, repo)


def _t173_load_vae(fam, repo):
    """load_vae; G56CT_FLUX_ENV_FILES with the validator's VAE qualified: that file, exactly as load_vae's comfy branch"""
    fl = t173_flux_files(fam)
    if not fl or not fl.get("vae"):
        return _load_vae_t173(fam, repo)
    try:
        import torch
        import comfy.sd
        import comfy.utils
        vae = comfy.sd.VAE(sd=comfy.utils.load_torch_file(str(fl["vae"])), dtype=torch.float32)
        vae.first_stage_model.eval().requires_grad_(False)
        reg = getattr(vae.first_stage_model, "regularization", None)
        if reg is not None and getattr(reg, "sample", False):
            raise ValueError("VAE would sample the posterior")
        return ("comfy", vae)
    except Exception as e:  # noqa: BLE001  (the validator's VAE failed to load: the baked VAE)
        log(f"WARN flux env files (T173): the validator VAE did not load ({type(e).__name__}: {str(e)[:120]}); the baked VAE")
        return _load_vae_t173(fam, repo)


load_clip = _t173_load_clip  # noqa: F811  (callers look these up by name: the knob off -> the wrapped functions themselves)
load_vae = _t173_load_vae  # noqa: F811


# ----------------------------------------------------------------------------------------------------------------------
# ours (T172, 24 Oct 2026; rc-B): G56CT_KREA2_BIGN_X1H - the krea2 N >= 27 cell's exposure table on a task budget of at least
# T159_KREA2_BIGN_LR_MIN_H (1.0 h: the evidence regime). The value (an alias of T159_EXPOSURE_ALIASES or a spec) replaces the cell's
# table (CFG krea2_bign_exposure) for the run right before T159's cell applies it, so the cell's LR (T170) follows the table it
# applied. An explicit G56CT_KREA2_BIGN_EXPOSURE wins; a budget below 1.0 h (or unknown), a task outside the cell (N <= 26, another
# family, G56CT_FAMILY_DEFAULTS=0, no cell table) or '' / off: nothing (one private line where the cell acts and the knob is set).
# B0F = band 0 at E 8.0 (the spec's unit: round(E x N / 2) cases per prompt half and member, = 4 per image), taken from bands 2-3 (E 5.0
# -> 3.5), the rest = EXLP: the member's case total is EXLP's at N 36 (1440) and within 4 cases (<= 0.4 % for N 27-100) otherwise
# (the rounding: N 42 1690 / 1688, N 43 1716 / 1720): a member moves by <= 4 steps, K / a fill flip only at their thresholds - the
#
#
#
# G56CT_KREA2_BIGN_EXPOSURE of its measured lines byte for byte, its N36 member total 1440; N 27-100 vs EXLP: b10 / b12 within 4 cases,
# b14 18 (<= 1 %), the XTT tables 40.222 E per half, up to 1.51 % more): xb = B0F bands 0-3 + XTT bands 4-15 (T172XB),
# b10 / b12 / b14 = band 0 at E 10 / 12 / 14 (T178 W45-W49), b10x / b12x / b14x = those + XTT's bands 4-15 change (b4-11 -0.25, b12-13
# +0.111, b14-15 +1.0 E vs EXLP), xtt = EXLP bands 0-3 + XTT bands 4-15 (the T172XTT lines).
# ours (T172, 24 Oct 2026; rc-B), second cell: G56CT_KREA2_X075 / G56CT_KREA2_FILL075 - the krea2 14-26 cell (FAMILY_DEFAULTS_BIG_N_BAND
#
# the (image, band) walk (CFG exposure; an explicit G56CT_EXPOSURE wins) and / or the fill-member threshold (CFG seeds_fill; an explicit
# G56CT_SEEDS_FILL wins); it acts right after the task-size defaults; a budget >= 1.0 h or unknown, N outside 14-26, another family or
# G56CT_FAMILY_DEFAULTS=0: nothing. Evidence / rules: PLAN sec. 11 (T172R75 / E75 / F75 lines; both OFF until those verdicts).
# rc-B switches (one constant each; G56CT_PROFILE=c26s applies them at import as the CFG defaults; an explicit env var wins):
#   T172_C26S_KREA2_X1H       "" (off: EXLP at every budget, rc-A) | one of T172_X1H_VALUES (the 1 h table)
#   T172_C26S_KREA2_SMALL075  "" (off: the walk, rc-A) | "exl" (the EXL table)
#   T172_C26S_KREA2_FILL075   0.0 (off: the family's 0.5) | 0.75 (no fill member below 0.75 of the cap)
#   T172_C26S_KREA2_FILL1H    "" (off: the family's 0.5) | "0.55" (the N >= 27 cell on >= 1.0 h: no fill member below 0.55 of the cap -
#                             the SXM5 35cc borderline fill only; 09af 0.66 / 5bea 0.99 keep theirs) | "0" (no fill: not releasable, PLAN sec. 14)
#   T172_C26S_KREA2_X1H_OPENAI / _GOOGLE  "" (no override: the 1 h table above) | one of T172_X1HG_VALUES ("exlp" = rc-A's table): the
#                             1 h table of 'openai' / of 'google' + 'unknown' training sets (below)
# ours (T172, 25 Oct 2026; rc-B, PLAN t178 3.12e; coordinator GO 04:2x WIB): G56CT_KREA2_X1H_OPENAI / G56CT_KREA2_X1H_GOOGLE - the
# krea2 N >= 27 cell's 1 h table by the training set's generator. decode_items records the stored size of every decoded training
# image (nothing else); right after G56CT_KREA2_BIGN_X1H and before T159's cell applies the table (so the cell's lines and its T170
# LR follow it) gen_detect (T058) of that record picks CFG krea2_x1h_openai for 'openai' (every image 1024x768) and CFG
# krea2_x1h_google for 'google' / 'unknown'; the 1 h table's gates (a budget >= 1.0 h, the cell acts, an explicit
# G56CT_KREA2_BIGN_EXPOSURE / G56CT_EXPOSURE wins); a record that does not belong to these N images -> no override (one WARN line).
# '' / off = no override: the table G56CT_KREA2_BIGN_X1H left; both off -> nothing at all, no line. Evidence: the band-0 response of
#
