def _t172_c26s():
    """G56CT_PROFILE is c26s (T172's own wording: the other blocks' profile tests are mutation anchors of their checks, each once)"""
    return "c26s" == str(os.environ.get("G56CT_PROFILE") or "").strip().lower()


def t172_c26s_value():
    """the 1 h table the rc-B switch gives c26s; a value outside T172_X1H_VALUES -> '' (off: rc-A's table) and one private WARN line"""
    val = str(T172_C26S_KREA2_X1H).strip().lower()
    if val not in T172_X1H_VALUES:
        log(f"WARN profile: T172_C26S_KREA2_X1H {T172_C26S_KREA2_X1H!r} is not one of {T172_X1H_VALUES}; '' (off)")
        val = ""
    return val


def t172_small_values():
    """(table, fill) the second cell's rc-B switches give c26s; a value outside its allowed values -> off and one private WARN line"""
    tab = str(T172_C26S_KREA2_SMALL075).strip().lower()
    if tab not in T172_SMALL075_VALUES:
        log(f"WARN profile: T172_C26S_KREA2_SMALL075 {T172_C26S_KREA2_SMALL075!r} is not one of {T172_SMALL075_VALUES}; '' (off)")
        tab = ""
    try:
        fil = float(T172_C26S_KREA2_FILL075)
    except (TypeError, ValueError):
        fil = -1.0
    if fil not in T172_FILL075_VALUES:
        log(f"WARN profile: T172_C26S_KREA2_FILL075 {T172_C26S_KREA2_FILL075!r} is not one of {T172_FILL075_VALUES}; 0.0 (off)")
        fil = 0.0
    return tab, fil


def _t172_wins(var):
    return f" [{var}={os.environ.get(var)!r} set: it wins]" if os.environ.get(var) not in (None, "") else ""


CFG.update(krea2_bign_x1h=env("KREA2_BIGN_X1H", t172_c26s_value() if _t172_c26s() else ""))
_t172_sv = t172_small_values() if _t172_c26s() else ("", 0.0)
CFG.update(krea2_x075=env("KREA2_X075", _t172_sv[0]), krea2_fill075=env("KREA2_FILL075", _t172_sv[1], float))
del _t172_sv


