# ----------------------------------------------------------------------------------------------------------------------
# ours (T179, 25 Oct 2026; coordinator decision B: a real-defect fix, active by default): on a slow disk the seeds-auto fill member's
# margin counts the armed final transform. train_loop plans its shortened last member (fill_member_steps) to end margin + PLAN_MARGIN_S
# - 30 before the deadline (margin = 30 s + the slow-disk part of _save_margin), which never counted the armed final transform
# (T157_EST: flux-fc / zimg-p1): on sph14 (~123 MB/s: 3.51 GB written in 28.6 s) z-image P1 failed its skip rule ('zimg-p1: skipped
# (34s to the watchdog stop < the estimated 42s)') and flux FC ran 4 s past the deadline. Two wrappers by assignment, no line above
# edited: _save_margin keeps the run's context (its value unchanged); fill_member_steps re-plans the fill with the predicted tail's
# excess added to its margin, only when the measured write time per byte is above T179_SLOW_SPB (~200 MB/s): a faster disk (Shadeform /
# sph12 / Oblivus ~0.7-0.9 GB/s, box 2 ~330 MB/s from the final rewrites) plans as before; a fill the excess would drop stays as planned.
# G56CT_TAIL_SLOW_SPB (25 Oct, value knob, unset = T179_SLOW_SPB = this rule as before): 0 = the rule on every disk (_t179_slow_spb).
T179_SLOW_SPB = 0.0  # s per byte: the rule on every disk (TS0 flip, T202 audit 26 Oct: acts only where the tail would not fit; was 5e-9 = ~200 MB/s)
T179_MIN_BYTES = 1e8  # a member file below 100 MB never acts: its time per byte is the writes' fixed overhead (synthetic test states)
_T179 = {"c": None, "said": set()}
_save_margin_t179 = _save_margin


def _t179_slow_spb():
    """G56CT_TAIL_SLOW_SPB (T179, 25 Oct 2026, coordinator 16:2x: insurance for Monday if C8 is rejected): the measured write time per
    byte above which this rule acts. Unset = T179_SLOW_SPB (the rule exactly as before); 0 = on every disk (box 2, z-image 0.5 h K 8,
    5.61 GB at ~285 MB/s: 'zimg-p1: skipped (31s to the watchdog stop < the estimated 32s)'); not a number >= 0 = the default, one
    private WARN. Read once per process."""
    if "spb" not in _T179:
        raw, v = str(os.environ.get("G56CT_TAIL_SLOW_SPB", "") or "").strip(), T179_SLOW_SPB
        if raw:
            try:
                f = float(raw)
                if not (f >= 0 and math.isfinite(f)):
                    raise ValueError(raw)
                v = f
            except ValueError:
                log(f"WARN seeds-auto: G56CT_TAIL_SLOW_SPB {raw!r} is not a number >= 0; {T179_SLOW_SPB:g} (T179)")
        _T179["spb"] = v
    return _T179["spb"]


def _t179_save_margin(c):
    """_save_margin itself (the same value); the run's context c is kept for _t179_fill_member_steps (member count and sizes)."""
    _T179["c"] = c
    return _save_margin_t179(c)


def _t179_tail(margin):
    """(seconds the predicted tail after the fill member exceeds its planned end before the deadline, tag, tail) on a slow disk with an
    armed final transform, else (0.0, None, 0.0). tail = the final file's canonical form (the reference save's time, linear in
    members: rank k1 x r, units x k1^2) + its write + the transform's own estimate (_t157_run's skip-rule formula); the planned end is
    margin + PLAN_MARGIN_S - 30 before the deadline (fill_member_steps)."""
    fin, c = _T157.get("fin"), _T179.get("c")
    tag = fin[0] if fin else None
    spb = float(_SAVE_STATS.get("spb") or 0.0)
    if tag not in T157_EST or spb <= _t179_slow_spb() or not c or float(c.get("member_bytes", 0) or 0) < T179_MIN_BYTES:
        return 0.0, None, 0.0
    k1 = int(c.get("k_done", 0)) + 1
    nb = k1 * float(c.get("member_bytes", 0) or 0)
    ref, mu = _SAVE_STATS.get("canon_ref"), float(c.get("member_units", 0) or 0)
    canon = ref[1] * k1 * math.sqrt(mu / ref[0]) if ref and ref[0] > 0 and mu > 0 else 0.0
    tail = canon + spb * nb + T157_EST[tag][0] + T157_EST[tag][1] * nb + 2.0 + spb * nb
    dmargin = float(CFG.get("plan_margin_s", 30.0)) - 30.0  # the value of the T126 helper _t126_dmargin, inline (t126_check pins its call count)
    return max(0.0, tail - float(margin) - dmargin), tag, tail


_fill_member_steps_t179 = fill_member_steps


def _t179_fill_member_steps(durs, steps, remaining, full_cap, frac, margin=30.0, safety=1.10):
    """fill_member_steps itself, except on a slow disk with an armed final transform (_t179_tail): the fill planned with the tail's
    excess added to the margin; a fill that excess would drop (below the fill threshold) stays as planned (a fill member is worth more
    than the transform). One private line per decision. Any error: the plan as before."""
    n = _fill_member_steps_t179(durs, steps, remaining, full_cap, frac, margin, safety)
    try:
        if n <= 0 or n >= full_cap:
            return n
        x, tag, tail = _t179_tail(margin)
        if x <= 0:
            return n
        n2 = _fill_member_steps_t179(durs, steps, remaining, full_cap, frac, margin + x, safety)
        if (n, n2) not in _T179["said"]:
            _T179["said"].add((n, n2))
            thr = _t179_slow_spb()
            log(f"seeds-auto: fill member {n} -> {n if n2 <= 0 else n2} steps for the armed {tag} (T179: write "
                f"{1e-6 / float(_SAVE_STATS['spb']):.0f} MB/s " + (f"< {1e-6 / thr:.0f} MB/s" if thr > 0 else "(G56CT_TAIL_SLOW_SPB 0: every disk)")
                + f"; predicted tail {tail:.0f}s, margin +{x:.0f}s"
                + ("; kept: the margin would drop the fill member)" if n2 <= 0 else ")"))
        return n if n2 <= 0 else n2
    except Exception:  # noqa: BLE001  (never ends a run: the plan as before)
        return n


_t179_save_margin.__wrapped__ = _save_margin_t179  # inspect.getsource(_save_margin) -> the trainer's own
_t179_fill_member_steps.__wrapped__ = _fill_member_steps_t179  # inspect.getsource(fill_member_steps) -> the trainer's own
_save_margin = _t179_save_margin  # noqa: F811  (train_loop / _run_one call it by name)
fill_member_steps = _t179_fill_member_steps  # noqa: F811  (train_loop / stretch_plan_keepk call it by name)


# ----------------------------------------------------------------------------------------------------------------------
# ours (T193, 25 Oct 2026; owner 25 Oct 17:5x WIB via the coordinator: new code when proven; default OFF): G56CT_ZIMG_P1 takes ONE more
# part, 'tail<K0>:<S>' (e.g. 'tail64:1.6;tpb:0.853,0.212;attn:1.1'). With it, before P1, every module of the z-image state (the 208 of
# the shipped file) has its canonical components i >= K0 scaled - lora_up' = float32(float64(lora_up) x f), f = [1] * K0 + [S] * (R - K0)
#
# that state (its TPB rows from the tail-scaled LoRA, its group factors on top), so the shipped file == zt21_ops + zbed.py on the
# untransformed final file (T193 PLAN.md: the fcp1_check --real proof). A value without a tail part takes the original parser and
# transform object: the release value 'tpb:0.853,0.212;attn:1.1' runs exactly as before (the trainer unchanged in behaviour).
# Refused (the state written as given, as P1's own refusals): SAVE_BF16, the identity state, a module outside the canonical form with
# alpha == rank (_t157_canon), a module of rank <= K0, a state of != 208 modules. A failed tail verification, or P1 refusing / failing on
# the tail-scaled state, ships the state as given (never a half-transformed file). A parsed tail adds T193_TAIL_SPB s per state byte to
# the zimg-p1 skip-rule estimate T157_EST (the FC pass's cost; the T179 tail rule reads the same table).
#
#
# ----------------------------------------------------------------------------------------------------------------------
T193_TAIL_SPB = 1.3e-9         # s per state byte the tail adds to the zimg-p1 estimate (FC's ~1.3 s per GB, comfytrain/tools/fcp1_check.py --bench)
T193_TAIL_MODS = 208           # the z-image file's module count (zt21_ops.py --expect-scaled 208)
_t193_p1_spec0, _t193_p1_0 = _t157_p1_spec, _t157_p1
_T193 = {"est": False}


def _t157_p1_spec(spec):  # noqa: F811  (T193: + one 'tail<K0>:<S>' part; no tail part = the original parser, its result unchanged)
    parts = [p.strip() for p in spec.split(";")]
    tl = [p for p in parts if p.startswith("tail")]
    if not tl:
        return _t193_p1_spec0(spec)
    if len(tl) != 1:
        raise ValueError("tail: at most one tail part")
    m = re.fullmatch(r"tail(\d+):([0-9]+(?:\.[0-9]+)?)", tl[0])
    if not m:
        raise ValueError(f"{tl[0]}: tail<K0>:<S>")
    k0, sc = int(m.group(1)), float(m.group(2))
    if k0 < 1 or not (math.isfinite(sc) and 0.0 < sc <= 4.0):
        raise ValueError(f"{tl[0]}: K0 >= 1 and S in (0, 4]")
    inner = _t193_p1_spec0(";".join(p for p in parts if not p.startswith("tail")))
    if not _T193["est"]:
        a, b = T157_EST["zimg-p1"]
        T157_EST["zimg-p1"] = (a, b + T193_TAIL_SPB)
        _T193["est"] = True
    return ("T193TAIL", k0, sc, inner)


def _t157_p1(parsed, sd):  # noqa: F811  (T193: the tail first, then the original P1 on the tail-scaled state)
    if not (isinstance(parsed, tuple) and len(parsed) == 4 and parsed[0] == "T193TAIL"):
        return _t193_p1_0(parsed, sd)
    import torch
    _, k0, sc, inner = parsed
    if CFG.get("save_bf16"):
        raise _T157Refuse("G56CT_SAVE_BF16 (the tail scales F32 canonical factors)")
    if _t157_zero(sd):
        raise _T157Refuse("identity state: every lora_up is zero")
    mods = _t157_mods(sd)
    if len(mods) != T193_TAIL_MODS:
        raise _T157Refuse(f"tail: {len(mods)} modules, the shipped z-image file {T193_TAIL_MODS}")
    for m, ks in mods.items():
        dn = sd[ks[".lora_down.weight"]]
        _t157_canon(m, sd[ks[".lora_up.weight"]], dn, _t157_alpha(sd, m))
        if dn.shape[0] <= k0:
            raise _T157Refuse(f"tail: {m} has rank {dn.shape[0]} <= K0 {k0}")

    def fvec(n):
        f = torch.ones(n, dtype=torch.float64)
        f[k0:] = sc
        return f
    st = {k: ((v.to(torch.float64) * fvec(v.shape[1])).to(torch.float32).contiguous() if k.endswith(".lora_up.weight") else v)
          for k, v in sd.items()}
    for k, v in sd.items():  # verify (b20f_ops.py verify): the scaled bytes == float32(float64(src) x f), every other entry kept
        if k.endswith(".lora_up.weight"):
            want = (v.to(torch.float64) * fvec(v.shape[1])).to(torch.float32)
            if st[k].dtype != torch.float32 or st[k].shape != v.shape or not torch.equal(st[k].view(torch.int32), want.view(torch.int32)):
                return sd, f"WARN zimg-p1: tail verification failed ({k}); written as given"
        elif st[k] is not v:
            return sd, f"WARN zimg-p1: tail verification failed ({k} not the state's own tensor); written as given"
    out, msg = _t193_p1_0(inner, st)
    if out is st:   # P1 failed its own verification on the tail-scaled state: ship the state as given, not a half-transformed one
        return sd, f"{msg} (tail{k0}:{sc:g} dropped with it)"
    return out, msg.replace("zimg-p1: ON ", f"zimg-p1: ON tail{k0}:{sc:g} on {len(mods)} modules, then ", 1)



# ----------------------------------------------------------------------------------------------------------------------
# ours (T194, 25 Oct 2026; owner GO 18:4x WIB via the image coordinator): planner v2 in a qwen-image cell keeps the D15 window.
# OFF by default: it acts only when G56CT_PLANNER=v2 AND G56CT_PLANNER_CELLS holds a qwen-image cell (the default cells
# 'krea2:27:2.0,ideogram4:31:1.25' have none; the value of the switch is e.g. 'krea2:27:2.0,qwen-image:20:1.3'). Then:
#   (1) v2 runs for qwen-image only in the Jib D15 cell (CFG qf8_d15 on: c26s sets it in the F8_E5M2 basecond cell); any other
#       qwen run keeps the v2safe rules (_t159_v2_off, wrapped by assignment);
#   (2) v2 LENGTHENS the members only up to the deadline less T194 D15 reserve = g56qd15.estimate_s of the D15 pass (the 180 S15
#       matrices, T194_D15_ELEMENTS, at QF8_D15_EST_US per element per worker, workers = _t167_workers) + the D15 pass's tail
#       (qf8_d15_ship's 10 s + 2 x bytes / 400 MB/s) + T194_D15_SLACK_S (the steps between the last write and the D15 check):
#       _T159Plan.length is called with the deadline moved earlier by that reserve. K is NOT touched (_T159Plan.fit is the v2
#       rule as before: the reserve never costs a member; when even the base length leaves less than the reserve, the members
#       keep the base length and the D15 gate decides at the end, exactly as without the switch).
# Why: qwen Jib 1.5 h leaves 17-28 % of the budget idle after K members + D15 (6173 SXM5 K2: 931 s, PCIe K1: ~1520 s); v2 alone
#
#
# ----------------------------------------------------------------------------------------------------------------------
T194_D15_ELEMENTS = 3397386240  # the D15 plan's elements: 15 S15 blocks x (8 attn 3072^2 + 4 mlp 3072 x 12288) ('3.40 G elements')
T194_D15_SLACK_S = 45.0
T194_D15_MEMBER_CAP_B = 3.0e9  # one member's bytes in the estimate at most (Jib K1 LoRA file 1.41 GB, K2 2.59 GB)
T194_D15_FALLBACK_S = 420.0   # the reserve when its own estimate cannot be computed (the largest projection seen, 244 + 38 s, + slack)
_T194 = {"said": set()}


def t194_d15_armed(fam):
    """qwen-image with D15 on (the Jib D15 cell): the only qwen runs the T194 v2 cell plans"""
    return fam == "qwen-image" and bool(CFG.get("qf8_d15"))


def t194_d15_reserve(plan, K):
    """seconds v2 keeps free before the deadline for the D15 pass of a K-member qwen Jib run: g56qd15.estimate_s's arithmetic
    (fixed 15 s + elements x QF8_D15_EST_US us / min(workers, 8) + 2 x bytes / 400 MB/s; inlined: no numpy at plan time) + the
    D15 pass's tail (qf8_d15_ship: 10 s + 2 x bytes / 400 MB/s) + T194_D15_SLACK_S. Never raises: any problem ->
    T194_D15_FALLBACK_S (a reserve that only shortens the lengthening; K is never touched)."""
    try:
        w = max(1, min(int(_t167_workers()[0]), 8))
        mb = min(sum(int(p.numel()) for p in plan.c["params"]) * (2 if CFG.get("save_bf16") else 4), T194_D15_MEMBER_CAP_B)
        nb = T194_D15_ELEMENTS + max(1, int(K)) * mb   # >= the D15 file (e4m3 codes + the kept tensors; folded LoRA counted too)
        est = 15.0 + T194_D15_ELEMENTS * float(CFG.get("qf8_d15_est_us", 0.45)) * 1e-6 / w + 2.0 * nb / 400e6
        return est + 10.0 + 2.0 * nb / 400e6 + T194_D15_SLACK_S
    except Exception as e:  # noqa: BLE001  (the planner never fails on the reserve)
        if "err" not in _T194["said"]:
            _T194["said"].add("err")
            log(f"WARN planner-v2: qwen D15 reserve: {type(e).__name__}: {str(e)[:120]}; {T194_D15_FALLBACK_S:g}s reserved")
        return T194_D15_FALLBACK_S


_t194_length_t159 = _T159Plan.length


def _t194_length(self, now, D, K, j, cur):
    """_T159Plan.length; a qwen Jib D15 run: with the deadline less the D15 reserve (never below the base length)"""
    if not t194_d15_armed(self.fam):
        return _t194_length_t159(self, now, D, K, j, cur)
    r = t194_d15_reserve(self, K)
    L = _t194_length_t159(self, now, D - r, K, j, cur)
    if ("res", K) not in _T194["said"]:
        _T194["said"].add(("res", K))
        log(f"planner-v2: qwen D15 window kept: {r:.0f}s reserved before the deadline for the D15 pass (K {K}; T194)")
    return L


_T159Plan.length = _t194_length
_t194_v2_off_t159 = _t159_v2_off


def _t159_v2_off(c):  # noqa: F811  (T194: a qwen-image v2 cell plans the Jib D15 cell only)
    fam = c.get("fam") or _T157.get("fam")
    if fam == "qwen-image" and not t194_d15_armed(fam):
        return "qwen-image without D15 (the T194 qwen v2 cell plans the Jib D15 cell only)"
    return _t194_v2_off_t159(c)


