def t210_io_fold_sd(sd, mods, prefix="diffusion_model."):
    """G56CT_IO_FOLD core (pure: torch only): sd = the LoRA file's tensors, mods = _IO_FIX["mods"] {module: (k, d codes uint8)}.
    Returns (out, totals): out = sd with every io module m that has '<prefix>m.lora_up.weight' folded into '<prefix>m.diff'
    (float32 = 2^k * float(d8) + up @ down * alpha / rank) and the LoKr pairs of the other io modules added; totals = {m: diff}.
    Raises ValueError on a shape mismatch or another key of a folded module."""
    import torch
    import g56dense as DN
    out = dict(sd)
    ov = [m for m in sorted(mods) if prefix + m + ".lora_up.weight" in out]
    totals = {}
    for m in ov:
        up = out.pop(prefix + m + ".lora_up.weight").float()
        dn = out.pop(prefix + m + ".lora_down.weight").float()
        al = out.pop(prefix + m + ".alpha", None)
        a = float(al) if al is not None else float(dn.shape[0])
        if any(k_.startswith(prefix + m + ".") for k_ in out):
            raise ValueError(f"{m}: the LoRA file holds other keys of this module")
        k_, d_ = mods[m]
        rest = (2.0 ** int(k_)) * d_.contiguous().view(torch.float8_e4m3fn).float()
        dl = (up @ dn) * (a / dn.shape[0])
        if tuple(rest.shape) != tuple(dl.shape):
            raise ValueError(f"{m}: restoration {tuple(rest.shape)} vs LoRA delta {tuple(dl.shape)}")
        totals[m] = (rest + dl).contiguous()
        out[prefix + m + ".diff"] = totals[m]
    out.update(DN.io_lokr_tensors({m: v for m, v in mods.items() if m not in totals}))
    return out, totals


def _t210_io_fold_ship(final, repo, mp, hard, device):
    """io_ship_lora with G56CT_IO_FOLD (the note above); IO_FOLD off, IO_FIX off or no io module in the LoRA file: the function it
    wraps, exactly."""
    if not CFG.get("io_fold") or not _IO_FIX.get("mods"):
        return _io_ship_lora_t210(final, repo, mp, hard, device)
    import torch
    from safetensors import safe_open
    from safetensors.torch import save_file
    final = Path(final)
    P = "diffusion_model."
    with safe_open(str(final), framework="pt", device="cpu") as fl:
        lkeys = set(fl.keys())
    if not any(P + m + ".lora_up.weight" in lkeys for m in _IO_FIX["mods"]):
        return _io_ship_lora_t210(final, repo, mp, hard, device)
    rep = {"modules": len(_IO_FIX["mods"]), "in": "none", "fold": []}
    tmp = final.parent.parent / f".{final.parent.name}.io.tmp"
    t0 = time.time()
    try:
        import comfy.lora
        if hard - time.time() < CFG["io_est_s"]:
            raise ValueError(f"{hard - time.time():.0f}s before the hard stop < IO_EST_S {CFG['io_est_s']:g}s")
        with safe_open(str(final), framework="pt", device="cpu") as fl:
            sd = {k_: fl.get_tensor(k_) for k_ in fl.keys()}
            meta = fl.metadata()
        out, totals = t210_io_fold_sd(sd, _IO_FIX["mods"], P)
        save_file(fg_inject(out), str(tmp), metadata=meta)
        del out
        with safe_open(str(tmp), framework="pt", device="cpu") as fv:
            vsd = {k_: fv.get_tensor(k_) for k_ in fv.keys()}
        want = (set(sd) - {P + m + s_ for m in totals for s_ in (".lora_up.weight", ".lora_down.weight", ".alpha")}) \
            | {P + m + ".diff" for m in totals} | {P + m + s_ for m in _IO_FIX["mods"] if m not in totals for s_ in (".lokr_w1", ".lokr_w2")}
        if set(vsd) != want:
            raise ValueError(f"key set differs: missing {sorted(want - set(vsd))[:2]} extra {sorted(set(vsd) - want)[:2]}")
        for k_ in sd:
            if k_ in vsd and not torch.equal(sd[k_].reshape(-1).contiguous().view(torch.uint8), vsd[k_].reshape(-1).contiguous().view(torch.uint8)):
                raise ValueError(f"{k_} differs from the LoRA file")
        n, missing = verify_lora_loadable(mp, vsd)
        if missing:
            raise ValueError(f"{len(missing)} keys not consumed, e.g. {missing[0][:100]}")
        patches = comfy.lora.load_lora(vsd, comfy.lora.model_lora_keys_unet(mp.model, {}), log_missing=False)
        for m, d_ in totals.items():
            pk = [v for kk, v in patches.items() if (kk[0] if isinstance(kk, tuple) else kk) == P + m + ".weight"]
            if len(pk) != 1 or not (isinstance(pk[0], tuple) and pk[0][0] == "diff" and torch.equal(pk[0][1][0].float(), d_)):
                raise ValueError(f"{m}: the evaluator's patch is not the folded diff ({type(pk[0]).__name__ if pk else 'none'})")
        if time.time() > hard:
            raise ValueError("hard stop passed after the io fold write")
        os.replace(tmp, final)
        try:
            os.chmod(final, 0o644)
        except Exception:  # noqa: BLE001
            pass
        rep.update({"in": "lora+fold", "fold": sorted(totals), "seconds": round(time.time() - t0, 1)})
        log(f"io fold: {len(totals)} io module(s) shipped as one float32 '.diff' each (restoration + trained delta) "
            f"{json.dumps({m: list(d_.shape) for m, d_ in totals.items()})}, {len(_IO_FIX['mods']) - len(totals)} as io LoKr pairs; "
            f"{final.stat().st_size / 1e9:.2f} GB ({time.time() - t0:.0f}s)")
    except Exception as e:  # noqa: BLE001  (never fails the run): drop the io LoRA keys, ship the io pairs as today
        try:
            tmp.unlink()
        except FileNotFoundError:
            pass
        rep["skip"] = f"{type(e).__name__}: {str(e)[:200]}"
        log(f"WARN io fold: {rep['skip']}; the io LoRA keys are dropped and the io pairs ship as without the knob")
        try:
            with safe_open(str(final), framework="pt", device="cpu") as fl:
                sd = {k_: fl.get_tensor(k_) for k_ in fl.keys()}
                meta = fl.metadata()
            for m in _IO_FIX["mods"]:
                for s_ in (".lora_up.weight", ".lora_down.weight", ".alpha"):
                    sd.pop(P + m + s_, None)
            tmp2 = final.parent.parent / f".{final.parent.name}.io2.tmp"
            save_file(fg_inject(sd), str(tmp2), metadata=meta)
            os.replace(tmp2, final)
            rep["io"] = _io_ship_lora_t210(final, repo, mp, hard, device)
        except Exception as e2:  # noqa: BLE001
            log(f"WARN io fold: the fallback failed too ({type(e2).__name__}: {str(e2)[:120]}); the LoRA file ships as written")
    return rep


io_ship_lora = _t210_io_fold_ship  # noqa: F811  (T210: _t173_dense_ship calls it by name; IO_FOLD off -> the wrapped function)


# ----------------------------------------------------------------------------------------------------------------------
# G56CT_FAST_TRIM (T210, 28 Oct 2026; speed; OFF by default: with 0 nothing below is bound and the trainer is unchanged byte for
# byte). The 28 Oct qwen-image profile (paired r32, FAST_LORA + FAST_MERGE): 61 472 kernels per step, most of them tiny casts of
# the LoRA path - every fast forward / backward of every LoRA Linear casts lora_up, lora_down, s * lora_down and the frozen
# bias to the compute dtype again, and _mm32_hl spends two kernels on its fp32 remainder (a.float() then a - hi). With
# FAST_TRIM 1, on the FAST_FWD forward (_fast_lr_inputs / _fast_lr_y) and the fast backward (_fast_backward):
#  - the compute-dtype copies of lora_up / lora_down / s * lora_down and of the frozen bias are made once per training step
#    and served again inside that step (paired: 2 forwards + 2 backwards; balanced: 1 + 1): the cache is emptied at the start
#    of every step (stretch_tail_step, called once per step by _run_one), and inside a step an entry is served only while
#    its key (data_ptr, _version, dtype, shape, the scale's value) still matches; the copy is the same .to() / mul call on
#    the same input, so its bytes are the per-use ones;
#  - _mm32_hl's remainder is torch.sub(a, hi) (fp32 minus the exactly promoted compute-dtype hi, one kernel) instead of
#    a - hi.float() (two): the same fp32 values element for element.
# Self-check: the first _TRIM_CHECKS uses of every key compare the served copy with a fresh one (torch.equal), and every
# _TRIM_EVERY-th use after that; any difference (or exception) switches FAST_TRIM off for the rest of the run (one WARN line)
# and the call takes the untrimmed function. Counts in one private line at the end of member 1 (_t210_trim_line).
# ----------------------------------------------------------------------------------------------------------------------
CFG.update(fast_trim=env("FAST_TRIM", False, bool))
_TRIM = {"on": False, "cache": {}, "hits": 0, "made": 0, "checks": 0, "said": False, "scale": {}, "nserve": {}}
_TRIM_CHECKS, _TRIM_EVERY = 2, 4096
_fast_lr_y_t210, _fast_lr_inputs_t210, _fast_backward_t210, _mm32_hl_t210 = _fast_lr_y, _fast_lr_inputs, _fast_backward, _mm32_hl


def _t210_trim_off(why):
    if _TRIM["on"]:
        _TRIM["on"] = False
        log(f"WARN fast trim: off for the rest of the run ({why})")


def _t210_scale(ad):
    """LoraDiff's alpha / rank as a Python float, computed ONCE per adapter (one device read) and served again while alpha is
    unchanged (key: alpha's data_ptr and _version): a float in the cache keys and in mul_ costs no host sync per call, and it is
    exactly the fp32 value of the 0-dim tensor (so x * s and x.mul_(s) give the bytes the tensor operand gives)."""
    a = ad.alpha
    key = (a.data_ptr(), a._version, ad.rank)
    ent = _TRIM["scale"].get(id(ad))
    if ent is None or ent[0] != key:
        ent = (key, float((a / ad.rank).detach()))
        _TRIM["scale"][id(ad)] = ent
    return ent[1]


def torch_equal(a, b):
    import torch
    return torch.equal(a, b)


def _t210_trim_cast(t, dt, scale=None):
    """t.detach().to(dt) (scale None) or (t.detach() * scale).to(dt), served from the FAST_TRIM cache while t is unchanged."""
    s_key = None if scale is None else float(scale)
    key = (id(t) if not t.is_cuda else t.data_ptr(), t._version, dt, tuple(t.shape), s_key)
    slot = (t.data_ptr(), dt, s_key)
    ent = _TRIM["cache"].get(slot)
    if ent is not None and ent[0] == key:
        n = _TRIM["nserve"].get(slot, 0) + 1  # serves of this slot over the RUN (the per-step cache is emptied every step)
        _TRIM["nserve"][slot] = n
        _TRIM["hits"] += 1
        if n <= _TRIM_CHECKS or n % _TRIM_EVERY == 0:  # a host sync: only the first serves of a slot and every 4096th
            fresh = t.detach().to(dt) if scale is None else (t.detach() * scale).to(dt)
            _TRIM["checks"] += 1
            if not (fresh.dtype == ent[1].dtype and fresh.shape == ent[1].shape and bool(torch_equal(fresh, ent[1]))):
                _t210_trim_off(f"a served copy differs from a fresh cast (shape {tuple(t.shape)}, {dt})")
                return fresh
        return ent[1]
    v = t.detach().to(dt) if scale is None else (t.detach() * scale).to(dt)
    _TRIM["cache"][slot] = [key, v, 0]
    _TRIM["made"] += 1
    return v


def _t210_fast_lr_y(x, w, bias, lora_up, lora_down, s):
    """_fast_lr_y with the FAST_TRIM factor copies (the same calls on the same copies' bytes)."""
    if not _TRIM["on"]:
        return _fast_lr_y_t210(x, w, bias, lora_up, lora_down, s)
    import torch
    dt = x.dtype
    y = torch.nn.functional.linear(x, w, bias)
    if not y.is_contiguous():
        y = y.contiguous()
    h = torch.mm(x.reshape(-1, x.shape[-1]), _t210_trim_cast(lora_down, dt).t())
    y.view(-1, y.shape[-1]).addmm_(h, _t210_trim_cast(lora_up, dt).t(), alpha=s)
    return y


def _t210_fast_lr_inputs(m, x):
    """_fast_lr_inputs with the frozen bias's compute-dtype copy served from the FAST_TRIM cache."""
    if not _TRIM["on"]:
        return _fast_lr_inputs_t210(m, x)
    import torch
    with torch.no_grad():
        w = _fast_base_weight(m, x.dtype)
        b = _t210_trim_cast(m.bias, x.dtype) if getattr(m, "bias", None) is not None else None
    return w, b


def _t210_mm32_hl(a, b):
    """_mm32_hl with the remainder in one kernel: torch.sub(a, hi) = a - hi.float() element for element (exact promotion)."""
    import torch
    f32 = torch.float32
    if a.dtype == f32 and b.dtype == f32:
        return torch.mm(a, b)
    if a.dtype == f32:
        hi = a.to(b.dtype)
        return _mm32(hi, b).add_(_mm32(torch.sub(a, hi).to(b.dtype), b))
    hi = b.to(a.dtype)
    return _mm32(a, hi).add_(_mm32(a, torch.sub(b, hi).to(a.dtype)))


def _t210_fast_backward(rec, need, gy, x, up, down):
    """_fast_backward with the FAST_TRIM factor copies and _t210_mm32_hl (the same products on the same bytes)."""
    if not _TRIM["on"]:
        return _fast_backward_t210(rec, need, gy, x, up, down)
    import torch
    m, ad, st, name = rec
    dt = gy.dtype
    gy2 = gy.reshape(-1, gy.shape[-1])
    x2 = x.reshape(-1, x.shape[-1])
    s = _t210_scale(ad)  # a Python float (no host sync per call; the fp32 value of alpha / rank)
    gyu = _mm32(gy2, _t210_trim_cast(up, dt)) if (need[0] or need[4]) else None
    gx = gu = gd = None
    if need[0]:
        gx = torch.mm(gyu.to(dt), _t210_trim_cast(down, dt, s)).addmm_(gy2, _fast_base_weight(m, dt)).reshape(x.shape)
    if need[3]:
        gu = _t210_mm32_hl(gy2.t(), _mm32(x2, _t210_trim_cast(down, dt).t())).mul_(s)
    if need[4]:
        gd = _t210_mm32_hl(gyu.t(), x2).mul_(s)
    if st.probe is not None:
        _fast_probe(st, name, m, ad, gy2, x2, up.detach(), down.detach(), gx, gu, gd)
    return gx, gu, gd


def _t210_trim_line():
    """One private line with the FAST_TRIM counts (once)."""
    if CFG.get("fast_trim") and not _TRIM["said"]:
        _TRIM["said"] = True
        log(f"fast trim: {'on' if _TRIM['on'] else 'OFF'}; {_TRIM['made']} copies made, {_TRIM['hits']} served, "
            f"{_TRIM['checks']} served copies checked against a fresh cast (all equal: {_TRIM['on']}); {len(_TRIM['cache'])} keys")


# G56CT_FAST_LRB (T210, 28 Oct 2026; speed; OFF by default: nothing below is bound and the trainer is unchanged). The fast
# backward's two factor gradients each run two token-contraction GEMMs (_mm32_hl: the fp32 tokens x r operand as hi + lo
# compute-dtype parts) and the FAST_FWD backward recomputes x D^T (fp32) that its forward already formed. With FAST_LRB 1:
#  - gu = s gy^T [hi | lo] and gd = s [hi ; lo] x: ONE GEMM per factor on the stacked parts (N or M = 2r), the two halves
#    summed in fp32 - the same products and the same fp32 sum as the two GEMMs, up to the GEMM's own fp32 accumulation order;
#  - the FAST_FWD forward forms x D^T once with an fp32 result (mm out_dtype, = _mm32), rounds it to the compute dtype for the
#    side product (what the compute-dtype GEMM's epilogue does) and keeps it for its backward (tokens x r fp32 per module:
#    ~0.3 MB at 2k tokens, r 32), so the backward has no x D^T GEMM.
# Numerics: not bit-identical (accumulation order) - fast_lora_guard's local test (fast vs the old path's formulas, every
# module) and FAST_FWD's first-use check run on these functions as on the ones they replace. Any exception on the fast path
# switches it off as before (FastLoRAFallback: the step is redone on the old path).
CFG.update(fast_lrb=env("FAST_LRB", False, bool))
_FAST_FN_LRB = []
_fast_fn_lr_t210 = _fast_fn_lr


def _t210_c(t, dt, scale=None):
    """the compute-dtype copy of a LoRA factor: FAST_TRIM's per-step copy when that knob is on, else a fresh cast"""
    if _TRIM["on"]:
        return _t210_trim_cast(t, dt, scale)
    return t.detach().to(dt) if scale is None else (t.detach() * scale).to(dt)


def _t210_hl_cat_left(a32, b):
    """(a32 @ b) with a32 fp32 r x T (or any fp32 left factor) and b compute dtype T x n: ONE _mm32 on [hi ; lo] (2r x T)."""
    import torch
    r = a32.shape[0]
    buf = torch.empty((2 * r, a32.shape[1]), dtype=b.dtype, device=b.device)
    buf[:r].copy_(a32)
    buf[r:].copy_(torch.sub(a32, buf[:r]))
    res = _mm32(buf, b)
    return res[:r].add_(res[r:])


def _t210_hl_cat_right(a, b32):
    """(a @ b32) with a compute dtype n x T and b32 fp32 T x r: ONE _mm32 on [hi | lo] (T x 2r)."""
    import torch
    r = b32.shape[1]
    buf = torch.empty((b32.shape[0], 2 * r), dtype=a.dtype, device=a.device)
    buf[:, :r].copy_(b32)
    buf[:, r:].copy_(torch.sub(b32, buf[:, :r]))
    res = _mm32(a, buf)
    return torch.add(res[:, :r], res[:, r:])


def _t210_lrb_backward(rec, need, gy, x, up, down, xd=None):
    """_fast_backward with the stacked hi / lo GEMMs (and x D^T from the forward when given)."""
    import torch
    m, ad, st, name = rec
    dt = gy.dtype
    gy2 = gy.reshape(-1, gy.shape[-1])
    x2 = x.reshape(-1, x.shape[-1])
    s = _t210_scale(ad)  # a Python float (no host sync per call; the fp32 value of alpha / rank)
    gyu = _mm32(gy2, _t210_c(up, dt)) if (need[0] or need[4]) else None              # tokens x r, fp32
    gx = gu = gd = None
    if need[0]:
        gx = torch.mm(gyu.to(dt), _t210_c(down, dt, s)).addmm_(gy2, _fast_base_weight(m, dt)).reshape(x.shape)
    if need[3]:
        xdt = xd if xd is not None else _mm32(x2, _t210_c(down, dt).t())                # tokens x r, fp32
        gu = _t210_hl_cat_right(gy2.t(), xdt).mul_(s)                                   # out x r
    if need[4]:
        gd = _t210_hl_cat_left(gyu.t(), x2).mul_(s)                                     # r x in
    if st.probe is not None:
        _fast_probe(st, name, m, ad, gy2, x2, up.detach(), down.detach(), gx, gu, gd)
    return gx, gu, gd


def _t210_lrb_y(x, w, bias, lora_up, lora_down, s):
    """_fast_lr_y with x D^T formed once in fp32 (returned for the backward): y = x W^T + b + s round(x D^T) U^T."""
    import torch
    dt = x.dtype
    y = torch.nn.functional.linear(x, w, bias)
    if not y.is_contiguous():
        y = y.contiguous()
    xd = _mm32(x.reshape(-1, x.shape[-1]), _t210_c(lora_down, dt).t())
    y.view(-1, y.shape[-1]).addmm_(xd.to(dt), _t210_c(lora_up, dt).t(), alpha=s)
    return y, xd


def _t210_lrb_y_only(x, w, bias, lora_up, lora_down, s):
    """FAST_LRB: the y of _t210_lrb_y (what FAST_FWD's first-use check and the RB no-grad forward compute)."""
    return _t210_lrb_y(x, w, bias, lora_up, lora_down, s)[0]


def _t210_fast_fn_lr():
    """FAST_LRB: the FAST_FWD autograd.Function that keeps x D^T (fp32) from its forward for its backward."""
    if not _FAST_FN_LRB:
        import torch

        class FastLoRALowRankForwardLRB(torch.autograd.Function):
            @staticmethod
            def forward(ctx, x, w_base, bias, lora_up, lora_down, rec):
                ctx.save_for_backward(x, lora_up, lora_down)
                ctx.rec = rec
                y, xd = _t210_lrb_y(x, w_base, bias, lora_up, lora_down, rec[2].lr_scale[rec[3]])
                ctx.xd = xd
                return y

            @staticmethod
            def backward(ctx, gy):
                x, up, down = ctx.saved_tensors[:3]
                st, name = ctx.rec[2], ctx.rec[3]
                xd, ctx.xd = ctx.xd, None
                try:
                    gx, gu, gd = _t210_lrb_backward(ctx.rec, ctx.needs_input_grad, gy, x, up, down, xd=xd)
                except torch.cuda.OutOfMemoryError:
                    raise
                except Exception as e:  # noqa: BLE001
                    st.fail(f"{name} backward {type(e).__name__}: {str(e)[:160]}")
                    raise FastLoRAFallback(f"fast lora backward failed in {name}: {type(e).__name__}: {str(e)[:120]}") from e
                return gx, None, None, gu, gd, None

        _FAST_FN_LRB.append(FastLoRALowRankForwardLRB)
    return _FAST_FN_LRB[0]


_stretch_tail_step_t210 = stretch_tail_step


def _t210_trim_step(c, step, band_pool, cases, acc_groups, tail_on):
    """stretch_tail_step (called once at the start of every training step of _run_one) + FAST_TRIM: every cached copy is
    given back first, so a copy never outlives the step it was made in (a parameter changed through .data - canonical
    form, EMA swaps, a redo - never meets a stale copy, whatever its _version says); the line with the counts once."""
    if _TRIM["cache"]:
        _TRIM["cache"].clear()
    if step >= 50:
        _t210_trim_line()
    return _stretch_tail_step_t210(c, step, band_pool, cases, acc_groups, tail_on)


if CFG.get("fast_trim"):
    _TRIM["on"] = True
    _fast_lr_y, _fast_lr_inputs, _fast_backward = _t210_fast_lr_y, _t210_fast_lr_inputs, _t210_fast_backward  # noqa: F811
    stretch_tail_step = _t210_trim_step  # noqa: F811  (_run_one calls it by name once per step)
if CFG.get("fast_lrb"):
    _fast_backward = _t210_lrb_backward  # noqa: F811  (FastLoRALinear.backward and the compile path call it by name)
    _fast_fn_lr = _t210_fast_fn_lr  # noqa: F811  (_fast_forward calls it by name for the FAST_FWD forward)
    _fast_lr_y = _t210_lrb_y_only  # noqa: F811  (FAST_FWD's first-use check and the RB no-grad forward: the LRB forward's own y)



# ----------------------------------------------------------------------------------------------------------------------
# G56CT_LIFT (T210, 29 Oct 2026; ideogram4 only; OFF by default: G56CT_LIFT unset / 0 and T210_LIFT_DEFAULT False -> lift_gate returns
# at once, _LIFT['active'] stays False and every wrapper below returns the function it wraps: the trainer unchanged).
#
# folder's per-channel ('fine') base and shipping the restoration W_fine - W0_eval + the LoRA delta (+ the UNC rows) folded into ONE
# LoKr fp8 pair per fp8 module (211: lokr_w1 = [[2^k]] F32, lokr_w2 = F8_E4M3 codes of d / 2^k, k = ceil(log2(amax|d| / 448)))
#
#
# On: (1) lift_gate (main(), before the deadline): a write-speed probe next to the upload folder + a fold self-test on 2 modules of the
#   task's cache; a predicted folded write > LIFT_MAX_FOLD_S, too little disk or any problem -> LIFT off for the run (the family's own
#   shape trains; one line); else BASE=fine, IO_FIX off, io fold off, the 7 io modules trained by the LoRA (INCLUDE_EXTRA if unset).
# (2) _lift_save_lora: the identity file before training goes to the upload folder bare (untrained = as today); EVERY later write goes
#   to a private folder next to the upload folder (.<name>.lift/, never uploaded); only the FIRST trained non-interim write (member 1;
#   folded at the next reinit_adapters, i.e. between members and outside every timed save - 29 Oct fix: a fold inside save_lora inflated
#   the save-time model, V0 stopped at K4 - retried if it failed) and the final file (dense_ship, right after training) are folded INTO the upload folder:
#   stream-written next to it, re-read and checked (key set, w1 = 2^k, sampled modules' codes bit for bit, patched weight vs target,
#   the live key map), then os.replace. The upload folder thus only ever holds the bare identity or a folded file; a failed fold keeps
#   the previous one (one WARN), so a kill at any point never ships the fine-trained LoRA bare.
# (3) _dense_reserve_s: the deadline reserves 1.5 x the predicted folded write (probe rate) + 30 s. (4) _t126_fixed_bytes: the K-plan
#   size cap reads the identity LoRA's size, not the folded file (constant ~9.28 GB; LIFT_CAP_GB 10 caps it apart). W0_eval =
#   g56dense.w0_exact (211/211 layers bit-equal to the evaluator's Comfy-Org file: SH__t210w0check, 28 Oct). Checks: tools/lift_check.py.
# ----------------------------------------------------------------------------------------------------------------------
T210_LIFT_DEFAULT = True    # flip switch for an entry (False = the trainer unchanged unless G56CT_LIFT=1); True since the 2 Nov entry
#
CFG.update(lift=env("LIFT", T210_LIFT_DEFAULT, bool), lift_max_fold_s=env("LIFT_MAX_FOLD_S", 180.0, float),
           lift_cap_gb=env("LIFT_CAP_GB", 10.0, float), lift_probe_mb=env("LIFT_PROBE_MB", 512, int),
           lift_test=env("LIFT_TEST", "", str),   # TEST ONLY: 'slow' (the gate sees a disk 2 x too slow), 'fold' (every fold raises)
           lift_io_scale=env("LIFT_IO_SCALE", 1.0, float),   # the 7 io modules' trained delta x this in the fold (1.0 = as trained;
           rank_io=env("RANK_IO", 0, int))   # G56CT_RANK_IO (I4): the LoRA rank of the 7 io modules (IO_FIX_SETS['all']); 0 = the run's rank
# (lift_io_scale:
#
_LIFT = {"active": False, "armed": False, "rate": None, "repo": None, "files": None, "fp8": None, "mp": None, "folds": 0,
         "src_stat": None, "ident_bytes": None, "why": "", "pending": False, "fold_s": None, "reserve": None}
LIFT_EST_BYTES = 9.3e9   # ideogram4's folded file: 211 fp8 modules, 9,278 M codes + 211 w1
LIFT_SUFFIXES = (".lora_up.weight", ".lora_down.weight", ".alpha", ".diff")


def _lift_priv(out_dir):
    """the private folder of the LoRA writes under LIFT: next to the upload folder, never inside it"""
    out_dir = Path(out_dir)
    return out_dir.parent / f".{out_dir.name}.lift"


def _lift_fp8_layers(files):
    """[(module, shape)] of the task folder's fp8 matrices that carry a weight_scale (the evaluator's 211 scale-1 layers)"""
    from safetensors import safe_open
    out, hs = [], {}
    try:
        for k in sorted(files):
            if not k.endswith(".weight") or (k[: -len(".weight")] + ".weight_scale") not in files:
                continue
            fn = files[k]
            if fn not in hs:
                hs[fn] = safe_open(fn, framework="pt", device="cpu")
            sl = hs[fn].get_slice(k)
            if sl.get_dtype() == "F8_E4M3" and len(sl.get_shape()) == 2:
                out.append((k[: -len(".weight")], tuple(int(x) for x in sl.get_shape())))
    finally:
        hs.clear()
    return out


def _lift_codes(q8, s, delta, device):
    """(k, w2 fp8, d, wf, w0) of one module: wf = fp32(q * s_row) (the fine weight), w0 = g56dense.w0_exact (the evaluator's value),
    d = wf - w0 (+ delta), k = ceil(log2(amax|d| / 448)) (-15 for a zero d), w2 = fp8(d / 2^k)"""
    import torch
    import g56dense as DN
    q8d = q8.to(device)
    sc = s.to(device=device, dtype=torch.float32)
    s2 = sc.reshape(-1, 1) if sc.numel() > 1 else sc.reshape(1, 1)
    wf = q8d.to(torch.float32) * s2
    w0 = DN.w0_exact(q8d, sc).to(torch.float32)
    d = wf - w0
    if delta is not None:
        d = d + delta.to(device=device, dtype=torch.float32).reshape(d.shape)
    amax = float(d.abs().max())
    k = int(math.ceil(math.log2(amax / 448.0))) if amax > 0 else -15
    w2 = (d / (2.0 ** k)).to(torch.float8_e4m3fn)
    return k, w2, d, wf, w0


def _lift_get(files, hs, k):
    from safetensors import safe_open
    fn = files[k]
    if fn not in hs:
        hs[fn] = safe_open(fn, framework="pt", device="cpu")
    return hs[fn].get_tensor(k)


def lift_self_test(files, fp8):
    """fold of a zero delta on 2 modules (the first block matrix, input_proj) on the CPU: codes finite, the patched weight
    w0 + 2^k * w2 within 2e-2 (rel. L2) of the fine weight. Raises on a problem; returns {module: rel}."""
    import torch
    names = [m for m, _ in fp8]
    pick = [m for m in names if m.startswith("layers.")][:1] + [m for m in names if m == "input_proj"]
    if len(pick) != 2:
        raise ValueError(f"self-test modules {pick}")
    out, hs = {}, {}
    try:
        for m in pick:
            k, w2, d, wf, w0 = _lift_codes(_lift_get(files, hs, m + ".weight"), _lift_get(files, hs, m + ".weight_scale"), None, "cpu")
            got = w0 + (2.0 ** k) * w2.to(torch.float32)
            rel = float((got - wf).norm() / max(float(wf.norm()), 1e-30))
            if not bool(torch.isfinite(got).all()) or rel > 2e-2:
                raise ValueError(f"{m}: self-test rel {rel:.3g}")
            out[m] = round(rel, 7)
    finally:
        hs.clear()
    return out


def lift_gate(fam, repo, out_dir):
    """G56CT_LIFT start gate (main(), before the deadline); returns _LIFT['active']. Never raises: any problem -> LIFT off (one line)."""
    _LIFT.update(active=False, armed=False, rate=None, repo=repo, files=None, fp8=None, mp=None, folds=0, src_stat=None,
                 ident_bytes=None, why="", pending=False, fold_s=None, reserve=None)
    if not CFG.get("lift") or fam != "ideogram4":
        return False
    try:
        import shutil
        out_dir = Path(out_dir)
        out_dir.parent.mkdir(parents=True, exist_ok=True)
        free = shutil.disk_usage(str(out_dir.parent)).free
        if free < 3 * LIFT_EST_BYTES:
            raise ValueError(f"{free / 1e9:.1f} GB free next to the upload folder (< {3 * LIFT_EST_BYTES / 1e9:.0f} GB)")
        probe = out_dir.parent / f".{out_dir.name}.lift.probe"
        nb = max(1, int(CFG.get("lift_probe_mb") or 512)) << 20
        buf = b"\0" * (1 << 24)
        t0 = time.time()
        try:
            with open(probe, "wb") as f:
                left = nb
                while left > 0:
                    f.write(buf[: min(left, len(buf))])
                    left -= min(left, len(buf))
                f.flush()
                os.fsync(f.fileno())
            dt = max(time.time() - t0, 1e-3)
        finally:
            try:
                probe.unlink()
            except OSError:
                pass
        rate = nb / dt
        if str(CFG.get("lift_test") or "") == "slow":   # TEST ONLY: a disk twice too slow for LIFT_MAX_FOLD_S
            rate = LIFT_EST_BYTES / (2.0 * max(float(CFG["lift_max_fold_s"]), 1e-3))
        pred = LIFT_EST_BYTES / rate
        if pred > float(CFG["lift_max_fold_s"]):
            raise ValueError(f"predicted folded write {pred:.0f}s at {rate / 1e6:.0f} MB/s > LIFT_MAX_FOLD_S {CFG['lift_max_fold_s']:g}s")
        files = _dense_cache_files(repo)
        fp8 = _lift_fp8_layers(files)
        if len(fp8) != 211:
            raise ValueError(f"{len(fp8)} fp8 matrices with a weight_scale in the task folder (ideogram4: 211)")
        st = lift_self_test(files, fp8)
        _LIFT.update(rate=rate, files=files, fp8=fp8)
        CFG.update(base="fine", io_fix="", io_fold=False)
        if not str(CFG.get("include_extra") or "").strip():
            CFG["include_extra"] = T210_I4_IO_EXTRA
        if not str(CFG.get("dense") or "").strip():
            CFG["dense"] = "lora"
        _LIFT["active"] = True
        log(f"lift: on ({rate / 1e6:.0f} MB/s next to the upload folder, a folded write ~{pred:.0f}s; self-test {json.dumps(st)}); "
            f"BASE fine, IO_FIX off, include_extra {CFG['include_extra']!r}")
        return True
    except Exception as e:  # noqa: BLE001  (never fails the run: the family's own shape trains)
        _LIFT.update(active=False, why=f"{type(e).__name__}: {str(e)[:160]}")
        log(f"WARN lift: off for this run ({_LIFT['why']}); the family's shape trains")
        return False


def lift_fold_file(src, out_dir, tag="fold"):
    """Fold the private LoRA file src into out_dir/last.safetensors (the note above). Raises on any problem (the caller keeps the
    previous upload file); returns a small report."""
    import struct
    import torch
    from safetensors import safe_open
    import g56dense as DN
    t0 = time.time()
    P = "diffusion_model."
    out_dir = Path(out_dir)
    files, fp8 = _LIFT["files"], _LIFT["fp8"]
    dev = "cuda" if torch.cuda.is_available() else "cpu"
    tmp = out_dir.parent / f".{out_dir.name}.lift.tmp"
    rep = {"modules": len(fp8), "lora": 0, "sampled": 0}
    hs = {}
    try:
        with safe_open(str(src), framework="pt", device="cpu") as fl:
            lkeys = list(fl.keys())
            lset = set(lkeys)
            fmods = {P + m for m, _ in fp8}
            owned = set()
            for m, _ in fp8:
                for suf in LIFT_SUFFIXES:
                    if P + m + suf in lset:
                        owned.add(P + m + suf)
            stray = [k for k in lkeys if k not in owned and any(k.startswith(pm + ".") for pm in fmods)]
            if stray:
                raise ValueError(f"unexpected keys of an fp8 module: {stray[:3]}")
            entries = []
            for m, sh in fp8:
                entries.append((P + m + ".lokr_w1", "F32", (1, 1), 4))
                entries.append((P + m + ".lokr_w2", "F8_E4M3", sh, int(sh[0]) * int(sh[1])))
            passthru = [k for k in lkeys if k not in owned]
            for k in passthru:
                sl = fl.get_slice(k)
                t = fl.get_tensor(k)
                entries.append((k, sl.get_dtype(), tuple(sl.get_shape()), int(t.numel() * t.element_size())))
            header, _, total = DN._header(entries)
            if total > float(CFG["lift_cap_gb"]) * 1e9:
                raise ValueError(f"folded file {total / 1e9:.2f} GB > LIFT_CAP_GB {CFG['lift_cap_gb']:g}")
            every = max(1, len(fp8) // 8)
            samp = {}
            with open(tmp, "wb") as f:
                f.write(header)
                for i, (m, sh) in enumerate(fp8):
                    delta = None
                    up_k, dn_k, al_k, df_k = (P + m + s_ for s_ in LIFT_SUFFIXES)
                    if up_k in lset and dn_k in lset:
                        up = fl.get_tensor(up_k).to(device=dev, dtype=torch.float32)
                        dn = fl.get_tensor(dn_k).to(device=dev, dtype=torch.float32)
                        r = dn.shape[0]
                        al = float(fl.get_tensor(al_k)) if al_k in lset else float(r)
                        delta = (up.flatten(1) @ dn.flatten(1)) * (al / r)
                        rep["lora"] += 1
                        del up, dn
                    if df_k in lset:
                        dd = fl.get_tensor(df_k).to(device=dev, dtype=torch.float32)
                        delta = dd if delta is None else delta + dd.reshape(delta.shape)
                    ios = float(CFG.get("lift_io_scale") or 1.0)
                    if delta is not None and ios != 1.0 and not m.startswith("layers."):   # G56CT_LIFT_IO_SCALE: io modules only
                        delta = delta * ios
                        rep["io_scaled"] = rep.get("io_scaled", 0) + 1
                    q8_, s_ = _lift_get(files, hs, m + ".weight"), _lift_get(files, hs, m + ".weight_scale")
                    try:
                        k, w2, d, wf, w0 = _lift_codes(q8_, s_, delta, dev)
                    except torch.cuda.OutOfMemoryError:   # the training state fills the GPU: this module on the CPU (same math)
                        torch.cuda.empty_cache()
                        delta = delta.cpu() if delta is not None else None
                        k, w2, d, wf, w0 = _lift_codes(q8_, s_, delta, "cpu")
                        rep["cpu_modules"] = rep.get("cpu_modules", 0) + 1
                    if str(CFG.get("lift_test") or "") == "fold":   # TEST ONLY: a failure in the middle of the write
                        raise RuntimeError("LIFT_TEST fold: injected failure")
                    c8 = w2.contiguous().view(torch.uint8).cpu()
                    f.write(struct.pack("<f", 2.0 ** k))
                    f.write(c8.numpy().tobytes())
                    if i % every == 0 or i == len(fp8) - 1 or not m.startswith("layers."):   # the first 64 rows are checked after the write
                        tg = (wf + delta.reshape(wf.shape)) if delta is not None else wf
                        samp[m] = (k, c8[:64].clone(), tg[:64].cpu(), w0[:64].cpu())
                        del tg
                    del w2, d, wf, w0, delta
                for k_ in passthru:
                    t = fl.get_tensor(k_).contiguous()
                    f.write(t.reshape(-1).view(torch.uint8).numpy().tobytes())
                f.flush()
                os.fsync(f.fileno())
        if os.path.getsize(tmp) != total:
            raise ValueError(f"written {os.path.getsize(tmp)} B != header total {total} B")
        with safe_open(str(tmp), framework="pt", device="cpu") as fv:
            want = {e[0] for e in entries}
            if set(fv.keys()) != want:
                raise ValueError("folded key set differs from its header plan")
            for m, (k, c8, target, w0) in samp.items():
                w1 = float(fv.get_tensor(P + m + ".lokr_w1").reshape(-1)[0])
                w2 = fv.get_slice(P + m + ".lokr_w2")[:64]
                if w1 != 2.0 ** k or not torch.equal(w2.contiguous().view(torch.uint8).reshape(-1), c8.reshape(-1)):
                    raise ValueError(f"{m}: the written pair is not the computed one")
                got = w0 + w1 * w2.to(torch.float32)
                rel = float((got - target).norm() / max(float(target.norm()), 1e-30))
                if not bool(torch.isfinite(got).all()) or rel > 2e-2:
                    raise ValueError(f"{m}: patched weight vs target rel {rel:.3g}")
            rep["sampled"] = len(samp)
        mp = _LIFT.get("mp")
        if mp is not None:
            import comfy.lora
            km = comfy.lora.model_lora_keys_unet(mp.model, {})
            miss = [m for m, _ in fp8 if P + m not in km]
            if miss:
                raise ValueError(f"{len(miss)} folded modules not in the evaluator's key map, e.g. {miss[0]}")
            rep["keymap"] = "ok"
        os.replace(tmp, out_dir / "last.safetensors")
        try:
            os.chmod(out_dir / "last.safetensors", 0o644)
        except Exception:  # noqa: BLE001
            pass
        rep.update(bytes=int(total), seconds=round(time.time() - t0, 1))
        return rep
    finally:
        hs.clear()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
        try:
            tmp.unlink()
        except FileNotFoundError:
            pass
        except Exception:  # noqa: BLE001
            pass


def _lift_fold_now(out_dir, tag):
    """fold the newest private LoRA file into the upload folder unless that state is already folded; True when the upload folder
    holds the folded state afterwards. A failure: one WARN, the previous upload file stays."""
    src = _lift_priv(out_dir) / "last.safetensors"
    try:
        st = os.stat(src)
        key = (st.st_ino, st.st_mtime_ns, st.st_size)
        if key == _LIFT.get("src_stat"):
            log(f"lift: {tag}: the upload folder already holds this state folded")
            return True
        rep = lift_fold_file(src, out_dir, tag)
        _LIFT["folds"] += 1
        _LIFT["src_stat"] = key
        log(f"lift: {tag}: folded into the upload folder {json.dumps(rep)}")
        return True
    except Exception as e:  # noqa: BLE001  (never fails the run; never leaves the bare trained LoRA in the upload folder)
        log(f"WARN lift: {tag}: fold failed ({type(e).__name__}: {str(e)[:200]}); the upload folder keeps its previous file")
        return False


def _lift_untrained(sd):
    """every LoRA module of the state has an all-zero up or down factor (the identity file before training)"""
    ups = [k for k in sd if k.endswith(".lora_up.weight")]
    for k in ups:
        dn = sd.get(k[: -len(".lora_up.weight")] + ".lora_down.weight")
        try:
            if bool((sd[k] != 0).any()) and dn is not None and bool((dn != 0).any()):
                return False
        except Exception:  # noqa: BLE001
            return False
    return True


_lift_inner_save = save_lora


def _lift_save_lora(sd, out_dir, meta=None, interim=False):
    """save_lora under G56CT_LIFT (the note above); LIFT off or another folder than the upload folder: the wrapped function exactly."""
    if not _LIFT.get("active") or _OUT_DIR is None or Path(out_dir) != Path(_OUT_DIR):
        return _lift_inner_save(sd, out_dir, meta, interim)
    if not _LIFT["armed"]:
        _LIFT["armed"] = True
        if _lift_untrained(sd):  # the identity file before training: bare in the upload folder (as without the knob)
            ok = _lift_inner_save(sd, out_dir, meta, interim)
            if ok:
                try:
                    _LIFT["ident_bytes"] = os.path.getsize(Path(out_dir) / "last.safetensors")
                except OSError:
                    pass
            return ok
    ok = _lift_inner_save(sd, _lift_priv(out_dir), meta, interim)
    if ok and not interim and _LIFT["folds"] == 0:
        # T210 29 Oct fix (V0 lost 2 members): NOT folded here - every caller times save_lora (_note_save_rate keeps the WORST
        # seconds per byte, _save_margin scales it by k + 1), so a fold inside it inflated every later stop margin
        # ('next needs ~1015s' at K4). The fold runs at the next reinit_adapters (before the next member, untimed) or at the final.
        _LIFT["pending"] = True
    return ok


save_lora = _lift_save_lora  # noqa: F811  (every caller writes through save_lora by name)

_lift_inner_dense_ship = dense_ship


def _lift_dense_ship(fam, repo, mp, out_dir, t_start, hours, device):
    """main()'s post-training ship under G56CT_LIFT: the final private file folded into the upload folder (nothing else ships: no io
    pairs, no dense pass); LIFT off: the wrapped function exactly"""
    if not _LIFT.get("active"):
        return _lift_inner_dense_ship(fam, repo, mp, out_dir, t_start, hours, device)
    _LIFT["mp"] = mp
    ok = _lift_fold_now(out_dir, "final")
    return {"mode": "lift", "shipped": bool(ok), "folds": _LIFT["folds"]}


dense_ship = _lift_dense_ship  # noqa: F811

_lift_inner_reserve = _dense_reserve_s


def _lift_dense_reserve_s():
    """the deadline reserve: under G56CT_LIFT at least 1.5 x the predicted fold (the larger of the probe prediction and the measured
    member-1 fold) + 30 s"""
    r = _lift_inner_reserve()
    if _LIFT.get("active") and _LIFT.get("rate"):
        lr = 1.5 * max(LIFT_EST_BYTES / float(_LIFT["rate"]), float(_LIFT.get("fold_s") or 0.0)) + 30.0
        _LIFT["reserve"] = lr
        r = max(float(r), lr)
    return r


_dense_reserve_s = _lift_dense_reserve_s  # noqa: F811

_lift_inner_reinit = reinit_adapters


def _lift_reinit_adapters(c, seed, member=0):
    """reinit_adapters under G56CT_LIFT: a pending member-1 fold runs first (between members: untimed by the save model and outside
    the member's own duration); when its measured time asks for a larger final-fold reserve (1.5 x max(probe, measured) + 30 s) the
    run's deadline moves earlier by the difference. LIFT off or nothing pending: the wrapped function exactly."""
    if _LIFT.get("active") and _LIFT.get("pending") and c.get("out_dir") is not None:
        t0 = time.time()
        ok = _lift_fold_now(c["out_dir"], "member 1")
        if ok:
            _LIFT["pending"] = False
            _LIFT["fold_s"] = max(float(_LIFT.get("fold_s") or 0.0), time.time() - t0)
            old = float(_LIFT.get("reserve") or 0.0)
            new = 1.5 * max(LIFT_EST_BYTES / float(_LIFT["rate"] or 1.0), _LIFT["fold_s"]) + 30.0
            if new > old and c.get("deadline"):
                c["deadline"] -= new - old
                _LIFT["reserve"] = new
                log(f"lift: the measured fold {_LIFT['fold_s']:.0f}s -> final-fold reserve {new:.0f}s (was {old:.0f}s): deadline -{new - old:.0f}s")
    return _lift_inner_reinit(c, seed, member)


reinit_adapters = _lift_reinit_adapters  # noqa: F811  (the member loops call reinit_adapters by name)

_lift_inner_fixed = _t126_fixed_bytes


def _lift_t126_fixed_bytes(c, mb):
    """the K-plan size cap's fixed bytes: under G56CT_LIFT the identity LoRA's size (the upload folder holds the folded file)"""
    if _LIFT.get("active") and _LIFT.get("ident_bytes"):
        return max(0, int(_LIFT["ident_bytes"]) - int(mb))
    return _lift_inner_fixed(c, mb)


_t126_fixed_bytes = _lift_t126_fixed_bytes  # noqa: F811
# ours (T208, 26 Oct 2026; default OFF): G56CT_TAIL_KEPT - the T179 'kept' edge of a short z-image fill member. T179's rule (block
# above) re-plans a seeds-auto fill member with the armed final transform's predicted tail; when that re-plan falls below the fill
# threshold (fill_member_steps returns 0; z-image FILL25: 0.25 x the step cap) the fill keeps its planned length ('kept: the margin
# would drop the fill member') and the transform's own skip rule then decides at the end - the official smoke R26BFMs0__a727a89b
# (h1up4, 26 Oct): fill 500 / 1770 kept -> 'zimg-p1: skipped (26s to the watchdog stop < the estimated 29s)'. T179 wrote 'a fill
# member is worth more than the transform' at the 0.45 threshold; its re-plan returning 0 conflates 'below the threshold' with 'no
# fill member'. G56CT_TAIL_KEPT '<m>[:keep|:drop]' (0 < m < 1; families T208_KEPT_FAMS = z-image only): in that kept case only, the
# fill member gets the steps that fit the predicted tail (fill_member_steps' own formula at the margin + the tail's excess, without
# the fill threshold) when that is >= m x the step cap; below m, ':keep' (the default) = the fill as planned (T179 as before),
# ':drop' = no fill member ('stop after K member(s)'), so the transform fits. '' (default) / 'off' = off: T179's function itself
# decides, nothing else is computed or logged. A malformed value: one private WARN line, off. Never raises (any error: T179's plan).
# Wrapped by assignment (fill_member_steps = T179's wrapper of the original; train_loop / stretch_plan_keepk call it by name; the
# z-image production runs have keep-K stretch off: 'stretch: off (G56CT_EXPOSURE sets the member length)').
# ----------------------------------------------------------------------------------------------------------------------
T208_KEPT_FAMS = ("z-image",)
CFG["tail_kept"] = env("TAIL_KEPT", "")
_T208 = {"said": set()}
_fill_member_steps_t208 = fill_member_steps


def t208_kept_spec(raw):
    """G56CT_TAIL_KEPT value -> ((m, mode), None); (None, None) for '' / 'off'; (None, why) when malformed"""
    v = str(raw or "").strip().lower()
    if v in ("", "off", "none"):
        return None, None
    m_s, _, mode = v.partition(":")
    mode = mode.strip() or "keep"
    try:
        m = float(m_s)
    except ValueError:
        return None, f"{raw!r} is not '<m>[:keep|:drop]'"
    if not (math.isfinite(m) and 0.0 < m < 1.0) or mode not in ("keep", "drop"):
        return None, f"{raw!r}: m must lie in (0, 1) and the mode be keep or drop"
    return (m, mode), None


def _t208_fill_member_steps(durs, steps, remaining, full_cap, frac, margin=30.0, safety=1.10):
    """T179's fill_member_steps; with G56CT_TAIL_KEPT on (a z-image run), T179's kept case re-planned as the value says. One private
    line per decision; any error: T179's plan."""
    n = _fill_member_steps_t208(durs, steps, remaining, full_cap, frac, margin, safety)
    if not str(CFG.get("tail_kept") or "").strip():
        return n
    try:
        spec, why = t208_kept_spec(CFG.get("tail_kept"))
        if why is not None:
            if "bad" not in _T208["said"]:
                _T208["said"].add("bad")
                log(f"WARN seeds-auto: G56CT_TAIL_KEPT {why}; off (T208)")
            return n
        c = _T179.get("c") or {}
        if spec is None or c.get("fam") not in T208_KEPT_FAMS or n <= 0 or n >= full_cap:
            return n
        x, tag, tail = _t179_tail(margin)
        if x <= 0 or _fill_member_steps_t179(durs, steps, remaining, full_cap, frac, margin + x, safety) > 0:
            return n  # T179 did not act, or it shortened the fill itself (n is that length)
        m, mode = spec
        fit = _fill_member_steps_t179(durs, steps, remaining, full_cap, 1e-9, margin + x, safety)  # the tail's fit, no threshold
        out = fit if fit > 0 and fit >= m * full_cap else (0 if mode == "drop" else n)
        if (n, out) not in _T208["said"]:
            _T208["said"].add((n, out))
            log(f"seeds-auto: fill member {n} -> {out} steps for the armed {tag} (T208 G56CT_TAIL_KEPT {CFG['tail_kept']!r}: the "
                f"predicted tail {tail:.0f}s fits {fit} steps = {fit / max(1, full_cap):.3f} of the cap, "
                + (f">= {m:g}: the fill below the fill threshold)" if out == fit and out > 0 else
                   f"< {m:g}: " + ("no fill member, the transform fits)" if out == 0 else "the fill as planned)")))
        return out
    except Exception:  # noqa: BLE001  (never ends a run: T179's plan)
        return n


_t208_fill_member_steps.__wrapped__ = _fill_member_steps_t208  # (T179's wrapper; its own __wrapped__ = the trainer's function)
fill_member_steps = _t208_fill_member_steps  # noqa: F811  (train_loop / stretch_plan_keepk call it by name)


# ----------------------------------------------------------------------------------------------------------------------
# ours (T208 F1, 28 Oct 2026; coordinator: entry-2-Nov candidate; every knob default OFF = the trainer unchanged): the final
#
# PLAN.md sec. 15-15b): 7 of 131 armed runs skipped the transform, every one a T179 'kept' fill (26-32 s to the watchdog stop when it
# began, the estimate 29-41 s, the real transform + rewrite 18-29 s); T179's tail prediction is conservative (real / predicted <= 0.86
# over 50 runs); the rewrite is atomic (save_lora: .last.safetensors.tmp + os.replace), so a transform the watchdog cuts ships the
# previous complete file. Three switches:
# (a) G56CT_TAIL_KEPT (the block above): T208_KEPT_FAMS now holds flux too - a kept flux fill is shortened / dropped like z-image's.
# (b') G56CT_T157_SKIP 'measured': the skip rule starts the transform iff the time to the watchdog stop >= T208_T157_SAFETY (1.2) x
#      (its compute, T208_T157_COMPUTE: a + b x state bytes = the fit of the logged transforms + their largest residual, + the bytes
#      to write x THIS run's measured save time per byte (_SAVE_STATS spb = the slowest save of the run: the validator's disk, not
#      ours)). '' (default) = T157's rule unchanged. Implemented by swapping T157_EST[tag] for the call only (the rule's own code and
#      message, so a skip still reads 'skipped (Ls to the watchdog stop < the estimated Es)').
# (c) G56CT_T157_PARTS=1: each part of the value applied on its own. z-image: the tail (T193 'tail<K0>:<S>'), TPB, the group scales;
#      flux: the tail, the group scales. A part that refuses or fails its verification is dropped alone (one note in the ON line);
#      before, any part's refusal shipped the file as given (a K1 / rank <= K0 run lost TPB and attn with the tail). Nothing applied
#      -> as given, as before.
# ----------------------------------------------------------------------------------------------------------------------
T208_KEPT_FAMS = ("z-image", "flux")  # noqa: F811  (F1 (a): the kept-fill rule for both armed transforms)
CFG.update(t157_skip=env("T157_SKIP", ""), t157_parts=env("T157_PARTS", False, bool))
T208_T157_COMPUTE = {"zimg-p1": (9.6, 0.68e-9),  # 72 logged P1 (0.70-5.61 GB): 6.66 s + 0.68 s/GB, largest residual +2.91 s
                     "flux-fc": (3.0, 0.3e-9)}   # 62 logged FC (0.62-4.95 GB): <= 1.34 s since 22 Oct (older code: up to 32 s)
T208_T157_SAFETY = 1.2
_T208F1 = {"said": set()}
_t157_run_t208 = _t157_run


def _t208_t157_run(tag, fn, parsed, sd):
    """_t157_run; G56CT_T157_SKIP 'measured': the skip rule's estimate = 1.2 x (compute + bytes x the run's measured save time)"""
    mode = str(CFG.get("t157_skip") or "").strip().lower()
    if not mode or mode in ("off", "0", "none") or tag not in T208_T157_COMPUTE or tag not in T157_EST:
        return _t157_run_t208(tag, fn, parsed, sd)
    if mode != "measured":
        if ("bad", mode) not in _T208F1["said"]:
            _T208F1["said"].add(("bad", mode))
            log(f"WARN t157-skip: G56CT_T157_SKIP {mode!r} is not 'measured'; T157's rule (T208)")
        return _t157_run_t208(tag, fn, parsed, sd)
    old = T157_EST[tag]
    try:
        a, b = T208_T157_COMPUTE[tag]
        spb = float(_SAVE_STATS.get("spb", 0.0) or 0.0)
        s = T208_T157_SAFETY
        # T157's rule: skip iff left < A + B x nb + 2 + spb x nb; with A = s a - 2, B = s b + (s - 1) spb it reads s (a + b nb + spb nb)
        T157_EST[tag] = (s * a - 2.0, s * b + (s - 1.0) * spb)
        if ("on", tag) not in _T208F1["said"]:
            _T208F1["said"].add(("on", tag))
            log(f"t157-skip: measured for {tag} (T208): start iff the time to the watchdog stop >= {s:g} x ({a:g} s + {b * 1e9:.2f} s/GB + "
                f"bytes x this run's save time {spb * 1e9:.2f} s/GB)")
        return _t157_run_t208(tag, fn, parsed, sd)
    finally:
        T157_EST[tag] = old


def _t208_tail_only(k0, sc, sd):
    """T193's tail part alone (its checks, scaling and verification, the same arithmetic) -> (state, None) or (sd, why)"""
    import torch
    try:
        if CFG.get("save_bf16"):
            return sd, "G56CT_SAVE_BF16"
        if _t157_zero(sd):
            return sd, "identity state"
        mods = _t157_mods(sd)
        if len(mods) != T193_TAIL_MODS:
            return sd, f"{len(mods)} modules, the shipped z-image file {T193_TAIL_MODS}"
        for m, ks in mods.items():
            dn = sd[ks[".lora_down.weight"]]
            _t157_canon(m, sd[ks[".lora_up.weight"]], dn, _t157_alpha(sd, m))
            if dn.shape[0] <= k0:
                return sd, f"{m} has rank {dn.shape[0]} <= K0 {k0}"

        def fvec(n):
            f = torch.ones(n, dtype=torch.float64)
            f[k0:] = sc
            return f
        st = {k: ((v.to(torch.float64) * fvec(v.shape[1])).to(torch.float32).contiguous() if k.endswith(".lora_up.weight") else v)
              for k, v in sd.items()}
        for k, v in sd.items():
            if k.endswith(".lora_up.weight"):
                want = (v.to(torch.float64) * fvec(v.shape[1])).to(torch.float32)
                if st[k].dtype != torch.float32 or st[k].shape != v.shape or not torch.equal(st[k].view(torch.int32), want.view(torch.int32)):
                    return sd, f"verification failed ({k})"
            elif st[k] is not v:
                return sd, f"verification failed ({k} not the state's own tensor)"
        return st, None
    except _T157Refuse as e:
        return sd, str(e)


def _t208_p1_try(parsed, st):
    """the original P1 (T157) on st -> (state, line) or (st, why) - a refusal / a failed verification never raises here"""
    try:
        out, msg = _t193_p1_0(parsed, st)
    except _T157Refuse as e:
        return st, str(e)
    return (st, msg) if out is st else (out, msg)


_t157_p1_t208 = _t157_p1


def _t208_p1(parsed, sd):
    """T193's P1 (tail, then T157's TPB + group scales); G56CT_T157_PARTS=1: each part on its own (a failing part dropped alone)"""
    if not CFG.get("t157_parts"):
        return _t157_p1_t208(parsed, sd)
    tail = (parsed[1], parsed[2]) if (isinstance(parsed, tuple) and len(parsed) == 4 and parsed[0] == "T193TAIL") else None
    inner = parsed[3] if tail else parsed
    ab, gam, rows, groups = inner
    notes, st, on = [], sd, []
    if tail is not None:
        st, why = _t208_tail_only(tail[0], tail[1], sd)
        (notes if why else on).append(f"tail{tail[0]}:{tail[1]:g}" + (f" off: {why}" if why else ""))
    out, msg = _t208_p1_try(inner, st)
    if out is st and gam is not None and groups:  # TPB + groups failed as a whole: the group scales alone, else TPB alone
        first = str(msg)[:120]
        out, msg = _t208_p1_try((ab, None, rows, groups), st)
        if out is not st:
            notes.append(f"tpb off: {first}")
        else:
            notes.append(f"groups off: {str(msg)[:120]}")
            out, msg = _t208_p1_try((ab, gam, rows, []), st)
            if out is st:
                notes.append(f"tpb off: {str(msg)[:120]}")
    elif out is st:
        notes.append(("tpb" if gam is not None else "groups") + f" off: {str(msg)[:120]}")
    if out is st and st is sd:
        raise _T157Refuse("no part applied: " + "; ".join(notes))
    if out is st:  # only the tail applied
        msg = f"zimg-p1: ON tail{tail[0]}:{tail[1]:g} on {len(_t157_mods(sd))} modules only"
    elif on:
        msg = msg.replace("zimg-p1: ON ", f"zimg-p1: ON {on[0]} on {len(_t157_mods(sd))} modules, then ", 1)
    return out, msg + (f" (T208 parts: {'; '.join(notes)})" if notes else " (T208 parts: all applied)")


_t157_fc_t208 = _t157_fc


def _t208_fc(parsed, sd):
    """T157's FC; G56CT_T157_PARTS=1: a refused / failed FC retried without its tail, then the tail alone"""
    if not CFG.get("t157_parts"):
        return _t157_fc_t208(parsed, sd)
    groups, tail = parsed
    try:
        out, msg = _t157_fc_t208(parsed, sd)
        if out is not sd:
            return out, msg + " (T208 parts: all applied)"
        why = msg
    except _T157Refuse as e:
        why = str(e)
    for sub, drop in (((groups, None), "tail"), (([], tail), "groups")):
        if (drop == "tail" and (tail is None or not groups)) or (drop == "groups" and (tail is None or not groups)):
            continue
        try:
            out, msg = _t157_fc_t208(sub, sd)
        except _T157Refuse as e:
            why += f"; without the {drop}: {e}"
            continue
        if out is not sd:
            return out, msg + f" (T208 parts: {drop} off: {str(why)[:120]})"
        why += f"; without the {drop}: {str(msg)[:80]}"
    raise _T157Refuse(f"no part applied: {str(why)[:240]}")


_t208_t157_run.__wrapped__ = _t157_run_t208
_t208_p1.__wrapped__ = _t157_p1_t208
_t208_fc.__wrapped__ = _t157_fc_t208
_t157_run = _t208_t157_run  # noqa: F811  (_t157_final calls it by name)
_t157_p1 = _t208_p1  # noqa: F811  (the transform registry looks it up by name when a write is recorded)
_t157_fc = _t208_fc  # noqa: F811


# ----------------------------------------------------------------------------------------------------------------------
# ours (T208 F1d, 29 Oct 2026; coordinator: entry-2-Nov candidate; default OFF = the trainer unchanged): a member CUT before its
# planned steps (the deadline / SAFE stopped it mid-cosine) no longer joins the soup at the full weight 1/K. Scan of the uc1 / uc2 / uc3
#
# W33S e792 333 / 406, T172E75s2 e792 296 / 369, flux F7HB 14e9 223 / 285, FXBR 14e9 300 / 351, z-image KC2 c38a 199 / 207 - every one
# averaged in at 1/K (the trigger in CX14: one sparse write of 94.6 s vs 19.3 s in its twin).
# G56CT_CUT_MEMBER: '' (default) / 'off' = today; 'drop:<x>' (0 < x <= 1) = a member that ended below x of ITS planned steps (the
# step cap train_loop set for it: the full cap or its fill length) is not averaged in - unless no member has joined yet (then it is
# kept aside like an abandoned one: shipped only if no member completes); 'weight' = such a member (any cut, p = steps / planned < 1)
# weighs p in every average written once it joined (complete members 1). Every family. The planned steps are recorded by a wrapper of
# _run_one (cfg max_steps at the call); a malformed value: one private WARN line, off. SAVE_MEMBERS files stay as written.
# ----------------------------------------------------------------------------------------------------------------------
CFG.update(cut_member=env("CUT_MEMBER", ""))
_T208D = {"said": set()}
_run_one_t208d = _run_one


def _t208d_run_one(c, model_wrap, conds, extra_args, device, seed, t_end, run_idx):
    """_run_one; records the member's planned steps (cfg max_steps at the call) in its result for G56CT_CUT_MEMBER"""
    planned = int(c["cfg"].get("max_steps") or 0)
    r = _run_one_t208d(c, model_wrap, conds, extra_args, device, seed, t_end, run_idx)
    if isinstance(r, dict) and "t208_planned" not in r:
        r["t208_planned"] = planned
    return r


def t208_cut_spec(raw):
    """G56CT_CUT_MEMBER value -> (('drop', x) | ('weight', None), None); (None, None) for '' / 'off'; (None, why) when malformed"""
    v = str(raw or "").strip().lower()
    if v in ("", "off", "none"):
        return None, None
    if v == "weight":
        return ("weight", None), None
    mode, _, xs = v.partition(":")
    if mode == "drop":
        try:
            x = float(xs)
        except ValueError:
            return None, f"{raw!r} is not 'drop:<x>' (0 < x <= 1) or 'weight'"
        if math.isfinite(x) and 0.0 < x <= 1.0:
            return ("drop", x), None
    return None, f"{raw!r} is not 'drop:<x>' (0 < x <= 1) or 'weight'"


def t208_cut_progress(r):
    """steps done / planned for a member result, or None (no record / not cut / abandoned: the ensemble's own rules)"""
    planned, n = int(r.get("t208_planned") or 0), int(r.get("steps") or 0)
    if planned <= 0 or n <= 0 or n >= planned or r.get("abandoned"):
        return None
    return n / planned


class _T208CutEnsemble(_SafeEnsemble):
    """the ensemble above with G56CT_CUT_MEMBER: a cut member dropped ('drop:x', below x of its plan) or weighted by its progress
    ('weight') in every average written once it joined; off / no cut member: the class above's calls and tensors"""

    def __init__(self, c, scale):
        super().__init__(c, scale)
        self.t208dw, self.t208dnext = [], None

    def add(self, r, k):
        raw = str(CFG.get("cut_member") or "").strip()
        if not raw:
            return super().add(r, k)
        spec, why = t208_cut_spec(raw)
        if why is not None:
            if "bad" not in _T208D["said"]:
                _T208D["said"].add("bad")
                log(f"WARN cut-member: G56CT_CUT_MEMBER {why}; off (T208)")
            return super().add(r, k)
        p = t208_cut_progress(r) if spec is not None else None
        if p is not None and spec[0] == "drop" and p < spec[1]:
            if self.sds:
                log(f"safe: member {k + 1} cut at {r.get('steps')} of {r.get('t208_planned')} planned steps ({p:.3f} < {spec[1]:g}): "
                    f"not averaged (T208 G56CT_CUT_MEMBER {raw!r})", public=True)
                if CFG.get("save_members") and r.get("best_sd") is not None:
                    _t161_save_member(self.c, r["best_sd"], r, k)
                return None
            r = dict(r, abandoned=True)  # the first member cut: kept aside, shipped only if no member completes
            log(f"safe: member {k + 1} cut at {r.get('steps')} of {r.get('t208_planned')} planned steps ({p:.3f} < {spec[1]:g}) and no "
                f"member joined yet: kept aside (T208 G56CT_CUT_MEMBER {raw!r})", public=True)
        self.t208dnext = p if (p is not None and spec is not None and spec[0] == "weight") else 1.0
        n0 = len(self.sds)
        try:
            super().add(r, k)
        finally:
            if len(self.sds) > n0:
                self.t208dw.append(self.t208dnext)
                if self.t208dnext != 1.0:
                    log(f"cut-member: member {k + 1} ({r.get('steps')} of {r.get('t208_planned')} planned steps) weighs "
                        f"{self.t208dnext:.4f} in the average (T208 G56CT_CUT_MEMBER {raw!r})")
            self.t208dnext = None

    def t208d_weights(self):
        """the weights of self.sds (the member being added included); None when unknown"""
        w = list(self.t208dw)
        if len(w) == len(self.sds) - 1 and self.t208dnext is not None:
            w.append(self.t208dnext)
        return w if len(w) == len(self.sds) else None

    def average(self):
        w = self.t208d_weights() if str(CFG.get("cut_member") or "").strip() else None
        if not self.sds or w is None or all(x == 1.0 for x in w):
            return super().average()
        K, tot = len(self.sds), float(sum(w))
        sds = [{k_: (v * (K * wk / tot) if k_.endswith((".lora_up.weight", ".diff", ".diff_b")) else v) for k_, v in sd.items()}
               for sd, wk in zip(self.sds, w)]
        return scaled_sd(average_loras(sds) if K > 1 else sds[0], self.scale)


_t208d_run_one.__wrapped__ = _run_one_t208d
_run_one = _t208d_run_one  # noqa: F811  (train_loop / the T159 v2 loop call it by name)
_SafeEnsemble = _T208CutEnsemble  # noqa: F811  (train_loop / the T159 v2 loop build it by name; off -> the class above's calls)
#
# robustness fixes ON under the release profile G56CT_PROFILE=c26s (the trainer's entrypoint default sets it; without the profile it is
# unchanged, which the T208 checks rely on): (b') T157_SKIP 'measured' + (c) T157_PARTS 1 (z-image P1 / flux FC no longer lost to the
# tail), F1d CUT_MEMBER 'drop:0.9' (a member that ended below 0.9 of its planned steps is not averaged in; the deadline / SAFE cuts of the
# T208 scan ended at 0.29-0.85 of their plans, the one at 0.96 is kept). (a) TAIL_KEPT stays OFF (KA +0.042). An explicit env var wins
# (T157_SKIP / CUT_MEMBER 'off', T157_PARTS 0 switch a part off). Switch False = the profile does not touch them.
T208_C26S_F1 = True
if T208_C26S_F1 and str(os.environ.get("G56CT_PROFILE") or "").strip().lower() == "c26s":
    for _t208k, _t208e, _t208v in (("t157_skip", "T157_SKIP", "measured"), ("t157_parts", "T157_PARTS", True),
                                   ("cut_member", "CUT_MEMBER", "drop:0.9")):
        if os.environ.get("G56CT_" + _t208e) in (None, ""):
            CFG[_t208k] = _t208v
    log(f"profile: c26s -> t157_skip {CFG['t157_skip']!r}, t157_parts {CFG['t157_parts']!r}, cut_member {CFG['cut_member']!r} "
        f"(T208 F1 / F1d; switch T208_C26S_F1)")
    del _t208k, _t208e, _t208v


