T251_K2_PARTS = ("norm", "qkv", "res", "sgate", "swiglu")
T251_SANITY_LOSS = 1e-2


def _t251_parts():
    """G56CT_K2FUSE (env, the knob's first name) else CFG['fuse_k2'] (G56CT_FUSE_K2 / the family default) -> the pieces asked for ('' / 0 /
    off -> ())"""
    s = str(os.environ.get("G56CT_K2FUSE") or CFG.get("fuse_k2", "") or "").strip().lower()
    if s in ("", "0", "off", "false", "no", "none"):
        return ()
    if s in ("1", "all", "on", "true", "yes"):
        return T251_K2_PARTS
    want = {p.strip() for p in s.split(",") if p.strip()}
    bad = sorted(want - set(T251_K2_PARTS))
    if bad:
        log(f"WARN k2fuse: unknown piece(s) {bad} ignored (known {list(T251_K2_PARTS)})")
    return tuple(p for p in T251_K2_PARTS if p in want)


def _t251_case(c, model_wrap, conds, extra_args, device):
    """T241's parity case as a function: () -> (loss, LoRA-factor gradients); gradients None before and after, a private generator"""
    import torch
    cfg = c["cfg"]
    item = c["train"][0]
    sigma = (cfg["bands"] // 2 + 0.5) / cfg["bands"]
    gen = torch.Generator(device="cpu").manual_seed(5657)
    x0 = item["scaled"].to(device)
    eps = torch.randn(x0.shape, generator=gen, dtype=torch.float32).to(device)
    xt, target = (1 - sigma) * x0 + sigma * eps, eps - x0
    plan = [(item["cond_idx"], 1.0 - cfg["empty_weight"]), (c["empty_idx"], cfg["empty_weight"])]
    params = list(c["params"])

    def one():
        for p in params:
            p.grad = None
        tot = 0.0
        for idx, w in plan:
            if w > 0:
                den = predict(model_wrap, conds, idx, xt, sigma, extra_args)
                loss = ((xt - den.float()) / sigma - target).square().mean() * w
                loss.backward()
                tot += float(loss.detach())
                del den, loss
        out = [None if p.grad is None else p.grad.detach().float().cpu() for p in params]
        for p in params:
            p.grad = None
        return tot, out
    return one


def _t251_k2_gate(c, model_wrap, conds, extra_args, device, K, parts):
    """(2) + (3) of the block comment -> (kept pieces, log line); K = g56fused_k2i4 with `parts` installed"""
    import contextlib
    t0 = time.time()
    if not c.get("train"):
        return [], "no training case to check"
    one = _t251_case(c, model_wrap, conds, extra_args, device)
    saved = dict(K.FLAGS)
    K.uninstall_krea2()
    la, ga = one()  # the default path: ComfyUI's blocks under the run's SDPA
    K.install_krea2([p for p in parts if saved.get(p)])
    K.gate_begin()
    try:
        lf, gf = one()
        n_more = _t248_more_shapes(c, model_wrap, conds, extra_args, contextlib.nullcontext)
    finally:
        res, checked, counted, spent = K.gate_end()
    kept = K.gate_verdict(res, parts)
    lrel = abs(lf - la) / max(abs(la), 1e-30)
    sane = math.isfinite(lf) and lrel <= T251_SANITY_LOSS
    pf, worst = _t241_cos(gf, ga)
    del ga, gf
    per = "; ".join(f"{p} {'PASS' if p in kept else 'FAIL'} ({res[p]['n']} calls checked, worst rel vs fp32 {res[p]['worst']:.2e}, eager "
                    f"{res[p]['eager_at_worst']:.2e}{', ' + res[p]['why'] if res[p]['why'] else ''})" if p in res else f"{p} FAIL (no call checked)"
                    for p in parts)
    line = (f"(T251, on this GPU, online on the run's activations, {n_more} extra shape forwards, {checked} calls checked + {counted} counted "
            f"only, {spent:.1f}s of checks): {per}; forward loss sanity {'ok' if sane else 'FAIL'} (loss rel {lrel:.2e} <= "
            f"{T251_SANITY_LOSS:g}; default {la:.6f}, fused {lf:.6f}); pooled grad cos fused vs default {pf:.6f} (worst tensor {worst:.4f}; "
            f"logged only) ({time.time() - t0:.1f}s)")
    if not sane:
        return [], line
    return kept, line


def _t251_train_loop(c, model_wrap, conds, extra_args, device):
    """T251: the fused krea2 pieces around the training phase (block comment); requested-off / other families -> the wrapped train_loop"""
    parts = _t251_parts() if c.get("fam") == "krea2" else ()
    if not parts:
        return _t251_train_loop.__wrapped__(c, model_wrap, conds, extra_args, device)
    K = None
    try:
        sys.path.insert(0, str(Path(__file__).resolve().parent))
        import g56fused_k2i4 as K
        t0 = time.time()
        if K.triton is None:
            raise RuntimeError("no triton")
        sc = K.selfcheck(device, parts)
        ok_parts = tuple(p for p in parts if sc.get(p, (False, {}))[0])
        for p in parts:
            if p not in ok_parts:
                log(f"WARN k2fuse-{p}: self-check failed {json.dumps(sc.get(p, (False, {}))[1], default=str)[:300]}; eager")
        if not ok_parts:
            raise RuntimeError("every requested piece failed its self-check")
        K.STATS.clear()  # (the self-check's own calls are not training calls)
        on = K.install_krea2(ok_parts)
        log(f"k2fuse: on {on} (krea2: SingleStreamBlock patched; self-checks "
            f"{json.dumps({p: {k: float(f'{v:.3g}') for k, v in sc[p][1].items()} for p in ok_parts}, default=str)[:600]}, {time.time() - t0:.1f}s)")
        kept, info = _t251_k2_gate(c, model_wrap, conds, extra_args, device, K, on)
        log(f"k2fuse: gate {'PASS' if kept else 'FAIL'} {info}" + (f" -> kept {kept}" if kept else " -> ComfyUI's blocks"))
        if not kept:
            K.uninstall_krea2()
            log("WARN k2fuse: off (krea2: the gate kept no piece); eager blocks")
            return _t251_train_loop.__wrapped__(c, model_wrap, conds, extra_args, device)
    except Exception as e:  # noqa: BLE001  (incl. OOM: ComfyUI's blocks for the whole run)
        if K is not None:
            try:
                K.gate_end()
                K.uninstall_krea2()
            except Exception:  # noqa: BLE001
                pass
        try:
            gc.collect()
            import torch
            torch.cuda.empty_cache()
        except Exception:  # noqa: BLE001
            pass
        log(f"WARN k2fuse: off (krea2: {type(e).__name__}: {' '.join(str(e).split())[:160]}); eager blocks")
        return _t251_train_loop.__wrapped__(c, model_wrap, conds, extra_args, device)
    try:
        return _t251_train_loop.__wrapped__(c, model_wrap, conds, extra_args, device)
    finally:
        log(f"k2fuse: run done {json.dumps(dict(sorted(K.STATS.items())), default=str)[:400]}")
        K.uninstall_krea2()


_t251_train_loop.__wrapped__ = train_loop
train_loop = _t251_train_loop  # noqa: F811  (Loop.sample calls it by name; knob '' -> the wrapped chain itself)
#
T251_K2_FUSE = True
if T251_K2_FUSE:
    FAMILY_DEFAULTS["krea2"].update(fuse_k2="all")

# ----------------------------------------------------------------------------------------------------------------------
#
# above, comfytrain/g56qd15.py) over MORE blocks than the 15 stratified S15 when the run's idle window holds them. The same
# arithmetic, the same estimator gate, verify, spot check, load / effect check and swap: only the block set and its fits change -
# S60 (all 60 blocks) / S30 (S15 + QD.S30X) with QD.fits_table_x() = the 186 FITS + the T119 fits of the other 540 matrices from the
# same jib_bayes.jsonl (model 'abs'). Why: the Jib cell leaves 875-1150 s idle after its K members (K capped by the file size; logs
# B26Ks0 / T217C0Ks0 da13 at x1.41, R26B12s0 6173), D15 S15 uses ~127 s of it, and the eval-only graft on two Jib tasks grew with the
#
#   Switch off (default): _t249_d15x_plan is QD.plan(final, root, shards) - S15 and the 186 FITS exactly as before; nothing else runs.
#   Research lines: G56CT_QF8_D15X=1 turns it on for one run (=0 off; an explicit value wins over the switch); the images never set it.
#   On: in qf8_d15_ship (the plan line only), the first set of T249_D15X_SETS whose file fits T249_D15X_CAP_BYTES (the D15 cap
#   T167_CAP_BYTES is raised to it, owner 30 Oct: a LoRA / diff file up to 18 GB when its bytes lower the loss), the disk next to the
#   upload folder (as qf8_d15_ship counts it, + QF8_D15_FREE_GB) and the time window is planned; none fits -> S15 as before. One
#   private 'qf8-d15x:' line. The members are never shortened for it (K and the planner unchanged; T194's reserve stays S15's).
#   The time window (1 Nov 2026, owner 30 Oct: a file above 8.4 GB needs its write time from the run's OWN measured rate - validator
#   disks can be ~25 MB/s): T249_D15X_SAFETY x (g56qd15.estimate_s with its write / re-read term at THIS run's slowest measured
#   save, _SAVE_STATS spb - never faster than the estimator's 400 MB/s - + the tail qf8_d15_ship reserves, at that rate too) must
#   fit before the hard stop; no measured save in the run -> no extension (S15). qf8_d15_ship's own rule then applies unchanged
#   (it is looser), and its build still stops at the hard stop. The upload is not the binding gate: validator nodes uploaded
#   3.8-18.6 GB image outputs at 236-330 MB/s (Loki hf-upload lines x HF sizes, 26-27 Oct, 15 uploads), well inside the trainer
#
# ----------------------------------------------------------------------------------------------------------------------
T249_D15X = True                  # entry flip switch (False = the trainer unchanged)
T249_D15X_SETS = ("S30",)          # tried in this order, then S15 (the bedah verdict picks: GO-S60 -> ("S60", "S30"), GO-S30 -> this)
T249_D15X_CAP_BYTES = int(18e9)
T249_D15X_SAFETY = 1.2            # the extension starts only when this x its projection (measured write rate) fits (T208's factor)


def _t249_on():
    """D15X in effect: G56CT_QF8_D15X '1' / '0' when set (research lines; an explicit value wins), else the entry switch T249_D15X"""
    v = str(os.environ.get("G56CT_QF8_D15X", "") or "").strip()
    return bool(T249_D15X) if v == "" else v == "1"


if _t249_on():
    T167_CAP_BYTES = max(T167_CAP_BYTES, T249_D15X_CAP_BYTES)


def _t249_d15x_plan(QD, final, root, shards, hard):
    """qf8_d15_ship's plan (the note above): off -> QD.plan(final, root, shards); on -> the first fitting set of T249_D15X_SETS, else
    S15. Never raises past the S15 plan (an extension problem -> one WARN line, S15)."""
    if not _t249_on():
        return QD.plan(final, root, shards)
    import shutil
    notes = []
    try:
        fits = QD.fits_table_x()
        workers = _t167_workers()[0]
        us = float(CFG.get("qf8_d15_est_us", 0.45))
        free = shutil.disk_usage(str(Path(final).parent.parent)).free
        spb_m = float(_SAVE_STATS.get("spb") or 0.0)   # this run's slowest measured save, s per byte (T179; G56CT_SAFE saves)
        if spb_m <= 0.0:
            raise ValueError("no measured save rate in this run (the extension's write time needs one)")
        spb = max(spb_m, 1.0 / 400e6)
        rate = f"{1e-6 / spb_m:.0f} MB/s measured"
        for name in T249_D15X_SETS:
            pl = QD.plan(final, root, shards, blocks=QD.D15X_SETS[name], fits=fits)
            est = QD.estimate_s(pl, workers, us) + 2.0 * pl["out_bytes"] * (spb - 1.0 / 400e6)
            tail = 10.0 + 2.0 * pl["out_bytes"] * spb + (pl["src_bytes"] * spb if CFG.get("qf8_d15_keep") else 0.0)
            t_need = T249_D15X_SAFETY * (est + tail)
            need = pl["out_bytes"] + (pl["src_bytes"] if CFG.get("qf8_d15_keep") else 0) + float(CFG.get("qf8_d15_free_gb", 2.0)) * 2 ** 30
            left = hard - time.time()
            why = ("size" if pl["out_bytes"] > T249_D15X_CAP_BYTES else "disk" if free < need else "time" if left < t_need else None)
            if why is None:
                log(f"qf8-d15x: {name} ({len(pl['mods'])} modules, {pl['out_bytes'] / 1e9:.2f} GB, projected {T249_D15X_SAFETY:g} x "
                    f"({est:.0f}s + {tail:.0f}s) = {t_need:.0f}s at {rate}, window {left:.0f}s, {workers} workers)")
                return pl
            notes.append(f"{name}: {why} ({pl['out_bytes'] / 1e9:.2f} GB, projected {T249_D15X_SAFETY:g} x ({est:.0f}s + {tail:.0f}s) = "
                         f"{t_need:.0f}s at {rate}, window {left:.0f}s)")
        log("qf8-d15x: S15 (" + "; ".join(notes) + ")")
    except Exception as e:  # noqa: BLE001  (the extension never costs D15 itself)
        log(f"WARN qf8-d15x: {type(e).__name__}: {str(e)[:160]}; S15")
    return QD.plan(final, root, shards)


# ----------------------------------------------------------------------------------------------------------------------
# ours (T252, 1 Nov 2026; robustness): G56CT_GC_KEEP in the T159 v2 loop. T129's gc_keep_setup ran in train_loop only (v1 /
# v2safe); the v2 loop's own lines before its members never sized it, so a v2 run with GC_KEEP set (qwen-image's c26s cell:
# 'auto') kept every block checkpointed and member 1's probe planned the members at that speed (uc1 x1.41, Jib 6173: 1.22-1.41
# s/step at 51.4 GiB, the v1 control 0.84-0.85 s/step with 60 of 60 blocks kept; T161's WARN line). Since T252 the v2 loop calls
# gc_keep_setup at train_loop's own place (after the FAST_LORA guard and SPEC_INIT, before the cache probe and member 1), so member
# 1's planner probe measures the kept-block speed. _run_one's OOM rung (_gc_keep_oom: every block checkpointed again, the step
# redone with its own draws) is _run_one's own and acts the same under both loops. The re-plan after such a drop: v1's
# _gc_keep_replan prices the time that ran with blocks kept at the all-checkpointed speed (x c['gc_keep_slow']); the v2 plan reads
# the last member's speed only (_T159Plan.done: the median of its last 5 blocks of 40 steps), so a drop in a member's last ~120
# steps would leave the next members planned at the kept speed. _T252Plan, the v2 loop's plan when GC_KEEP is set: its step hooks
# note the first step made after the drop, and done() prices that member's steps before the drop x gc_keep_slow (its seconds +
# that part x (slow - 1): v1's formula) - v1's pricing in v2's own measure; a drop before the member (an LR pilot) leaves it as
# measured; without a drop every number is _T159Plan's. GC_KEEP off: the v2 loop builds _T159Plan and never calls gc_keep_setup.
# ----------------------------------------------------------------------------------------------------------------------
class _T252Plan(_T159Plan):
    """_T159Plan with G56CT_GC_KEEP set: an OOM drop of the kept blocks priced as v1's _gc_keep_replan (the note above); without a
    drop every number is _T159Plan's"""

    def __init__(self, c, cell):
        super().__init__(c, cell)
        self.gk_drop, self.gk_t0 = None, None  # the running member's steps before the drop (None: none seen), its start

    def _gk_mark(self, step):
        if self.gk_drop is None and self.c.get("gc_keep_replan") is not None:  # the step just made ran after the drop (redone)
            self.gk_drop = max(0, int(step) - 1)

    def probe(self, step, step_times, lat):
        self._gk_mark(step)
        return super().probe(step, step_times, lat)

    def track(self, step, step_times, lat):
        self._gk_mark(step)
        return super().track(step, step_times, lat)

    def brake(self, step, step_times, lat):
        self._gk_mark(step)
        return super().brake(step, step_times, lat)

    def begin(self, k):
        self.gk_drop, self.gk_t0 = None, time.time()
        return super().begin(k)

    def done(self, k, r, d, interim, w):
        t_drop = self.c.pop("gc_keep_replan", None)  # _gc_keep_oom's time of the drop, consumed here (as _gc_keep_replan does)
        if t_drop is None:
            return super().done(k, r, d, interim, w)
        slow = max(1.0, float(self.c.get("gc_keep_slow", 1.0) or 1.0))
        steps = int(r.get("steps") or 0)
        ts, ls = self.cur_times, self.cur_lats
        live = ts is not None and len(ts) == steps and len(ls) == steps  # the hooks saw every step of this member
        i_d = self.gk_drop if self.gk_drop is not None else (steps if live else None)
        if i_d is not None and ts is not None:  # the steps made before the drop, exactly: their seconds x slow
            i_d = min(int(i_d), len(ts))
            fast = float(sum(ts[:i_d]))
            self.cur_times = [t * slow for t in ts[:i_d]] + list(ts[i_d:])
            how = f"its {i_d} step(s) before the drop"
        else:  # no step record: the member's seconds before the drop by the clock (v1's own rule)
            t0 = self.gk_t0 if self.gk_t0 is not None else float(t_drop)
            fast = max(0.0, min(d - interim, float(t_drop) - t0))
            how = "its seconds before the drop"
        super().done(k, r, d + fast * (slow - 1.0), interim, w)
        self.members[-1].update(seconds=round(d, 1), gc_keep_drop=i_d, gc_keep_slow=round(slow, 3))
        self.gk_drop = None
        log(f"planner-v2: member {k + 1}: gc keep went off (OOM): {how} ({fast:.0f}s) priced x{slow:.2f} (every block "
            f"checkpointed, as _gc_keep_replan); s_step for the re-plan {self.u:.4f}")


# ----------------------------------------------------------------------------------------------------------------------
# ours (T255, 1 Nov 2026; owner 16:10 WIB "is our planner perfect with the newest speed and mechanisms?"; default OFF = the trainer
# unchanged): G56CT_PLAN_STOP - the seeds-auto loop plans its last member against _run_one's OWN stop rule. The defect: _run_one
# stops a member before the step where now + its recent s/step + margin > the deadline, margin = max(STOP_MARGIN_S or 1.2 x
# eval_cost (72 s in the all-data recipes), SAFE's save margin) (_run_one, 'margin = ... _t126_stop' / '_save_margin'), but
# fill_member_steps sizes the fill member to end (margin = 30 s + the save margin's part above that stop) + PLAN_MARGIN_S - 30
# before the deadline: it never subtracts the stop itself (72 s; 15 s in the flux cells), only the 10 % PLAN_SAFETY on the
# member's seconds. A fill of less than ~(stop - PLAN_MARGIN_S) / (PLAN_SAFETY - 1) seconds (~420 s at the defaults) is cut by
# the deadline stop before its cosine ends, and below G56CT_CUT_MEMBER drop:0.9 of its plan (c26s) it is not averaged at all: its
# seconds are wasted. Logs uc1 / uc2 / Shadeform 31 Oct - 1 Nov: krea2 N10 d03e 'member 12 cut at 284 of 329 planned steps (0.863
# < 0.9): not averaged' (uc1 x1, 224 s left), d03e x1.48 uc2 240 / 274 (0.876), 14bc real PCIe Shadeform 303 / 341 (0.889); the
# ideogram4 R1 0.75 h fills 548 / 550, 616 / 619, 331 / 358, 320 / 353, 484 / 498 (averaged, cut mid-cosine); 106 of 528 fill
# members in the four boxes' logs ended below their plan. The same arithmetic can start a FULL member that the stop cuts (need =
# PLAN_SAFETY x its seconds + PLAN_MARGIN_S + the save part fits, its seconds + the stop do not: members < ~420 s).
# G56CT_PLAN_STOP=1 (CFG plan_stop; T255_PLAN_STOP is the entry switch): (1) a fill plan that would not complete before that stop
# (its steps x s + T255_O_S + stop > the time left) is capped at floor((left - stop - T255_O_S) / (s x (1 + T255_TOL))), s = the
# members' measured seconds per step (the fill rule's own max over members), stop = the margin _run_one will use (STOP_MARGIN_S /
# 1.2 x eval_cost + the save margin's part the caller passed). A plan that completes is unchanged; a capped plan below the fill
# threshold runs only
# when the old one would have been averaged anyway (G56CT_CUT_MEMBER off / weight, or drop:x with the capped length >= x of the old
# plan), else no fill member - the shipped average is then exactly the old one (its cut member was dropped). (2) a FULL member
# whose measured length + the stop + T255_O_S no longer fit takes the fill path (planned against the stop by (1)); its seconds
# come from this block's _run_one record (the call's wall time, the interim saves out as train_loop takes them out), never more
# than train_loop's own duration, so a member that fits is never turned into a fill. Every family; seeds-auto all-data only (the
# names it wraps are called only there). One private line per decision. Off: every wrapped name returns its inner value, nothing
# else runs (tools/t255_check.py: off == the parent trainer on every replayed cell; on: no member cut, K never below off's).
# ----------------------------------------------------------------------------------------------------------------------
T255_PLAN_STOP = False   # entry switch (False = the trainer unchanged; G56CT_PLAN_STOP overrides it either way)
T255_TOL = 0.01          # a capped fill: the measured s/step x (1 + this) (member-to-member spread on the 31 Oct - 1 Nov logs <= 1 %)
T255_O_S = 2.0           # s between the plan and the member's first step (reinit, _run_one's setup; logs 0.4-1.5 s, T159_MEMBER_O)
CFG.update(plan_stop=env("PLAN_STOP", T255_PLAN_STOP, bool))
_T255 = {"said": set()}
_fill_member_steps_t255 = fill_member_steps
_t126_fill_only_t255 = globals().get("_t126_fill_only")  # None in a text without T126's block (t126_check's knob-free build)
_run_one_t255 = _run_one


def _t255_on():
    return bool(CFG.get("plan_stop"))


def _t255_stop0():
    """the all-data stop base _run_one uses: G56CT_STOP_MARGIN_S when > 0, else 1.2 x the run's eval_cost (60 s unless measured) - the
    value of the T126 stop helper, inline (t126_check pins the T126 helpers' call counts outside their block)"""
    c = globals().get("_T179", {}).get("c")
    ev = c.get("eval_cost", 60.0) if isinstance(c, dict) else 60.0
    b = float(CFG.get("stop_margin_s", 0.0) or 0.0)
    return b if b > 0 else 1.2 * ev


def t255_fit_steps(per_step, left, stop):
    """steps a member planned now completes before _run_one's stop: floor((left - stop - T255_O_S) / (per_step x (1 + T255_TOL)))"""
    if not (per_step > 0) or not math.isfinite(per_step):
        return 0
    return max(0, int((left - stop - T255_O_S) / (per_step * (1.0 + T255_TOL))))


def t255_kept_if_cut(n_fit, n_old):
    """would the old plan's member, cut by the stop at about n_fit of its n_old steps, have been averaged? (G56CT_CUT_MEMBER)"""
    try:
        spec, why = t208_cut_spec(CFG.get("cut_member"))
    except Exception:  # noqa: BLE001  (a trainer text without T208 F1d: every member is averaged)
        return True
    if why is not None or spec is None or spec[0] != "drop":
        return True
    return n_old > 0 and n_fit / n_old >= spec[1]


def _t255_fill_member_steps(durs, steps, remaining, full_cap, frac, margin=30.0, safety=1.10):
    """fill_member_steps (T208 / T179 / the trainer's); G56CT_PLAN_STOP: capped at the steps that complete before _run_one's stop"""
    n = _fill_member_steps_t255(durs, steps, remaining, full_cap, frac, margin, safety)
    if not _t255_on():
        return n
    _T255["in_fill"] = len(durs)  # train_loop's fill path of member len(durs) + 1 (_t255_fill_only: _t126_fill_cap's call)
    if n <= 0 or not durs:
        return n
    try:
        per = max(d / max(1, k) for d, k in zip(durs, steps))
        stop = _t255_stop0() + max(0.0, float(margin) - 30.0)  # the caller's margin = 30 s + the save margin's part above the stop
        if n * per + T255_O_S + stop <= remaining:  # the plan completes at the measured speed: unchanged
            return n
        fit = t255_fit_steps(per, remaining, stop)
        thr = (min(frac, float(CFG.get("plan_fill_min", 0.5))) if CFG.get("plan_fill") else frac) * full_cap  # T126's fill threshold, inline
        # where the old plan's member would be cut: at the fastest measured s/step, no tolerance (never below the true point, so a
        # member the old plan would have averaged is never judged dropped - K never falls below the old plan's)
        cut_old = int((remaining - stop) / max(1e-9, min(d / max(1, k) for d, k in zip(durs, steps))))
        out = fit if fit > 0 and (fit >= thr or t255_kept_if_cut(cut_old, n)) else 0
        key = ("fill", n, out)
        if key not in _T255["said"]:
            _T255["said"].add(key)
            log(f"seeds-auto: fill member {n} -> {out} steps (T255 G56CT_PLAN_STOP: _run_one stops {stop:.0f}s before the deadline; "
                f"{n} steps at {per:.4f}s/step would end ~{n * per + T255_O_S + stop - remaining:.0f}s past it; {remaining:.0f}s left"
                + (")" if out else f"; {fit} steps < the fill threshold {thr:.0f} and the old member would not be averaged: no fill)"))
        return out
    except Exception as e:  # noqa: BLE001  (never ends a run: the plan as before)
        log(f"WARN seeds-auto: T255 G56CT_PLAN_STOP: {type(e).__name__}: {str(e)[:120]}; the fill as planned")
        return n


def _t255_run_one(c, model_wrap, conds, extra_args, device, seed, t_end, run_idx):
    """_run_one; G56CT_PLAN_STOP: records the member's seconds per step (wall time of the call, minus its interim saves when
    PLAN_NET takes them out of train_loop's duration) for the full-member check of _t255_fill_only"""
    if not _t255_on():
        return _run_one_t255(c, model_wrap, conds, extra_args, device, seed, t_end, run_idx)
    _T255["in_fill"] = None  # (a fill path's marker never outlives the member it planned)
    t0 = time.time()
    r = _run_one_t255(c, model_wrap, conds, extra_args, device, seed, t_end, run_idx)
    try:
        d = time.time() - t0 - (float(c.get("interim_s", 0.0)) if CFG.get("plan_net") else 0.0)
        n = int(r.get("steps") or 0) if isinstance(r, dict) else 0
        if n > 0 and not r.get("abandoned"):
            c.setdefault("t255_per", []).append(d / n)
    except Exception:  # noqa: BLE001
        pass
    return r


def _t255_fill_only(k, c):
    """_t126_fill_only; G56CT_PLAN_STOP: also True in train_loop's condition (not in the fill path's own call from _t126_fill_cap)
    when member k + 1 at the full step cap would be cut by _run_one's stop - it then takes the fill path, planned against it"""
    out = _t126_fill_only_t255(k, c)
    if out or not _t255_on() or k < 1:
        return out
    try:
        if _T255.get("in_fill") == k:  # inside the fill path of this member (_t126_fill_cap's call): the parent's answer
            return out
        per = max(c.get("t255_per") or [0.0])
        cap = int(c["cfg"].get("max_steps") or 0)
        if per <= 0 or cap <= 0:
            return out
        stop = max(_t255_stop0(), _save_margin(c) if c["cfg"].get("safe") else 0.0)
        left = c["deadline"] - time.time()
        if cap * per + T255_O_S + stop <= left:
            return out
        log(f"seeds-auto: member {k + 1} at its full {cap} steps would be cut ({cap * per:.0f}s at {per:.4f}s/step + {stop:.0f}s stop > "
            f"{left:.0f}s left): the fill path (T255 G56CT_PLAN_STOP)")
        return True
    except Exception as e:  # noqa: BLE001
        log(f"WARN seeds-auto: T255 G56CT_PLAN_STOP: {type(e).__name__}: {str(e)[:120]}; member {k + 1} as planned")
        return out


# T255 (b) - the ideogram4 R1 window (flip switch, default OFF = the trainer unchanged): the 0.75 h ideogram4 cells end 11-19 % of the
# window early (T251IFVs0 31 Oct - 1 Nov: 'done in' 2201 / 2367 / 2358 / 2348 s of 2700, Shadeform real PCIe 2365 / 2395) - the family's
# generic wall_frac 0.97 + reserve_s 120 (81 + 120 s, the pre-LIFT / dense-pass margins; ship 'lora' since T173), the LIFT final-fold
# reserve (1.5 x the measured fold + 30 s = 69-90 s) and SAFE's save margin at x2 (2810: 205 s at k 6, 'next needs ~503s, 301s left',
# for a final save measured at ~50 s). T255_I4_WINDOW True: ideogram4 tasks with N <= T255_I4_WINDOW_MAX_N training images (every
# R1 task: N 9-27) take the flux cell's measured margins (FAMILY_DEFAULTS_BIG_N['flux'], every flux task since 15 Oct): wall_frac 1.0,
# reserve_s 75, PLAN_SAFETY 1.03, PLAN_MARGIN_S 10, STOP_MARGIN_S 15, SAVE_MARGIN_X 1.0, through FAMILY_DEFAULTS_BIG_N_BAND (an explicit
# env var still wins; _t126_deadline re-derives the deadline as for flux). The LIFT reserve and its fold are untouched. The time goes
# to the v1 planner's own members (K + 1 full or a longer fill, sized from the measured member seconds; G56CT_PLAN_STOP plans the last
#
T255_I4_WINDOW = False   # flip switch (False = the trainer unchanged)
T255_I4_WINDOW_MAX_N = 30
T255_I4_WINDOW_VALUES = dict(plan_stop=True, wall_frac=1.0, reserve_s=75.0, plan_safety=1.03, plan_margin_s=10.0, stop_margin_s=15.0,
                             save_margin_x=1.0)
if T255_I4_WINDOW and "ideogram4" not in FAMILY_DEFAULTS_BIG_N_BAND:
    FAMILY_DEFAULTS_BIG_N_BAND["ideogram4"] = (1, T255_I4_WINDOW_MAX_N, dict(T255_I4_WINDOW_VALUES))
# T255 (b) GPTQ guard (T231 01 Nov 19:5x, simulating the flip on b9ecfe0: planner2_check gate164 failed): with G56CT_DENSE=gptq the
# dense pass's window W = ghard - deadline + DENSE_GPTQ_RESERVE_S is computed from the deadline, and the window's wall_frac 1.0 +
# reserve_s 75 put the deadline 126 s later - on H100 SXM5 (x1.0) 36b4 / 03d1 went from a KEPT pass to SKIPPED ('projected 272s >
# 225s'). Under G56CT_DENSE=gptq the window therefore never sets its margins: apply_big_n_defaults' wrapper takes them back right
# after the band set them (the values from before the band, the 'applied' record without them); plan_stop stays (it plans only the
# last member, after the speed gate's decision). The c26s entry ships ideogram4 as 'lora' (T173_C26S_I4_SHIP): no dense pass exists
# there, so the window applies whole (the validation arms' env). Switch off: the band is never installed and the wrapper returns
# the parent's value untouched.
T255_I4_WINDOW_GPTQ_KEEP = ("plan_stop",)
_T255_ABSENT = object()
_apply_big_n_defaults_t255 = apply_big_n_defaults


def _t255_apply_big_n(fam, n_images):
    """apply_big_n_defaults (T172's / T159's wrappers, the trainer's); T255_I4_WINDOW under G56CT_DENSE=gptq: the window's planner /
    deadline margins taken back (the values before the band; plan_stop kept) so the dense GPTQ pass's window is the one off has"""
    band = FAMILY_DEFAULTS_BIG_N_BAND.get("ideogram4") if (T255_I4_WINDOW and fam == "ideogram4") else None
    keys = [k for k in T255_I4_WINDOW_VALUES if k not in T255_I4_WINDOW_GPTQ_KEEP]
    before = {k: CFG.get(k, _T255_ABSENT) for k in keys} if band is not None else None
    applied = _apply_big_n_defaults_t255(fam, n_images)
    if before is None or not _gptq_mode() or not isinstance(applied, dict):
        return applied
    took = [k for k in keys if k in applied]
    for k in took:
        if before[k] is _T255_ABSENT:
            CFG.pop(k, None)
        else:
            CFG[k] = before[k]
        applied.pop(k, None)
    if took:
        log(f"i4-window: G56CT_DENSE=gptq -> the planner margins stay ({', '.join(took)} as before the window; plan_stop kept) (T255)")
    return applied


_t255_apply_big_n.__wrapped__ = _apply_big_n_defaults_t255
