def _t280f_gs_why_not(c, cfg, te, small_params, pilot):
    """_t241_gs_why_not; G56CT_R1F_GRAPH2 (c): a run whose items hold exactly the images' one latent shape + the phase twins' is not
    refused for its shapes (every other reason stands)"""
    why = _t280f_inner_gs_why(c, cfg, te, small_params, pilot)
    if not why or not CFG.get("r1f_graph2") or not str(why).startswith("2 latent shapes"):
        return why
    tw = c.get("t277_tw")
    if tw is None:
        return why
    n = int(tw["n"])
    tr = c.get("train") or []
    img = {tuple(it["scaled"].shape) for it in tr[:n] if it.get("scaled") is not None}
    twn = {tuple(it["scaled"].shape) for it in tr[n:2 * n] if it.get("scaled") is not None}
    allv = {tuple(it["scaled"].shape) for it in tr if it.get("scaled") is not None}
    if len(img) != 1 or len(twn) != 1 or allv != img | twn:
        return why
    try:
        import torch
        if not torch.cuda.is_available():
            return "no CUDA"
    except Exception:  # noqa: BLE001
        return "no torch"
    _t280f_say(("graph2",), f"r1f graph2: the CUDA graph step on 2 latent shapes (the images' {sorted(img)[0]} + the phase twins' "
                            f"{sorted(twn)[0]}); T241's keys, memory gate, first-replay check and fallback as before")
    return None


_t280f_gs_why_not.__wrapped__ = _t280f_inner_gs_why
_t241_gs_why_not = _t280f_gs_why_not  # noqa: F811  (the T241 graph setup calls it by name; off -> the function above itself)
