def _t284_kind(d):
    """the drawn case (_T277['draw']: item, band, half, twin flag / kind) -> (kind 0 image / 1 phase twin / 2 mirror, half) or (None, None)"""
    if d is None:
        return None, None
    return (2 if d[3] == 2 else 1 if d[3] else 0), int(d[2])


def _t284_resolved(c, conds, plan):
    """(d): the plan as the eager step conditions it - each half's prompt index through this run's T277 / R1F predict wrappers (the
    member's own predict is built from the same ones), in the current grad mode: a phase twin's / mirror's empty half -> its tag alone"""
    res = _t277_predict(lambda *a, **k: a[2] if len(a) > 2 else k.get("cond_idx"), c)
    return [(res(None, conds, i_, None, None, None), w_) for i_, w_ in plan]


def _t284_check(c, gs, model_wrap, conds, plan, mapped, xt, target, sigma, extra_args, fs):
    """(d): this step's per-half graph losses vs no-grad eager forwards through the trainer's predict (the rank-r route of T241's own
    later-key check) of the resolved prompts and of the plan's own -> (ok, rel to the resolved, rel to the plan's), or None when the
    step left no graph entry (the memory gate's eager step)"""
    import torch
    hm = [(i_, w_) for i_, w_ in mapped if w_ > 0]
    hp = [(i_, w_) for i_, w_ in plan if w_ > 0]
    k = gs.key(xt, conds, hm, fs)
    e = gs.ent.get(k) if k is not None else None
    if e is None or e.get("vals") is None:
        return None
    rv = [float(x) for x in e["vals"].detach().float().cpu().tolist()[1:1 + len(hm)]]

    def eager(halves):
        lv = []
        with torch.no_grad(), _FastLrNoGrad(c):
            for idx, w in halves:
                den = predict(model_wrap, conds, idx, xt, sigma, extra_args)
                lv.append(float(((((xt - den.float()) / sigma) - target).square().mean() * w).detach()))
                del den
        return lv

    def rel(a, b):
        return max([abs(x - y) / max(abs(y), 1e-30) if math.isfinite(x) else float("inf") for x, y in zip(a, b)] or [0.0])
    rt, rp = rel(rv, eager(hm)), rel(rv, eager(hp))
    # bit-exact regimes (flux G10: the first key's graph vs no-grad offset is 0.0 [T248F* logs]): a graph loss that equals the plan's
    # prompt's eager loss but not the resolved prompt's is the plan's prompt, however small the two prompts' difference; else T241's tolerance
    ok = rt == 0.0 or (rp != 0.0 and rt <= float(gs.nograd_tol))
    return ok, rt, rp


def _t284_graph_run(c, params, model_wrap, conds, plan, xt, target, sigma, extra_args, opt, step, ckpt_on, fs, fst, device, te,
                    small_params, pilot):
    """_t241_graph_run, _run_one's step hook (None = this step eager); (d): in a run with twins / mirrors the graph gets the plan
    resolved as the eager step's predict conditions it, the first graph step of each twin kind is checked against eager forwards (a
    mismatch: the graphs dropped, this step eager), every step counted per kind and half (c['t284_gs']); no twins: the hook itself"""
    if not plan or (c.get("t277_tw") is None and c.get("t280_ftw") is None):
        return _t284_inner_graph_run(c, params, model_wrap, conds, plan, xt, target, sigma, extra_args, opt, step, ckpt_on, fs, fst,
                                     device, te, small_params, pilot)
    st = c.get("t284_gs")
    if st is None:
        st = c["t284_gs"] = {"graph": {}, "eager": {}, "checked": {}}
    kind, half = _t284_kind(_T277.get("draw"))
    name = f"{T284_KINDS[kind] if kind is not None else 'unknown'} {('caption', 'empty')[half] if half in (0, 1) else 'half?'}"
    try:
        mapped = _t284_resolved(c, conds, plan)
    except Exception as e:  # noqa: BLE001  (this step eager: its own predict resolves the prompt)
        _t280f_say(("t284_res",), f"WARN r1f graph: a step's prompts not resolved ({type(e).__name__}: {str(e)[:120]}); such steps eager")
        st["eager"][name] = st["eager"].get(name, 0) + 1
        return None
    r = _t284_inner_graph_run(c, params, model_wrap, conds, mapped, xt, target, sigma, extra_args, opt, step, ckpt_on, fs, fst, device,
                              te, small_params, pilot)
    if r is None:
        st["eager"][name] = st["eager"].get(name, 0) + 1
        return None
    gs = c.get("gs")
    if kind in (1, 2) and mapped != list(plan) and T284_KINDS[kind] not in st["checked"] and gs is not None:
        try:
            got = _t284_check(c, gs, model_wrap, conds, plan, mapped, xt, target, sigma, extra_args, fs)
            why = None
        except Exception as e:  # noqa: BLE001  (an out-of-memory included: the graphs dropped, this step eager)
            got, why = (False, float("nan"), float("nan")), f"{type(e).__name__}: {' '.join(str(e).split())[:120]}"
        if got is not None:
            ok, rt, rp = got
            st["checked"][T284_KINDS[kind]] = {"ok": bool(ok), "rel": float(f"{rt:.3g}"), "rel_plan": float(f"{rp:.3g}"), "step": int(step),
                                               "prompt": [i_ for i_, _ in mapped], "plan": [i_ for i_, _ in plan],
                                               "tolerance": float(f"{float(gs.nograd_tol):.3g}")}
            log(f"r1f graph: the first {T284_KINDS[kind]}-twin empty-half graph step (step {step}): prompt {[i_ for i_, _ in mapped]} "
                f"(the plan's {[i_ for i_, _ in plan]}) - its graph loss vs a no-grad eager forward of that prompt rel {rt:.1e} "
                f"(tolerance {float(gs.nograd_tol):.1e}), of the plan's prompt rel {rp:.1e}"
                + (f" ({why})" if why else "") + (" -> ok" if ok else " -> MISMATCH: the graphs dropped, eager steps"))
            if not ok:
                for p in params:
                    p.grad = None
                gs.off(f"r1f graph: the {T284_KINDS[kind]}-twin empty-half check failed (rel {rt:.1e})")
                st["eager"][name] = st["eager"].get(name, 0) + 1
                return None
    st["graph"][name] = st["graph"].get(name, 0) + 1
    return r


_t284_graph_run.__wrapped__ = _t284_inner_graph_run
_t241_graph_run = _t284_graph_run  # noqa: F811  (_run_one calls it by name; no twins -> the function above itself)


# ----------------------------------------------------------------------------------------------------------------------
#
#   G56CT_T290_PJ '1' | 'bands:<lo>-<hi>[,p:<p>][,bank:<n>]' (z-image / ideogram4 / flux; '1' = the defaults): PHASE JITTER. At main()
#     time every training image is also encoded, by the run's own VAE function (encode_latent below every wrapper), at the first n of
#     T290_PJ_OFFSETS: windows ONE TOKEN smaller in each axis whose top-left corner (dx, dy) is a fraction of a token (z-image / flux:
#     token 16 px = VAE 8 x patch 2; ideogram4: one latent position = 16 px), i.e. the same content shifted against the token / latent
#     grid by a sub-token phase. In training, a case of such an image whose band lies in [lo, hi] trains, with probability p, one of the
#     image's n phase latents (uniform) in place of its own latent: the SAME caption / empty prompt, the SAME case - cell counts, image
#     order and the schedule's RNG unchanged (PJ draws only from its own random.Random; the noise generator draws the phase latent's
#     one-token-smaller shape, so the noise stream moves on differently from a PJ-off run). No tag, no extra case, no extra item.
#     Twins / mirrors / any other item keep their own latent. Needs G56CT_EXPOSURE (the drawn case gives the band) and G56CT_FAST_SYNC
#     (the latent's device copy is where a phase latent is served); without them PJ does not act (one private WARN line at the end).
#     Why (first principles): where an image's content falls on the token grid is a nuisance variable that is uniformly distributed
#     over the evaluator's test images; training on ONE fixed alignment per image lets the LoRA fit grid-aligned detail of the N
#     training images; drawing the alignment at random is an augmentation that keeps the data distribution unbiased (up to one token
#     of border). Unlike a tagged twin it reaches the empty prompt too, and it dilutes no band (no case is added).
#     Values (ours, not tuned): offsets = the half / quarter / three-quarter token points of a 4 x 4 phase grid (geometry); bands 0-11
#     = where content detail matters (sigma <= 0.72; at the top bands the target is coarse layout); p 0.5 = half the visits keep the
#     exact test-resolution image (risk balance); n 7 = every listed offset.
#   G56CT_T290_ECRN '1' | 'bands:<lo>-<hi>' (z-image / ideogram4 / flux; '1' = bands 8-15): COMMON RANDOM NUMBERS for the two halves of
#     an item under EXPOSURE. When a case (item, band, half) of a band in [lo, hi] is drawn and the schedule still holds the same item's
#     other half in that band, that case is moved to the front of the member's queue (no case added or removed, no draw from the
#     schedule's RNG): the two halves train in consecutive steps on the SAME noisy sample - the second half's noise is the first one's
#     (the trainer's noise generator still draws as before, so every stream stays aligned), its sigma the same band midpoint.
#     Why: with one shared target v, the noise of the target cancels from the caption-effect direction (f_caption - f_empty) of the
#     pair's summed update and stays in the shared direction only; independent halves put it in both. EXPOSURE (balanced-only) dropped
#     the paired-noise property of PROMPT_MODE=paired; ECRN brings it back without halving the optimizer steps. Bands 8-15 (ours) =
#
#     sec. 0.1). Needs G56CT_EXPOSURE and SIGMA_MODE=mid (else off, one private WARN line).
# Logging: private lines 't290 ...' only. Robustness: a malformed value -> that knob off (one private WARN line); any exception at main()
# time -> no phase latent (one WARN), in training -> that step as without the knob and the knob off for the rest of the run (one WARN).
# ----------------------------------------------------------------------------------------------------------------------
CFG.update(t290_pj=env("T290_PJ", ""), t290_ecrn=env("T290_ECRN", ""))
T290_KNOBS = ("t290_pj", "t290_ecrn")
T290_FAMS = ("z-image", "ideogram4", "flux")
T290_OFF = ("", "0", "off", "none", "false", "no")
T290_TOKEN = {"z-image": 16, "ideogram4": 16, "flux": 16}  # px per token / latent position (VAE factor x patch), ours from the models
T290_PJ_OFFSETS = ((0.5, 0.5), (0.5, 0.0), (0.0, 0.5), (0.25, 0.25), (0.75, 0.75), (0.25, 0.75), (0.75, 0.25))  # x token px
T290_PJ_DEFAULT = {"bands": (0, 11), "p": 0.5, "bank": 7}
T290_ECRN_DEFAULT = {"bands": (8, 15)}
_T290 = {"said": set(), "pj_lat": {}, "pj_bad": None, "pj_enc_s": 0.0, "st": None}


def _t290_say(key, msg):
    """one private line per key and process"""
    if key not in _T290["said"]:
        _T290["said"].add(key)
        log(msg)


def _t290_bands(v, raw):
    a, sep, b = v.partition("-")
    lo, hi = int(a), int(b if sep else a)
    if not 0 <= lo <= hi <= 15:
        raise ValueError(f"bands {v!r} outside 0-15 in {raw!r}")
    return lo, hi


def t290_spec(knob, raw):
    """a G56CT_T290_* value -> None (off: '', '0', 'off', ...) or its parameters; ValueError on a bad value. '1' / 'on' = the defaults.
    t290_pj: parts 'bands:lo-hi' (0 <= lo <= hi <= 15), 'p:x' (0 < x <= 1), 'bank:n' (1 <= n <= 7); t290_ecrn: 'bands:lo-hi'.
    Each part at most once."""
    s = str(raw if raw is not None else "").strip().lower()
    if s in T290_OFF:
        return None
    out = dict(T290_PJ_DEFAULT if knob == "t290_pj" else T290_ECRN_DEFAULT)
    if s in ("1", "on"):
        return out
    keys = ("bands", "p", "bank") if knob == "t290_pj" else ("bands",)
    seen = set()
    for part in s.split(","):
        k, sep, v = part.partition(":")
        k, v = k.strip(), v.strip()
        if not sep or k not in keys or k in seen or not v:
            raise ValueError(f"bad part {part!r} in {raw!r}")
        seen.add(k)
        if k == "bands":
            out["bands"] = _t290_bands(v, raw)
        elif k == "p":
            x = float(v)
            if not (math.isfinite(x) and 0.0 < x <= 1.0):
                raise ValueError(f"p {v!r} outside (0, 1] in {raw!r}")
            out["p"] = x
        else:
            n = int(v)
            if not 1 <= n <= len(T290_PJ_OFFSETS):
                raise ValueError(f"bank {v!r} outside 1-{len(T290_PJ_OFFSETS)} in {raw!r}")
            out["bank"] = n
    return out


def _t290_main_spec(knob):
    """the knob's parameters for this run (an R1 family, the knob set and well formed) or None"""
    try:
        sp = t290_spec(knob, CFG.get(knob))
    except ValueError as e:
        _t290_say((knob, "bad"), f"WARN t290: G56CT_{knob.upper()}: {e}; off")
        return None
    if sp is None:
        return None
    fam = _T157.get("fam")
    if fam not in T290_FAMS:
        _t290_say((knob, "fam", fam), f"t290: G56CT_{knob.upper()} off (for {', '.join(T290_FAMS)} only; family {fam})")
        return None
    return sp


def t290_pj_crop(img, fx, fy, token):
    """the phase window of a prepared image: one token smaller in each axis, its top-left corner at (fx, fy) x token px
    -> (PIL image, box) or (None, why) when the window is not a whole number of tokens"""
    w, h = img.size
    dx, dy = int(round(fx * token)), int(round(fy * token))
    cw, ch = w - token, h - token
    if cw < 2 * token or ch < 2 * token or cw % token or ch % token or not (0 <= dx < token and 0 <= dy < token):
        return None, f"{w}x{h} -> {cw}x{ch} at ({dx}, {dy}) is not a whole number of {token} px tokens"
    box = (dx, dy, dx + cw, dy + ch)
    return img.crop(box), box


_encode_latent_t290 = encode_latent
_t290_enc0 = encode_latent  # the trainer's own encode (below every wrapper): a phase window never reaches a twin / mirror recorder
while getattr(_t290_enc0, "__wrapped__", None) is not None:
    _t290_enc0 = _t290_enc0.__wrapped__


def _t290_encode_latent(vae_pair, image, device):
    """encode_latent; with G56CT_T290_PJ also the image's phase windows (t290_pj_crop at T290_PJ_OFFSETS) by the same VAE function,
    keyed by decode_items' sha of the image"""
    lat = _encode_latent_t290(vae_pair, image, device)
    sp = _t290_main_spec("t290_pj")
    if sp is None or _T290.get("pj_bad"):
        return lat
    try:
        key = t277_image_sha(image)
        if key in _T290["pj_lat"]:
            return lat
        tok = T290_TOKEN[_T157.get("fam")]
        t0 = time.time()
        vs = []
        for fx, fy in T290_PJ_OFFSETS[:sp["bank"]]:
            crop, box = t290_pj_crop(image, fx, fy, tok)
            if crop is None:
                _T290.update(pj_bad=box, pj_lat={})
                log(f"WARN t290 pj: off for this run (an image {box}); no phase latent at all")
                return lat
            vs.append(_t290_enc0(vae_pair, crop, device))
        _T290["pj_lat"][key] = vs
        _T290["pj_enc_s"] += time.time() - t0
    except Exception as e:  # noqa: BLE001  (never ends a run: no phase latent)
        _T290.update(pj_bad=f"{type(e).__name__}: {str(e)[:120]}", pj_lat={})
        log(f"WARN t290 pj: encode {_T290['pj_bad']}; no phase latents")
    return lat


encode_latent = _t290_encode_latent  # noqa: F811  (main() calls it by name)
_t290_encode_latent.__wrapped__ = _encode_latent_t290


def _t290_flush(st):
    """the private line of the member whose cases the knobs saw (nothing for a member without one)"""
    pj, ec = st.get("pj"), st.get("ecrn")
    parts = []
    if pj is not None and pj["count"]:
        tot = sum(v[0] + v[1] for v in pj["count"].values())
        jit = sum(v[1] for v in pj["count"].values())
        pj["runs"].append({"member": st["member"], "cases": tot, "phase": jit})
        parts.append(f"pj {jit} of {tot} cases of the phase images in bands {pj['spec']['bands'][0]}-{pj['spec']['bands'][1]} on a phase "
                     f"latent (per band phase / plain: " + ", ".join(f"b{b} {v[1]}/{v[0]}" for b, v in sorted(pj["count"].items())) + ")")
        pj["count"] = {}
    if ec is not None and (ec["m"]["pairs"] or ec["m"]["broken"]):
        ec["runs"].append(dict(ec["m"], member=st["member"]))
        parts.append(f"ecrn {ec['m']['pairs']} pairs formed, {ec['m']['shared']} second halves on the first half's noise, "
                     f"{ec['m']['broken']} broken (the partner not drawn next), {ec['m']['lone']} cases without a partner left")
        ec["m"] = {"pairs": 0, "shared": 0, "broken": 0, "lone": 0}
    if parts:
        log(f"t290: member {st['member']}: " + "; ".join(parts))


def _t290_install(c, sp_pj, sp_ec):
    """the training-time state + hooks: Exposure.draw (PJ's choice, ECRN's pairing), _t208_fs_dev (PJ's phase latent), _t208_fs_h2d
    (ECRN's shared noise) -> the state (or None when no knob can act)"""
    st = {"pj": None, "ecrn": None, "exs": None, "member": 0, "draws": 0, "fs_calls": 0, "h2d_calls": 0, "on": True,
          "draw0": _T277_EXP_BASE.draw, "fs0": globals()["_t208_fs_dev"], "h2d0": globals()["_t208_fs_h2d"]}
    if sp_pj is not None:
        lat = _T290.get("pj_lat") or {}
        train = list(c["train"])
        miss = [it.get("name") for it in train if not lat.get(it.get("sha"))]
        if not lat or miss:
            log(f"WARN t290 pj: {len(miss)} of {len(train)} training image(s) without phase latents (e.g. {miss[:1]}); PJ off for this run")
        else:
            mp = c["mp"]
            bank = {id(it): [mp.model.process_latent_in(v.clone()).float().cpu() for v in lat[it["sha"]]] for it in train}
            st["pj"] = {"spec": sp_pj, "bank": bank, "choice": None, "rng": None, "count": {}, "runs": []}
            fam = _T157.get("fam")
            shapes = sorted({tuple(v.shape) for vs in bank.values() for v in vs})
            log(f"t290 pj: on: {len(train)} images x {sp_pj['bank']} phase latents (latents {shapes[:2]}, from "
                f"{sorted({tuple(it['scaled'].shape) for it in train})[:2]}; encoded in {_T290.get('pj_enc_s', 0.0):.1f}s at main()), "
                f"bands {sp_pj['bands'][0]}-{sp_pj['bands'][1]}, p {sp_pj['p']:g}, offsets (px) "
                f"{[(int(round(fx * T290_TOKEN[fam])), int(round(fy * T290_TOKEN[fam]))) for fx, fy in T290_PJ_OFFSETS[:sp_pj['bank']]]}")
    if sp_ec is not None:
        if c["cfg"].get("sigma_mode") != "mid":
            log(f"WARN t290 ecrn: off (needs SIGMA_MODE=mid: the two halves' sigma; {c['cfg'].get('sigma_mode')!r})")
        else:
            st["ecrn"] = {"spec": sp_ec, "first": None, "second": None, "role": None, "eps": None, "ex": None, "pj": None,
                          "m": {"pairs": 0, "shared": 0, "broken": 0, "lone": 0}, "runs": []}
            log(f"t290 ecrn: on: bands {sp_ec['bands'][0]}-{sp_ec['bands'][1]} (an item's two halves in consecutive steps on one noisy "
                f"sample under EXPOSURE)")
    if st["pj"] is None and st["ecrn"] is None:
        return None
    draw0, fs0, h2d0 = st["draw0"], st["fs0"], st["h2d0"]
    pj, ec = st["pj"], st["ecrn"]

    def off(where, e):
        st["on"] = False
        if pj is not None:
            pj["choice"] = None
        if ec is not None:
            ec.update(role=None, eps=None, first=None, second=None)
        log(f"WARN t290: {where} {type(e).__name__}: {str(e)[:120]}; the knobs off for the rest of this run")

    def draw(ex):
        pend = ex.pending is not None
        r = draw0(ex)
        if not st["on"]:
            return r
        try:
            if st["exs"] is not ex:  # a new member's schedule
                _t290_flush(st)
                st.update(exs=ex, member=st["member"] + 1)
                if pj is not None:
                    pj.update(choice=None, rng=random.Random(f"g56-t290-pj:{CFG['seed']}:{st['member']}"))
                if ec is not None:
                    ec.update(first=None, second=None, role=None, eps=None, ex=ex, pj=None)
            st["draws"] += 1
            if pend:  # a redone case (the same pending one) keeps its choice and its role
                return r
            b, h = int(r[1]), int(r[2])
            second = False
            if ec is not None:
                if ec["second"] is not None and tuple(r) == ec["second"] and ec["ex"] is ex:
                    ec.update(role="second", second=None)
                    second = True
                else:
                    if ec["second"] is not None:
                        ec["m"]["broken"] += 1
                    ec.update(role=None, first=None, second=None, eps=None, pj=None)
                    lo, hi = ec["spec"]["bands"]
                    if lo <= b <= hi:
                        want = (int(r[0]), b, h ^ 1)
                        q = ex.queue
                        j = next((n for n in range(len(q) - 1, -1, -1) if tuple(q[n]) == want), None)
                        if j is None:
                            ec["m"]["lone"] += 1
                        else:
                            q.append(q.pop(j))  # the partner is the schedule's next draw (pop() takes the end)
                            ec.update(role="first", first=tuple(r), second=want)
                            ec["m"]["pairs"] += 1
            if pj is not None:
                if second and ec["pj"] is not None:  # the second half: the very latent of the first half
                    pj["choice"] = (b, ec["pj"][1])
                else:
                    lo, hi = pj["spec"]["bands"]
                    k = None
                    if lo <= b <= hi and pj["rng"].random() < pj["spec"]["p"]:
                        k = pj["rng"].randrange(pj["spec"]["bank"])
                    pj["choice"] = (b, k)
                if ec is not None and ec["role"] == "first":
                    ec["pj"] = pj["choice"]
        except Exception as e:  # noqa: BLE001
            off("draw", e)
        return r

    def fs_dev(cc, item, device):
        if not st["on"] or pj is None or cc.get("lr_pilot_run"):
            return fs0(cc, item, device)
        try:
            st["fs_calls"] += 1
            vs, ch = pj["bank"].get(id(item)), pj.get("choice")
            if vs is None or ch is None:
                return fs0(cc, item, device)
            b, k = ch
            if k is None:  # a plain case: counted (per band) only inside the phase bands
                if pj["spec"]["bands"][0] <= b <= pj["spec"]["bands"][1]:
                    pj["count"].setdefault(b, [0, 0])[0] += 1
                return fs0(cc, item, device)
            pj["count"].setdefault(b, [0, 0])[1] += 1
            return fs0(cc, {"scaled": vs[k]}, device)
        except Exception as e:  # noqa: BLE001
            off("latent", e)
            return fs0(cc, item, device)

    def h2d(t, device, on):
        out = h2d0(t, device, on)
        if not st["on"] or ec is None:
            return out
        try:
            st["h2d_calls"] += 1
            if ec["role"] == "first":
                ec["eps"] = out
            elif ec["role"] == "second" and ec["eps"] is not None:
                if tuple(ec["eps"].shape) == tuple(out.shape):
                    ec["m"]["shared"] += 1
                    return ec["eps"]
                ec["m"]["broken"] += 1
                ec.update(role=None, eps=None)
        except Exception as e:  # noqa: BLE001
            off("noise", e)
        return out

    _T277_EXP_BASE.draw = draw
    if pj is not None:
        globals()["_t208_fs_dev"] = fs_dev
    if ec is not None:
        globals()["_t208_fs_h2d"] = h2d
    st.update(draw=draw, fs=fs_dev, h2d=h2d)
    return st


def _t290_remove(st):
    """the hooks restored (only where they are still ours), the last member's line, the run's summary"""
    if _T277_EXP_BASE.__dict__.get("draw") is st.get("draw"):
        _T277_EXP_BASE.draw = st["draw0"]
    if globals().get("_t208_fs_dev") is st.get("fs"):
        globals()["_t208_fs_dev"] = st["fs0"]
    if globals().get("_t208_fs_h2d") is st.get("h2d"):
        globals()["_t208_fs_h2d"] = st["h2d0"]
    _t290_flush(st)
    pj, ec = st.get("pj"), st.get("ecrn")
    if pj is not None and (st["draws"] == 0 or st["fs_calls"] == 0):
        log(f"WARN t290 pj: did not act ({st['draws']} drawn cases, {st['fs_calls']} latent fetches: it needs G56CT_EXPOSURE and "
            f"G56CT_FAST_SYNC)")
    if ec is not None and (st["draws"] == 0 or not any(r["shared"] for r in ec["runs"])):
        log(f"WARN t290 ecrn: did not act ({st['draws']} drawn cases, {st['h2d_calls']} noise transfers: it needs G56CT_EXPOSURE)")
    log(f"t290: done {json.dumps({'pj': pj['runs'] if pj else None, 'ecrn': ec['runs'] if ec else None, 'draws': st['draws'], 'on': st['on']})[:900]}")


_train_loop_t290 = train_loop


def _t290_train_loop(c, model_wrap, conds, extra_args, device):
    """train_loop; with G56CT_T290_PJ / G56CT_T290_ECRN their state + hooks for the training phase (restored when it returns / raises)"""
    sp_pj, sp_ec = _t290_main_spec("t290_pj"), _t290_main_spec("t290_ecrn")
    st = None
    if sp_pj is not None or sp_ec is not None:
        try:
            st = _t290_install(c, sp_pj, sp_ec)
        except Exception as e:  # noqa: BLE001  (never ends a run: the knobs off)
            st = None
            log(f"WARN t290: setup {type(e).__name__}: {str(e)[:120]}; the knobs off for this run")
    _T290["st"] = st
    try:
        return _train_loop_t290(c, model_wrap, conds, extra_args, device)
    finally:
        if st is not None:
            try:
                _t290_remove(st)
            except Exception as e:  # noqa: BLE001
                log(f"WARN t290: teardown {type(e).__name__}: {str(e)[:120]}")
        _T290.update(st=None, pj_lat={}, pj_bad=None, pj_enc_s=0.0)


_t290_train_loop.__wrapped__ = _train_loop_t290
train_loop = _t290_train_loop  # noqa: F811  (Loop.sample calls it by name; knobs off -> the wrapped train_loop itself)


# ----------------------------------------------------------------------------------------------------------------------
#
#
# z-image / flux (G56CT_ZCB_KLAW + G56CT_ZCB_TWIN; with mirrors also G56CT_R1F_FLIP). A view is a window of the evaluator-prepared
# image, or of its mirror (PIL ImageOps.mirror), with the SHAPE of the run's phase twin - axis 'wh': one token smaller in both axes,
# axis 'w': one token smaller in the width only - whose top-left corner sits at a sub-token phase (T300_OFFS; window 0 = the twin's
# own crop). Every window is encoded at main() time by the run's own VAE function (the innermost encode_latent), keyed by
# decode_items' sha. In training every drawn case keeps what the twin / mirror / exposure knobs drew - item, band, half, prompt, the
# schedule's draws: no item, case, prompt or random draw is added or changed - and only the LATENT the case trains is served from the
# bank, through _t208_fs_dev (needs G56CT_FAST_SYNC):
#   'twin:<n>'    a phase-twin case of image i trains, in rotation, the twin itself (slot 0) or one of windows 1 .. n-1;
#   'mirror:<n>'  a mirror case (G56CT_R1F_FLIP) trains, in rotation, the mirror itself (slot 0) or one of the mirror's windows
#                 0 .. n-2;
#   'img:<lo>-<hi>[,share:<s>][,imgn:<n>]'  an image case in the bands lo..hi trains, in rotation, the image itself or - in a share s
#                 of the slots (default 1/2, a fraction a/b with b <= 8) - one of its windows 0 .. n-1 (default: every window of the
#                 axis) under its own caption / empty prompt.
# Rotation (deterministic, no RNG): per (kind, image, band quarter b // 4, half) one counter over the whole run; the slot of a case
# = list[(start + count) mod len], start = image + half x len // 2 + quarter x max(1, len // 4): within any run of consecutive cases
# of one key every slot is served up to one apart, and each member starts where the previous one stopped (the per-member offset).
# A redone case keeps its view. Every view has the shape of an item of the run (the phase twin's), so the fused kernels' shapes and
# flux's CUDA graph (R1F_GRAPH2: two shapes; a twin case keeps the twin's shape) are what the knobs off give.
#
# image is trained on in the low sigma bands; the bank adds views without adding a case, a member or a latent shape.
# Values (ours, geometry): the windows = the half / quarter / three-quarter token points; the axis 'w' list keeps the height's
# phase 0 (a phase in y gave z-image no gain, riset sec. 1.4); share 1/2 = T290 PJ's p. Test values live in queue lines only.
# Every line private. A failure (a window not whole tokens, an encode / build / draw error): one private WARN line and the run as
# without the knob from there on (never a lost run). Not with G56CT_T290_PJ / G56CT_T290_ECRN (one bank at a time).
# ----------------------------------------------------------------------------------------------------------------------
CFG.update(t300_vb=env("T300_VB", ""))
T300_FAMS = ("ideogram4", "z-image", "flux")
T300_OFFS = {"wh": ((0.5, 0.5), (0.5, 0.0), (0.0, 0.5), (0.25, 0.25), (0.75, 0.75), (0.25, 0.75), (0.75, 0.25)),
             "w": ((0.5, 0.0), (0.25, 0.0), (0.75, 0.0))}  # x token px; window 0 = the twin's own crop
T300_KEYS = ("twin", "mirror", "img", "share", "imgn")
_T300 = {"said": set(), "src": None, "vb": None, "exs": None}


def _t300_say(key, msg):
    """one private line per key and process"""
    if key not in _T300["said"]:
        _T300["said"].add(key)
        log(msg)


def t300_spec(raw):
    """a G56CT_T300_VB value -> None (off: '', '0', 'off', ...) or {'twin': n, 'mirror': n, 'img': (lo, hi) or None, 'share': s,
    'imgn': n or None}; ValueError on a bad value (each key at most once; something must rotate)"""
    s = str(raw if raw is not None else "").strip().lower()
    if s in T277_OFF:
        return None
    out = {"twin": 1, "mirror": 1, "img": None, "share": 0.5, "imgn": None}
    seen = set()
    for part in s.split(","):
        k, sep, v = part.partition(":")
        k, v = k.strip(), v.strip()
        if not sep or k not in T300_KEYS or k in seen or not v:
            raise ValueError(f"bad part {part!r} in {raw!r} (keys: {', '.join(T300_KEYS)})")
        seen.add(k)
        if k in ("twin", "mirror", "imgn"):
            if not re.fullmatch(r"\d+", v):
                raise ValueError(f"{k} {v!r} is not a whole number in {raw!r}")
            n, top = int(v), (8 if k == "mirror" else 7)
            if not 1 <= n <= top:
                raise ValueError(f"{k} {v!r} outside 1-{top} in {raw!r}")
            out[k] = n
        elif k == "img":
            m = re.fullmatch(r"(\d+)-(\d+)", v)
            lo, hi = (int(m.group(1)), int(m.group(2))) if m else (-1, -1)
            if not 0 <= lo <= hi <= 15:
                raise ValueError(f"img {v!r} is not a band range lo-hi within 0-15 in {raw!r}")
            out["img"] = (lo, hi)
        else:
            from fractions import Fraction
            x = float(v)
            fr = Fraction(x).limit_denominator(8) if math.isfinite(x) else None
            if fr is None or not 0.0 < x <= 1.0 or abs(float(fr) - x) > 1e-9:
                raise ValueError(f"share {v!r} is not a fraction a/b (b <= 8) in (0, 1] in {raw!r}")
            out["share"] = x
    if ("share" in seen or "imgn" in seen) and out["img"] is None:
        raise ValueError(f"share / imgn need img in {raw!r}")
    if out["twin"] == 1 and out["mirror"] == 1 and out["img"] is None:
        raise ValueError(f"nothing rotates in {raw!r} (twin:1, mirror:1, no img)")
    return out


def t300_window(img, fx, fy, axis, token, mirrored=False):
    """one view: the prepared image (its mirror when asked) cut to the phase twin's shape - axis 'wh' one token smaller in both axes,
    'w' in the width only (fy 0) - with its top-left corner at (fx, fy) x token px -> (PIL image, box) or (None, why)"""
    from PIL import ImageOps
    src = ImageOps.mirror(img) if mirrored else img
    w, h = src.size
    dx, dy = int(round(fx * token)), int(round(fy * token))
    cw, ch = w - token, (h - token if axis == "wh" else h)
    if axis not in ("w", "wh") or (axis == "w" and dy) or not (0 <= dx < token and 0 <= dy < token) \
            or cw < 2 * token or ch < 2 * token or cw % token or ch % token:
        return None, f"{w}x{h} -> {cw}x{ch} at ({dx}, {dy}) is not a whole number of {token} px tokens (axis {axis})"
    box = (dx, dy, dx + cw, dy + ch)
    return src.crop(box), box


def t300_needs(sp, axis):
    """(the image's windows, the mirror's windows) a spec serves on the twin axis: twin slots 1..n-1 = windows 1..n-1, image phase
    slots = windows 0..imgn-1 (default every window of the axis), mirror slots 1..n-1 = the mirror's windows 0..n-2"""
    img = set(range(1, sp["twin"]))
    if sp["img"] is not None:
        img |= set(range(sp["imgn"] if sp["imgn"] is not None else len(T300_OFFS[axis])))
    return img, set(range(sp["mirror"] - 1))


def t300_img_slots(share, n):
    """the image list: None (the image itself) or a window index; share a/b -> n x b slots, a of every b of them windows (Bresenham),
    the windows in order -> every window a times, the image itself n x (b - a) times"""
    from fractions import Fraction
    fr = Fraction(share).limit_denominator(8)
    a, b = fr.numerator, fr.denominator
    out, k = [], 0
    for t in range(n * b):
        if ((t + 1) * a) // b > (t * a) // b:
            out.append(k % n)
            k += 1
        else:
            out.append(None)
    return out


def t300_slot(lst, i, q, h, count):
    """the rotation: the slot of the count-th case of the key (kind, image i, band quarter q, half h) in the list lst"""
    n = len(lst)
    return (i + h * (n // 2) + q * max(1, n // 4) + count) % n


_t300_enc0 = encode_latent  # the trainer's own encode (below every wrapper): a view never reaches a twin / mirror / PJ recorder
while getattr(_t300_enc0, "__wrapped__", None) is not None:
    _t300_enc0 = _t300_enc0.__wrapped__


def _t300_main_spec():
    """this run's bank spec at main() time (the knob set and well formed, an R1 family, the T277 twins recorded with axis 'w' / 'wh',
    mirrors recorded when mirror > 1, no T290 knob) or None (one private line why)"""
    raw = CFG.get("t300_vb")
    try:
        sp = t300_spec(raw)
    except ValueError as e:
        _t300_say(("bad", str(raw)), f"WARN t300 vb: off (G56CT_T300_VB: {e}); the twins / mirrors as their knobs wrote them")
        return None
    if sp is None:
        return None
    fam = _T157.get("fam")
    if fam not in T300_FAMS:
        _t300_say(("fam", fam), f"t300 vb: off (G56CT_T300_VB is for {', '.join(T300_FAMS)} only; family {fam})")
        return None
    on290 = [k for k in ("t290_pj", "t290_ecrn") if str(CFG.get(k) or "").strip().lower() not in T277_OFF]
    if on290:
        _t300_say(("t290",), f"WARN t300 vb: off ({', '.join(on290)} on: one bank at a time)")
        return None
    ts = _T277.get("twin_src")
    if ts is None:
        _t300_say(("notwin",), "t300 vb: off (needs the T277 twins: G56CT_ZCB_KLAW + G56CT_ZCB_TWIN)")
        return None
    axis = ts["spec"].get("axis")
    if axis not in T300_OFFS:
        _t300_say(("axis", axis), f"WARN t300 vb: off (the twin axis {axis!r}: the windows know 'w' and 'wh')")
        return None
    if sp["imgn"] is not None and sp["imgn"] > len(T300_OFFS[axis]):
        _t300_say(("imgn", axis), f"WARN t300 vb: off (imgn {sp['imgn']} > the {len(T300_OFFS[axis])} windows of axis {axis!r})")
        return None
    if sp["twin"] > len(T300_OFFS[axis]) or sp["mirror"] - 1 > len(T300_OFFS[axis]):
        _t300_say(("n", axis), f"WARN t300 vb: off (twin {sp['twin']} / mirror {sp['mirror']} > the windows of axis {axis!r})")
        return None
    if sp["mirror"] > 1 and _T280F.get("src") is None:
        _t300_say(("nomirror",), "WARN t300 vb: off (mirror > 1 needs the R1F mirrors: G56CT_R1F_FLIP)")
        return None
    return sp


_read_rows_t300 = read_rows


def _t300_read_rows(src):
    """read_rows (the T277 / R1F chain first); with G56CT_T300_VB on a run whose twins (and mirrors) are recorded: the views' record"""
    rows = _read_rows_t300(src)
    _T300.update(src=None, vb=None, exs=None)
    try:
        sp = _t300_main_spec()
        if sp is not None:
            axis = _T277["twin_src"]["spec"]["axis"]
            ni, nm = t300_needs(sp, axis)
            _T300["src"] = {"spec": sp, "axis": axis, "img_w": sorted(ni), "mir_w": sorted(nm), "lat": {}, "bad": None, "n_enc": 0,
                            "enc_s": 0.0, "boxes": []}
    except Exception as e:  # noqa: BLE001  (never ends a run: no views)
        _T300["src"] = None
        log(f"WARN t300 vb: {type(e).__name__}: {str(e)[:120]}; no views")
    return rows


_t300_read_rows.__wrapped__ = _read_rows_t300
read_rows = _t300_read_rows  # noqa: F811  (main() calls it by name)
_encode_latent_t300 = encode_latent


def _t300_encode_latent(vae_pair, image, device):
    """encode_latent (the twin / mirror / PJ chain); with the views' record also the image's windows and its mirror's windows by the
    trainer's own encode (the same VAE function), keyed by the image's sha (t277_image_sha = decode_items' key)"""
    lat = _encode_latent_t300(vae_pair, image, device)
    vs = _T300.get("src")
    if vs is None or vs.get("bad"):
        return lat
    try:
        key = t277_image_sha(image)
        if key in vs["lat"]:
            return lat
        token, offs, t0 = T277_TOKEN[_T157.get("fam")], T300_OFFS[vs["axis"]], time.time()
        out = {"img": {}, "mir": {}}
        for part, ks, mir in (("img", vs["img_w"], False), ("mir", vs["mir_w"], True)):
            for k in ks:
                crop, box = t300_window(image, offs[k][0], offs[k][1], vs["axis"], token, mir)
                if crop is None:
                    vs.update(bad=box, lat={})
                    log(f"WARN t300 vb: off for this run (a view {box}); the twins / mirrors as their knobs wrote them")
                    return lat
                out[part][k] = _t300_enc0(vae_pair, crop, device)
                if len(vs["boxes"]) < 3:
                    vs["boxes"].append((part, k, image.size, box))
        vs["lat"][key] = out
        vs["n_enc"] += len(out["img"]) + len(out["mir"])
        vs["enc_s"] += time.time() - t0
    except Exception as e:  # noqa: BLE001
        vs.update(bad=f"{type(e).__name__}: {str(e)[:120]}", lat={})
        log(f"WARN t300 vb: encode {vs['bad']}; no views")
    return lat


_t300_encode_latent.__wrapped__ = _encode_latent_t300
encode_latent = _t300_encode_latent  # noqa: F811  (main() calls it by name)


def _t300_live(tw=None):
    """the bank of the twins T277 is training now (c['t277_tw'] / _T277['tw'] of this very loop), else None: a bank left from an
    earlier train_loop in the same process never acts"""
    vb = _T300.get("vb")
    cur = _T277.get("tw") if tw is None else tw
    return vb if (vb is not None and cur is not None and vb.get("tw") is cur) else None


_t300_inner_twins_build = _t277_twins_build


def _t300_twins_build(c, model_wrap, conds, device):
    """_t277_twins_build (T280's: the N phase twins, then the N mirrors, after the N images), then with G56CT_T300_VB the bank: per
    image its windows' and its mirror's windows' latents through the base's process_latent_in, the rotation lists -> c['t300_vb']"""
    _T300["vb"] = None
    c.pop("t300_vb", None)
    tw = _t300_inner_twins_build(c, model_wrap, conds, device)
    vs = _T300.get("src")
    if vs is None:
        return tw
    try:
        sp = t300_spec((c.get("cfg") or CFG).get("t300_vb"))
    except ValueError:
        sp = None
    if sp is None:
        return tw
    if tw is None or vs.get("bad"):
        log("WARN t300 vb: the T277 twins / the view latents are missing; no views (the twins / mirrors as their knobs wrote them)")
        return tw
    train = list(c["train"])
    n = int(tw["n"])
    ftw = c.get("t280_ftw")
    try:
        if sp["mirror"] > 1 and ftw is None:
            raise RuntimeError("mirror > 1 but no R1F mirror items in this run")
        if len(train) != (3 if ftw is not None else 2) * n:
            raise RuntimeError(f"{len(train)} items for {n} images ({'+ twins + mirrors' if ftw is not None else '+ twins'})")
        proc = c["mp"].model.process_latent_in
        bank, miss = [], []
        for i, it in enumerate(train[:n]):
            rec = vs["lat"].get(it.get("sha"))
            if rec is None:
                miss.append(it.get("name"))
                continue
            twin_shape = tuple(train[n + i]["scaled"].shape)
            b_ = {"img": {k: proc(v.clone()).float().cpu() for k, v in rec["img"].items()},
                  "mir": {k: proc(v.clone()).float().cpu() for k, v in rec["mir"].items()}}
            bad = [(p, k, tuple(v.shape)) for p in ("img", "mir") for k, v in b_[p].items() if tuple(v.shape) != twin_shape]
            if bad:
                raise RuntimeError(f"image {i}: a view's latent {bad[0]} is not the twin's shape {twin_shape}")
            bank.append(b_)
        if miss:
            raise RuntimeError(f"{len(miss)} image(s) without view latents (e.g. {miss[:1]})")
        lists = {}
        if sp["twin"] > 1:
            lists[1] = [None] + list(range(1, sp["twin"]))
        if sp["mirror"] > 1:
            lists[2] = [None] + list(range(sp["mirror"] - 1))
        if sp["img"] is not None:
            imgn = sp["imgn"] if sp["imgn"] is not None else len(T300_OFFS[vs["axis"]])
            lists[0] = t300_img_slots(sp["share"], imgn)
        vb = {"n": n, "items": train, "spec": sp, "axis": vs["axis"], "lists": lists, "bank": bank, "tw": tw, "ftw": ftw, "cnt": {},
              "img": sp["img"]}
        c["t300_vb"] = vb
        _T300["vb"] = vb
        offs = T300_OFFS[vs["axis"]]
        px = T277_TOKEN[_T157.get("fam")]

        def nm(kind, s):
            if s is None:
                return {0: "own", 1: "twin", 2: "mirror"}[kind]
            o = offs[s]
            return f"{'m' if kind == 2 else 'w'}({int(round(o[0] * px))},{int(round(o[1] * px))})"
        parts = []
        for kind, label in ((1, "twin cases"), (2, "mirror cases"), (0, "image cases")):
            if kind in lists:
                where = f" bands {sp['img'][0]}-{sp['img'][1]}, share {sp['share']:g}" if kind == 0 else ""
                parts.append(f"{label}{where}: {'/'.join(nm(kind, s) for s in lists[kind])}")
        shapes = sorted({tuple(v.shape) for b_ in bank for p in ("img", "mir") for v in b_[p].values()})
        log(f"t300 vb: on: axis {vs['axis']}, {n} images x {len(bank[0]['img'])} windows + {len(bank[0]['mir'])} mirror windows "
            f"({vs['n_enc']} view latents encoded in {vs['enc_s']:.1f}s, latents {shapes[:4]} = the twins' shapes); "
            + "; ".join(parts) + f"; e.g. {vs['boxes'][:3]}")
    except Exception as e:  # noqa: BLE001  (never ends a run: no views)
        c.pop("t300_vb", None)
        _T300["vb"] = None
        log(f"WARN t300 vb: {type(e).__name__}: {str(e)[:160]}; no views (the twins / mirrors as their knobs wrote them)")
    return tw


_t300_twins_build.__wrapped__ = _t300_inner_twins_build
_t277_twins_build = _t300_twins_build  # noqa: F811  (_t277_train_loop calls it by name)


class _T300Exposure(_T277Exposure):
    """the T277 (R1F) member schedule; with G56CT_T300_VB each drawn case - its item, band, half and prompt exactly the schedule's own -
    gets the latent it trains from the bank by the rotation (kind 0 image / 1 phase twin / 2 mirror); a redone case keeps its view.
    Draws stay Exposure's own (same seed, same stream)."""

    def __init__(self, counts, n_images, seed):
        super().__init__(counts, n_images, seed)
        vb = _t300_live()
        self.t300 = None if vb is None else {"vb": vb, "cur": None, "trained": {}, "per": {}, "served": 0, "own": 0}
        _T300["exs"] = self

    def draw(self):
        pend = self.pending is not None
        r = super().draw()
        st = self.t300
        if st is None:
            return r
        if pend and st["cur"] is not None and st["cur"][0] == int(r[0]):
            return r
        st["cur"] = None
        try:
            vb = st["vb"]
            n = int(vb["n"])
            item, b, h = int(r[0]), int(r[1]), int(r[2])
            d = _T277.get("draw")
            kd = d[3] if (d is not None and int(d[0]) == item) else None
            kind = 2 if kd == 2 else (1 if (kd is True or kd == 1) else 0)
            lst = vb["lists"].get(kind)
            if lst is None or (kind == 0 and not vb["img"][0] <= b <= vb["img"][1]):
                return r
            i, q = item % n, b // 4
            key = (kind, i, q, h)
            cnt = vb["cnt"].get(key, 0)
            vb["cnt"][key] = cnt + 1
            pos = t300_slot(lst, i, q, h, cnt)
            s = lst[pos]
            lat = None if s is None else vb["bank"][i]["mir" if kind == 2 else "img"][s]
            st["cur"] = (item, lat, kind, i, q, h, pos)
            st["per"][kind, i, q, h, pos] = st["per"].get((kind, i, q, h, pos), 0) + 1  # the assignment (a dropped case still took its slot)
        except Exception as e:  # noqa: BLE001  (never ends a run: this member's cases on their own latents from here)
            self.t300 = None
            log(f"WARN t300 vb: draw {type(e).__name__}: {str(e)[:120]}; the member's cases on their own latents from here")
        return r

    def done(self):
        st = self.t300
        if st is not None and st["cur"] is not None:
            _, _, kind, i, q, h, pos = st["cur"]
            st["trained"][kind, pos] = st["trained"].get((kind, pos), 0) + 1
            st["cur"] = None
        super().done()

    def drop(self):
        st = self.t300
        if st is not None:
            st["cur"] = None
        super().drop()


_T277Exposure = _T300Exposure  # noqa: F811  (_t277_train_loop_planned swaps it in by name; no bank -> T280's / T277's draw itself)
_t300_inner_member_run = _t277_member_run


def _t300_member_run(c, model_wrap, conds, extra_args, device, seed, t_end, run_idx):
    """_t277_member_run with the bank's latent fetch (_t208_fs_dev: a rotated case's view in place of its item's latent, the device
    copy cached as T208's) for exactly this member; one private line per member with its cases per slot"""
    vb = _t300_live(c.get("t277_tw"))
    if vb is None:
        return _t300_inner_member_run(c, model_wrap, conds, extra_args, device, seed, t_end, run_idx)
    mod = globals()
    fs0 = mod["_t208_fs_dev"]
    calls = {"n": 0, "bad": 0}

    def fs_dev(cc, item, dev):
        ex = _T300.get("exs")
        st = getattr(ex, "t300", None) if ex is not None else None
        cur = st["cur"] if st is not None else None
        if cur is None or cc.get("lr_pilot_run"):
            return fs0(cc, item, dev)
        calls["n"] += 1
        if item is not vb["items"][cur[0]]:
            calls["bad"] += 1
            return fs0(cc, item, dev)
        if cur[1] is None:
            st["own"] += 1
            return fs0(cc, item, dev)
        st["served"] += 1
        return fs0(cc, {"scaled": cur[1]}, dev)
    mod["_t208_fs_dev"] = fs_dev
    _T300["exs"] = None
    try:
        return _t300_inner_member_run(c, model_wrap, conds, extra_args, device, seed, t_end, run_idx)
    finally:
        if mod.get("_t208_fs_dev") is fs_dev:
            mod["_t208_fs_dev"] = fs0
        ex = _T300.get("exs")
        st = getattr(ex, "t300", None) if ex is not None else None
        try:
            if st is not None:
                parts = []
                for kind, label in ((1, "twin"), (2, "mirror"), (0, "image")):
                    lst = vb["lists"].get(kind)
                    if lst is None:
                        continue
                    cnt = [st["trained"].get((kind, p), 0) for p in range(len(lst))]
                    spread = 0
                    for key in {k[:4] for k in st["per"] if k[0] == kind}:
                        per = [st["per"].get(key + (p,), 0) for p in range(len(lst))]
                        spread = max(spread, max(per) - min(per))
                    parts.append(f"{label} {cnt} (per image, quarter and half max - min {spread})")  # cnt trained, spread assigned
                act = st["served"] > 0
                log(f"t300 vb: member {run_idx + 1}: cases by slot: {'; '.join(parts)}; {st['served']} view latents served, "
                    f"{st['own']} own" + ("" if act and not calls["bad"] else
                                          f"; WARN t300 vb: did not act as written ({calls['n']} fetches, {calls['bad']} not the drawn "
                                          f"item; it needs G56CT_FAST_SYNC)"))
            elif _T300.get("exs") is None:
                log(f"WARN t300 vb: member {run_idx + 1}: no bank schedule (no EXPOSURE draw in this member)")
        except Exception as e:  # noqa: BLE001  (a log line only)
            log(f"WARN t300 vb: member line {type(e).__name__}: {str(e)[:80]}")
        _T300["exs"] = None


_t300_member_run.__wrapped__ = _t300_inner_member_run
_t277_member_run = _t300_member_run  # noqa: F811  (_t277_loop calls it by name)


# ----------------------------------------------------------------------------------------------------------------------
# ours (T286, 05 Nov 2026; every knob OFF by default = the trainer unchanged byte for byte): krea2 joins the T277 member loop, and the
#
#   T277_FAMS + krea2 (T284's pattern for ideogram4): the G56CT_ZCB_* knobs act on krea2 runs too (G56CT_ZCB_KLAW 'mode:entry' = the
#     entry's member structure inside that loop, G56CT_ZCB_TWIN, G56CT_ZCB_DIV, ...). Half a krea2 token = 8 px of its 16 px token (VAE
#     factor 8 x patch 2): the cut of T282's R2U_TWIN (krea2 4 Nov: 1024x752 -> 1008x752, latents 94x128 -> 94x126).
#   G56CT_R2S_TWSHARE '<s>' (0 < s <= 1; acts only with the G56CT_ZCB_TWIN twins of the T277 loop, not with G56CT_ZCB_XREC): in every
#     twin band (half, band) the image cell keeps (1 - s) x the EXPOSURE table's E and its twin cell gets s x E, so a member's case total,
#     its length, K and every band's dose stay the table's (up to rounding: round(E' x N / 2) per cell), and only a share s of the twin
#     bands' cases is drawn on the phase-shifted twins (their tagged prompts as T277 wrote them). Off ('' / malformed: one private WARN
#     line): the twins ADD their cells exactly as T277 wrote them. TEST values live in queue lines only; no release value here.
# Every line private. A failure in the replaced table: one private WARN line and the additive twins of T277 (never a lost run).
# ----------------------------------------------------------------------------------------------------------------------
T277_FAMS = T277_FAMS + ("krea2",)
T277_HALF_TOKEN["krea2"] = 8
T277_TOKEN["krea2"] = 16
CFG.update(r2s_twshare=env("R2S_TWSHARE", ""))
_T286 = {"said": set()}


def _t286_say(key, msg):
    """one private line per key and process"""
    if key not in _T286["said"]:
        _T286["said"].add(key)
        log(msg)


def t286_share(cfg):
    """G56CT_R2S_TWSHARE -> s in (0, 1], or None (off; a malformed value: one private WARN line)"""
    raw = str(cfg.get("r2s_twshare") if cfg.get("r2s_twshare") is not None else "").strip()
    if raw.lower() in T277_OFF:
        return None
    try:
        s = float(raw)
        if not (math.isfinite(s) and 0.0 < s <= 1.0):
            raise ValueError("not in (0, 1]")
    except ValueError as e:
        _t286_say(("bad", raw), f"WARN r2s twshare: off (G56CT_R2S_TWSHARE {raw!r}: {e}); the twins add their cases as T277 wrote")
        return None
    return s


_t277_exposure_setup_t286 = _t277_exposure_setup


def _t286_exposure_setup(c, tw):
    """_t277_exposure_setup; with twins and G56CT_R2S_TWSHARE s the twin bands' E split (1 - s) images / s twins (see the block above)"""
    cfg = c["cfg"]
    s = t286_share(cfg) if tw is not None else None
    if s is not None and str(cfg.get("zcb_xrec") or "").strip().lower() not in T277_OFF:
        _t286_say(("xrec",), "r2s twshare: off (G56CT_ZCB_XREC's entry phase reads the table's own image cells)")
        s = None
    if s is None:
        return _t277_exposure_setup_t286(c, tw)
    train = c["train"]
    c["train"] = train[:tw["n"]]
    try:
        rec = exposure_setup(c)
    finally:
        c["train"] = train
    if rec is None:
        return None
    try:
        lo, hi = tw["spec"]["bands"]
        cells = exposure_cells(rec["spec"], cfg["bands"])
        img = {k: (e * (1.0 - s) if lo <= k[1] <= hi else e) for k, e in cells.items()}
        tcells = {(h + 2, b): e * s for (h, b), e in cells.items() if lo <= b <= hi}
        counts = {**exposure_counts(img, tw["n"]), **exposure_counts(tcells, tw["n"])}
        if sum(counts.values()) < 1:
            raise ValueError("no case")
    except Exception as e:  # noqa: BLE001  (never ends a run: T277's additive twins)
        log(f"WARN r2s twshare: {type(e).__name__}: {str(e)[:120]}; the twins add their cases as T277 wrote")
        c.pop("exposure", None)
        return _t277_exposure_setup_t286(c, tw)
    total0 = rec["total"]
    rec["counts"], rec["total"] = counts, sum(counts.values())
    if os.environ.get("G56CT_MAX_STEPS", "").strip() in ("", "0"):
        cfg["max_steps"] = rec["total"]
    tc = {k: v for k, v in counts.items() if k[0] >= 2}
    log(f"r2s twshare: on (s {s:g}): bands {lo}-{hi} of both halves split {1.0 - s:g} images / {s:g} twins - {sum(tc.values())} twin "
        f"cases per member ({', '.join(f'{chr(84 if h == 2 else 69)}{b} {v}' for (h, b), v in sorted(tc.items()))}); {rec['total']} "
        f"cases per member over {tw['n']} images + {tw['n']} twins (the table alone: {total0})")
    cells = {**img, **tcells}
    rec["t277_cells"] = cells
    return cells


_t286_exposure_setup.__wrapped__ = _t277_exposure_setup_t286
_t277_exposure_setup = _t286_exposure_setup  # noqa: F811  (_t277_loop calls it by name)


# ----------------------------------------------------------------------------------------------------------------------
# ours (T287, 05 Nov 2026; the release integration of the UNION branch; with REL_C9N empty, T287_QUIET and T287_DISGUISE off the trainer trains and
# writes byte for byte as without this block): every block above meets in one release - the z-image member bundle (T277), ideogram4
# and krea2 in its loop (T284 / T286), the flux mirror bundle (T280 / T284) - and the release turns its mechanisms on in CODE.
#   (a) G56CT_R2S_TWSHARE x G56CT_R1F_FLIP: written apart (T286 / T280). On one run the share's split table (images + phase twins only)
#       would drop the mirrors' cells (R1F adds them to the table T277 builds) -> with mirrors the share stays off (one private line).
#   (b) REL_C9N: the release layer of the c26s profile. Per family a list of rows (cell, {CFG key: value}); a row applies when every
#       selector of its cell matches the run - 'hours' (lo, hi) on --hours-to-complete, 'n' (lo, hi) on the training images N, 'gen'
#       (labels of gen_detect, read from the training images' stored sizes), 'base' (the root checkpoint's probe dtype, base_root_dtype);
#       no selector = every run of the family - in table order, a later row winning a key. It acts in main() right after the per-base FC
#       (fcpb_setup), the last of the default layers (family -> task size -> generator -> base -> per-base FC), so no task-size or
#       generator cell overrides it (review T283 R1F-M2 / U-3), only under the c26s profile, with G56CT_FAMILY_DEFAULTS on and
#       G56CT_C9N not '0' / 'off' (a test switch: the same tree without its layer); an explicit G56CT_<KEY> env var wins as for every
#       family default. A value takes the CFG key's type (t287_coerce); an unknown key, a key main() has used before the layer
#       (T287_C9N_LATE) or a value of another kind: that key skipped + one private WARN line. The twin / mirror knobs (T287_C9N_RECORD)
#       decide in main()'s read_rows: set here, read_rows' T277 / R1F records are made again from its rows (no second zip read). One
#       private line per run names the cell, the matched rows and the applied keys; nothing public. Filling it: RELEASE-9NOV-UNION.md
#       sec. 3 (the adopted arm's knob values, ours, per cell; then tools/rel9n_check.py + the release suite).
#   (c) T287_QUIET (release switch; False = the public stdout unchanged): under the c26s profile the public heartbeat is time-based - a
#       daemon thread writes 'training advancing' every T287_HB_S seconds from 'comfy trainer start' to 'comfy trainer finished' - and
#       the step heartbeat (every 200 steps: it times the speed) goes to the private log; the two T208 cut-member lines keep their step
#       counts and knob value in the private log only (the public line says what happened, no number).
#   (d) Near the top of this file: run as the entrypoint (the validator runs the image's ENTRYPOINT) with no G56CT_PROFILE, the trainer
#
#       to the dedup judge, which assumes every other variable unset); an explicit value ('' / off included) wins; imported (every CPU
#       check) it stays off, so the knob-off identities of the checks are unchanged.
#   (e) T287_DISGUISE (release switch; False = the shipped file as written; coordinator 05 Nov 2026 08:22 WIB, owner: the shipped
#
#       last.safetensors (ensemble, T157's final rewrite, dense / D15 rewrites) and before T161's hard exit - each LoRA module
#       (lora_up / lora_down [+ alpha]) of a family in T287_DG_RANK is rewritten at that family's fixed rank T287_DG_RANK: up' = s up V,
#       down' = V^T down with V an R x R' block of a random orthogonal matrix (orthonormal rows; seeded per module from its own bytes:
#       deterministic), s = alpha / R folded into up' and alpha' = R' (scale 1), stored in T287_DG_DTYPE (float32: the product up' down'
#       = s up down to float32 rounding; bfloat16: to its rounding - checked per module on probe vectors before the write against
#       T287_DG_TOL, else nothing is written), the header's ranks no longer
#       K x r and the factors no longer in canonical form. Every other tensor (qwen-image .diff / .diff_b / LoKr, the metadata) as it
#       was. ideogram4: excluded (T287_DG_EXCLUDE). One atomic rewrite, only when its estimate (the measured seconds per byte) ends
#       T287_DG_MARGIN_S before the watchdog stop / the kill, else the file stays as written (one private line either way); a kill or a
#       crash before main()'s end ships the last written file (undisguised). T287_DG_RESERVE_S (empty: no training-time change) moves
#       the training deadline earlier for it per family. Nothing public. Source code is never obfuscated.
# ----------------------------------------------------------------------------------------------------------------------
