def _t287_say(key, msg):
    """one private line per key and process"""
    if key not in _T287["said"]:
        _T287["said"].add(key)
        log(msg)


def t287_profile_on():
    """the run's profile is the one this block belongs to (G56CT_PROFILE, set by the env or by the entrypoint default)"""
    return str(os.environ.get("G56CT_PROFILE") or "").strip().lower() == T287_PROFILE


