def _t287_exposure_setup(c, tw):
    """_t277_exposure_setup (T286's -> R1F's -> T277's); (a): a run with R1F mirrors and G56CT_R2S_TWSHARE -> the share off for it"""
    cfg = c["cfg"]
    if c.get("t280_ftw") is None or str(cfg.get("r2s_twshare") or "").strip().lower() in T277_OFF:
        return _t277_exposure_setup_t287(c, tw)
    _t287_say(("share_flip",), "r2s twshare: off (G56CT_R1F_FLIP's mirrors add their cells to the table's own image cells; T287 (a))")
    saved = cfg.get("r2s_twshare")
    cfg["r2s_twshare"] = ""
    try:
        return _t277_exposure_setup_t287(c, tw)
    finally:
        cfg["r2s_twshare"] = saved


